-- SAT ScoreBoost -- bulk import of the practice question bank into public.questions
-- Generated by supabase/generate_import.js -- do not hand-edit, regenerate instead.
-- Run in the Supabase SQL editor AFTER schema.sql (requires write access, i.e. run as yourself in the dashboard).
-- Part 5 of 10 (806 questions). Run every part.

-- Allow difficulty 4 (Extra Hard); harmless to repeat in every part.
alter table public.questions drop constraint if exists questions_difficulty_check;
alter table public.questions add constraint questions_difficulty_check check (difficulty between 1 and 4);

insert into public.questions
  (id, module, domain, skill, difficulty, passage, prompt, choices, answer, explanation, choice_explanations)
values
  ($q$ei-644$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$A student has gathered the following notes:
• Rainbows appear after rain.
• Sunlight passes through raindrops.
• The drops split the light into colors.$q$, $q$The student wants to explain how rainbows form. Which choice most effectively does this?$q$, $q$["Rainbows are colorful.","Sunlight is bright.","Rainbows form when sunlight passes through raindrops, which split the light into colors.","Rain falls from clouds."]$q$::jsonb, 2, $q$The choice states the mechanism.$q$, null),
  ($q$ei-645$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$A student has gathered the following notes:
• Writer Zora Neale Hurston collected folklore in the American South.
• She recorded stories, songs, and sayings.
• Her work preserved traditions that might otherwise have been lost.
• Her novel Their Eyes Were Watching God was published in 1937.$q$, $q$The student wants to emphasize Hurston's work as a folklorist. Which choice most effectively does this?$q$, $q$["Hurston wrote a novel in 1937.","By recording stories, songs, and sayings across the American South, Zora Neale Hurston preserved folklore traditions that might otherwise have been lost.","The South is a region.","Folklore is a kind of story."]$q$::jsonb, 1, $q$The choice focuses on her folklore collection and its value.$q$, null),
  ($q$ei-646$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$A student has gathered the following notes:
• The moon's gravity pulls on Earth's oceans.
• This causes tides.
• There are usually two high tides each day.$q$, $q$The student wants to explain the cause of tides. Which choice most effectively does this?$q$, $q$["Oceans are large.","The moon's gravity pulls on Earth's oceans, causing the tides, with usually two high tides each day.","Tides can be high or low.","The moon orbits Earth."]$q$::jsonb, 1, $q$The choice states the cause and the pattern.$q$, null),
  ($q$ei-647$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$A student has gathered the following notes:
• Sea turtles return to the beach where they hatched to lay eggs.
• Scientists think they sense Earth's magnetic field.
• Experiments show turtles swim in the expected direction when the field is altered in a lab.$q$, $q$The student wants to present the evidence for the magnetic hypothesis. Which choice most effectively does this?$q$, $q$["Magnetic fields exist.","Sea turtles lay eggs.","Beaches are sandy.","Scientists hypothesize that sea turtles use Earth's magnetic field to return to their natal beaches, and lab experiments in which the field was altered changed the turtles' swimming direction in line with that idea."]$q$::jsonb, 3, $q$The choice states the hypothesis and the supporting experiment.$q$, null),
  ($q$ei-648$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$A student has gathered the following notes:
• Honey never spoils.
• Archaeologists found edible honey in Egyptian tombs.
• Its low water content and acidity prevent bacteria from growing.$q$, $q$The student wants to explain why honey lasts so long. Which choice most effectively does this?$q$, $q$["Honey is sweet.","Egyptian tombs are old.","Bacteria are small.","Honey never spoils because its low water content and acidity prevent bacteria from growing, which is why edible honey has been found in Egyptian tombs."]$q$::jsonb, 3, $q$The choice gives the reason and the supporting example.$q$, null),
  ($q$ei-649$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$A student has gathered the following notes:
• Maria planted a vegetable garden.
• She grew tomatoes, beans, and squash.
• She shared the vegetables with her neighbors.$q$, $q$The student wants to emphasize Maria's generosity. Which choice most effectively does this?$q$, $q$["Maria planted a garden.","Beans grow on vines.","Maria planted a vegetable garden of tomatoes, beans, and squash and shared the harvest with her neighbors.","Tomatoes are red."]$q$::jsonb, 2, $q$The choice emphasizes sharing.$q$, null),
  ($q$ei-650$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$A student has gathered the following notes:
• The telegraph transmitted messages over wires in the 1840s.
• News that once took days could arrive in minutes.
• Newspapers began to cover distant events almost as they happened.$q$, $q$The student wants to explain how the telegraph changed journalism. Which choice most effectively does this?$q$, $q$["The 1840s were long ago.","Newspapers are printed daily.","Because the telegraph let news that once took days arrive within minutes, newspapers began covering distant events almost as they happened.","The telegraph used wires."]$q$::jsonb, 2, $q$The choice shows the telegraph's effect on newspapers.$q$, null),
  ($q$ei-651$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$A student has gathered the following notes:
• Dr. Chen studies glaciers in Alaska.
• Her team measures how fast the ice is melting.
• Their data show a loss of 75 billion tons per year.$q$, $q$The student wants to present the team's key finding. Which choice most effectively does this?$q$, $q$["Dr. Chen studies glaciers.","Glaciers are made of ice.","Dr. Chen's team, which measures how fast Alaska's glaciers are melting, found a loss of 75 billion tons of ice per year.","Alaska is cold."]$q$::jsonb, 2, $q$The choice states the finding clearly.$q$, null),
  ($q$ei-652$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$A student has gathered the following notes:
• The school started a recycling program.
• Students sort paper, plastic, and glass.
• The program has cut the school's waste in half.$q$, $q$The student wants to highlight the program's results. Which choice most effectively does this?$q$, $q$["Recycling is good.","Paper comes from trees.","Students sort items.","The school's recycling program, in which students sort paper, plastic, and glass, has cut its waste in half."]$q$::jsonb, 3, $q$The choice highlights the result.$q$, null),
  ($q$ei-653$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$The class read two novels this term. ______ they wrote a short essay comparing the main characters.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["However,","Likewise,","Instead,","Afterward,"]$q$::jsonb, 3, $q$The essay followed the reading in time.$q$, null),
  ($q$ei-654$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Gold is a soft metal. ______ it is often mixed with other metals to make jewelry more durable.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Meanwhile,","Therefore,","Likewise,","However,"]$q$::jsonb, 1, $q$Mixing with other metals is a result of gold's softness.$q$, null),
  ($q$ei-655$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Wolves hunt in packs. ______ mountain lions usually hunt alone.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Therefore,","For example,","Similarly,","By contrast,"]$q$::jsonb, 3, $q$The hunting styles differ.$q$, null),
  ($q$ei-656$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$The software update fixed several bugs. ______ it introduced a new problem with the login screen.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For example,","Previously,","Likewise,","Unfortunately,"]$q$::jsonb, 3, $q$The new problem is a negative development after the fixes.$q$, null),
  ($q$ei-657$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Critics have long called the novel unreadable. ______ it has never been out of print, and each generation of readers rediscovers it.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Therefore,","For example,","Even so,","Likewise,"]$q$::jsonb, 2, $q$Continued readership contrasts with the critics' judgment.$q$, null),
  ($q$ei-658$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Elephants have an excellent memory. ______ they can recognize the calls of dozens of other elephants years after last hearing them.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Instead,","For instance,","Regardless,","On the other hand,"]$q$::jsonb, 1, $q$Recognizing calls years later is a specific example of an excellent memory. "For instance" introduces it.$q$, null),
  ($q$ei-659$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Ancient Polynesian navigators crossed thousands of miles of open ocean without instruments. They read the positions of stars, the patterns of ocean swells, and the flight paths of birds. ______ they could locate islands far beyond the horizon.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In contrast,","Despite this,","Instead,","In this way,"]$q$::jsonb, 3, $q$The second sentence explains how they navigated, and the third states what those methods allowed. "In this way" links the methods to the outcome.$q$, null),
  ($q$ei-660$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Lichens can survive in some of the harshest places on Earth, from frozen Antarctic rocks to scorching deserts. ______ some lichens have even survived exposure to the vacuum of space during experiments on the International Space Station.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Remarkably,","Instead,","Otherwise,","However,"]$q$::jsonb, 0, $q$Surviving in space is an even more extreme example that builds on the first sentence. "Remarkably" signals that striking addition.$q$, null),
  ($q$ei-661$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• Mae Jemison was born in Decatur, Alabama, in 1956.
• She trained as a doctor and served in the Peace Corps.
• In 1992, she flew aboard the space shuttle Endeavour.
• She was the first African American woman to travel to space.$q$, $q$The student wants to state Mae Jemison's historic achievement. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In 1992, Mae Jemison became the first African American woman to travel to space.","In 1992, the space shuttle Endeavour flew with Mae Jemison aboard.","Before flying in space, Mae Jemison served in the Peace Corps as a doctor.","Mae Jemison, born in Decatur, Alabama, in 1956, later trained as a doctor."]$q$::jsonb, 0, $q$The goal is to state her historic achievement. Only the sentence about being the first African American woman in space does so.$q$, null),
  ($q$ei-662$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• Maria Tallchief was an Osage ballet dancer.
• She became America's first major prima ballerina.
• She danced with the New York City Ballet from 1947 to 1965.
• She was known for her role in The Firebird.$q$, $q$The student wants to introduce Maria Tallchief to an audience unfamiliar with her. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Maria Tallchief danced with the New York City Ballet from 1947 to 1965.","The Firebird was one of the ballets in which Maria Tallchief performed.","Maria Tallchief, an Osage dancer, became America's first major prima ballerina.","Maria Tallchief was known for her role in the ballet The Firebird."]$q$::jsonb, 2, $q$An introduction should say who she is and why she matters. Only the sentence identifying her as an Osage dancer and America's first major prima ballerina does that.$q$, null),
  ($q$ei-663$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$The chef's first restaurant closed after only a year. ______ she opened a second restaurant that became one of the most popular in the city.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","Undeterred,","Consequently,","In summary,"]$q$::jsonb, 1, $q$Opening a second restaurant after a failure shows persistence. "Undeterred" captures that. The success didn't result from the closure, so "consequently" doesn't fit.$q$, null),
  ($q$ei-664$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$The poet Gwendolyn Brooks often wrote about everyday life in Chicago's South Side. Her collection A Street in Bronzeville, ______ portrays the hopes and struggles of the neighborhood's residents.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["however,","in contrast,","regardless,","for example,"]$q$::jsonb, 3, $q$The collection is an example of Brooks's writing about the South Side. "For example" introduces it.$q$, null),
  ($q$ei-665$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Kudzu is a vine native to Japan and China.
• It was introduced to the United States in 1876.
• In the 1930s, farmers were paid to plant it to prevent soil erosion.
• It now covers millions of acres in the southeastern U.S. and is considered invasive.$q$, $q$The student wants to show that a solution to one problem created another. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Kudzu, a vine native to Japan and China, was introduced to the United States in 1876.","In the 1930s, farmers in the United States were paid to plant kudzu on their land.","Planted in the 1930s to stop erosion, kudzu now invades millions of southern acres.","Kudzu, a vine from Japan and China, is now considered invasive in the United States."]$q$::jsonb, 2, $q$The goal requires both the original purpose (preventing erosion) and the new problem (invasion). Only one choice includes both.$q$, null),
  ($q$ei-666$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• The Silk Road was a network of trade routes connecting China and the Mediterranean.
• Merchants traded silk, spices, and precious metals.
• Ideas, religions, and technologies such as papermaking also spread along the routes.
• The routes were in use from about 130 BCE to 1453 CE.$q$, $q$The student wants to emphasize that the Silk Road spread more than goods. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Besides silk and spices, the Silk Road carried ideas, religions, and papermaking.","Merchants on the Silk Road traded silk, spices, and precious metals across Asia.","The Silk Road was a network of trade routes connecting China and the Mediterranean.","The Silk Road was in use for about 1,500 years, from 130 BCE to 1453 CE."]$q$::jsonb, 0, $q$The goal is to show the Silk Road spread more than goods. Only the choice that mentions ideas, religions, and technologies does so.$q$, null),
  ($q$ei-667$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Some scientists think the first dogs were domesticated in Europe. ______ other researchers point to genetic evidence suggesting that dogs were first domesticated in East Asia.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Therefore,","Similarly,","For instance,","Meanwhile,"]$q$::jsonb, 3, $q$The text presents a competing view held by different researchers. "Meanwhile" introduces that alternative position; "therefore" implies a result, "similarly" implies agreement, and "for instance" implies an example.$q$, null),
  ($q$ei-668$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• The Library of Alexandria was founded in Egypt in the 3rd century BCE.
• It may have held hundreds of thousands of scrolls.
• Scholars from across the Mediterranean studied there.
• Its decline took place gradually over several centuries.$q$, $q$The student wants to emphasize the size of the Library of Alexandria's collection. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Library of Alexandria was founded in the 3rd century BCE.","The Library of Alexandria may have held hundreds of thousands of scrolls.","The Library of Alexandria declined gradually over several centuries.","Scholars from across the Mediterranean studied at the Library of Alexandria."]$q$::jsonb, 1, $q$Only the sentence about the number of scrolls addresses the size of the collection.$q$, null),
  ($q$ei-669$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• The Great Wall of China is a series of fortifications built over many centuries.
• Its total length, including all branches, is about 13,000 miles.
• Construction began as early as the 7th century BCE.
• Much of the existing wall was built during the Ming dynasty (1368–1644).$q$, $q$The student wants to emphasize the length of the Great Wall. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Great Wall of China is a series of fortifications built over many centuries.","Construction of the Great Wall of China began as early as the 7th century BCE.","Much of the existing Great Wall was built during the Ming dynasty.","Including all of its branches, the Great Wall of China stretches about 13,000 miles."]$q$::jsonb, 3, $q$The goal is to emphasize length. Only the sentence giving the 13,000-mile figure does that; the others focus on when or how the wall was built.$q$, null),
  ($q$ei-670$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Jazz musician Mary Lou Williams composed and arranged music for some of the biggest bands of the 1930s. ______ she mentored younger musicians such as Thelonious Monk and Dizzy Gillespie.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Because of her mentors,","In contrast to her mentors,","Beyond her own work,","Instead of composing,"]$q$::jsonb, 2, $q$Mentoring is an accomplishment in addition to her composing. "Beyond her own work" signals that addition; the other choices wrongly suggest she stopped composing or that the musicians were her mentors.$q$, null),
  ($q$ei-671$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• Sojourner Truth was born into slavery in New York around 1797.
• She escaped to freedom in 1826.
• She became a well-known speaker against slavery.
• She also spoke out for women's rights.$q$, $q$The student wants to highlight Sojourner Truth's role as an advocate for two causes. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Sojourner Truth escaped from slavery to freedom in 1826.","Sojourner Truth spoke out both against slavery and for women's rights.","Sojourner Truth became a well-known and powerful speaker.","Sojourner Truth was born into slavery in New York around 1797."]$q$::jsonb, 1, $q$The goal mentions two causes. Only the sentence naming both abolition and women's rights achieves it.$q$, null),
  ($q$ei-672$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• Rice is a staple food for more than half of the world's population.
• It is grown on every continent except Antarctica.
• Most rice is grown in flooded fields called paddies.
• Asia produces about 90 percent of the world's rice.$q$, $q$The student wants to emphasize where most of the world's rice is produced. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["About 90 percent of the world's rice is produced in Asia.","Rice is a staple food for more than half of the world's population.","Most rice is grown in flooded fields called paddies.","Rice is grown on every continent except Antarctica."]$q$::jsonb, 0, $q$Only the sentence giving Asia's 90 percent share addresses where most rice is produced.$q$, null),
  ($q$ei-673$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• In 2019, a team of astronomers released the first image of a black hole.
• The black hole is at the center of the galaxy M87, about 55 million light-years away.
• The image was made using the Event Horizon Telescope, a network of eight radio telescopes around the world.
• Combining the telescopes created a virtual telescope about the size of Earth.$q$, $q$The student wants to explain how astronomers were able to capture the image. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Astronomers linked eight radio telescopes into a virtual Earth-sized telescope to capture the image.","The black hole in the 2019 image is about 55 million light-years away, in the galaxy M87.","The first image of a black hole, released in 2019, was made with the Event Horizon Telescope.","In 2019, astronomers released the first image of a black hole, located in the galaxy M87."]$q$::jsonb, 0, $q$The goal is to explain how the image was made. Only the sentence describing the combined telescope network does so.$q$, null),
  ($q$ei-674$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$The trail to the waterfall is only two miles long. ______ it climbs more than 1,500 feet, so most hikers need several hours to finish it.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Therefore,","However,","Similarly,","For example,"]$q$::jsonb, 1, $q$The second sentence contrasts with the first: the trail is short, but steep and slow. "However" signals that contrast.$q$, null),
  ($q$ei-675$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$The theater's old seats were uncomfortable and worn. ______ the owners replaced all of them last summer.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Accordingly,","Likewise,","Instead,","Nevertheless,"]$q$::jsonb, 0, $q$Replacing the seats is a fitting response to their condition. "Accordingly" signals that logical result.$q$, null),
  ($q$ei-676$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Most of the students voted to hold the dance in the gym. ______ the student council chose the gym as the location.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["However,","Similarly,","Instead,","Thus,"]$q$::jsonb, 3, $q$The council's choice follows from the vote. "Thus" signals that result.$q$, null),
  ($q$ei-677$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• Jesse Owens was an American track and field athlete.
• He competed in the 1936 Olympics in Berlin.
• He won four gold medals at those Games.
• His events included the 100 meters and the long jump.$q$, $q$The student wants to state how many gold medals Jesse Owens won in 1936. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Jesse Owens competed at the 1936 Olympic Games in Berlin.","At the 1936 Olympics in Berlin, Jesse Owens won four gold medals.","Jesse Owens competed in the 100 meters and the long jump in 1936.","Jesse Owens was an American track and field athlete in the 1930s."]$q$::jsonb, 1, $q$Only the sentence with the number of gold medals accomplishes the goal.$q$, null),
  ($q$ei-678$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$The ancient Romans built roads with several layers of stone and gravel. ______ many of these roads have survived for more than 2,000 years.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Instead of this careful construction,","Because of this careful construction,","Despite this careful construction,","Unlike this careful construction,"]$q$::jsonb, 1, $q$The roads survived because they were built carefully. Only "Because of this careful construction" states that causal link.$q$, null),
  ($q$ei-679$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Maya practiced the piano for an hour every day for a year. ______ she was ready to perform at the spring recital.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Eventually,","Nonetheless,","In comparison,","Instead,"]$q$::jsonb, 0, $q$The second sentence describes what happened after a long period of practice. "Eventually" signals that sequence in time.$q$, null),
  ($q$ei-680$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$The mathematician Katherine Johnson calculated the flight paths for several early NASA missions. Before John Glenn's 1962 orbit of Earth, ______ he asked that she personally verify the computer's calculations.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["in contrast,","in fact,","however,","instead,"]$q$::jsonb, 1, $q$Glenn's request emphasizes how much NASA trusted Johnson's work. "In fact" signals that reinforcing detail.$q$, null),
  ($q$ei-681$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$The first version of the robot could only move forward. ______ the second version could turn, climb steps, and pick up objects.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For instance,","Similarly,","In contrast,","Therefore,"]$q$::jsonb, 2, $q$The second version's abilities differ sharply from the first's. "In contrast" signals that difference.$q$, null),
  ($q$ei-682$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Penguins cannot fly. ______ they are excellent swimmers, reaching speeds of up to 22 miles per hour underwater.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","Still,","Likewise,","For example,"]$q$::jsonb, 1, $q$Although penguins can't fly, they are skilled in the water. "Still" signals that contrast with the first sentence.$q$, null),
  ($q$ei-683$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• The Tour de France is a bicycle race held each July.
• It was first held in 1903.
• The race covers about 2,200 miles over 21 stages.
• The leader wears a yellow jersey.$q$, $q$The student wants to emphasize the distance of the Tour de France. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The leader of the Tour de France wears a yellow jersey.","The Tour de France is a bicycle race held each July.","The Tour de France, held each July, was first held in 1903.","Riders in the Tour de France cover about 2,200 miles over 21 stages."]$q$::jsonb, 3, $q$Only the sentence with the 2,200-mile figure addresses distance.$q$, null),
  ($q$ei-684$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Volunteers removed more than two tons of trash from the river last spring. ______ water quality tests showed a noticeable improvement within a few months.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nonetheless,","Likewise,","Subsequently,","Conversely,"]$q$::jsonb, 2, $q$The improved test results came after the cleanup. "Subsequently" signals that sequence.$q$, null),
  ($q$ei-685$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Ice cores are cylinders of ice drilled from glaciers and ice sheets.
• Air bubbles trapped in the ice preserve samples of the ancient atmosphere.
• The oldest continuous ice core, from Antarctica, records about 800,000 years of climate history.
• Scientists use these records to compare past carbon dioxide levels with today's.$q$, $q$The student wants to explain how ice cores help scientists study past climates. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Scientists drill ice cores from glaciers and ice sheets in places such as Antarctica.","Air bubbles in ice cores preserve ancient air, letting scientists compare past and present carbon dioxide.","The oldest continuous ice core, from Antarctica, records about 800,000 years of history.","Ice cores are cylinders of ice drilled from glaciers and ice sheets, including some in Antarctica."]$q$::jsonb, 1, $q$The goal is to explain how ice cores reveal past climates. Only the sentence linking trapped air bubbles to comparisons of carbon dioxide levels explains the method.$q$, null),
  ($q$ei-686$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Glass frogs have translucent skin that lets observers see their hearts and digestive organs. Researchers recently found that while the frogs sleep, they hide nearly 90 percent of their red blood cells inside their livers. ______ the frogs become almost completely transparent, which helps them avoid predators.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In contrast,","Nevertheless,","Similarly,","As a result,"]$q$::jsonb, 3, $q$Hiding red blood cells causes the frogs to become almost transparent. "As a result" signals that cause-and-effect relationship.$q$, null),
  ($q$ei-687$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• The Hubble Space Telescope was launched in 1990.
• Soon after launch, scientists found a flaw in its main mirror that made images blurry.
• In 1993, astronauts installed corrective optics during a spacewalk.
• After the repair, Hubble produced some of the sharpest images of space ever taken.$q$, $q$The student wants to describe how an early setback was overcome. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Hubble Space Telescope was launched in 1990 and has operated for decades since then.","Soon after Hubble's launch in 1990, scientists found a flaw in its main mirror.","A flawed mirror blurred Hubble's early images, but a 1993 repair made them remarkably sharp.","Hubble has produced some of the sharpest images of space that have ever been taken."]$q$::jsonb, 2, $q$The goal requires the setback and how it was fixed. Only one choice includes both the flaw and the repair.$q$, null),
  ($q$ei-688$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$The first vaccine for smallpox was developed in 1796. ______ it took nearly two centuries of vaccination campaigns before the World Health Organization declared the disease eradicated in 1980.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Even so,","For example,","As a result,","Similarly,"]$q$::jsonb, 0, $q$Despite the early vaccine, eradication took a very long time. "Even so" signals that concession.$q$, null),
  ($q$ei-689$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$First, the students mixed the baking soda and water. ______ they slowly added vinegar and watched the mixture bubble.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Next,","For example,","In contrast,","However,"]$q$::jsonb, 0, $q$The steps follow one another in order. "Next" signals the second step.$q$, null),
  ($q$ei-690$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• The Underground Railroad was a network of routes and safe houses.
• It helped enslaved people escape to free states and Canada.
• Harriet Tubman made about 13 trips to guide roughly 70 people to freedom.
• She never lost a single person she guided.$q$, $q$The student wants to emphasize Harriet Tubman's skill as a guide. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Harriet Tubman guided about 70 people to freedom and never lost a single one.","The Underground Railroad helped enslaved people escape to free states and Canada.","Harriet Tubman made about 13 trips to guide people on the Underground Railroad.","The Underground Railroad was a network of secret routes and safe houses."]$q$::jsonb, 0, $q$Her perfect record of never losing anyone best shows her skill. Only one choice includes it.$q$, null),
  ($q$ei-691$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• The Pantheon in Rome was completed around 125 CE.
• Its dome is made of unreinforced concrete.
• The dome is about 142 feet across.
• It is still the largest unreinforced concrete dome in the world.$q$, $q$The student wants to emphasize the lasting achievement of the Pantheon's builders. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Pantheon in Rome was completed around 125 CE with a concrete dome.","The Pantheon's dome is made of concrete that contains no reinforcement.","Nearly 1,900 years later, the Pantheon's dome is still the largest of its kind.","The Pantheon's dome, made of unreinforced concrete, is about 142 feet across."]$q$::jsonb, 2, $q$A lasting achievement is one that still stands out today. Only the choice stating the dome remains the largest of its kind emphasizes that.$q$, null),
  ($q$ei-692$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Toni Morrison was an American novelist.
• Her novel Beloved won the Pulitzer Prize in 1988.
• In 1993, she became the first Black woman to win the Nobel Prize in Literature.
• She also worked as an editor at Random House.$q$, $q$The student wants to present Morrison's most significant international honor. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Toni Morrison's novel Beloved won the Pulitzer Prize, a major American award, in 1988.","Before becoming a celebrated novelist, Toni Morrison worked as an editor at Random House.","In 1993, Toni Morrison became the first Black woman to win the Nobel Prize in Literature.","Toni Morrison was an American novelist whose works include the Pulitzer-winning Beloved."]$q$::jsonb, 2, $q$The Nobel Prize is an international honor, unlike the Pulitzer, which is an American prize. Only the sentence about the Nobel accomplishes the goal.$q$, null),
  ($q$ei-693$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Migrating Arctic terns fly from the Arctic to the Antarctic and back each year.
• The round trip can be more than 40,000 miles.
• Arctic terns can live 30 years or more.
• Over a lifetime, a tern may fly a distance equal to three trips to the Moon and back.$q$, $q$The student wants to emphasize the total distance an Arctic tern may fly in its life. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In its lifetime, an Arctic tern may fly as far as three round trips to the Moon.","An Arctic tern's yearly round trip between the poles can exceed 40,000 miles.","Arctic terns migrate from the Arctic to the Antarctic and back every year.","Arctic terns, which migrate between the poles each year, can live 30 years or more."]$q$::jsonb, 0, $q$The goal is lifetime distance. The yearly figure is impressive but doesn't address a lifetime; only the Moon comparison does.$q$, null),
  ($q$ei-694$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$The city's population grew rapidly in the 1990s. ______ its public transit system expanded slowly, leaving many new neighborhoods without bus or train service.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For example,","Meanwhile,","Similarly,","Therefore,"]$q$::jsonb, 1, $q$The slow transit expansion happened at the same time as the rapid growth and contrasts with it. "Meanwhile" signals those simultaneous, contrasting developments.$q$, null),
  ($q$ei-695$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Sign languages are complete languages with their own grammar.
• American Sign Language (ASL) and British Sign Language (BSL) are very different.
• ASL is more closely related to French Sign Language.
• This is because a French teacher helped found the first U.S. school for deaf students in 1817.$q$, $q$The student wants to explain why ASL is more closely related to French Sign Language than to BSL. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["ASL is more closely related to French Sign Language than to British Sign Language.","Sign languages such as ASL and BSL are complete languages with their own grammar.","American Sign Language and British Sign Language are very different from each other.","ASL resembles French Sign Language because a French teacher helped found the first U.S. deaf school."]$q$::jsonb, 3, $q$Only the choice that names the French teacher's role explains the connection.$q$, null),
  ($q$ei-696$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• Octopuses have three hearts.
• Two hearts pump blood to the gills.
• The third heart pumps blood to the rest of the body.
• Their blood is blue because it contains copper.$q$, $q$The student wants to explain why octopus blood is blue. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Two of an octopus's hearts pump blood to its gills.","An octopus's third heart pumps blood to the rest of its body.","Octopuses have three hearts.","Octopus blood is blue because it contains copper."]$q$::jsonb, 3, $q$Only the sentence about copper explains the blue color.$q$, null),
  ($q$ei-697$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Architect I. M. Pei designed the glass pyramid at the Louvre in Paris.
• The pyramid opened in 1989.
• Many Parisians initially criticized it as out of place among the museum's historic buildings.
• It is now one of the most photographed structures in the city.$q$, $q$The student wants to emphasize how opinions of the Louvre pyramid changed over time. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Louvre pyramid, which opened in 1989, sits among the museum's historic buildings.","Once criticized as out of place, the Louvre pyramid is now one of Paris's most photographed sights.","I. M. Pei designed the glass pyramid at the Louvre, which opened to the public in 1989.","When it opened in 1989, many Parisians criticized the Louvre pyramid as out of place."]$q$::jsonb, 1, $q$A change in opinion requires both the early criticism and the later popularity. Only one choice includes both.$q$, null),
  ($q$ei-698$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Vincent van Gogh produced about 2,100 artworks.
• He sold very few paintings during his lifetime.
• In 1990, his Portrait of Dr. Gachet sold for $82.5 million.
• He painted it in 1890, the last year of his life.$q$, $q$The student wants to contrast van Gogh's lack of commercial success while alive with the value of his work later. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Though he sold few paintings in his life, van Gogh's Portrait of Dr. Gachet later sold for $82.5 million.","Van Gogh painted Portrait of Dr. Gachet in 1890, the last year of his life, among about 2,100 works.","Van Gogh produced about 2,100 artworks, including Portrait of Dr. Gachet, painted in 1890.","In 1990, a century after it was painted, Portrait of Dr. Gachet sold for $82.5 million."]$q$::jsonb, 0, $q$The contrast needs both his lack of sales while alive and the later price. Only one choice includes both.$q$, null),
  ($q$ei-699$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$The store's prices are higher than those at the supermarket. ______ many shoppers go there because the produce is fresher.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Even so,","For example,","Therefore,","Likewise,"]$q$::jsonb, 0, $q$Shoppers choose the store despite its higher prices. "Even so" signals that concession.$q$, null),
  ($q$ei-700$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Some frogs can survive being frozen in winter. ______ the wood frog's heart stops beating, and it thaws back to life in spring.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In contrast,","However,","For example,","Even so,"]$q$::jsonb, 2, $q$The wood frog is a specific example of a frog that survives freezing. "For example" introduces it.$q$, null),
  ($q$ei-701$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Cats are often thought to be independent animals. ______ many cats form close bonds with their owners and seek out their company.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","Yet","Similarly,","For example,"]$q$::jsonb, 1, $q$The second sentence challenges the common view in the first. "Yet" signals that contrast.$q$, null),
  ($q$ei-702$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$The school library added 500 new books this year. ______ it installed ten new computers for student use.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Additionally,","Nevertheless,","Consequently,","Instead,"]$q$::jsonb, 0, $q$The second sentence adds another improvement to the library. "Additionally" signals that addition.$q$, null),
  ($q$ei-703$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$The painter spent most of her career in obscurity, selling few works. ______ after her death, her paintings began to appear in major museums around the world.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","For instance,","Similarly,","Decades"]$q$::jsonb, 3, $q$The recognition came long after the obscurity described in the first sentence. "Decades after her death" marks that passage of time; the other choices imply a result, a similarity, or an example.$q$, null),
  ($q$ei-704$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Some people prefer to read books on paper. ______ others prefer the convenience of reading on a tablet.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For example,","Thus,","Meanwhile,","As a result,"]$q$::jsonb, 2, $q$The second sentence presents a different group's preference alongside the first. "Meanwhile" signals that the two contrasting situations exist side by side.$q$, null),
  ($q$ei-705$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• The cheetah is the fastest land animal.
• It can reach speeds of about 70 miles per hour.
• It can maintain top speed for only about 30 seconds.
• Cheetahs live mainly in eastern and southern Africa.$q$, $q$The student wants to describe a limitation of the cheetah's speed. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The cheetah can run about 70 miles per hour but only for about 30 seconds.","The cheetah, the fastest land animal, can reach speeds of about 70 miles per hour.","Cheetahs, which live mainly in eastern and southern Africa, are extremely fast.","The cheetah, which lives mainly in Africa, is the fastest land animal on Earth."]$q$::jsonb, 0, $q$A limitation is something that restricts its speed. Only the sentence about holding top speed for just 30 seconds describes one.$q$, null),
  ($q$ei-706$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• The printing press was invented by Johannes Gutenberg around 1440.
• Before it, books were copied by hand, which could take months.
• By 1500, printing presses in Europe had produced more than 20 million books.
• The spread of books helped increase literacy.$q$, $q$The student wants to emphasize how dramatically the printing press increased book production. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Before Gutenberg's printing press, books in Europe were copied by hand.","Johannes Gutenberg invented the printing press in Europe around the year 1440.","The spread of printed books in Europe after 1440 helped increase literacy rates.","Copying one book by hand took months, yet presses printed over 20 million books by 1500."]$q$::jsonb, 3, $q$The contrast between months for one handwritten book and 20 million printed books emphasizes the dramatic increase. The other choices lack that comparison.$q$, null),
  ($q$ei-707$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$In 2004, NASA's rovers Spirit and Opportunity were expected to operate on Mars for about 90 days. ______ Opportunity kept exploring for nearly 15 years before a dust storm ended its mission.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","Consequently,","Remarkably,","In other words,"]$q$::jsonb, 2, $q$Opportunity far exceeded expectations. "Remarkably" signals that surprising outcome; nothing about the expectation caused it, and it isn't a restatement.$q$, null),
  ($q$ei-708$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Earth's magnetic field is generated by molten iron moving in the planet's outer core.
• The field shields Earth from harmful solar radiation.
• Many migrating animals, including sea turtles and some birds, use the field to navigate.
• The field's north and south poles have reversed many times in Earth's history.$q$, $q$The student wants to explain one way animals rely on Earth's magnetic field. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Earth's magnetic north and south poles have reversed many times.","Earth's magnetic field is generated by molten iron in the outer core.","Many migrating animals, including sea turtles and some birds, use Earth's magnetic field to navigate.","Earth's magnetic field shields the planet from harmful solar radiation."]$q$::jsonb, 2, $q$Only the sentence about navigation describes how animals rely on the field.$q$, null),
  ($q$ei-709$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Monarch butterflies that hatch in early summer live only a few weeks. Those that hatch in late summer, ______ can live up to eight months, long enough to migrate to Mexico and back.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["as a result,","for example,","on the other hand,","in addition,"]$q$::jsonb, 2, $q$Late-summer monarchs live much longer than early-summer ones. "On the other hand" signals that contrast.$q$, null),
  ($q$ei-710$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• The Mariana Trench is in the western Pacific Ocean.
• Its deepest point, the Challenger Deep, is about 36,000 feet below sea level.
• Mount Everest is about 29,000 feet tall.
• Only a few people have traveled to the bottom of the trench.$q$, $q$The student wants to compare the depth of the Mariana Trench with the height of Mount Everest. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Mount Everest, at about 29,000 feet, is the tallest mountain above sea level.","The Mariana Trench, whose deepest point is the Challenger Deep, is in the western Pacific.","Only a few people have traveled to the Challenger Deep, at the bottom of the Mariana Trench.","At about 36,000 feet deep, the Challenger Deep exceeds Everest's 29,000-foot height."]$q$::jsonb, 3, $q$Only the sentence that gives both measurements makes the comparison.$q$, null),
  ($q$ei-711$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Paper money was first used in China during the Tang dynasty, more than 1,000 years ago. ______ it did not become common in Europe until the 1600s.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["By contrast,","Therefore,","For example,","Similarly,"]$q$::jsonb, 0, $q$Europe's much later adoption contrasts with China's early use. "By contrast" signals that difference.$q$, null),
  ($q$ei-712$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Researchers expected that students who listened to music while studying would score lower on tests. ______ the students who listened to instrumental music scored slightly higher than those who studied in silence.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Likewise,","Surprisingly,","Accordingly,","Predictably,"]$q$::jsonb, 1, $q$The result was the opposite of what researchers expected. "Surprisingly" signals that unexpected finding.$q$, null),
  ($q$ei-713$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Bioluminescence is light produced by living organisms.
• Fireflies use it to attract mates.
• Anglerfish use a glowing lure to attract prey.
• Some squid use it to camouflage themselves against moonlit water.$q$, $q$The student wants to emphasize the variety of purposes bioluminescence serves. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Anglerfish, like fireflies, produce light, using a glowing lure to attract prey.","Fireflies use bioluminescence to attract mates, anglerfish to lure prey, and squid to hide.","Fireflies and anglerfish are both bioluminescent, meaning that they produce light.","Bioluminescence is light produced by living organisms, such as fireflies and anglerfish."]$q$::jsonb, 1, $q$The goal calls for variety. Only the choice listing three different purposes shows it.$q$, null),
  ($q$ei-714$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$The company spent two years designing a new electric scooter. ______ the scooter sold out within a week of its release.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In other words,","Ultimately,","Conversely,","Similarly,"]$q$::jsonb, 1, $q$The sellout is the final outcome of the long design process. "Ultimately" signals that conclusion.$q$, null),
  ($q$ei-715$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Urban trees provide shade that can lower nearby street temperatures by several degrees. ______ they absorb rainwater, reducing the amount of runoff that flows into storm drains.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Even so,","In addition,","Instead,","In contrast,"]$q$::jsonb, 1, $q$Absorbing rainwater is another benefit of urban trees. "In addition" signals this added benefit.$q$, null),
  ($q$ei-716$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• The Amazon rainforest covers about 2.1 million square miles.
• It produces about 20 percent of the world's oxygen.
• It is home to about 10 percent of known species.
• It spans nine countries.$q$, $q$The student wants to emphasize the Amazon's biodiversity. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Amazon rainforest covers about 2.1 million square miles of land.","The Amazon rainforest spans nine countries in South America.","The Amazon rainforest produces about 20 percent of the world's oxygen.","The Amazon rainforest is home to about 10 percent of the world's known species."]$q$::jsonb, 3, $q$Biodiversity refers to the variety of living things. Only the sentence about species addresses it.$q$, null),
  ($q$ei-717$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Many people assume that the Sahara has always been a desert. ______ evidence from ancient lake beds and rock paintings of hippos and giraffes shows that the region was green and wet as recently as 6,000 years ago.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Accordingly,","Likewise,","For this reason,","In reality,"]$q$::jsonb, 3, $q$The evidence corrects a mistaken assumption. "In reality" signals that the truth differs from what people assume.$q$, null),
  ($q$ei-718$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Mangrove trees grow along tropical coastlines.
• Their tangled roots slow waves and reduce erosion.
• Mangrove forests store up to four times more carbon than many inland forests.
• They provide nurseries for many species of fish.$q$, $q$The student wants to emphasize mangroves' role in fighting climate change. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Mangrove trees grow along tropical coastlines, where their roots form tangles.","Mangrove roots slow incoming waves and help reduce erosion along coastlines.","Mangrove forests can store up to four times more carbon than many inland forests.","Mangrove forests provide nurseries for many species of fish in tropical waters."]$q$::jsonb, 2, $q$Storing carbon is how mangroves help fight climate change. The other benefits are real but unrelated to the goal.$q$, null),
  ($q$ei-719$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• The Harlem Renaissance was a cultural movement in the 1920s and 1930s.
• It was centered in the Harlem neighborhood of New York City.
• Writers such as Zora Neale Hurston and Langston Hughes were part of it.
• Musicians such as Duke Ellington also played a major role.$q$, $q$The student wants to name two writers associated with the Harlem Renaissance. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Harlem Renaissance took place in the 1920s and 1930s.","Zora Neale Hurston and Langston Hughes were writers of the Harlem Renaissance.","The Harlem Renaissance was centered in New York City.","Duke Ellington was a musician who played a major role in the Harlem Renaissance."]$q$::jsonb, 1, $q$The goal is to name two writers. Only the sentence naming Hurston and Hughes does so; Ellington was a musician.$q$, null),
  ($q$ei-720$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Electric cars produce no tailpipe emissions. ______ the electricity used to charge them may come from power plants that burn fossil fuels.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Additionally,","For example,","However,","Therefore,"]$q$::jsonb, 2, $q$The second sentence qualifies the environmental benefit described in the first. "However" signals that contrast.$q$, null),
  ($q$ei-721$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$The new park has a playground and a picnic area. ______ it has a walking path that circles a small pond.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Instead,","In contrast,","However,","Moreover,"]$q$::jsonb, 3, $q$The text lists another feature of the park. "Moreover" signals that addition; the other choices signal contrast.$q$, null),
  ($q$ei-722$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$The first season of the television series received poor reviews. By the third season, ______ critics were calling it one of the best shows on the air.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["for example,","however,","similarly,","therefore,"]$q$::jsonb, 1, $q$The critics' later praise contrasts with the earlier poor reviews. "However" signals that change.$q$, null),
  ($q$ei-723$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Coral reefs cover less than 1 percent of the ocean floor. ______ they support about 25 percent of all known marine species.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","Nevertheless,","In addition,","Therefore,"]$q$::jsonb, 1, $q$The large share of species contrasts with the reefs' tiny area. "Nevertheless" signals that surprising contrast.$q$, null),
  ($q$ei-724$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• Hedy Lamarr was a famous film actress in the 1930s and 1940s.
• During World War II, she co-invented a radio technology called frequency hopping.
• Frequency hopping helped prevent signals from being jammed.
• Similar technology is now used in Wi-Fi and Bluetooth.$q$, $q$The student wants to emphasize the lasting impact of Hedy Lamarr's invention. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Hedy Lamarr, a famous film actress of the 1930s and 1940s, was also an inventor.","Hedy Lamarr's wartime invention, frequency hopping, underlies today's Wi-Fi and Bluetooth.","During World War II, film star Hedy Lamarr co-invented a radio technology.","Frequency hopping, which Hedy Lamarr co-invented, helped keep radio signals from being jammed."]$q$::jsonb, 1, $q$"Lasting impact" calls for the invention's present-day use. Only the sentence connecting it to Wi-Fi and Bluetooth shows that.$q$, null),
  ($q$ei-725$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$The town council approved funding for a new skate park. ______ construction can't begin until the state approves the environmental review.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Likewise,","Therefore,","Still,","Specifically,"]$q$::jsonb, 2, $q$The required approval limits what the funding achieves right away. "Still" signals that qualification.$q$, null),
  ($q$ei-726$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Jacob Lawrence was an American painter.
• In 1941, he completed The Migration Series, a set of 60 panels.
• The series depicts the movement of Black Americans from the rural South to northern cities.
• Half of the panels are owned by the Museum of Modern Art, and half by the Phillips Collection.$q$, $q$The student wants to describe the subject of The Migration Series. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Jacob Lawrence was an American painter who completed a 60-panel series in 1941.","Lawrence's The Migration Series depicts Black Americans moving from the South to northern cities.","Jacob Lawrence completed The Migration Series, a set of 60 panels, in 1941.","Half of The Migration Series is owned by MoMA and half by the Phillips Collection."]$q$::jsonb, 1, $q$Only the sentence explaining what the series depicts describes its subject.$q$, null),
  ($q$ei-727$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Sourdough bread is made with a starter rather than commercial yeast.
• A starter is a mixture of flour and water that collects wild yeast and bacteria.
• The bacteria produce lactic acid, which gives sourdough its tangy flavor.
• Some starters have been kept alive for more than 100 years.$q$, $q$The student wants to explain what gives sourdough its distinctive taste. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Sourdough bread is made with a starter rather than with commercial yeast.","Some sourdough starters have been kept alive for more than 100 years.","A sourdough starter is a mixture of flour and water that collects wild yeast.","Bacteria in a sourdough starter produce lactic acid, which gives the bread its tangy flavor."]$q$::jsonb, 3, $q$Only the sentence about lactic acid explains the bread's distinctive taste.$q$, null),
  ($q$ei-728$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• Wangari Maathai was a Kenyan environmental activist.
• She founded the Green Belt Movement in 1977.
• The movement has planted more than 50 million trees.
• In 2004, she won the Nobel Peace Prize.$q$, $q$The student wants to highlight the scale of the Green Belt Movement's work. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Wangari Maathai was a Kenyan environmental activist and Nobel Prize winner.","Kenyan activist Wangari Maathai founded the Green Belt Movement in 1977.","Maathai's Green Belt Movement has planted more than 50 million trees.","Wangari Maathai, founder of the Green Belt Movement, won the 2004 Nobel Peace Prize."]$q$::jsonb, 2, $q$The scale of the movement's work is shown by the number of trees planted, which only one choice mentions.$q$, null),
  ($q$ei-729$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$To make the poster, Priya first sketched her design in pencil. ______ she traced over the lines with black ink.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Instead,","Afterward,","For example,","However,"]$q$::jsonb, 1, $q$Tracing over the lines follows sketching. "Afterward" signals that order.$q$, null),
  ($q$ei-730$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Jupiter is the largest planet in our solar system. ______ more than 1,300 Earths could fit inside it.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Otherwise,","In fact,","Instead,","However,"]$q$::jsonb, 1, $q$The second sentence emphasizes just how large Jupiter is. "In fact" signals that strengthening detail.$q$, null),
  ($q$ei-731$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• A team of engineers built a solar-powered water purifier.
• It costs about $20 to make.
• It can clean about 10 liters of water per day.
• It is designed for rural communities without electricity.$q$, $q$The student wants to emphasize that the purifier is suited to communities with limited resources. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The $20 solar purifier needs no electricity, which suits rural communities.","The solar-powered purifier can clean about 10 liters of water per day.","Engineers built a solar-powered water purifier that cleans 10 liters daily.","A team of engineers built a water purifier that can clean 10 liters a day."]$q$::jsonb, 0, $q$Limited resources call for low cost and no need for electricity. Only one choice highlights both.$q$, null),
  ($q$ei-732$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Mount Vesuvius erupted in 79 CE.
• Ash buried the Roman cities of Pompeii and Herculaneum.
• The ash preserved buildings, artwork, and everyday objects.
• Excavations since the 1700s have given historians detailed knowledge of Roman daily life.$q$, $q$The student wants to explain why the eruption is valuable to historians. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Excavations at Pompeii and Herculaneum have been taking place since the 1700s.","Ash from Mount Vesuvius buried the Roman cities of Pompeii and Herculaneum.","Mount Vesuvius erupted in 79 CE, burying the Roman cities of Pompeii and Herculaneum.","By preserving buildings and objects, Vesuvius's ash revealed details of Roman daily life."]$q$::jsonb, 3, $q$The goal is to explain why the eruption matters to historians. Only one choice connects the preserved remains to knowledge of Roman life.$q$, null),
  ($q$ei-733$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• A study tracked 500 commuters in two cities.
• City X has a large network of protected bike lanes; City Y has very few.
• In City X, 22 percent of commuters biked to work.
• In City Y, 4 percent of commuters biked to work.$q$, $q$The student wants to compare bike commuting rates in the two cities. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In City X, 22 percent of commuters biked to work, compared with 4 percent in City Y.","A study tracked 500 commuters in two cities with very different numbers of bike lanes.","City X has a large network of protected bike lanes, while City Y has very few lanes.","In City X, which has many protected bike lanes, 22 percent of commuters biked to work."]$q$::jsonb, 0, $q$A comparison of rates needs both cities' percentages. Only one choice gives both.$q$, null),
  ($q$ei-734$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Bees are important pollinators of crops. ______ many bats and birds pollinate flowering plants, especially in the tropics.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In other words,","As a result,","Likewise,","Instead,"]$q$::jsonb, 2, $q$Bats and birds play a role similar to that of bees. "Likewise" signals that similarity. The pollination by bats doesn't result from bees, and it isn't a restatement.$q$, null),
  ($q$ei-735$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$The scientist checked the results three times. ______ she asked a colleague to repeat the experiment.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Instead,","Then,","Nonetheless,","In contrast,"]$q$::jsonb, 1, $q$Asking a colleague comes after checking the results. "Then" signals that sequence.$q$, null),
  ($q$ei-736$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$For decades, historians assumed that medieval European peasants rarely traveled more than a few miles from home. Records from pilgrimage routes and trade fairs, ______ show that many ordinary people journeyed hundreds of miles during their lifetimes.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["however,","therefore,","in other words,","moreover,"]$q$::jsonb, 0, $q$The records contradict the historians' assumption, so a contrasting transition is needed. "Moreover" adds, "therefore" shows a result, and "in other words" restates.$q$, null),
  ($q$ei-737$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$The town's only bridge was damaged in the flood. ______ residents had to drive 40 minutes to reach the nearest grocery store.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In contrast,","For instance,","Likewise,","As a result,"]$q$::jsonb, 3, $q$The long drive is a consequence of the bridge being damaged. "As a result" signals that cause-and-effect relationship.$q$, null),
  ($q$ei-738$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• Venus is the second planet from the Sun.
• Its surface temperature is about 870°F.
• This makes it the hottest planet in the solar system.
• Mercury is closer to the Sun but is not as hot.$q$, $q$The student wants to explain which planet is the hottest in the solar system. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["At about 870°F, Venus is the hottest planet in the solar system.","Mercury is the planet closest to the Sun, but it is not as hot as Venus.","Venus and Mercury are the two planets that orbit closest to the Sun.","Venus is the second planet from the Sun, just beyond Mercury."]$q$::jsonb, 0, $q$Only the sentence that names Venus as the hottest planet and gives its temperature accomplishes the goal.$q$, null),
  ($q$ei-739$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Ruth Bader Ginsburg served on the U.S. Supreme Court from 1993 to 2020.
• Before becoming a justice, she argued six gender discrimination cases before the Court.
• She won five of those six cases.
• She co-founded the Women's Rights Project at the ACLU.$q$, $q$The student wants to emphasize Ginsburg's success as a lawyer before she joined the Court. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Before joining the Court, Ginsburg won five of the six cases she argued before it.","Before joining the Court, Ginsburg argued six gender discrimination cases.","Ruth Bader Ginsburg co-founded the Women's Rights Project at the ACLU.","Ruth Bader Ginsburg served as a Supreme Court justice from 1993 until 2020."]$q$::jsonb, 0, $q$Her success as a lawyer is shown by her record of five wins out of six cases. A sentence that mentions only that she argued the cases leaves out the success.$q$, null),
  ($q$ei-740$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Phillis Wheatley was born in West Africa around 1753.
• She was enslaved and brought to Boston as a child.
• In 1773, she published Poems on Various Subjects, Religious and Moral.
• She was the first African American woman to publish a book of poetry.$q$, $q$The student wants to emphasize the historical significance of Wheatley's 1773 book. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Wheatley's 1773 book made her the first African American woman to publish a book of poetry.","In 1773, Phillis Wheatley published Poems on Various Subjects, Religious and Moral.","Phillis Wheatley, who was enslaved in Boston, published a book of poems in 1773.","Phillis Wheatley was born in West Africa around 1753 and brought to Boston as a child."]$q$::jsonb, 0, $q$The book's significance is that it was the first by an African American woman poet. Only one choice states that.$q$, null),
  ($q$ei-741$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Squids and octopuses can change the color of their skin in a fraction of a second. ______ chameleons need several seconds or even minutes to complete a color change.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For example,","In addition,","As a result,","By comparison,"]$q$::jsonb, 3, $q$The chameleon's slower change is being compared with the cephalopods' speed. "By comparison" signals that comparison.$q$, null),
  ($q$ei-742$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• The Venus flytrap is native to a small region of North and South Carolina.
• It traps insects with hinged leaves that snap shut.
• The trap closes only if trigger hairs are touched twice within about 20 seconds.
• This prevents the plant from wasting energy on raindrops or debris.$q$, $q$The student wants to explain how the flytrap avoids closing unnecessarily. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Venus flytrap, native to the Carolinas, traps insects with hinged leaves that snap shut.","The Venus flytrap is native to a small region of North and South Carolina.","A flytrap closes only if touched twice in about 20 seconds, so it ignores raindrops and debris.","The Venus flytrap's hinged leaves have trigger hairs that cause them to snap shut."]$q$::jsonb, 2, $q$The goal is to explain how it avoids unnecessary closing. Only one choice describes the two-touch mechanism and its purpose.$q$, null),
  ($q$ei-743$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• Bamboo is a type of grass.
• Some species can grow up to 35 inches in a single day.
• Bamboo is used to build houses, furniture, and bridges.
• It is native to every continent except Europe and Antarctica.$q$, $q$The student wants to emphasize how quickly bamboo grows. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Bamboo is a type of grass.","Some species of bamboo can grow up to 35 inches in a single day.","Bamboo is used to build houses, furniture, and bridges.","Bamboo is native to every continent except Europe and Antarctica."]$q$::jsonb, 1, $q$Only the sentence giving the 35-inch-per-day figure addresses growth speed.$q$, null),
  ($q$ei-744$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$The novelist wrote her first three books in longhand on yellow legal pads. ______ she switched to a typewriter, claiming it helped her write faster.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For example,","In other words,","Similarly,","Later,"]$q$::jsonb, 3, $q$The switch to a typewriter came after the first three books. "Later" signals that shift in time.$q$, null),
  ($q$ei-745$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Owls hunt mostly at night. Hawks, ______ hunt mostly during the day.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["similarly,","for example,","as a result,","by contrast,"]$q$::jsonb, 3, $q$Hawks' daytime hunting is the opposite of owls' nighttime hunting. "By contrast" signals that difference.$q$, null),
  ($q$ei-746$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Many desert plants store water in thick stems. The saguaro cactus, ______ can hold hundreds of gallons of water after a heavy rain.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["meanwhile,","in contrast,","however,","for example,"]$q$::jsonb, 3, $q$The saguaro is a specific instance of a desert plant that stores water in its stem. "For example" introduces that illustration.$q$, null),
  ($q$ei-747$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• A survey asked 1,200 teenagers how they get their news.
• 48 percent said social media was their main source.
• 21 percent said television.
• Only 6 percent said print newspapers.$q$, $q$The student wants to emphasize how few teenagers rely mainly on print newspapers. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Nearly half of the teenagers surveyed said social media was their main source.","Of the teenagers surveyed, 21 percent got their news mainly from television.","Only 6 percent of the teenagers surveyed relied mainly on print newspapers.","A survey asked 1,200 teenagers how they usually get their news each day."]$q$::jsonb, 2, $q$Only the sentence with the 6 percent figure addresses print newspapers.$q$, null),
  ($q$ei-748$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Wind turbines convert the energy of moving air into electricity.
• Offshore turbines are built in bodies of water, usually the ocean.
• Winds over the ocean are generally stronger and steadier than winds over land.
• Offshore turbines are more expensive to build and maintain.$q$, $q$The student wants to present an advantage of offshore wind turbines. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Offshore wind turbines are more expensive to build and maintain than turbines on land.","Wind turbines, including offshore ones, convert the energy of moving air into electricity.","Offshore wind turbines are built in bodies of water, usually in the ocean.","Offshore turbines benefit from ocean winds, which are stronger and steadier than winds on land."]$q$::jsonb, 3, $q$Only the sentence about stronger, steadier winds presents an advantage; the cost is a disadvantage.$q$, null),
  ($q$ei-749$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Some economists argue that raising the minimum wage leads to job losses. ______ several studies of neighboring states with different wage laws have found little or no difference in employment.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","Likewise,","Specifically,","However,"]$q$::jsonb, 3, $q$The studies' findings challenge the economists' argument. "However" signals that contrast.$q$, null),
  ($q$ei-750$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Honeybees communicate the location of food through a "waggle dance." The angle of the dance shows the direction of the food relative to the sun. ______ the length of the dance indicates how far away the food is.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","As a result,","Instead,","Similarly,"]$q$::jsonb, 3, $q$The length of the dance is a second, parallel piece of information the dance conveys. "Similarly" signals that parallel; the length isn't caused by the angle.$q$, null),
  ($q$ei-751$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• Lake Baikal is in Siberia, Russia.
• It is the deepest lake in the world, at about 5,400 feet.
• It holds about 20 percent of the world's unfrozen fresh surface water.
• It is more than 25 million years old.$q$, $q$The student wants to emphasize how old Lake Baikal is. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Lake Baikal is in Siberia, Russia.","Lake Baikal is more than 25 million years old.","Lake Baikal holds about 20 percent of the world's unfrozen fresh surface water.","Lake Baikal is the deepest lake in the world."]$q$::jsonb, 1, $q$Only the sentence about its age of more than 25 million years addresses the goal.$q$, null),
  ($q$ei-752$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• Gabriel García Márquez was a Colombian writer.
• His most famous novel is One Hundred Years of Solitude.
• The novel was published in 1967.
• He won the Nobel Prize in Literature in 1982.$q$, $q$The student wants to identify García Márquez's most famous novel and when it was published. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Gabriel García Márquez was a Colombian writer who won the Nobel Prize in 1982.","One Hundred Years of Solitude is the most famous novel by García Márquez.","García Márquez's most famous novel, One Hundred Years of Solitude, appeared in 1967.","Colombian writer Gabriel García Márquez won the Nobel Prize in Literature in 1982."]$q$::jsonb, 2, $q$Only the sentence naming the novel and giving its publication year accomplishes both parts of the goal.$q$, null),
  ($q$ei-753$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• The axolotl is a salamander native to lakes near Mexico City.
• It can regrow lost limbs, parts of its heart, and even parts of its brain.
• Scientists study axolotls to learn how tissue regeneration works.
• Wild axolotls are critically endangered because of pollution and habitat loss.$q$, $q$The student wants to explain why scientists are interested in axolotls. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Pollution and habitat loss have made wild axolotls, found near Mexico City, critically endangered.","Scientists study axolotls, which can regrow limbs and organs, to learn how regeneration works.","Axolotls, which live in lakes near Mexico City, are studied by scientists around the world.","The axolotl, a salamander native to lakes near Mexico City, is now critically endangered."]$q$::jsonb, 1, $q$Only the sentence linking the axolotl's regenerative abilities to scientists' research explains their interest.$q$, null),
  ($q$ei-754$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Most metals expand when heated. ______ a steel bridge is longer on a hot summer day than on a cold winter night, which is why engineers include expansion joints in its design.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","In contrast,","Previously,","Nevertheless,"]$q$::jsonb, 0, $q$The bridge's change in length is a consequence of the general rule about metals. "Thus" signals that application.$q$, null),
  ($q$ei-755$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Some volcanoes erupt violently, sending ash miles into the sky. ______ Hawaii's Kilauea usually erupts gently, with lava flowing slowly down its slopes.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In addition,","As a result,","By contrast,","Similarly,"]$q$::jsonb, 2, $q$Kilauea's gentle eruptions differ from violent ones. "By contrast" signals that difference.$q$, null),
  ($q$ei-756$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Early telescopes produced blurry images because different colors of light focused at slightly different points. In the 1750s, optician John Dollond combined two kinds of glass in a single lens. ______ telescopes could produce much sharper images.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Despite this innovation,","With this innovation,","Unlike this innovation,","Before this innovation,"]$q$::jsonb, 1, $q$Dollond's lens led to sharper images. "With this innovation" signals that it made the improvement possible; the other choices imply the opposite or the wrong timing.$q$, null),
  ($q$ei-757$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$In the 1800s, many doctors did not wash their hands between patients. ______ infections spread quickly in hospitals, especially in maternity wards.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In contrast,","Likewise,","Nonetheless,","Consequently,"]$q$::jsonb, 3, $q$The spread of infections resulted from doctors not washing their hands. "Consequently" signals that result.$q$, null),
  ($q$ei-758$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$The recipe calls for fresh basil. ______ dried basil can be used if fresh basil isn't available.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Therefore,","In addition,","However,","Similarly,"]$q$::jsonb, 2, $q$The second sentence offers an exception to the first. "However" signals that contrast.$q$, null),
  ($q$ei-759$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Shirley Chisholm was elected to the U.S. House of Representatives in 1968.
• She was the first Black woman elected to Congress.
• In 1972, she ran for the Democratic presidential nomination.
• Her campaign slogan was "Unbought and Unbossed."$q$, $q$The student wants to emphasize that Chisholm broke barriers more than once. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Shirley Chisholm, elected to Congress in 1968, campaigned with the slogan \"Unbought and Unbossed.\"","Shirley Chisholm was elected to the House of Representatives in 1968, representing New York.","The first Black woman elected to Congress, Chisholm later sought the 1972 presidential nomination.","In 1972, Shirley Chisholm campaigned with the slogan \"Unbought and Unbossed.\""]$q$::jsonb, 2, $q$Breaking barriers more than once requires two firsts or milestones. Only one choice combines her election to Congress with her presidential run.$q$, null),
  ($q$ei-760$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• The ancient city of Petra is in present-day Jordan.
• It was built by the Nabataeans, who were skilled traders.
• Many of its buildings were carved directly into rose-colored sandstone cliffs.
• The Nabataeans built an advanced system of channels and cisterns to collect rainwater.$q$, $q$The student wants to highlight the Nabataeans' engineering skill. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Petra's rose-colored sandstone cliffs give the city in present-day Jordan its color.","The Nabataeans built channels and cisterns to collect rainwater for desert Petra.","The Nabataeans, skilled traders, carved many of Petra's buildings into sandstone cliffs.","Petra, in present-day Jordan, was built by the Nabataeans, who were skilled traders."]$q$::jsonb, 1, $q$Engineering skill is best shown by the water system. The other choices highlight trading, location, or the color of the rock.$q$, null),
  ($q$ei-761$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$Before the invention of refrigeration, people preserved food in many ways. Fish was often salted or smoked, ______ fruit was dried in the sun or cooked into jam.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["unless","so","because","while"]$q$::jsonb, 3, $q$The two clauses describe parallel preservation methods for different foods. "While" links these comparable facts; "because" and "so" imply cause, and "unless" implies a condition.$q$, null),
  ($q$ei-762$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• The Sahara is the largest hot desert in the world.
• It covers about 3.6 million square miles.
• That is roughly the size of the United States.
• Only about 25 percent of the Sahara is covered in sand dunes.$q$, $q$The student wants to correct a common misconception about the Sahara. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Sahara is the largest hot desert in the world, covering about 3.6 million square miles.","The Sahara covers about 3.6 million square miles, roughly the size of the United States.","The Sahara, the world's largest hot desert, is roughly the size of the United States.","Despite its image as endless dunes, only about 25 percent of the Sahara is sand."]$q$::jsonb, 3, $q$Only the sentence about the small share of sand dunes addresses a misconception.$q$, null),
  ($q$ei-763$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$It rained all morning. ______ the soccer game was moved to the afternoon.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For example,","Therefore,","However,","Similarly,"]$q$::jsonb, 1, $q$Moving the game is a consequence of the rain. "Therefore" signals that result.$q$, null),
  ($q$ei-764$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• The violinist practiced the concerto for six hours a day.
• She had only three weeks to learn it.
• Her teacher had told her the piece usually takes months to master.
• She performed it without a single mistake.$q$, $q$The student wants to emphasize how quickly the violinist mastered the concerto. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The violinist mastered in three weeks a concerto that usually takes months.","The violinist performed the difficult concerto without a single mistake.","The violinist's teacher said the concerto usually takes months to master.","The violinist practiced the concerto for six hours a day for three weeks."]$q$::jsonb, 0, $q$Contrasting the usual months with her three weeks emphasizes her speed. The other choices give only part of that picture.$q$, null),
  ($q$ei-765$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• The blue whale is the largest animal known to have ever lived.
• It can grow to about 100 feet long.
• It feeds mainly on tiny shrimp-like animals called krill.
• It can eat about 4 tons of krill a day.$q$, $q$The student wants to contrast the blue whale's size with the size of its food. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The blue whale is the largest animal known to have ever lived on Earth.","The blue whale can eat about 4 tons of krill, its main food, every day.","The blue whale grows to about 100 feet long but feeds mainly on tiny krill.","Krill, the blue whale's main food, are shrimp-like animals found in the sea."]$q$::jsonb, 2, $q$The contrast requires both the whale's huge size and the tiny size of its food. Only one sentence includes both.$q$, null),
  ($q$ei-766$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Sea otters often float on their backs while they eat. ______ they use their bellies as tables, placing shellfish on their chests and cracking them open with rocks.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Instead,","In fact,","Nevertheless,","However,"]$q$::jsonb, 1, $q$The second sentence adds a striking detail that builds on the first. "In fact" signals that elaboration. "However," "Instead," and "Nevertheless" signal contrast, which doesn't fit.$q$, null),
  ($q$ei-767$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Glaciers in the Alps have been shrinking for more than a century.
• Since 1850, they have lost about 60 percent of their volume.
• The melting has accelerated since the 1980s.
• Some smaller glaciers have disappeared entirely.$q$, $q$The student wants to emphasize that the rate of glacier loss is increasing. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Some smaller glaciers in the Alps have already disappeared entirely.","Alpine glaciers have been shrinking since the 1800s, and the melting has sped up since the 1980s.","Since 1850, Alpine glaciers have lost about 60 percent of their volume.","Glaciers in the Alps have been shrinking for more than a century."]$q$::jsonb, 1, $q$An increasing rate means acceleration. Only the choice noting that melting has sped up since the 1980s addresses the rate.$q$, null),
  ($q$ei-768$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$The architect Zaha Hadid was known for buildings with dramatic, flowing curves. Her design for the London Aquatics Centre, ______ features a roof shaped like a wave that seems to ripple over the pool below.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["nonetheless,","instead,","for instance,","however,"]$q$::jsonb, 2, $q$The Aquatics Centre is a specific example of Hadid's curving designs. "For instance" introduces it.$q$, null),
  ($q$ei-769$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 2, $q$The new law requires all restaurants to post calorie counts on their menus. Supporters say it will help diners make healthier choices. ______ critics argue that it will raise costs for small businesses.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Likewise,","For example,","On the other hand,","Therefore,"]$q$::jsonb, 2, $q$The critics' view contrasts with the supporters' view. "On the other hand" signals that opposing perspective.$q$, null),
  ($q$ei-770$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• Chess originated in India around the 6th century CE.
• It spread to Persia and then to Europe.
• The modern rules were set in the 15th century.
• Today, millions of people play chess online.$q$, $q$The student wants to describe how chess spread from its place of origin. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Chess originated in India around the 6th century CE.","Chess began in India and spread to Persia and then to Europe.","The modern rules of chess were set in Europe in the 15th century.","Today, millions of people around the world play chess online."]$q$::jsonb, 1, $q$The goal is to describe how chess spread. Only the sentence tracing its path from India to Persia to Europe does this.$q$, null),
  ($q$ei-771$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• The Andes is the longest continental mountain range in the world.
• It runs about 4,300 miles along the western coast of South America.
• It passes through seven countries.
• Its highest peak is Aconcagua, at 22,838 feet.$q$, $q$The student wants to identify the highest peak in the Andes. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Andes is the longest continental mountain range in the world.","Aconcagua, at 22,838 feet, is the highest peak in the Andes.","The Andes passes through seven countries.","The Andes runs about 4,300 miles along South America's western coast."]$q$::jsonb, 1, $q$Only the sentence naming Aconcagua and its height identifies the highest peak.$q$, null),
  ($q$ei-772$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• Tardigrades are tiny animals about 0.5 millimeters long.
• They are sometimes called "water bears."
• They can survive temperatures from near absolute zero to above 300°F.
• They have been found on every continent.$q$, $q$The student wants to emphasize how hardy tardigrades are. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Tardigrades are tiny animals, only about 0.5 millimeters long, found worldwide.","Tardigrades, sometimes called \"water bears,\" are found on every continent.","Known by the nickname \"water bears,\" tardigrades measure about half a millimeter.","Tardigrades can survive temperatures ranging from near absolute zero to above 300°F."]$q$::jsonb, 3, $q$Hardiness means the ability to survive harsh conditions. Only the sentence about the extreme temperature range shows that.$q$, null),
  ($q$ei-773$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$The club planned to meet in the library. ______ the library was closed for repairs, so the members met in the cafeteria.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["However,","For instance,","Therefore,","Likewise,"]$q$::jsonb, 0, $q$The library's closure contrasts with the plan. "However" signals that contrast.$q$, null),
  ($q$ei-774$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Many species of cicada spend most of their lives underground as nymphs.
• Periodical cicadas emerge every 13 or 17 years.
• Both 13 and 17 are prime numbers.
• Some scientists think prime-numbered cycles help cicadas avoid predators with shorter, regular cycles.$q$, $q$The student wants to present a hypothesis about cicadas' life cycles. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Periodical cicadas spend 13 or 17 years underground before they emerge.","Periodical cicadas emerge every 13 or 17 years, both of which are prime numbers.","Some scientists think cicadas' prime-numbered cycles help them avoid predators.","Many cicadas spend most of their lives underground as nymphs before emerging."]$q$::jsonb, 2, $q$A hypothesis is a proposed explanation. Only one choice states what some scientists think explains the cycles.$q$, null),
  ($q$ei-775$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Researchers studied two groups of tomato plants.
• Group A was watered with rainwater; Group B was watered with tap water.
• After eight weeks, Group A plants were on average 15 percent taller.
• The researchers concluded that rainwater may promote faster growth in tomatoes.$q$, $q$The student wants to present the study's conclusion. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Researchers watered one group of tomato plants with rainwater and one with tap water.","After eight weeks, the plants watered with rainwater were 15 percent taller on average.","Since rainwater-fed tomatoes grew taller, researchers concluded rainwater may speed growth.","Researchers compared two groups of tomato plants, labeled Group A and Group B, for eight weeks."]$q$::jsonb, 2, $q$Only the sentence stating what the researchers concluded, along with the result supporting it, presents the conclusion.$q$, null),
  ($q$ei-776$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Scientists placed motion-activated cameras in a national park.
• Over one year, the cameras recorded 34 species of mammals.
• Seven of the species had never before been documented in the park.
• One of the new species was a rare spotted cat.$q$, $q$The student wants to emphasize the study's new findings. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Over one year, the park's motion-activated cameras recorded 34 species of mammals.","The study used motion-activated cameras to record mammals in a national park.","Of the 34 mammal species recorded, seven had never been documented in the park.","Scientists placed motion-activated cameras throughout a national park for one year."]$q$::jsonb, 2, $q$"New findings" refers to species not documented before. Only one choice mentions the seven newly documented species.$q$, null),
  ($q$ei-777$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• Ada Lovelace was an English mathematician born in 1815.
• She worked with Charles Babbage on his design for a mechanical computer.
• She wrote what is considered the first computer program.
• A programming language, Ada, is named after her.$q$, $q$The student wants to emphasize Ada Lovelace's contribution to computing. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Ada Lovelace worked with Charles Babbage on his mechanical computer.","A programming language called Ada is named after Ada Lovelace.","Ada Lovelace wrote what is considered the first computer program.","Ada Lovelace was an English mathematician who was born in 1815."]$q$::jsonb, 2, $q$Writing the first computer program is her contribution; the other sentences give background or a later tribute.$q$, null),
  ($q$ei-778$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$Leo forgot his umbrella at home. ______ he got soaked walking to school.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["On the other hand,","In addition,","As a result,","For example,"]$q$::jsonb, 2, $q$Getting soaked follows from forgetting the umbrella. "As a result" signals that consequence.$q$, null),
  ($q$ei-779$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$The bakery ran out of flour on Tuesday morning. ______ it could not make any bread until a new shipment arrived that afternoon.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","Consequently,","In contrast,","For instance,"]$q$::jsonb, 1, $q$Being unable to bake follows from running out of flour. "Consequently" signals that result.$q$, null),
  ($q$ei-780$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 1, $q$The museum was crowded on Saturday. ______ the line to see the dinosaur exhibit stretched out the front door.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Indeed,","Otherwise,","Instead,","Still,"]$q$::jsonb, 0, $q$The long line reinforces the claim that the museum was crowded. "Indeed" signals that emphasis.$q$, null),
  ($q$ei-781$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 2, $q$While researching a topic, a student has taken the following notes:
• Two species of bird, the Galápagos finch and the Hawaiian honeycreeper, have been studied extensively.
• Both groups descended from a single ancestral species that arrived on the islands.
• Over time, each group evolved many species with differently shaped beaks.
• The beak shapes match the foods available on different islands.$q$, $q$The student wants to emphasize a similarity between the two bird groups. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Galápagos finch and the Hawaiian honeycreeper have both been studied extensively.","Hawaiian honeycreepers evolved beaks shaped to match the foods on different islands.","The Galápagos finch and the Hawaiian honeycreeper live on different island chains.","Both bird groups descended from one ancestor and evolved beaks suited to different foods."]$q$::jsonb, 3, $q$The goal is to show what the groups share. Only one choice describes their common pattern of descent and evolution; noting that they live on different island chains points out a difference instead.$q$, null),
  ($q$ei-782$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 1, $q$While researching a topic, a student has taken the following notes:
• The Eiffel Tower was completed in 1889.
• It was built for the World's Fair in Paris.
• Many artists at first criticized its design.
• Today it is one of the most visited monuments in the world.$q$, $q$The student wants to contrast early reactions to the Eiffel Tower with its later popularity. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Eiffel Tower, completed in 1889, is one of the most visited monuments in the world.","The Eiffel Tower was completed in 1889 for the World's Fair held in Paris that year.","When it was built for the 1889 World's Fair, many artists criticized the tower's design.","Once criticized by many artists, the Eiffel Tower is now among the most visited monuments."]$q$::jsonb, 3, $q$The goal requires both the early criticism and the later popularity. Only one sentence includes both.$q$, null),
  ($q$ei-h1$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Bioluminescence is the production of light by living organisms.<br>• Fireflies use bioluminescence to attract mates.<br>• The anglerfish uses a glowing lure to attract prey in the deep sea.<br>• The Hawaiian bobtail squid uses light from symbiotic bacteria to match moonlight from above, hiding its shadow from predators below.<br>• All three organisms produce light through a chemical reaction involving a molecule called luciferin.$q$, $q$The student wants to emphasize a similarity in how the three organisms produce light while noting a difference in how they use it. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Fireflies use bioluminescence to attract mates, anglerfish use a glowing lure to attract prey, and Hawaiian bobtail squid use light from bacteria to hide their shadows from predators below.","Fireflies, anglerfish, and Hawaiian bobtail squid all produce light through a chemical reaction involving luciferin, a process known as bioluminescence that occurs in many living organisms.","Like the anglerfish, which uses a glowing lure in the deep sea, the Hawaiian bobtail squid relies on light from symbiotic bacteria, which matches the moonlight shining down from above.","Although fireflies, anglerfish, and bobtail squid all produce light through a reaction involving luciferin, they use it for different purposes: attracting mates, luring prey, and hiding from predators."]$q$::jsonb, 3, $q$The goal requires both a similarity (the shared chemical mechanism) and a difference (the various uses). Only the correct answer states both. The choice about luciferin and the choice comparing the squid with the anglerfish state only similarities, and the choice listing what each organism uses light for states only differences.$q$, null),
  ($q$ei-h2$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• In 2018, archaeologists reported findings from a site in the Olorgesailie Basin in southern Kenya.<br>• They found more than 500 stone tools.<br>• The tools were dated to about 320,000 years ago.<br>• Earlier tools at the site were large, heavy hand axes.<br>• The newer tools were smaller and more precisely shaped, and some were made from obsidian transported from more than 90 kilometers away.$q$, $q$The student wants to describe how the newer tools differed from those made earlier at the site. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In 2018, archaeologists reported finding more than 500 stone tools, dated to about 320,000 years ago, at a site in the Olorgesailie Basin in southern Kenya.","Some stone tools found at a site in southern Kenya were made from obsidian that had been transported to the site from more than 90 kilometers away.","The site's 320,000-year-old tools were smaller and more precisely shaped than its earlier hand axes, and some were made of obsidian from over 90 kilometers away.","Before about 320,000 years ago, people at a site in the Olorgesailie Basin made large, heavy hand axes, and more than 500 stone tools have been found there."]$q$::jsonb, 2, $q$The goal is to describe how the newer tools differed from the older ones. Only the correct answer contrasts the newer tools (smaller, precisely shaped, made of distant obsidian) with the earlier hand axes. The other choices describe the excavation or only one set of tools.$q$, null),
  ($q$ei-h3$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Octavia Butler (1947–2006) was an American science fiction author.<br>• Her novel Kindred (1979) follows a Black woman from 1970s California who is repeatedly transported to a Maryland plantation in the early 1800s.<br>• Butler described Kindred as "a kind of grim fantasy" rather than science fiction, since it offers no scientific explanation for the time travel.<br>• Kindred has sold more than half a million copies and is widely taught in high schools and colleges.$q$, $q$The student wants to introduce Kindred to an audience unfamiliar with Octavia Butler and emphasize the novel's lasting popularity. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Octavia Butler, an American author who lived from 1947 to 2006, described her novel Kindred as \"a kind of grim fantasy\" because it gives no scientific explanation for time travel.","Octavia Butler's 1979 novel Kindred, which follows a modern Black woman transported to an antebellum plantation, has sold more than half a million copies and is widely taught in schools.","Kindred, a novel about a Black woman from 1970s California who is repeatedly transported to a Maryland plantation, was written by the science fiction author Octavia Butler.","Widely taught in high schools and colleges, Kindred has sold more than half a million copies since it was first published in 1979."]$q$::jsonb, 1, $q$The goal is to introduce the novel to an unfamiliar audience and indicate its popularity. The correct answer gives the author, title, date, and premise, and mentions its sales and use in schools. The others omit either the premise or the evidence of popularity.$q$, null),
  ($q$ei-h4$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers studied two groups of honeybees.<br>• Group A was exposed to a common pesticide at levels typical of farm fields.<br>• Group B was not exposed.<br>• After four weeks, bees in Group A were 30% less likely to return to the hive after foraging.<br>• The researchers concluded that the pesticide impairs bees' navigation.$q$, $q$The student wants to present the study's conclusion and the evidence that supports it. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Bees exposed to field levels of the pesticide were 30% less likely to return to the hive, leading researchers to conclude that it impairs navigation.","Researchers exposed one group of honeybees to a common pesticide at levels typical of farm fields for four weeks and compared it with a second group that was not exposed.","After four weeks, honeybees exposed to a common pesticide were 30% less likely than unexposed bees to return to the hive after foraging.","Researchers who studied two groups of honeybees concluded that a common pesticide, used at levels typical of farm fields, impairs bees' ability to navigate."]$q$::jsonb, 0, $q$The goal is to present the study's conclusion along with the evidence for it. Only the correct answer states both the finding (30% less likely to return) and the conclusion (impaired navigation). The others describe the method without the result or conclusion.$q$, null),
  ($q$ei-h5$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Svalbard Global Seed Vault is located on an island in the Arctic Ocean, about 1,300 kilometers from the North Pole.<br>• It stores duplicate samples of seeds from gene banks around the world.<br>• The vault is built 120 meters inside a mountain.<br>• Permafrost keeps the seeds frozen even if the cooling system fails.<br>• In 2015, researchers withdrew seeds to replace collections lost in a gene bank damaged during the war in Syria.$q$, $q$The student wants to provide an example of the seed vault serving its intended purpose. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Svalbard Global Seed Vault, which stores duplicate seed samples from gene banks around the world, is built 120 meters inside a mountain on an island in the Arctic Ocean.","Located about 1,300 kilometers from the North Pole, the Svalbard Global Seed Vault uses permafrost to keep seeds frozen even if its cooling system fails.","In 2015, a gene bank in Syria was damaged during the war there, and its collections were lost, prompting concern about the world's seed supply.","In 2015, researchers used duplicate seeds stored at the Svalbard Global Seed Vault to replace collections lost when a gene bank in Syria was damaged during the war there."]$q$::jsonb, 3, $q$The goal is to give an example of the vault fulfilling its purpose. Only the correct answer describes a specific instance (2015, Syria) in which stored seeds replaced lost collections. The others describe the vault's location or design.$q$, null),
  ($q$ei-h6$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Mangrove forests grow along tropical coastlines.<br>• Their dense, tangled roots slow incoming waves.<br>• A 2020 study estimated that mangroves prevent more than $65 billion in flood damage worldwide each year.<br>• Mangroves store up to four times as much carbon per hectare as most tropical rainforests.<br>• About 35% of the world's mangroves have been lost since 1980, mainly to shrimp farms and coastal development.$q$, $q$The student wants to emphasize the contrast between the value of mangrove forests and the rate at which they are disappearing. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Mangroves, whose dense roots slow incoming waves, prevent more than $65 billion in flood damage worldwide each year and store up to four times as much carbon per hectare as most rainforests.","About 35% of the world's mangroves, which grow along tropical coastlines, have been lost since 1980, mainly to shrimp farms and coastal development.","Mangroves provide valuable benefits—preventing more than $65 billion in flood damage each year and storing large amounts of carbon—yet about 35% of them have been lost since 1980.","Mangrove forests grow along tropical coastlines, where their dense, tangled roots slow incoming waves and help store large amounts of carbon."]$q$::jsonb, 2, $q$The goal calls for highlighting the contrast between mangroves' value and their loss. Only the correct answer includes both the benefits and the decline. The others give only benefits or only the loss.$q$, null),
  ($q$ei-h7$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Composer Hildegard of Bingen lived in Germany from 1098 to 1179.<br>• She was the abbess of a Benedictine convent.<br>• She wrote more than seventy liturgical songs.<br>• Her musical play Ordo Virtutum is one of the earliest known morality plays.<br>• Unlike most composers of her time, she is known by name; most medieval church music is anonymous.$q$, $q$The student wants to emphasize how Hildegard of Bingen differed from most composers of her era. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Hildegard of Bingen, who lived in Germany from 1098 to 1179, was the abbess of a Benedictine convent and wrote more than seventy liturgical songs.","Unlike the composers of most medieval church music, which is anonymous, Hildegard of Bingen is known by name.","Hildegard of Bingen's musical play Ordo Virtutum, written in twelfth-century Germany, is one of the earliest known morality plays.","Like many church musicians of her era, Hildegard of Bingen, a Benedictine abbess, composed liturgical songs—more than seventy in all."]$q$::jsonb, 1, $q$The goal is to emphasize what made Hildegard unusual among medieval composers. Only the correct answer explicitly contrasts her with typical, anonymous composers of the period.$q$, null),
  ($q$ei-h8$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Tardigrades are microscopic animals about 0.5 millimeters long.<br>• They can survive temperatures from −272°C to 150°C.<br>• In 2007, tardigrades were exposed to the vacuum of space for ten days aboard a satellite.<br>• Many survived and later reproduced normally.<br>• They survive extreme conditions by entering a dehydrated state called a tun.$q$, $q$The student wants to explain how tardigrades survive extreme conditions and provide a striking example of their resilience. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["By entering a dehydrated state called a tun, tardigrades can survive extremes—many even survived ten days in the vacuum of space.","Tardigrades, microscopic animals about 0.5 millimeters long, can survive temperatures as low as −272°C and as high as 150°C.","In 2007, tardigrades were exposed to the vacuum of space for ten days aboard a satellite, and many of them later reproduced normally.","Tardigrades, which are only about 0.5 millimeters long, survive extreme conditions by entering a dehydrated state called a tun."]$q$::jsonb, 0, $q$The goal requires both the mechanism (the tun state) and a dramatic illustration of survival. Only the correct answer explains how they survive and gives the space experiment as evidence.$q$, null),
  ($q$ei-h9$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The city of Medellín, Colombia, built a system of outdoor escalators in 2011.<br>• The escalators connect a hillside neighborhood, Comuna 13, to the city center.<br>• Before the escalators, residents had to climb the equivalent of a 28-story building to reach their homes.<br>• The trip now takes about six minutes.<br>• The escalators have become a tourist attraction.$q$, $q$The student wants to emphasize the escalators' impact on the daily lives of Comuna 13's residents. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Built in 2011, Medellín's outdoor escalators connect the hillside neighborhood of Comuna 13 to the city center and have since become a tourist attraction.","Before 2011, residents of Comuna 13, a hillside neighborhood in Medellín, had to climb the equivalent of a 28-story building to reach their homes.","Medellín's outdoor escalators, which connect Comuna 13 to the city center, have become a popular tourist attraction since they were built in 2011.","Medellín's outdoor escalators, built in 2011, cut what was once a climb equivalent to 28 stories into a six-minute ride for residents of Comuna 13."]$q$::jsonb, 3, $q$The goal is to emphasize the escalators' practical benefit to residents. Only the correct answer compares the old climb with the new six-minute ride. The others mention the escalators' existence, location, or tourist appeal.$q$, null),
  ($q$ei-h10$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researcher Mei Tanaka studied how children learn new words.<br>• She showed three-year-olds an unfamiliar object and named it once.<br>• A week later, 70% of the children correctly identified the object by name.<br>• When the object was named while the children were actively playing with it, 90% identified it correctly.<br>• Tanaka concluded that physical interaction strengthens word learning.$q$, $q$The student wants to compare the results of the two conditions in Tanaka's study. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Mei Tanaka showed three-year-olds an unfamiliar object and named it once, and a week later 70% of the children correctly identified the object by name.","Based on her study of how three-year-olds learn new words, Mei Tanaka concluded that physical interaction strengthens word learning.","Tanaka found that three-year-olds were more likely to remember an object's name a week later if they heard it while playing with the object (90%) than otherwise (70%).","When an object was named while children were actively playing with it, 90% of the three-year-olds in Tanaka's study identified it correctly a week later."]$q$::jsonb, 2, $q$The goal is to compare the results of the two conditions. Only the correct answer presents both percentages and identifies what distinguished the conditions.$q$, null),
  ($q$ei-h11$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Great Wall of China is not a single wall.<br>• It is a series of fortifications built over roughly two thousand years.<br>• The best-preserved sections were built during the Ming dynasty (1368–1644).<br>• A 2012 survey measured the total length of all sections at about 21,000 kilometers.<br>• Many earlier sections were made of rammed earth and have largely eroded.$q$, $q$The student wants to correct a common misconception about the Great Wall of China. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The best-preserved sections of the Great Wall of China were built during the Ming dynasty, while many earlier sections, made of rammed earth, have largely eroded.","Rather than a single wall, the Great Wall of China is a series of fortifications built over some two thousand years, with a total length of about 21,000 kilometers.","A 2012 survey measured the total length of all sections of the Great Wall of China at about 21,000 kilometers, though many have eroded.","Built during the Ming dynasty (1368–1644), the best-preserved sections of the Great Wall of China are among the most visited."]$q$::jsonb, 1, $q$The goal is to correct a misconception about the wall. Only the correct answer directly states that it is not a single wall and gives supporting details.$q$, null),
  ($q$ei-h12$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Mariana Trench is the deepest known part of Earth's oceans.<br>• Its deepest point, the Challenger Deep, is about 10,935 meters below sea level.<br>• Mount Everest's peak is about 8,849 meters above sea level.<br>• In 2019, explorer Victor Vescovo reached the bottom of the Challenger Deep in a submersible.<br>• He found a plastic bag on the sea floor.$q$, $q$The student wants to use a comparison to help readers grasp the depth of the Challenger Deep. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Challenger Deep, at about 10,935 meters below sea level, is deeper than Mount Everest is tall: Everest's peak is about 8,849 meters above sea level.","The Mariana Trench, the deepest known part of Earth's oceans, has a deepest point called the Challenger Deep, which Victor Vescovo reached in 2019.","In 2019, explorer Victor Vescovo reached the bottom of the Challenger Deep in a submersible and found a plastic bag on the sea floor.","Mount Everest's peak is about 8,849 meters above sea level, while the Mariana Trench is the deepest known part of Earth's oceans."]$q$::jsonb, 0, $q$The goal is to convey the depth of the trench by comparison with Everest. Only the correct answer gives both measurements and states the comparison. The choice giving Everest's height and calling the trench the deepest part of the oceans mentions both but gives no depth for the trench, so no comparison can be made.$q$, null),
  ($q$ei-h13$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Artist Yayoi Kusama was born in Japan in 1929.<br>• She moved to New York in 1958.<br>• Her "Infinity Mirror Rooms" use mirrors and lights to create the illusion of endless space.<br>• In 2017, an exhibition of her Infinity Mirror Rooms at a Washington, D.C., museum drew more than 160,000 visitors.<br>• Visitors were limited to about thirty seconds inside each room.$q$, $q$The student wants to describe Kusama's Infinity Mirror Rooms and indicate their popularity. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Yayoi Kusama, who was born in Japan in 1929 and moved to New York in 1958, is known for her Infinity Mirror Rooms.","Visitors to a 2017 exhibition of Yayoi Kusama's Infinity Mirror Rooms in Washington, D.C., were limited to about thirty seconds in each room.","More than 160,000 visitors attended a 2017 exhibition in Washington, D.C., featuring the work of Yayoi Kusama, who was born in Japan in 1929.","Kusama's Infinity Mirror Rooms, which create an illusion of endless space, drew over 160,000 visitors to a 2017 exhibition."]$q$::jsonb, 3, $q$The goal is to describe the rooms and show their popularity. Only the correct answer describes what the rooms are and gives the attendance figure.$q$, null),
  ($q$ei-h14$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Sea turtles return to the beaches where they hatched to lay their eggs.<br>• Scientists long wondered how they find these beaches after years at sea.<br>• A study by Kenneth Lohmann suggested that turtles detect the unique magnetic signature of their home beach.<br>• Each stretch of coastline has a slightly different magnetic field.<br>• Turtles may imprint on this signature as hatchlings.$q$, $q$The student wants to explain a possible answer to the question of how sea turtles find their home beaches. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Scientists long wondered how sea turtles, which return to the beaches where they hatched to lay their eggs, are able to find those beaches after years at sea.","Kenneth Lohmann studied sea turtles, which return to the beaches where they hatched in order to lay their eggs.","Sea turtles may find home by sensing magnetic signatures: each coastline has a slightly different field, which hatchlings may learn.","Each stretch of coastline has a slightly different magnetic field, and sea turtles return to the beaches where they hatched to lay their eggs."]$q$::jsonb, 2, $q$The goal is to explain a possible answer to the question of how turtles navigate. Only the correct answer explains the magnetic-signature hypothesis.$q$, null),
  ($q$ei-h15$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Voynich manuscript is a handwritten book dated to the early fifteenth century.<br>• It is written in an unknown script.<br>• It contains illustrations of plants that do not match any known species.<br>• Linguists, cryptographers, and computer scientists have tried to decode it.<br>• No proposed decipherment has been widely accepted.$q$, $q$The student wants to emphasize that the Voynich manuscript has resisted decoding despite considerable effort. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Voynich manuscript, a handwritten book from the early fifteenth century, contains illustrations of plants that do not match any known species.","Despite efforts by linguists, cryptographers, and computer scientists, no proposed decipherment of the fifteenth-century Voynich manuscript has been widely accepted.","Linguists, cryptographers, and computer scientists have studied the Voynich manuscript, a book written in an unknown script in the early fifteenth century.","Written in an unknown script, the fifteenth-century Voynich manuscript is illustrated with drawings of plants unlike any known species."]$q$::jsonb, 1, $q$The goal is to emphasize that the manuscript remains a mystery despite expert attempts to decode it. Only the correct answer mentions the attempts and their lack of success.$q$, null),
  ($q$ei-h16$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Two cities installed "cool roofs"—roofs painted white to reflect sunlight.<br>• In City A, cool roofs were installed on 10% of buildings.<br>• In City B, they were installed on 40% of buildings.<br>• Average summer temperatures dropped by 0.2°C in City A.<br>• Average summer temperatures dropped by 0.9°C in City B.$q$, $q$The student wants to suggest that the extent of cool-roof installation affected the amount of cooling. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Summer temperatures fell more in City B, where cool roofs covered 40% of buildings (0.9°C), than in City A, where they covered 10% (0.2°C).","Two cities installed cool roofs—roofs painted white to reflect sunlight—and average summer temperatures dropped in both City A and City B.","In City B, cool roofs were installed on 40% of buildings, and average summer temperatures there dropped by 0.9°C.","City A installed cool roofs on 10% of its buildings, while City B installed them on 40% of its buildings."]$q$::jsonb, 0, $q$The goal is to show that more cool roofs produced greater cooling. Only the correct answer pairs each city's coverage with its temperature drop, revealing the relationship.$q$, null),
  ($q$ei-h17$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Japanese art of kintsugi repairs broken pottery with lacquer mixed with powdered gold.<br>• The cracks are highlighted rather than hidden.<br>• The practice is associated with the philosophy of wabi-sabi, which finds beauty in imperfection.<br>• Kintsugi may have begun in the fifteenth century.<br>• Repaired pieces are sometimes valued more highly than undamaged ones.$q$, $q$The student wants to explain how kintsugi reflects a particular philosophy. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Kintsugi, a Japanese art that may have begun in the fifteenth century, repairs broken pottery using lacquer mixed with powdered gold.","Pottery repaired with kintsugi, which uses lacquer mixed with powdered gold, is sometimes valued more highly than pottery that was never broken.","The philosophy of wabi-sabi, which finds beauty in imperfection, is associated with many Japanese arts, including kintsugi, which may date to the fifteenth century.","Kintsugi, the Japanese art of repairing pottery with gold-flecked lacquer, highlights cracks rather than hiding them, reflecting a philosophy that finds beauty in imperfection."]$q$::jsonb, 3, $q$The goal is to explain the connection between the technique and its underlying philosophy. Only the correct answer describes the technique and links it to wabi-sabi's appreciation of imperfection.$q$, null),
  ($q$ei-h18$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers tested a new method of teaching fractions.<br>• Students in the experimental group used number lines.<br>• Students in the control group used pie diagrams.<br>• On a final test, the number-line group scored 15 points higher on average.<br>• The difference was largest on problems involving fractions greater than one.$q$, $q$The student wants to present the results of the study. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Researchers tested a new method of teaching fractions in which students in the experimental group used number lines while students in the control group used pie diagrams.","On a final test about fractions, students who used number lines answered problems involving fractions greater than one.","Students who learned fractions with number lines outperformed those who used pie diagrams by 15 points on average, with the largest advantage on fractions greater than one.","Students in a control group learned fractions with pie diagrams, a common method, while an experimental group tried a newer approach using number lines."]$q$::jsonb, 2, $q$The goal is to present the study's results. Only the correct answer reports the outcome, including the average difference and where it was largest.$q$, null),
  ($q$ei-h19$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Ada Lovelace (1815–1852) was an English mathematician.<br>• She worked with Charles Babbage on his proposed Analytical Engine, a mechanical computer that was never built.<br>• In 1843, she published notes describing how the machine could calculate a sequence of numbers called Bernoulli numbers.<br>• These notes are often considered the first computer program.<br>• She also suggested the machine might one day compose music.$q$, $q$The student wants to explain why Ada Lovelace is often regarded as a pioneer of computer programming. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Ada Lovelace, an English mathematician who lived from 1815 to 1852, worked with Charles Babbage on his proposed Analytical Engine.","Ada Lovelace's 1843 notes on how Babbage's Analytical Engine could calculate Bernoulli numbers are often considered the first computer program.","Ada Lovelace suggested that Charles Babbage's Analytical Engine, a mechanical computer that was never built, might one day compose music.","In 1843, Ada Lovelace published notes about Charles Babbage's Analytical Engine, a proposed mechanical computer that was never built."]$q$::jsonb, 1, $q$The goal is to explain why Lovelace is considered a pioneer of computing. Only the correct answer describes her notes and their significance as the first program.$q$, null),
  ($q$ei-h20$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers studied the diets of urban and rural red foxes in England.<br>• Urban foxes got about 35% of their food from human sources, such as garbage and pet food.<br>• Rural foxes got about 6% of their food from human sources.<br>• Urban foxes had shorter, wider snouts than rural foxes.<br>• The researchers suggested that softer human food may reduce the need for long snouts used to catch prey.$q$, $q$The student wants to present the researchers' explanation for a physical difference between urban and rural foxes. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Urban foxes, which ate more human food (35% vs. 6%), had shorter, wider snouts—possibly because soft human food reduces the need for long snouts.","Researchers studying red foxes in England found that urban foxes got about 35% of their food from human sources, compared with about 6% for rural foxes.","Urban red foxes in England had shorter, wider snouts than rural foxes and got about 35% of their food from garbage, pet food, and other human sources.","Researchers studying red foxes in England compared the diets of urban and rural foxes and also measured the length and width of their snouts."]$q$::jsonb, 0, $q$The goal requires linking diet differences to physical differences. Only the correct answer presents both the dietary difference and the snout difference, along with the proposed explanation connecting them.$q$, null),
  ($q$ei-h21$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The ancient city of Pompeii was buried by an eruption of Mount Vesuvius in 79 CE.<br>• Volcanic ash preserved buildings, frescoes, and even loaves of bread.<br>• Excavations began in 1748.<br>• About one-third of the city remains unexcavated.<br>• Archaeologists now prefer to leave some areas untouched so that future researchers, with better technology, can study them.$q$, $q$The student wants to explain why much of Pompeii has not been excavated. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Pompeii, buried by an eruption of Mount Vesuvius in 79 CE, has been excavated since 1748, revealing buildings, frescoes, and even loaves of bread.","Volcanic ash from the eruption of Mount Vesuvius in 79 CE preserved Pompeii's buildings and frescoes, which archaeologists began excavating in 1748.","About one-third of Pompeii, which was buried by an eruption of Mount Vesuvius in 79 CE, remains unexcavated today.","About a third of Pompeii remains unexcavated, partly because archaeologists want to leave areas for future researchers with better technology."]$q$::jsonb, 3, $q$The goal is to explain why part of Pompeii remains unexcavated. Only the correct answer gives the proportion unexcavated and the archaeologists' reason.$q$, null),
  ($q$ei-h22$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Some spiders "balloon": they release silk threads and float into the air.<br>• Ballooning spiders have been found more than 4 kilometers above the ground.<br>• Scientists long assumed wind was responsible for lifting them.<br>• A 2018 study found that spiders also respond to Earth's electric field.<br>• In the study, spiders began ballooning in a lab with no wind when an electric field was switched on.$q$, $q$The student wants to explain how a recent study challenged an earlier assumption about ballooning spiders. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Ballooning spiders, which release silk threads and float into the air, have been found more than 4 kilometers above the ground.","Scientists long assumed that wind was responsible for lifting ballooning spiders, which have been found more than 4 kilometers above the ground.","Challenging the belief that wind alone lifts them, a 2018 study showed spiders ballooning in a windless lab when an electric field was switched on.","A 2018 study found that ballooning spiders, which release silk threads to float into the air, respond to Earth's electric field."]$q$::jsonb, 2, $q$The goal is to show how new evidence challenged an earlier assumption. Only the correct answer states the earlier belief and the study's contradicting evidence.$q$, null),
  ($q$ei-h23$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The poet Pablo Neruda was born in Chile in 1904.<br>• His collection Twenty Love Poems and a Song of Despair was published in 1924, when he was nineteen.<br>• It became one of the best-selling books of poetry in the Spanish language.<br>• Neruda later wrote overtly political poetry.<br>• He received the Nobel Prize in Literature in 1971.$q$, $q$The student wants to emphasize how early in his life Neruda achieved success. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Pablo Neruda, who was born in Chile in 1904, wrote overtly political poetry later in his career and received the Nobel Prize in Literature in 1971.","Neruda was only nineteen when he published Twenty Love Poems and a Song of Despair, which became one of the best-selling books of Spanish poetry.","Published in 1924, Pablo Neruda's Twenty Love Poems and a Song of Despair became one of the best-selling books of poetry in the Spanish language.","Pablo Neruda, a Chilean poet who received the Nobel Prize in Literature in 1971, published Twenty Love Poems and a Song of Despair in 1924."]$q$::jsonb, 1, $q$The goal is to emphasize Neruda's early success. Only the correct answer highlights his age and the collection's sales, contrasting it with his much later Nobel Prize.$q$, null),
  ($q$ei-h24$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The European Union banned single-use plastic straws, plates, and cutlery in 2021.<br>• The ban aims to reduce ocean pollution.<br>• Single-use plastics make up about half of the litter found on European beaches.<br>• Businesses were allowed to sell existing stock after the ban took effect.<br>• Alternatives include products made of paper, bamboo, and wood.$q$, $q$The student wants to explain the purpose of the ban and the problem it was meant to address. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["To reduce ocean pollution—single-use plastics make up about half of the litter on European beaches—the EU banned plastic straws, plates, and cutlery in 2021.","In 2021, the European Union banned single-use plastic straws, plates, and cutlery, though businesses were allowed to sell their existing stock.","Single-use plastics, which make up about half of the litter on European beaches, can be replaced by products made of paper, bamboo, and wood.","The European Union's 2021 ban on single-use plastic straws, plates, and cutlery encouraged alternatives made of paper, bamboo, and wood."]$q$::jsonb, 0, $q$The goal is to explain the ban's purpose and the problem it addresses. Only the correct answer gives both the purpose and the evidence of the problem.$q$, null),
  ($q$ei-h25$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Wildfire smoke contains fine particles called PM2.5.<br>• These particles can travel thousands of kilometers.<br>• In 2023, smoke from wildfires in Quebec, Canada, caused hazardous air quality in New York City.<br>• New York City is more than 600 kilometers from the fires.<br>• Health officials urged residents to stay indoors.$q$, $q$The student wants to use an example to illustrate how far wildfire smoke can travel. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Wildfire smoke contains fine particles called PM2.5, which can travel thousands of kilometers from the fires that produce them.","In 2023, health officials urged New York City residents to stay indoors because of hazardous air quality caused by wildfire smoke.","In 2023, there were wildfires in Quebec, Canada, and the smoke they produced contained fine particles called PM2.5.","Smoke from 2023 Quebec wildfires caused hazardous air in New York City, more than 600 kilometers away."]$q$::jsonb, 3, $q$The goal is to illustrate, with an example, the distance smoke can travel. Only the correct answer gives a specific case with the distance involved.$q$, null),
  ($q$ei-h26$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers in Peru are studying a variety of potato called papa amarilla.<br>• It grows at altitudes above 3,500 meters.<br>• It is unusually resistant to frost.<br>• It is also more susceptible to a fungal disease called late blight than common varieties.<br>• Researchers hope to breed its frost resistance into other varieties.$q$, $q$The student wants to describe both an advantage and a disadvantage of papa amarilla. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Papa amarilla, a potato variety studied by researchers in Peru, grows at altitudes above 3,500 meters and is unusually resistant to frost.","Researchers in Peru hope to breed the unusual frost resistance of papa amarilla, which grows above 3,500 meters, into other potato varieties.","Papa amarilla, a potato variety grown above 3,500 meters in Peru, resists frost unusually well but is more susceptible to late blight than common varieties.","Papa amarilla is more susceptible to a fungal disease called late blight than common potato varieties grown at lower altitudes."]$q$::jsonb, 2, $q$The goal is to present both a strength and a weakness of the variety. Only the correct answer mentions frost resistance and susceptibility to late blight.$q$, null),
  ($q$ei-h27$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Nigerian author Chinua Achebe published Things Fall Apart in 1958.<br>• The novel depicts life in an Igbo village before and during British colonization.<br>• Achebe wrote it partly in response to European novels that portrayed Africans as lacking culture.<br>• It has been translated into more than fifty languages.<br>• It is one of the most widely read African novels.$q$, $q$The student wants to explain what motivated Achebe to write Things Fall Apart. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Things Fall Apart, Chinua Achebe's 1958 novel about life in an Igbo village before and during British colonization, has been translated into more than fifty languages.","Achebe wrote Things Fall Apart (1958), a novel depicting an Igbo village before and during colonization, partly to counter European novels that portrayed Africans as lacking culture.","Nigerian author Chinua Achebe's Things Fall Apart, published in 1958, is one of the most widely read African novels and has been translated into more than fifty languages.","Set in an Igbo village before and during British colonization, Things Fall Apart was published in 1958 by the Nigerian author Chinua Achebe."]$q$::jsonb, 1, $q$The goal is to explain Achebe's motivation for writing the novel. Only the correct answer describes the novel and identifies what it was responding to.$q$, null),
  ($q$ei-h28$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• A study compared two groups of hospital patients recovering from surgery.<br>• Patients in Group 1 had rooms with windows facing a grove of trees.<br>• Patients in Group 2 had rooms with windows facing a brick wall.<br>• Group 1 patients left the hospital about one day sooner on average.<br>• Group 1 patients also requested less pain medication.$q$, $q$The student wants to summarize the study's findings about the effect of a window view on recovery. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Surgical patients whose windows faced trees left the hospital about a day sooner and requested less pain medication than those whose windows faced a brick wall.","A study compared surgical patients whose hospital windows faced a grove of trees with patients whose windows faced a brick wall.","Researchers compared how much pain medication was requested by surgical patients whose windows faced trees and by those whose windows faced a brick wall.","Patients in Group 2, whose windows faced a brick wall, were compared with patients in Group 1, whose windows faced a grove of trees."]$q$::jsonb, 0, $q$The goal is to summarize the study's findings comparing the two groups. Only the correct answer states both outcomes and identifies both conditions.$q$, null),
  ($q$ei-h29$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The axolotl is a salamander native to lakes near Mexico City.<br>• Unlike most amphibians, it keeps its gills and lives in water its entire life.<br>• It can regrow lost limbs, parts of its heart, and even parts of its brain.<br>• Scientists study it to learn about tissue regeneration.<br>• It is critically endangered in the wild due to pollution and urban growth.$q$, $q$The student wants to contrast the axolotl's importance to science with its situation in the wild. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The axolotl, a salamander native to lakes near Mexico City, keeps its gills and lives in water its entire life, unlike most amphibians.","Scientists study the axolotl, which can regrow lost limbs and parts of its heart and brain, to learn about tissue regeneration.","The axolotl is critically endangered in the wild because of pollution and urban growth around the lakes near Mexico City.","Axolotls, which can regrow limbs and even parts of their brains, are valuable to science—yet critically endangered in the wild."]$q$::jsonb, 3, $q$The goal is to contrast the axolotl's scientific value with its endangered status. Only the correct answer includes both.$q$, null),
  ($q$ei-h30$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Hubble Space Telescope was launched in 1990.<br>• Its first images were blurry because of a flaw in its main mirror.<br>• In 1993, astronauts installed corrective optics during a spacewalk.<br>• After the repair, Hubble produced some of the sharpest images of space ever taken.<br>• Hubble has since been used in more than 19,000 published scientific papers.$q$, $q$The student wants to describe the problem Hubble faced and how it was resolved. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Launched in 1990, the Hubble Space Telescope has since been used in more than 19,000 published scientific papers.","In 1993, astronauts conducted a spacewalk to install corrective optics on the Hubble Space Telescope, which had been launched in 1990.","Hubble's first images were blurry due to a mirror flaw, but after astronauts added corrective optics in 1993, its images became exceptionally sharp.","After 1993, the Hubble Space Telescope produced some of the sharpest images of space ever taken and has been used in more than 19,000 papers."]$q$::jsonb, 2, $q$The goal is to describe the problem and how it was solved. Only the correct answer includes the flaw, the repair, and the result.$q$, null),
  ($q$ei-h31$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• In 1970, a researcher placed a mirror in front of chimpanzees after marking their faces with red dye while they were unconscious.<br>• When they saw their reflections, the chimpanzees touched the marks on their own faces.<br>• This "mirror test" is used to assess self-recognition.<br>• Elephants, dolphins, and magpies have also passed the test.<br>• Most monkeys and dogs have not.$q$, $q$The student wants to indicate which animals have passed the mirror test and which generally have not. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In 1970, a researcher marked chimpanzees' faces with red dye and found that, when they saw their reflections, the chimpanzees touched the marks on their own faces.","The mirror test, which assesses self-recognition, has been passed by chimpanzees, elephants, dolphins, and magpies, but not by most monkeys and dogs.","The mirror test, first used with chimpanzees in 1970, assesses self-recognition by marking an animal's face and observing its response to a mirror.","Elephants, dolphins, and magpies, like the chimpanzees first tested in 1970, have passed the mirror test."]$q$::jsonb, 1, $q$The goal is to indicate which animals have and have not passed the test. Only the correct answer names both groups.$q$, null),
  ($q$ei-h32$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Bamboo is a type of grass.<br>• Some species can grow up to 91 centimeters in a single day.<br>• Bamboo has a tensile strength comparable to that of steel.<br>• It regrows from its roots after being harvested, without replanting.<br>• In parts of Asia, it has been used for construction for thousands of years.$q$, $q$The student wants to make the case that bamboo is a sustainable building material. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Because bamboo is as strong as steel in tension and regrows from its roots after harvest without replanting, it can be an appealing renewable building material.","Bamboo, a type of grass, can grow up to 91 centimeters in a single day and has been used for construction in parts of Asia for thousands of years.","Some species of bamboo, a type of grass, can grow up to 91 centimeters in a single day and regrow from their roots after being harvested.","Bamboo has a tensile strength comparable to that of steel and has been used for construction in parts of Asia for thousands of years."]$q$::jsonb, 0, $q$The goal is to argue that bamboo is a sustainable building material. Only the correct answer combines its strength (suitability for building) with its regrowth (sustainability).$q$, null),
  ($q$ei-h33$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers placed GPS trackers on 30 Arctic terns.<br>• Arctic terns breed in the Arctic and spend the northern winter near Antarctica.<br>• The average bird flew about 70,900 kilometers per year.<br>• Over a lifetime of about thirty years, a tern may fly the equivalent of three round trips to the Moon.<br>• The terns did not fly in a straight line but followed wind patterns in an S-shaped route.$q$, $q$The student wants to emphasize the enormous distance an Arctic tern travels over its lifetime. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Researchers placed GPS trackers on 30 Arctic terns, birds that breed in the Arctic and spend the northern winter near Antarctica.","Arctic terns, which breed in the Arctic and winter near Antarctica, follow an S-shaped route shaped by wind patterns rather than flying in a straight line.","Arctic terns live about thirty years and spend the northern winter near Antarctica, following wind patterns in an S-shaped route.","An Arctic tern flies about 70,900 kilometers a year, so over a thirty-year lifetime it may travel the equivalent of three round trips to the Moon."]$q$::jsonb, 3, $q$The goal is to convey the immense distances terns travel. Only the correct answer gives the annual distance and the vivid Moon comparison.$q$, null),
  ($q$ei-h34$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• In 1955, Claudette Colvin, age fifteen, refused to give up her bus seat to a white passenger in Montgomery, Alabama.<br>• This happened nine months before Rosa Parks's more famous protest.<br>• Colvin was arrested.<br>• She later became a plaintiff in Browder v. Gayle, the case that ruled Montgomery's bus segregation unconstitutional.<br>• Her role was largely overlooked for decades.$q$, $q$The student wants to emphasize that Colvin's protest preceded Parks's but received far less attention. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In 1955, fifteen-year-old Claudette Colvin was arrested after refusing to give up her bus seat to a white passenger in Montgomery, Alabama.","Claudette Colvin later became a plaintiff in Browder v. Gayle, the case that ruled bus segregation in Montgomery, Alabama, unconstitutional.","Claudette Colvin refused to give up her bus seat nine months before Rosa Parks did, yet her role was overlooked for decades.","Like Rosa Parks, Claudette Colvin refused to give up her bus seat to a white passenger in Montgomery, Alabama, in 1955."]$q$::jsonb, 2, $q$The goal is to emphasize that Colvin acted before Parks yet received little recognition. Only the correct answer includes the timing relative to Parks and the decades of neglect.$q$, null),
  ($q$ei-h35$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers measured noise in 50 schools near a major airport.<br>• In schools under flight paths, aircraft noise exceeded 70 decibels about 40 times per day.<br>• Students in these schools scored lower on reading tests than students in quieter schools.<br>• After the airport moved its flight paths, reading scores in the affected schools improved within two years.<br>• Math scores showed no significant change.$q$, $q$The student wants to present the most compelling evidence that aircraft noise affects students' reading. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In 50 schools near a major airport, aircraft noise exceeded 70 decibels about 40 times per day in the schools located under flight paths.","After the airport moved its flight paths away from certain schools, students' reading scores improved within two years, suggesting that aircraft noise had hindered reading.","After the airport moved its flight paths, math scores at the affected schools showed no significant change within two years.","Students at schools under the airport's flight paths, where noise often exceeded 70 decibels, scored lower on reading tests than students at quieter schools."]$q$::jsonb, 1, $q$The goal is the most compelling evidence that noise affects reading. Scores improving after the flight paths moved (with noise as the only change) is stronger evidence than a simple comparison between noisy and quiet schools, which could differ in other ways. The other choices give background or a result unrelated to reading.$q$, null),
  ($q$ei-h36$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The mantis shrimp has the most complex eyes known in the animal kingdom.<br>• Humans have three types of color receptors.<br>• Mantis shrimp have twelve to sixteen.<br>• However, tests show they are worse than humans at distinguishing between similar colors.<br>• Scientists think they may recognize colors quickly without comparing them, like a scanner.$q$, $q$The student wants to present a surprising finding about mantis shrimp vision. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Despite having twelve to sixteen types of color receptors to humans' three, mantis shrimp are worse than humans at distinguishing similar colors.","Mantis shrimp, which have the most complex eyes known in the animal kingdom, have twelve to sixteen types of color receptors.","Humans have three types of color receptors, and scientists think that mantis shrimp may recognize colors quickly without comparing them, like a scanner.","With twelve to sixteen types of color receptors, compared with three in humans, mantis shrimp have the most complex eyes known."]$q$::jsonb, 0, $q$The goal is to present the surprising finding. Only the correct answer juxtaposes the large number of receptors with their poorer color discrimination.$q$, null),
  ($q$ei-h37$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Ibn Battuta was a Moroccan scholar born in 1304.<br>• Over about thirty years, he traveled roughly 117,000 kilometers.<br>• He visited West Africa, the Middle East, India, and China.<br>• After returning home, he dictated an account of his travels called the Rihla.<br>• The Rihla is a key source on fourteenth-century societies.$q$, $q$The student wants to emphasize the importance of the Rihla to modern historians. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Ibn Battuta, a Moroccan scholar born in 1304, traveled roughly 117,000 kilometers over about thirty years, visiting West Africa, the Middle East, India, and China.","After traveling to West Africa, the Middle East, India, and China, Ibn Battuta returned home and dictated an account of his journeys called the Rihla.","Born in Morocco in 1304, Ibn Battuta spent about thirty years traveling roughly 117,000 kilometers.","Ibn Battuta's Rihla, his account of some thirty years of travel across Africa and Asia, remains a key source for historians of the fourteenth century."]$q$::jsonb, 3, $q$The goal is to emphasize the Rihla's historical significance. Only the correct answer identifies the book and explains its value to historians.$q$, null),
  ($q$ei-h38$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Dead Sea is a salt lake between Jordan and Israel.<br>• Its surface is about 430 meters below sea level, the lowest land elevation on Earth.<br>• Its water is about ten times saltier than the ocean.<br>• People float easily in it because of the high salt content.<br>• The lake's level has dropped more than a meter per year in recent decades, mainly because water from the Jordan River is diverted for agriculture.$q$, $q$The student wants to explain why the Dead Sea has been shrinking. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Dead Sea, which lies between Jordan and Israel about 430 meters below sea level, is about ten times saltier than the ocean.","The level of the Dead Sea, the lowest land elevation on Earth, has dropped by more than a meter per year in recent decades.","The Dead Sea has dropped over a meter per year in recent decades, mainly because Jordan River water is diverted for agriculture.","Water from the Jordan River is diverted for agriculture in the region around the Dead Sea, a salt lake ten times saltier than the ocean."]$q$::jsonb, 2, $q$The goal is to explain a cause of the Dead Sea's decline. Only the correct answer gives both the decline and its cause.$q$, null),
  ($q$ei-h39$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers gave participants a list of 20 words to memorize.<br>• Half the participants walked on a treadmill while studying; half sat still.<br>• Both groups were tested immediately and again one week later.<br>• Immediately after studying, both groups recalled about 12 words.<br>• A week later, the walking group recalled 9 words on average; the sitting group recalled 6.$q$, $q$The student wants to emphasize that the difference between the groups appeared only after a delay. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Participants who walked on a treadmill while studying a list of 20 words recalled about 12 words immediately afterward and 9 words a week later.","Although both groups initially recalled about 12 words, a week later participants who walked while studying recalled more (9) than those who sat still (6).","A week after studying a list of 20 words, participants who walked while studying recalled 9 words on average, while those who sat still recalled 6.","Researchers tested participants' memory of a list of 20 words both immediately after studying and one week later."]$q$::jsonb, 1, $q$The goal is to show that the advantage of walking appeared only over time. Only the correct answer contrasts the identical immediate results with the different results a week later.$q$, null),
  ($q$ei-h40$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Lichens are composite organisms made of a fungus and an alga or cyanobacterium.<br>• The fungus provides structure and protection.<br>• The alga or cyanobacterium produces food through photosynthesis.<br>• Lichens can grow on bare rock, tree bark, and even Antarctic stones.<br>• They are highly sensitive to air pollution and are used to monitor air quality.$q$, $q$The student wants to explain a practical use humans have found for lichens. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Because lichens are highly sensitive to air pollution, scientists use them to monitor air quality.","Lichens, which are made of a fungus and an alga or cyanobacterium, can grow on bare rock, tree bark, and even Antarctic stones.","In a lichen, the fungus provides structure and protection, while the alga or cyanobacterium produces food through photosynthesis.","Lichens are composite organisms that can grow in harsh places, from bare rock to Antarctic stones."]$q$::jsonb, 0, $q$The goal is to explain a practical use of lichens. Only the correct answer describes their use in monitoring air quality and why they are suited to it.$q$, null),
  ($q$ei-h41$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Oxford English Dictionary (OED) began in 1857.<br>• Its editors asked the public to send in examples of how words were used in books.<br>• Thousands of volunteers mailed in slips of paper with quotations.<br>• One of the most prolific contributors, William Chester Minor, sent in more than 10,000 slips.<br>• The first complete edition was published in 1928, seventy-one years after the project began.$q$, $q$The student wants to emphasize the role that members of the public played in creating the OED. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Oxford English Dictionary, which began in 1857, took seventy-one years to complete, with its first full edition published in 1928.","William Chester Minor, one of the most prolific contributors to the Oxford English Dictionary, sent in more than 10,000 slips of paper with quotations.","The Oxford English Dictionary, begun in 1857, collected quotations showing how words had been used in books.","Thousands of volunteers mailed the OED quotations showing how words were used; one alone sent more than 10,000."]$q$::jsonb, 3, $q$The goal is to emphasize the role of public volunteers. Only the correct answer describes the volunteers' contributions and gives an example of their scale.$q$, null),
  ($q$ei-h42$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers placed cameras in a forest in Gabon.<br>• They recorded chimpanzees using stones to crack open hard-shelled nuts.<br>• Some chimpanzees carried stones more than 100 meters to nut trees.<br>• Young chimpanzees took up to seven years to master the technique.<br>• They learned by watching adults, especially their mothers.$q$, $q$The student wants to describe how young chimpanzees learn to crack nuts. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Researchers using cameras in a forest in Gabon recorded chimpanzees using stones to crack open hard-shelled nuts.","Some chimpanzees in Gabon carried stones more than 100 meters to nut trees in order to crack open the nuts' hard shells.","Young chimpanzees learn to crack nuts by watching adults, especially their mothers, and can take up to seven years to master it.","Chimpanzees in Gabon use stones to crack open hard-shelled nuts, a technique that young chimpanzees take years to master."]$q$::jsonb, 2, $q$The goal is to describe how young chimpanzees acquire the skill. Only the correct answer explains the learning process and its duration.$q$, null),
  ($q$ei-h43$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Trans-Siberian Railway connects Moscow and Vladivostok.<br>• It is about 9,289 kilometers long.<br>• It crosses eight time zones.<br>• Construction began in 1891 and the main line was completed in 1916.<br>• A nonstop trip takes about seven days.$q$, $q$The student wants to emphasize the immense length of the Trans-Siberian Railway. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Trans-Siberian Railway, which connects Moscow and Vladivostok, was begun in 1891 and its main line completed in 1916.","About 9,289 kilometers long, the Trans-Siberian Railway crosses eight time zones and takes about seven days to ride.","Completed in 1916, the Trans-Siberian Railway connects Moscow and Vladivostok, a trip that takes about seven days nonstop.","The Trans-Siberian Railway, which connects Moscow in the west with Vladivostok in the east, was built between 1891 and 1916."]$q$::jsonb, 1, $q$The goal is to convey the railway's length vividly. Only the correct answer gives the length and illustrates it with the time zones and travel time.$q$, null),
  ($q$ei-h44$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Some scientists want to bring back the woolly mammoth through genetic engineering.<br>• They plan to edit elephant DNA to include mammoth traits such as thick hair and fat.<br>• Supporters argue the animals could help restore Arctic grasslands.<br>• Critics argue the money would be better spent protecting living endangered species.<br>• Critics also note that elephants have long pregnancies, about 22 months.$q$, $q$The student wants to present the main argument on each side of the debate about reviving the woolly mammoth. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Supporters say revived mammoths could help restore Arctic grasslands; critics say the money should protect living endangered species.","Some scientists plan to bring back the woolly mammoth by editing elephant DNA to include traits such as thick hair and fat.","Critics of reviving the woolly mammoth note that elephants, whose DNA would be edited to include mammoth traits, have pregnancies lasting about 22 months.","Supporters of reviving the woolly mammoth by editing elephant DNA argue that the animals could help restore Arctic grasslands."]$q$::jsonb, 0, $q$The goal is to present both sides of the debate. Only the correct answer includes the supporters' and critics' main arguments.$q$, null),
  ($q$ei-h45$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Painter Amrita Sher-Gil was born in Budapest in 1913 to a Hungarian mother and an Indian father.<br>• She trained at the École des Beaux-Arts in Paris.<br>• Her early paintings followed European academic conventions.<br>• After moving to India in 1934, she began painting rural Indian women in a flattened, brightly colored style influenced by Mughal miniatures.<br>• She died in 1941 at age twenty-eight.$q$, $q$The student wants to describe how Sher-Gil's artistic style changed over her career. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Amrita Sher-Gil, born in Budapest in 1913 to a Hungarian mother and an Indian father, trained at the École des Beaux-Arts in Paris.","After moving to India in 1934, Amrita Sher-Gil painted rural Indian women, continuing to work until her death in 1941 at age twenty-eight.","Amrita Sher-Gil's early paintings, made while she trained at the École des Beaux-Arts in Paris, followed European academic conventions.","Sher-Gil moved from European academic conventions to a flat, vivid, Mughal-influenced style after settling in India in 1934."]$q$::jsonb, 3, $q$The goal is to describe how her style changed. Only the correct answer describes both the earlier European style and the later Mughal-influenced style. The others describe only her background, only her later subjects, or only her early style.$q$, null),
  ($q$ei-h46$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers studied 2,000 adults over ten years.<br>• Participants who ate nuts at least five times a week had a 20% lower risk of heart disease than those who rarely ate nuts.<br>• The nut-eaters also exercised more and smoked less on average.<br>• The researchers controlled for exercise and smoking in their analysis.<br>• Even after these adjustments, the nut-eaters had a 14% lower risk.$q$, $q$The student wants to address the possibility that the nut-eaters' lower risk was due only to their exercise and smoking habits. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Adults who ate nuts at least five times a week had a 20% lower risk of heart disease, though they also exercised more and smoked less on average.","In a ten-year study of 2,000 adults, people who ate nuts frequently had a lower risk of heart disease than those who rarely ate them.","Even after adjusting for exercise and smoking, researchers found that nut-eaters had a 14% lower risk of heart disease.","Because nut-eaters exercised more and smoked less, researchers adjusted their analysis of heart-disease risk to account for these differences."]$q$::jsonb, 2, $q$The goal is to show that the benefit persisted after other factors were considered. Only the correct answer reports the adjusted 14% figure along with the factors controlled. The choice reporting a 20% lower risk gives the unadjusted figure and leaves open whether exercise and smoking explain it.$q$, null),
  ($q$ei-h47$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Atacama Desert in Chile is one of the driest places on Earth.<br>• Some weather stations there have never recorded rain.<br>• Its high altitude, dry air, and lack of light pollution make it ideal for astronomy.<br>• It hosts several major observatories, including ALMA, an array of 66 radio antennas.<br>• NASA has tested Mars rovers there because its soil resembles that of Mars.$q$, $q$The student wants to illustrate the variety of scientific uses for the Atacama Desert. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Atacama Desert in Chile, where some weather stations have never recorded rain, is one of the driest places on Earth.","NASA tests Mars rovers in the Atacama's Mars-like soil, and its dry, dark skies host observatories such as ALMA.","With its high altitude, dry air, and lack of light pollution, the Atacama Desert hosts several major observatories, including ALMA.","ALMA, an array of 66 radio antennas, is one of several major observatories in Chile's extremely dry Atacama Desert."]$q$::jsonb, 1, $q$The goal is to show two different ways scientists use the desert. Only the correct answer mentions both rover testing and astronomy. The others focus on the desert's dryness or only on astronomy.$q$, null),
  ($q$ei-h48$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Inca built a road network called the Qhapaq Ñan.<br>• It extended about 40,000 kilometers across what is now Peru, Ecuador, Bolivia, Chile, Argentina, and Colombia.<br>• The Inca did not use wheeled vehicles.<br>• Relay runners called chasquis carried messages along the roads.<br>• Chasquis could carry a message about 240 kilometers in a single day.$q$, $q$The student wants to emphasize how quickly messages could travel across the Inca Empire. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Without wheeled vehicles, the Inca relied on relay runners called chasquis, who could carry a message about 240 kilometers along the Qhapaq Ñan in a single day.","The Qhapaq Ñan, an Inca road network, extended about 40,000 kilometers across what are now six South American countries.","Relay runners called chasquis carried messages along the Qhapaq Ñan, an Inca road network about 40,000 kilometers long.","The Inca, who did not use wheeled vehicles, built a road network that crossed what are now Peru, Ecuador, Bolivia, Chile, Argentina, and Colombia."]$q$::jsonb, 0, $q$The goal is to emphasize how quickly information moved. Only the correct answer gives the speed of the chasquis (240 kilometers a day). The choice about chasquis carrying messages along the 40,000-kilometer network mentions the runners but not their speed.$q$, null),
  ($q$ei-h49$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Two species of finches live on the same island.<br>• Species A has a large, thick beak.<br>• Species B has a small, narrow beak.<br>• During droughts, only large, hard seeds remain available.<br>• In a 1977 drought, Species A's population fell by 20%, while Species B's fell by 85%.$q$, $q$The student wants to suggest that beak shape influenced the finches' survival during the drought. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Two finch species on the same island differ in their beaks: Species A has a large, thick beak, while Species B has a small, narrow one.","In a 1977 drought on the island, the population of Species B, which has a small, narrow beak, fell by 85%.","Because only large, hard seeds remain available during droughts, both finch species on the island lost population during a drought in 1977.","During a 1977 drought, when only large, hard seeds remained, the thick-beaked Species A declined far less (20%) than the narrow-beaked Species B (85%)."]$q$::jsonb, 3, $q$The goal is to suggest that beak shape affected survival. Only the correct answer links each species' beak type to its population loss under drought conditions.$q$, null),
  ($q$ei-h50$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Sound travels about 343 meters per second in air.<br>• It travels about 1,480 meters per second in water.<br>• It travels about 5,960 meters per second in steel.<br>• Sound travels faster in materials whose particles are more tightly bound.<br>• Before modern communication, people sometimes put an ear to a railroad track to hear an approaching train.$q$, $q$The student wants to explain why putting an ear to a railroad track could help someone detect an approaching train. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Sound travels about 343 meters per second in air, about 1,480 meters per second in water, and about 5,960 meters per second in steel.","Before modern communication, people sometimes put an ear to a railroad track to listen for trains, since sound travels through materials.","Since sound moves far faster in steel (5,960 m/s) than in air (343 m/s), a train can be heard through the rails first.","Sound travels faster in materials whose particles are tightly bound, such as steel, than in materials such as air or water."]$q$::jsonb, 2, $q$The goal is to explain why listening to a rail works. Only the correct answer connects the speed difference in steel and air to the practice of listening to tracks.$q$, null),
  ($q$ei-h51$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Mary Anning (1799–1847) was a fossil collector in Lyme Regis, England.<br>• She discovered the first complete plesiosaur skeleton in 1823.<br>• Scientists of her time often published her findings without crediting her.<br>• As a woman, she was barred from joining the Geological Society of London.<br>• In 2010, the Royal Society named her one of the ten British women who most influenced the history of science.$q$, $q$The student wants to contrast the way Anning was treated in her lifetime with the recognition she later received. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Mary Anning, a fossil collector from Lyme Regis, discovered the first complete plesiosaur skeleton in 1823, when she was in her twenties.","Barred from the Geological Society and often uncredited in life, Anning was honored by the Royal Society in 2010.","In 2010, the Royal Society named Mary Anning, who discovered the first complete plesiosaur skeleton, one of ten influential British women in science.","Scientists of Mary Anning's time often published her findings without credit, and she was barred from the Geological Society of London."]$q$::jsonb, 1, $q$The goal is to contrast her treatment during her life with her later recognition. Only the correct answer includes both. The choice about the Royal Society naming her in 2010 and the choice about her findings being published without credit each give only one side.$q$, null),
  ($q$ei-h52$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• In a study, participants were asked to remember a seven-digit number.<br>• While holding the number in mind, they were offered a choice between fruit salad and chocolate cake.<br>• Participants remembering the number chose cake 63% of the time.<br>• A control group asked to remember a two-digit number chose cake 41% of the time.<br>• Researchers suggested that mental strain reduces self-control.$q$, $q$The student wants to present the study's findings and the conclusion the researchers drew from them. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["People holding seven digits in mind chose cake 63% of the time versus 41% for two digits, suggesting strain weakens self-control.","In a study, participants remembering a seven-digit number were offered a choice between fruit salad and chocolate cake.","Researchers who studied people choosing between fruit salad and chocolate cake suggested that mental strain may reduce self-control.","Participants who were asked to remember a seven-digit number chose chocolate cake over fruit salad 63% of the time."]$q$::jsonb, 0, $q$The goal is to present the evidence and conclusion together. Only the correct answer gives both groups' results and the researchers' interpretation. The choice reporting that seven-digit participants chose cake 63% of the time gives one group's result without the comparison.$q$, null),
  ($q$ei-h53$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The ancient Egyptians built the Great Pyramid of Giza around 2560 BCE.<br>• It was the tallest human-made structure in the world for about 3,800 years.<br>• It was originally covered in polished white limestone casing stones.<br>• Most of the casing stones were removed in the 1300s CE and reused in buildings in Cairo.<br>• Today, the pyramid's exposed core blocks give it a stepped appearance.$q$, $q$The student wants to explain why the Great Pyramid looks different today than it did when it was completed. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Built around 2560 BCE, the Great Pyramid of Giza was the tallest human-made structure in the world for about 3,800 years.","The Great Pyramid of Giza was originally covered in polished white limestone casing stones, which made it the tallest human-made structure for centuries.","In the 1300s CE, builders in Cairo reused stones taken from the Great Pyramid of Giza, which had been built around 2560 BCE.","The Great Pyramid's stepped look today results from the removal of most of its smooth white limestone casing in the 1300s CE for use in Cairo's buildings."]$q$::jsonb, 3, $q$The goal is to explain why the pyramid looks different today. Only the correct answer links the removal of the casing stones to its current stepped appearance.$q$, null),
  ($q$ei-h54$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers tested whether dogs understand human pointing.<br>• Dogs were shown two cups, one of which hid food; a person pointed to the correct cup.<br>• Adult dogs chose the correct cup about 70% of the time.<br>• Eight-week-old puppies with little human contact also chose correctly about 70% of the time.<br>• Researchers concluded that the ability may be largely inherited rather than learned.$q$, $q$The student wants to present the evidence that led the researchers to their conclusion. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Adult dogs shown two cups, one hiding food, chose the cup that a person pointed to about 70% of the time.","Researchers tested whether dogs and young puppies could find food hidden under one of two cups when a person pointed to it.","Puppies with little human contact read pointing as well as adult dogs (about 70%), so the ability may be largely inherited.","Researchers concluded that dogs' ability to understand human pointing may be largely inherited rather than learned through experience."]$q$::jsonb, 2, $q$The goal is to present the evidence for the conclusion. Only the correct answer explains that inexperienced puppies performed as well as adults, which is what supports the claim that the ability is inherited.$q$, null),
  ($q$ei-h55$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Great Molasses Flood occurred in Boston on January 15, 1919.<br>• A storage tank holding about 8.7 million liters of molasses burst.<br>• A wave of molasses up to 7.6 meters high swept through the streets at about 56 kilometers per hour.<br>• Twenty-one people were killed.<br>• Investigators found that the tank had been poorly built and never properly tested.$q$, $q$The student wants to identify the cause of the Great Molasses Flood. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["On January 15, 1919, a wave of molasses up to 7.6 meters high swept through Boston's streets at about 56 kilometers per hour.","The 1919 Great Molasses Flood, which killed twenty-one people in Boston, occurred because a poorly built, never properly tested storage tank burst.","In 1919, a storage tank in Boston burst and released about 8.7 million liters of molasses, killing twenty-one people.","Investigators studied the Great Molasses Flood, in which a storage tank holding 8.7 million liters of molasses burst in Boston in 1919."]$q$::jsonb, 1, $q$The goal is to identify the cause of the disaster. Only the correct answer explains why the tank burst (poor construction and lack of testing).$q$, null),
  ($q$ei-h56$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Bees and other pollinators are needed for about 75% of the world's food crop species.<br>• Almonds depend entirely on honeybee pollination.<br>• California produces about 80% of the world's almonds.<br>• Each spring, beekeepers truck about 2 million hives to California's almond orchards.<br>• That is more than two-thirds of all commercial honeybee hives in the United States.$q$, $q$The student wants to emphasize the scale of the effort required to pollinate California's almond crop. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Almond pollination requires about 2 million trucked-in hives each spring—over two-thirds of all U.S. commercial hives.","Bees and other pollinators are needed for about 75% of the world's food crop species, including almonds, which depend entirely on honeybees.","California produces about 80% of the world's almonds, a crop that depends entirely on pollination by honeybees.","Each spring, beekeepers transport hives to California, which produces about 80% of the world's almonds."]$q$::jsonb, 0, $q$The goal is to convey the scale of the almond pollination effort. Only the correct answer includes the number of hives and their share of all U.S. hives.$q$, null),
  ($q$ei-h57$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The aye-aye is a lemur found only in Madagascar.<br>• It taps on tree bark with a long, thin middle finger.<br>• It listens for hollow spaces made by insect larvae.<br>• It then gnaws a hole and uses its finger to pull out the larvae.<br>• Woodpeckers find food in a similar way on other continents, but there are no woodpeckers in Madagascar.$q$, $q$The student wants to draw a comparison between the aye-aye and woodpeckers. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The aye-aye, a lemur found only in Madagascar, taps on tree bark with a long, thin middle finger to locate insect larvae.","After locating larvae by tapping on bark, the aye-aye gnaws a hole in the tree and pulls the larvae out with its finger.","Woodpeckers, which do not live in Madagascar, find food on other continents by tapping on trees to locate insect larvae.","Madagascar has no woodpeckers, but the aye-aye finds larvae the same way: by tapping on bark."]$q$::jsonb, 3, $q$The goal is to compare the aye-aye with woodpeckers. Only the correct answer links the two, noting that the aye-aye uses a similar method where woodpeckers are absent.$q$, null),
  ($q$ei-h58$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Architect Zaha Hadid was born in Baghdad in 1950.<br>• In 2004, she became the first woman to win the Pritzker Architecture Prize.<br>• Her buildings are known for sweeping curves and the absence of right angles.<br>• For years, many of her designs were considered impossible to build.<br>• Advances in computer modeling eventually allowed many of them to be constructed.$q$, $q$The student wants to explain how technology helped make Hadid's designs a reality. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Zaha Hadid, who was born in Baghdad in 1950, became the first woman to win the Pritzker Architecture Prize in 2004.","Zaha Hadid's buildings, known for their sweeping curves and absence of right angles, earned her the Pritzker Architecture Prize in 2004.","Hadid's curving designs, once deemed impossible to build, became buildable thanks to advances in computer modeling.","For years, many of Zaha Hadid's designs, such as those with sweeping curves, were considered impossible to build."]$q$::jsonb, 2, $q$The goal is to explain how technology affected her career. Only the correct answer links computer modeling to the eventual construction of her designs.$q$, null),
  ($q$ei-h59$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Doppler effect is the change in frequency of a wave as its source moves.<br>• As an ambulance approaches, its siren sounds higher in pitch.<br>• As it moves away, the siren sounds lower.<br>• Astronomers use the Doppler effect with light.<br>• Light from galaxies moving away from Earth shifts toward red, which shows that the universe is expanding.$q$, $q$The student wants to explain how the Doppler effect helps astronomers learn about the universe. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Doppler effect explains why an ambulance siren sounds higher in pitch as it approaches and lower as it moves away.","Astronomers apply the Doppler effect to light: redshifted light from receding galaxies shows the universe is expanding.","The Doppler effect, which is the change in a wave's frequency as its source moves, can be observed in both sound and light.","Light from galaxies moving away from Earth shifts toward red, a phenomenon that astronomers have studied extensively."]$q$::jsonb, 1, $q$The goal is to explain how astronomers use the Doppler effect to learn about the universe. Only the correct answer links the effect to redshift and the conclusion that the universe is expanding.$q$, null),
  ($q$ei-h60$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Bajau people live in coastal Southeast Asia.<br>• Many Bajau free-dive for fish, spending up to five hours a day underwater.<br>• A 2018 study found that the Bajau have spleens about 50% larger than those of a nearby group that does not dive.<br>• The spleen releases oxygen-rich red blood cells during dives.<br>• The researchers identified a gene variant linked to larger spleens that is common among the Bajau.$q$, $q$The student wants to present evidence that the Bajau have a physical adaptation suited to their diving lifestyle. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Bajau, who free-dive for hours daily, have spleens about 50% larger than those of a nearby non-diving group.","The Bajau, who live in coastal Southeast Asia, free-dive for fish and may spend up to five hours a day underwater.","The spleen releases oxygen-rich red blood cells during dives, and a gene variant linked to larger spleens is common among some groups.","Researchers studying the Bajau and a nearby group that does not dive identified a gene variant linked to spleen size."]$q$::jsonb, 0, $q$The goal is to present evidence of a physical adaptation to diving. Only the correct answer compares the Bajau's spleen size with that of a non-diving group and connects it to diving.$q$, null),
  ($q$ei-h61$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Volunteers in a citizen-science project counted birds in their backyards each February.<br>• In 2023, more than 500,000 people participated.<br>• They submitted about 380,000 checklists from 190 countries.<br>• Scientists use the data to track changes in bird populations.<br>• Data from past counts helped document the spread of the Eurasian collared-dove across North America.$q$, $q$The student wants to provide a specific example of how the project's data have been useful to scientists. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In 2023, more than 500,000 people in 190 countries took part in a citizen-science project in which they counted backyard birds.","Each February, volunteers in a citizen-science project count the birds in their backyards and submit checklists to scientists.","Volunteers submitted about 380,000 checklists from 190 countries for a 2023 bird count used by scientists to track populations.","Past counts by the project's volunteers helped scientists document the Eurasian collared-dove's spread across North America."]$q$::jsonb, 3, $q$The goal is to give a specific example of how scientists have used the data. Only the correct answer describes such a case (the collared-dove's spread).$q$, null),
  ($q$ei-h62$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Pantanal in South America is the world's largest tropical wetland.<br>• It covers about 150,000 square kilometers.<br>• It has one of the highest concentrations of jaguars in the world.<br>• In 2020, fires burned about 30% of the Pantanal.<br>• Scientists estimate that about 17 million vertebrate animals died in the fires.$q$, $q$The student wants to emphasize the severity of the 2020 fires in the Pantanal. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Pantanal, the world's largest tropical wetland, covers about 150,000 square kilometers and is home to many jaguars.","The Pantanal in South America has one of the highest concentrations of jaguars in the world, and fires burned parts of it in 2020.","In 2020, fires burned about 30% of the Pantanal, the world's largest tropical wetland, killing an estimated 17 million vertebrate animals.","Covering about 150,000 square kilometers, the Pantanal in South America is the largest tropical wetland on Earth."]$q$::jsonb, 2, $q$The goal is to emphasize the severity of the 2020 fires. Only the correct answer gives both the extent of the burned area and the number of animals killed.$q$, null),
  ($q$ei-h63$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Novelist Kazuo Ishiguro was born in Nagasaki, Japan, in 1954.<br>• His family moved to England when he was five.<br>• His novel The Remains of the Day (1989) is narrated by an English butler.<br>• Never Let Me Go (2005) is narrated by a young woman in a boarding school with a dark secret.<br>• Both narrators gradually reveal truths they have avoided facing.$q$, $q$The student wants to emphasize a similarity between the narrators of the two novels. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Kazuo Ishiguro, born in Nagasaki in 1954, wrote The Remains of the Day, which is narrated by an English butler.","Ishiguro's butler and boarding-school narrators share a habit: both slowly reveal truths they have avoided facing.","The Remains of the Day (1989) is narrated by an English butler, while Never Let Me Go (2005) is narrated by a young woman at a boarding school.","Kazuo Ishiguro's novel Never Let Me Go, published in 2005, is narrated by a young woman at a boarding school with a dark secret."]$q$::jsonb, 1, $q$The goal is to identify a similarity between the novels' narrators. Only the correct answer states what the narrators have in common. The choice contrasting the butler with the boarding-school narrator describes only how they differ.$q$, null),
  ($q$ei-h64$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers placed small cameras on the backs of emperor penguins.<br>• The penguins dove to depths of more than 500 meters.<br>• During dives, their heart rates dropped from about 70 beats per minute to as low as 6.<br>• This slowing reduced the amount of oxygen their bodies used.<br>• It allowed them to stay underwater for more than 20 minutes.$q$, $q$The student wants to explain how emperor penguins are able to remain underwater for long periods. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Slowing their hearts from about 70 to as few as 6 beats per minute saves oxygen, letting penguins dive for over 20 minutes.","Emperor penguins fitted with small cameras dove to depths of more than 500 meters and stayed underwater for more than 20 minutes.","During dives, emperor penguins' heart rates dropped from about 70 beats per minute to as low as 6, researchers found.","Researchers placed small cameras on the backs of emperor penguins, which dove to depths of more than 500 meters."]$q$::jsonb, 0, $q$The goal is to explain how penguins can stay underwater so long. Only the correct answer links the slowing heart rate to conserving oxygen and to the length of dives.$q$, null),
  ($q$ei-h65$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Rosetta Stone was discovered in Egypt in 1799.<br>• It contains the same decree in three scripts: hieroglyphic, Demotic, and ancient Greek.<br>• Scholars could already read ancient Greek.<br>• In 1822, Jean-François Champollion used the Greek text to help decipher the hieroglyphs.<br>• Before this, hieroglyphs had been unreadable for more than a thousand years.$q$, $q$The student wants to explain why the Rosetta Stone was key to deciphering hieroglyphs. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Rosetta Stone, discovered in Egypt in 1799, contains a decree written in hieroglyphic, Demotic, and ancient Greek scripts.","In 1822, Jean-François Champollion deciphered Egyptian hieroglyphs, which had been unreadable for more than a thousand years.","Scholars who studied the Rosetta Stone after its discovery in 1799 could already read ancient Greek, one of its three scripts.","Since the stone repeated its decree in readable Greek, Champollion could use it to decipher hieroglyphs in 1822."]$q$::jsonb, 3, $q$The goal is to explain why the stone was useful for deciphering hieroglyphs. Only the correct answer connects the readable Greek text to Champollion's decipherment.$q$, null),
  ($q$ei-h66$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• A city introduced a fee of $15 for cars entering its downtown during peak hours.<br>• In the first year, traffic downtown fell by about 18%.<br>• Average bus speeds increased by 10%.<br>• Revenue from the fee, about $500 million, was used to improve public transit.<br>• Some downtown business owners initially opposed the fee, fearing fewer customers.$q$, $q$The student wants to present evidence that the fee reduced traffic congestion. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["A city introduced a $15 fee for cars entering downtown at peak hours, despite initial opposition from some business owners.","Revenue from the city's $15 downtown entry fee, about $500 million, was used to improve public transit.","After the city began charging cars $15 to enter downtown at peak hours, traffic fell about 18% and bus speeds rose 10% in the first year.","Some downtown business owners initially opposed the city's $15 peak-hour fee for cars, fearing it would reduce customers."]$q$::jsonb, 2, $q$The goal is to show the fee's effect on traffic. Only the correct answer gives the traffic and bus-speed results.$q$, null),
  ($q$ei-h67$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Scientists sequenced the genome of the coelacanth, a fish once thought extinct.<br>• Coelacanths were known only from fossils until a living one was caught off South Africa in 1938.<br>• Their genes have changed more slowly than those of most other vertebrates.<br>• Coelacanths have fleshy, lobed fins with bones similar to those in limbs.<br>• They are more closely related to land animals than most fish are.$q$, $q$The student wants to explain why the coelacanth is of interest to scientists studying how land animals evolved. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Scientists who sequenced the coelacanth's genome found that its genes have changed more slowly than those of most other vertebrates.","Coelacanths have limb-like bones in their lobed fins and are closer relatives of land animals than most fish are.","The coelacanth, a fish that was once thought to be extinct, has been studied by scientists who sequenced its genome.","Until a living coelacanth was caught off South Africa in 1938, scientists knew the fish only from fossils and believed it extinct."]$q$::jsonb, 1, $q$The goal is to explain why the coelacanth interests scientists who study the evolution of land animals. Only the correct answer mentions the limb-like fins and the close relationship to land animals.$q$, null),
  ($q$ei-h68$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Phillis Wheatley was born in West Africa around 1753.<br>• She was kidnapped and enslaved in Boston as a child.<br>• In 1773, she published Poems on Various Subjects, Religious and Moral.<br>• It was the first book of poetry published by an African American.<br>• Some colonists doubted she had written the poems, so a panel of prominent Bostonians examined her and signed a statement confirming her authorship.$q$, $q$The student wants to emphasize an obstacle Wheatley faced in having her authorship accepted, along with the significance of her book. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Wheatley's 1773 book, the first by an African American poet, appeared only after Boston leaders vouched for her authorship.","Phillis Wheatley, born in West Africa around 1753, was kidnapped and enslaved in Boston as a child.","Phillis Wheatley published Poems on Various Subjects, Religious and Moral in 1773, after being enslaved in Boston as a child.","Some colonists doubted that Phillis Wheatley had written the poems in Poems on Various Subjects, Religious and Moral."]$q$::jsonb, 0, $q$The goal is to show the obstacles Wheatley faced in being recognized as an author. Only the correct answer includes both her achievement and the examination she had to undergo.$q$, null),
  ($q$ei-h69$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Traditional concrete production releases large amounts of carbon dioxide.<br>• Cement production accounts for about 8% of global carbon dioxide emissions.<br>• A startup has developed concrete that absorbs carbon dioxide as it hardens.<br>• Its concrete stores about 25 kilograms of carbon dioxide per cubic meter.<br>• The new concrete costs about the same as traditional concrete.$q$, $q$The student wants to argue that the new concrete could be a practical alternative to traditional concrete. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Cement production accounts for about 8% of global carbon dioxide emissions, so traditional concrete production releases large amounts of carbon dioxide.","A startup's concrete stores about 25 kilograms of carbon dioxide per cubic meter as it hardens.","A startup has developed a new concrete that costs about the same as traditional concrete, which is made using cement.","Unlike traditional concrete, whose cement accounts for about 8% of global CO₂ emissions, a startup's new concrete absorbs CO₂ as it hardens—and costs about the same."]$q$::jsonb, 3, $q$The goal is to emphasize that the new concrete is both environmentally better and affordable. Only the correct answer contrasts its carbon absorption with traditional concrete's emissions and notes its comparable cost.$q$, null),
  ($q$ei-h70$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers studied how long it takes people to recognize faces.<br>• Participants were shown photos for different lengths of time.<br>• With photos shown for 100 milliseconds, participants recognized familiar faces 90% of the time.<br>• With photos shown for 33 milliseconds, recognition dropped to 60%.<br>• Recognition of unfamiliar faces was below 50% at both durations.$q$, $q$The student wants to compare how well participants recognized familiar faces versus unfamiliar faces. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Participants recognized familiar faces 90% of the time when photos were shown for 100 milliseconds but only 60% when shown for 33 milliseconds.","Researchers showed participants photos of familiar and unfamiliar faces for 100 milliseconds and for 33 milliseconds.","Familiar faces were recognized at 90% and 60% rates, but unfamiliar faces stayed below 50% at both durations.","Recognition of unfamiliar faces was below 50% whether photos were shown for 100 milliseconds or 33 milliseconds."]$q$::jsonb, 2, $q$The goal is to compare familiar and unfamiliar faces. Only the correct answer gives results for both types. The choice giving familiar-face recognition at 100 versus 33 milliseconds compares durations rather than familiarity.$q$, null),
  ($q$ei-h71$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The longest-living known vertebrate is the Greenland shark.<br>• Researchers estimated ages by radiocarbon dating proteins in the sharks' eye lenses.<br>• The oldest shark studied was estimated to be about 392 years old.<br>• Greenland sharks grow about 1 centimeter per year.<br>• They do not reach reproductive maturity until about age 150.$q$, $q$The student wants to emphasize how slowly Greenland sharks grow and mature. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Researchers estimated the ages of Greenland sharks by radiocarbon dating proteins in the lenses of their eyes.","Greenland sharks grow only about a centimeter a year and do not mature until about 150, and one was estimated to be some 392 years old.","The Greenland shark, the longest-living known vertebrate, was studied by researchers using radiocarbon dating.","Using radiocarbon dating of eye-lens proteins, researchers estimated that the oldest Greenland shark they studied was about 392 years old."]$q$::jsonb, 1, $q$The goal is to emphasize the shark's slow pace of life. Only the correct answer mentions the slow growth and very late maturity, along with its great age.$q$, null),
  ($q$ei-h72$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Henrietta Lacks died of cervical cancer in 1951.<br>• Doctors took samples of her cancer cells without her knowledge or consent.<br>• Her cells, called HeLa cells, were the first human cells to survive and reproduce indefinitely in a lab.<br>• HeLa cells were used to develop the polio vaccine and in thousands of other studies.<br>• Her family did not learn about the cells until the 1970s.$q$, $q$The student wants to highlight both the scientific importance of HeLa cells and the ethical concerns surrounding them. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Taken without consent in 1951, HeLa cells helped create the polio vaccine, yet Lacks's family learned of them only in the 1970s.","HeLa cells, taken from Henrietta Lacks in 1951, were the first human cells to survive and reproduce indefinitely in a lab.","HeLa cells have been used in thousands of studies, including research that led to the polio vaccine.","Doctors took samples of Henrietta Lacks's cancer cells in 1951 without her knowledge or consent."]$q$::jsonb, 0, $q$The goal is to highlight both the scientific value and the ethical problem. Only the correct answer includes the cells' contributions and the lack of consent and disclosure.$q$, null),
  ($q$ei-h73$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers tested a new antibiotic on mice infected with drug-resistant bacteria.<br>• Mice receiving the antibiotic had a 95% survival rate.<br>• Mice receiving no treatment had a 10% survival rate.<br>• The antibiotic has not yet been tested in humans.<br>• Researchers expect human trials to begin in three years.$q$, $q$The student wants to present the antibiotic's promising results while acknowledging a limitation of the research. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Mice infected with drug-resistant bacteria and given a new antibiotic had a 95% survival rate, compared with 10% for untreated mice.","Researchers expect human trials of a new antibiotic, which was tested on mice infected with drug-resistant bacteria, to begin in three years.","A new antibiotic tested on mice infected with drug-resistant bacteria has not yet been tested in humans.","The antibiotic raised infected mice's survival to 95% (versus 10% untreated) but has not yet been tested in humans."]$q$::jsonb, 3, $q$The goal is to present the promising result while noting a limitation. Only the correct answer includes both. The choice reporting 95% versus 10% survival gives only the result.$q$, null),
  ($q$ei-h74$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Gothic cathedrals in Europe used flying buttresses.<br>• A flying buttress is an external arch that transfers the weight of the roof to a pier outside the building.<br>• Earlier churches needed thick walls to support the roof.<br>• Flying buttresses allowed walls to be thinner and taller.<br>• Thinner walls could contain large stained-glass windows.$q$, $q$The student wants to explain how flying buttresses made large stained-glass windows possible. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["A flying buttress is an external arch that transfers the weight of a cathedral's roof to a pier outside the building.","Gothic cathedrals, with their large stained-glass windows, used flying buttresses, unlike earlier churches, which had thick walls.","Flying buttresses moved the roof's weight to outside piers, allowing thinner walls with room for large stained-glass windows.","Earlier churches needed thick walls to support their roofs, while Gothic cathedrals had thinner, taller walls."]$q$::jsonb, 2, $q$The goal is to explain how flying buttresses made large windows possible. Only the correct answer traces the chain from transferred weight to thinner walls to room for windows.$q$, null),
  ($q$ei-h75$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The first successful human heart transplant was performed in 1967 in South Africa.<br>• The patient lived for eighteen days.<br>• Early transplant patients often died because their immune systems rejected the new organ.<br>• The drug cyclosporine, approved in 1983, suppressed rejection.<br>• After cyclosporine, one-year survival rates for heart transplant patients rose above 80%.$q$, $q$The student wants to explain how cyclosporine changed outcomes for heart transplant patients. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The first successful human heart transplant was performed in South Africa in 1967, and the patient lived for eighteen days.","Organ rejection killed many early heart transplant patients, but after cyclosporine (1983), one-year survival topped 80%.","Cyclosporine, a drug approved in 1983, suppresses the immune system's rejection of a transplanted organ.","Since the first heart transplant in 1967, survival rates for heart transplant patients have risen above 80%."]$q$::jsonb, 1, $q$The goal is to explain how a drug changed outcomes. Only the correct answer connects the problem (rejection), the drug, and the improved survival.$q$, null),
  ($q$ei-h76$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• A 2016 study examined three groups of commuters.<br>• Those who walked or cycled to work reported the highest satisfaction with their commutes.<br>• Those who took public transit reported moderate satisfaction.<br>• Those who drove reported the lowest satisfaction.<br>• Commute length had less effect on satisfaction than mode of travel.$q$, $q$The student wants to emphasize the study's finding about which factor most affected commuters' satisfaction. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In a 2016 study, travel mode affected commuters' satisfaction more than commute length did.","A 2016 study found that commuters who walked or cycled to work were the most satisfied with their commutes.","Commuters who drove to work reported the lowest satisfaction, while those who took public transit reported moderate satisfaction.","A 2016 study examined the satisfaction of commuters who walked or cycled, took public transit, or drove to work."]$q$::jsonb, 0, $q$The goal is to emphasize the study's finding about mode versus length. Only the correct answer includes that comparison along with the ranking.$q$, null),
  ($q$ei-h77$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Japanese artist Katsushika Hokusai created the woodblock print The Great Wave off Kanagawa around 1831.<br>• It was part of a series called Thirty-Six Views of Mount Fuji.<br>• Thousands of copies were printed.<br>• After Japan opened to trade in the 1850s, the print became popular in Europe.<br>• It influenced European artists such as Claude Monet and Vincent van Gogh.$q$, $q$The student wants to describe the influence of The Great Wave off Kanagawa beyond Japan. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Around 1831, Hokusai created The Great Wave off Kanagawa as part of his series Thirty-Six Views of Mount Fuji.","Thousands of copies of Hokusai's The Great Wave off Kanagawa, a woodblock print from around 1831, were printed.","The Great Wave off Kanagawa, a print in Hokusai's series Thirty-Six Views of Mount Fuji, is one of the most famous Japanese artworks.","Hokusai's The Great Wave became popular in Europe after the 1850s and influenced Monet and van Gogh."]$q$::jsonb, 3, $q$The goal is to describe the print's impact outside Japan. Only the correct answer describes its popularity in Europe and its influence on European artists.$q$, null),
  ($q$ei-h78$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Sleep researchers studied the effects of a 20-minute afternoon nap.<br>• Participants who napped scored 34% higher on an alertness test than those who did not.<br>• Participants who napped for 60 minutes woke feeling groggy.<br>• This grogginess, called sleep inertia, occurs when a person wakes from deep sleep.<br>• Deep sleep typically begins after about 30 minutes.$q$, $q$The student wants to explain why a shorter nap may be more beneficial than a longer one. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Participants who took a 20-minute afternoon nap scored 34% higher on an alertness test than participants who did not nap.","Grogginess after waking from deep sleep, which typically begins after about 30 minutes, is called sleep inertia.","Twenty-minute nappers gained 34% in alertness, but 60-minute nappers, likely reaching deep sleep, woke groggy.","Researchers compared the effects of afternoon naps lasting 20 minutes with those of naps lasting 60 minutes."]$q$::jsonb, 2, $q$The goal is to explain why a shorter nap may be better than a longer one. Only the correct answer contrasts both nap lengths and links grogginess to deep sleep.$q$, null),
  ($q$ei-h79$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The ancient Greek Antikythera mechanism was found in a shipwreck in 1901.<br>• It dates to about 100 BCE.<br>• It contains at least thirty interlocking bronze gears.<br>• It could predict eclipses and track the positions of the Sun and Moon.<br>• No device of comparable complexity is known until mechanical clocks appeared in Europe more than a thousand years later.$q$, $q$The student wants to emphasize how far ahead of its time the Antikythera mechanism was. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Found in a shipwreck in 1901, the Antikythera mechanism contains at least thirty interlocking bronze gears.","Nothing as complex as the Antikythera mechanism (c. 100 BCE) is known for over a thousand years after it.","The Antikythera mechanism, which dates to about 100 BCE, could predict eclipses and track the positions of the Sun and Moon.","Mechanical clocks appeared in Europe more than a thousand years after the Antikythera mechanism was made around 100 BCE."]$q$::jsonb, 1, $q$The goal is to emphasize how advanced the device was for its time. Only the correct answer states both what it did and that nothing comparable existed for more than a millennium.$q$, null),
  ($q$ei-h80$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers studied eye contact between dogs and their owners.<br>• When dogs and owners gazed at each other, levels of the hormone oxytocin rose in both.<br>• Oxytocin is associated with bonding between mothers and infants.<br>• Wolves raised by humans did not show the same oxytocin increase.<br>• The researchers suggested that this bonding mechanism developed during dog domestication.$q$, $q$The student wants to explain why the researchers concluded that the bonding mechanism developed during domestication. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Dogs and owners, but not human-raised wolves, showed oxytocin rises during mutual gaze, pointing to domestication.","When dogs and their owners gazed at each other, levels of oxytocin, a hormone associated with bonding, rose in both.","Oxytocin, a hormone associated with bonding between mothers and infants, rose in dogs and their owners during eye contact.","Researchers who studied dogs and wolves raised by humans examined whether eye contact affected oxytocin levels."]$q$::jsonb, 0, $q$The goal is to explain why researchers linked the effect to domestication. Only the correct answer includes the comparison with wolves, which is the evidence for that conclusion.$q$, null),
  ($q$ei-h81$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Composer Fanny Mendelssohn (1805–1847) wrote more than 460 pieces of music.<br>• Her father told her that music could be a career for her brother Felix but only an "ornament" for her.<br>• Some of her songs were published under Felix's name.<br>• In 2010, her Easter Sonata, long attributed to Felix, was identified as her work.<br>• Her music is now regularly performed and recorded.$q$, $q$The student wants to contrast how Fanny Mendelssohn's work was credited in the past with how it is regarded today. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Fanny Mendelssohn wrote more than 460 pieces, though her father considered music only an \"ornament\" for her.","Some of Fanny Mendelssohn's songs were published under the name of her brother, the composer Felix Mendelssohn.","In 2010, a sonata that had long been attributed to Felix Mendelssohn was identified as the work of his sister Fanny.","Long credited partly to her brother—her Easter Sonata was identified as hers only in 2010—Fanny's music is now widely performed."]$q$::jsonb, 3, $q$The goal is to contrast the past misattribution of her work with her present recognition. Only the correct answer includes both.$q$, null),
  ($q$ei-h82$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• In 1854, cholera killed more than 600 people in London's Soho district.<br>• Physician John Snow mapped the locations of deaths.<br>• Most deaths clustered around a public water pump on Broad Street.<br>• Snow persuaded officials to remove the pump's handle.<br>• New cases soon declined, supporting Snow's theory that cholera spread through contaminated water.$q$, $q$The student wants to summarize how John Snow's investigation supported his theory about cholera. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In 1854, cholera killed more than 600 people in London's Soho district, where John Snow was a physician.","John Snow persuaded officials in 1854 to remove the handle of a public water pump on Broad Street in London's Soho district.","Snow mapped Soho's 1854 cholera deaths, found them clustered at one pump, and saw cases fall once its handle was removed.","John Snow, a physician in London, believed that cholera spread through contaminated water rather than through the air."]$q$::jsonb, 2, $q$The goal is to summarize how Snow's investigation supported his theory. Only the correct answer includes his method (mapping), his finding (clustering), and the result of his intervention.$q$, null),
  ($q$ei-h83$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Oak trees produce acorns in highly variable amounts.<br>• In "mast years," all the oaks in a region produce enormous crops at the same time.<br>• In other years, they produce very few acorns.<br>• Scientists think mast years overwhelm seed-eating animals, so some acorns survive to grow.<br>• Mast years also cause spikes in mouse populations, which can increase the number of ticks carrying Lyme disease.$q$, $q$The student wants to describe a way in which mast years can affect human health. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In mast years, all the oaks in a region produce enormous crops of acorns at the same time, overwhelming seed-eating animals.","Mast years can have effects far beyond oaks: abundant acorns cause mouse populations to spike, which can increase ticks carrying Lyme disease.","Scientists think oaks produce huge acorn crops in mast years so that seed-eating animals are overwhelmed and some acorns survive.","Oak trees produce acorns in highly variable amounts, with enormous crops in mast years and very few in other years."]$q$::jsonb, 1, $q$The goal is to describe a consequence of mast years for human health. Only the correct answer traces the link from acorns to mice to Lyme-disease ticks.$q$, null),
  ($q$ei-h84$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Hedy Lamarr (1914–2000) was a Hollywood film star.<br>• During World War II, she co-invented a "frequency-hopping" system with composer George Antheil.<br>• It was designed to keep enemies from jamming radio-guided torpedoes.<br>• The U.S. Navy did not adopt it during the war.<br>• Frequency hopping later became a foundation for technologies such as Wi-Fi and Bluetooth.$q$, $q$The student wants to emphasize the unexpected and lasting significance of Lamarr's invention. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Lamarr, a film star, co-invented frequency hopping; ignored by the Navy, it later underpinned Wi-Fi and Bluetooth.","During World War II, Hollywood star Hedy Lamarr and composer George Antheil co-invented a frequency-hopping system for torpedoes.","Frequency hopping, which was designed to keep enemies from jamming radio-guided torpedoes, became a foundation for Wi-Fi and Bluetooth.","The U.S. Navy did not adopt the frequency-hopping system that Hedy Lamarr co-invented with George Antheil during World War II."]$q$::jsonb, 0, $q$The goal is to emphasize the surprising long-term importance of an invention by someone known for something else. Only the correct answer identifies her fame, the invention's early neglect, and its later impact.$q$, null),
  ($q$ei-h85$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers grew two groups of tomato plants in a greenhouse.<br>• One group was exposed to recordings of caterpillars chewing leaves.<br>• The other group was exposed to silence.<br>• Later, when real caterpillars were introduced, the first group produced more defensive chemicals.<br>• Researchers concluded that plants may respond to sounds associated with threats.$q$, $q$The student wants to present the key result of the experiment. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Researchers grew two groups of tomato plants, exposing one to recordings of caterpillars chewing leaves and the other to silence.","Researchers concluded from a greenhouse experiment with tomato plants that plants may respond to sounds associated with threats.","When caterpillars were introduced to a greenhouse, tomato plants produced defensive chemicals to protect their leaves.","When real caterpillars arrived, plants that had heard chewing recordings made more defensive chemicals than plants kept in silence."]$q$::jsonb, 3, $q$The goal is to present the key result. Only the correct answer compares the two groups' responses to real caterpillars.$q$, null),
  ($q$ei-h86$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers compared two methods of studying for a vocabulary test.<br>• Group 1 reread the word list four times.<br>• Group 2 read the list once and then quizzed themselves three times.<br>• One week later, Group 1 remembered 36% of the words.<br>• Group 2 remembered 61% of the words.$q$, $q$The student wants to use the study's results to recommend one study method over the other. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Researchers compared two groups: Group 1 reread a vocabulary list four times, while Group 2 read it once and then quizzed themselves three times before the test.","One week after studying, students who had reread a vocabulary list four times remembered 36% of the words.","Self-quizzing beat rereading: a week later, students who quizzed themselves recalled 61% of words versus 36%.","Researchers compared rereading and self-quizzing, two common methods that students use to study vocabulary."]$q$::jsonb, 2, $q$The goal is to recommend one method based on the results. Only the correct answer compares the outcomes of the two methods.$q$, null),
  ($q$ei-h87$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The kākāpō is a flightless parrot native to New Zealand.<br>• It is nocturnal and can live for up to 90 years.<br>• By 1995, only 51 kākāpō remained.<br>• Conservationists moved all of them to predator-free islands and monitored every nest.<br>• By 2022, the population had grown to 252.$q$, $q$The student wants to emphasize the success of conservation efforts for the kākāpō. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The kākāpō, a flightless and nocturnal parrot native to New Zealand, can live for up to 90 years.","Moving every remaining kākāpō to predator-free islands and monitoring each nest helped the population grow from 51 in 1995 to 252 by 2022.","By 1995, only 51 kākāpō—flightless, nocturnal parrots native to New Zealand that can live for up to 90 years—remained, and conservationists moved them to islands.","Conservationists moved all of New Zealand's kākāpō, a flightless parrot species, to islands free of predators."]$q$::jsonb, 1, $q$The goal is to show that conservation efforts worked. Only the correct answer links the efforts to the population increase.$q$, null),
  ($q$ei-h88$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Bread mold, Penicillium, and mushrooms are all fungi.<br>• Fungi were once classified as plants.<br>• Unlike plants, fungi cannot make their own food through photosynthesis.<br>• Fungi absorb nutrients from their surroundings.<br>• Genetic studies show that fungi are more closely related to animals than to plants.$q$, $q$The student wants to explain why fungi are no longer classified as plants. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Though once classified as plants, fungi cannot photosynthesize and are genetically closer to animals than to plants.","Fungi, including bread mold, Penicillium, and mushrooms, absorb nutrients from their surroundings, and they were once classified as plants by scientists.","Fungi such as mushrooms and bread mold were once classified as plants, the organisms that make food by photosynthesis.","Bread mold, Penicillium, and mushrooms are all fungi, which absorb nutrients from their surroundings."]$q$::jsonb, 0, $q$The goal is to explain why fungi are no longer considered plants. Only the correct answer gives both reasons: they don't photosynthesize and they're genetically closer to animals.$q$, null),
  ($q$ei-h89$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• In 1960, Jane Goodall began studying chimpanzees in Gombe, Tanzania.<br>• She observed a chimpanzee stripping leaves from a twig and using it to fish termites from a mound.<br>• At the time, toolmaking was considered a defining trait of humans.<br>• Her mentor, Louis Leakey, responded: "Now we must redefine tool, redefine man, or accept chimpanzees as humans."<br>• Goodall's research continued for more than sixty years.$q$, $q$The student wants to explain why Goodall's observation was significant. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In 1960, Jane Goodall began studying chimpanzees in Gombe, Tanzania, where she observed one stripping leaves from a twig to fish for termites; her research lasted sixty years.","Jane Goodall observed a chimpanzee in Gombe, Tanzania, using a twig to fish termites from a mound.","At the time Jane Goodall began her research in 1960, toolmaking was considered a defining trait of humans.","Goodall's 1960 observation of a chimpanzee shaping a twig to fish for termites challenged the belief that only humans make tools."]$q$::jsonb, 3, $q$The goal is to explain the significance of her observation. Only the correct answer connects what she saw to the challenge it posed to prevailing beliefs.$q$, null),
  ($q$ei-h90$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Sahara Desert covers about 9 million square kilometers.<br>• About 6,000 to 11,000 years ago, it was much wetter, a period called the African Humid Period.<br>• During this time, it had lakes, grasslands, and animals such as hippos and giraffes.<br>• Rock art from the period shows people herding cattle and swimming.<br>• Shifts in Earth's orbit are thought to have caused the change to desert.$q$, $q$The student wants to use evidence left by ancient people to show that the Sahara was once wetter. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Sahara Desert, which today covers about 9 million square kilometers, once had lakes, grasslands, and animals such as hippos and giraffes during the African Humid Period.","Shifts in Earth's orbit are thought to have changed the Sahara from a wetter landscape into the desert it is today.","Rock art showing people swimming and herding cattle reflects a time, 6,000 to 11,000 years ago, when the Sahara held lakes and grasslands.","About 6,000 to 11,000 years ago, the Sahara Desert was much wetter than it is today."]$q$::jsonb, 2, $q$The goal is to use evidence from human artifacts to show the Sahara was once wetter. Only the correct answer connects the rock art to the wetter period.$q$, null),
  ($q$ei-h91$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Engineers designed a building in Zimbabwe called the Eastgate Centre.<br>• Its ventilation system was inspired by termite mounds.<br>• Termite mounds keep a stable internal temperature using a network of air channels.<br>• The Eastgate Centre has no conventional air conditioning.<br>• It uses about 10% of the energy of similar-sized buildings for climate control.$q$, $q$The student wants to highlight a practical benefit of the Eastgate Centre's nature-inspired design. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Eastgate Centre, a building in Zimbabwe, was designed without a conventional air-conditioning system.","Inspired by termite mounds, the Eastgate Centre's ventilation uses about 10% of the climate-control energy of similar buildings.","Termite mounds use a network of air channels to keep their internal temperature stable.","Engineers designed Zimbabwe's Eastgate Centre, which has no conventional air conditioning, with a ventilation system inspired by the air channels in termite mounds."]$q$::jsonb, 1, $q$The goal is to show the practical benefit of imitating nature. Only the correct answer links the termite-inspired design to its energy savings.$q$, null),
  ($q$ei-h92$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Two researchers studied the effect of class size on student achievement.<br>• Researcher A found that students in classes of 15 scored higher than those in classes of 25.<br>• Researcher B found no significant difference between classes of 22 and 25.<br>• Researcher A's study included 11,000 students over four years.<br>• Researcher B's study included 800 students over one year.$q$, $q$The student wants to present the two findings along with details that might explain why they differ. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Researcher A, studying 11,000 students over four years, found an advantage for classes of 15 over 25; Researcher B, studying 800 students for one year, found none between 22 and 25.","Researcher A found that students in classes of 15 scored higher than students in classes of 25.","Researchers A and B both studied how class size affects student achievement; Researcher A found that classes of 15 outscored classes of 25, while B found no significant difference.","Researcher B found no significant difference in achievement between students in classes of 22 and classes of 25."]$q$::jsonb, 0, $q$The goal is to explain why the studies' different conclusions might not conflict. The correct answer shows that they examined different class sizes and differed in scale, which could account for the different results.$q$, null),
  ($q$ei-h93$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Sign languages are full languages with their own grammar.<br>• American Sign Language (ASL) and British Sign Language (BSL) are not mutually intelligible.<br>• ASL is more closely related to French Sign Language.<br>• A French teacher, Laurent Clerc, helped found the first American school for the deaf in 1817.<br>• ASL developed from a mix of French Sign Language and local sign systems.$q$, $q$The student wants to explain a surprising fact about the history of American Sign Language. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["American Sign Language and British Sign Language are both full languages with their own grammar, and each is used by deaf communities in a country where English is spoken.","Laurent Clerc, a teacher from France, helped found the first American school for the deaf in 1817.","ASL developed from a mix of French Sign Language and local sign systems and has its own grammar.","Despite English being spoken in both countries, ASL is unrelated to BSL; it descends partly from French Sign Language, brought by teacher Laurent Clerc in 1817."]$q$::jsonb, 3, $q$The goal is to explain a surprising fact about ASL's origins. Only the correct answer highlights the surprise (ASL unrelated to BSL despite shared English) and explains the French connection.$q$, null),
  ($q$ei-h94$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• In 2004, researchers found the fossil of Tiktaalik roseae in the Canadian Arctic.<br>• It lived about 375 million years ago.<br>• It had gills and scales like a fish.<br>• It also had a flexible neck and sturdy fins with wrist-like bones.<br>• Scientists consider it a transitional form between fish and four-legged land animals.$q$, $q$The student wants to explain why scientists consider Tiktaalik a transitional form. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Tiktaalik roseae, which lived about 375 million years ago, was found in the Canadian Arctic in 2004.","Tiktaalik roseae, found in the Canadian Arctic in 2004 and dated to about 375 million years ago, had sturdy fins with wrist-like bones and a flexible neck.","With fish-like gills and scales but also a neck and wrist-like fin bones, Tiktaalik shows features of both fish and land animals.","Scientists studying a 375-million-year-old fossil found in 2004 consider Tiktaalik a transitional form."]$q$::jsonb, 2, $q$The goal is to explain why Tiktaalik is considered transitional. Only the correct answer shows it has both fish and land-animal features. The choice saying scientists consider Tiktaalik a transitional form states the conclusion without the evidence.$q$, null),
  ($q$ei-h95$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers examined the effect of houseplants on indoor air quality.<br>• In a sealed chamber, plants removed some pollutants over 24 hours.<br>• Typical homes exchange their indoor air with outdoor air several times a day.<br>• Researchers calculated that a home would need 10 to 1,000 plants per square meter to match the air cleaning of normal ventilation.<br>• They concluded that houseplants have little measurable effect on air quality in real homes.$q$, $q$The student wants to explain why results from sealed-chamber experiments are misleading about houseplants in real homes. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In a sealed chamber, houseplants removed some pollutants over 24 hours, while typical homes exchange their indoor air with outdoor air several times a day through ventilation.","Though plants cleaned air in sealed chambers, homes would need 10 to 1,000 per square meter to match normal ventilation, so plants do little in real homes.","Researchers examined how houseplants affect indoor air quality, including in sealed chambers.","Typical homes exchange their indoor air with outdoor air several times a day through normal ventilation."]$q$::jsonb, 1, $q$The goal is to explain why lab results don't apply to homes. Only the correct answer contrasts the lab result with the number of plants needed in a real home.$q$, null),
  ($q$ei-h96$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Poet Emily Dickinson (1830–1886) wrote nearly 1,800 poems.<br>• Fewer than a dozen were published during her lifetime.<br>• Editors of those poems often changed her punctuation, especially her frequent dashes.<br>• After her death, her sister found her manuscripts.<br>• A 1955 edition by Thomas H. Johnson was the first to restore her original punctuation.$q$, $q$The student wants to explain how readers eventually came to see Dickinson's poems with her original punctuation. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Dickinson's distinctive dashes, often removed by early editors, weren't restored in print until Thomas H. Johnson's 1955 edition.","Emily Dickinson wrote nearly 1,800 poems, but fewer than a dozen were published during her lifetime, and her sister found her manuscripts only after her death in 1886.","After Emily Dickinson's death in 1886, her sister found the manuscripts of her nearly 1,800 poems.","Editors who published Emily Dickinson's poems during her lifetime worked on fewer than a dozen of them."]$q$::jsonb, 0, $q$The goal is to explain how readers came to see her poems as she wrote them. Only the correct answer describes the editors' changes and the later restoration.$q$, null),
  ($q$ei-h97$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Earth's magnetic field has reversed many times.<br>• During a reversal, magnetic north and south switch places.<br>• The last full reversal occurred about 780,000 years ago.<br>• Evidence comes from volcanic rocks, which record the direction of the magnetic field when they cool.<br>• Reversals take an average of about 7,000 years to complete.$q$, $q$The student wants to explain how scientists know that Earth's magnetic field has reversed. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Earth's magnetic field has reversed many times, most recently about 780,000 years ago.","During a reversal of Earth's magnetic field, magnetic north and south switch places, a process that takes about 7,000 years and last occurred about 780,000 years ago.","The last full reversal of Earth's magnetic field occurred about 780,000 years ago and took thousands of years.","Volcanic rocks record the magnetic field's direction as they cool, preserving evidence of past reversals."]$q$::jsonb, 3, $q$The goal is to explain how scientists know about past reversals. Only the correct answer describes the evidence (volcanic rocks) and how it records the field.$q$, null),
  ($q$ei-h98$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The ancient city of Great Zimbabwe was built between the 11th and 15th centuries.<br>• Its stone walls were built without mortar.<br>• Some walls are 11 meters high.<br>• Gold, Chinese porcelain, and Persian pottery have been found at the site.<br>• European colonial officials in the 1800s falsely claimed it had been built by outsiders, not by Africans.$q$, $q$The student wants to provide evidence that Great Zimbabwe had trade connections with distant regions. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Great Zimbabwe, built between the 11th and 15th centuries, has mortarless stone walls up to 11 meters high, and gold has been found among the ruins of the site.","European officials in the 1800s falsely claimed that Great Zimbabwe, with its mortarless walls, was built by outsiders.","Finds of Chinese porcelain and Persian pottery at Great Zimbabwe point to trade ties reaching far beyond Africa.","Gold has been found at Great Zimbabwe, a city built between the 11th and 15th centuries."]$q$::jsonb, 2, $q$The goal is to provide evidence of long-distance trade. Only the correct answer cites goods from China and Persia and draws that conclusion.$q$, null),
  ($q$ei-h99$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Velcro was invented by Swiss engineer George de Mestral.<br>• In 1941, after a walk, he noticed burrs stuck to his dog's fur.<br>• Under a microscope, he saw that the burrs had tiny hooks.<br>• He spent years developing a fastener with hooks on one strip and loops on another.<br>• Velcro was patented in 1955.$q$, $q$The student wants to explain how an observation of nature led to the invention of Velcro. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Swiss engineer George de Mestral patented Velcro in 1955, having spent years developing a fastener with hooks on one strip and loops on another strip.","George de Mestral modeled Velcro's hook-and-loop design on the tiny hooks he saw on burrs stuck to his dog's fur.","In 1941, George de Mestral noticed burrs stuck to his dog's fur after taking a walk in Switzerland.","Velcro, patented in 1955, has hooks on one strip and loops on another strip."]$q$::jsonb, 1, $q$The goal is to explain how nature inspired the invention. Only the correct answer connects the burrs' hooks to Velcro's design.$q$, null),
  ($q$ei-h100$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers measured the stress hormone cortisol in hospital nurses.<br>• Nurses working 12-hour shifts had higher average cortisol levels than nurses working 8-hour shifts.<br>• Nurses working 12-hour shifts reported higher job satisfaction.<br>• They worked fewer days per week.<br>• They said the extra days off helped them recover.$q$, $q$The student wants to present both a drawback and an advantage of 12-hour shifts. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Although 12-hour-shift nurses had higher cortisol, they reported greater job satisfaction, citing extra days off.","Nurses working 12-hour shifts had higher average cortisol levels than nurses working 8-hour shifts.","Nurses working 12-hour shifts worked fewer days per week and said the extra days off helped them recover.","Researchers measured cortisol, a stress hormone, in nurses working 12-hour and 8-hour shifts."]$q$::jsonb, 0, $q$The goal is to present a complicated picture with a downside and an upside. Only the correct answer includes both the higher stress and the higher satisfaction.$q$, null),
  ($q$ei-h101$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The ocean absorbs about a quarter of the carbon dioxide humans release.<br>• This makes seawater more acidic.<br>• Since the 1800s, ocean acidity has increased by about 30%.<br>• Acidic water makes it harder for oysters, clams, and corals to build shells and skeletons.<br>• Some oyster hatcheries in the Pacific Northwest now add chemicals to buffer the water.$q$, $q$The student wants to describe how ocean acidification is affecting a human industry. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The ocean absorbs about a quarter of the carbon dioxide humans release, which has made seawater about 30% more acidic since the 1800s and harder for corals to build skeletons.","Acidic water makes it harder for oysters, clams, and corals to build their shells and skeletons.","Since the 1800s, ocean acidity has increased by about 30% as seawater absorbs carbon dioxide.","Ocean acidification, which hampers shell-building, has led some Pacific Northwest oyster hatcheries to buffer their water chemically."]$q$::jsonb, 3, $q$The goal is to show how acidification affects human activity. Only the correct answer describes a human response (hatcheries buffering water) to its effects.$q$, null),
  ($q$ei-h102$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Mathematician Srinivasa Ramanujan grew up in India and had little formal training.<br>• In 1913, he sent a letter with pages of theorems to G. H. Hardy at Cambridge.<br>• Hardy recognized his genius and invited him to England.<br>• Ramanujan produced nearly 3,900 results, many without proofs.<br>• Some of his results are still being proved and applied today, including in physics.$q$, $q$The student wants to emphasize Ramanujan's lasting influence on mathematics. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In 1913, Srinivasa Ramanujan, who grew up in India with little formal training, sent a letter with pages of theorems to G. H. Hardy, who invited him to Cambridge.","G. H. Hardy recognized Ramanujan's genius and invited him to England from India.","Ramanujan, largely self-taught, produced nearly 3,900 results, some of which mathematicians are still proving and applying today.","Srinivasa Ramanujan, who grew up in India, had little formal training in mathematics."]$q$::jsonb, 2, $q$The goal is to emphasize his lasting influence. Only the correct answer notes that his work is still being proved and applied.$q$, null),
  ($q$ei-h103$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• A small town replaced its traffic lights at a busy intersection with a roundabout.<br>• In the three years before, there were 41 crashes, 9 with injuries.<br>• In the three years after, there were 30 crashes, 1 with injuries.<br>• Roundabouts force drivers to slow down.<br>• They eliminate high-speed, right-angle collisions.$q$, $q$The student wants to present the effect of the roundabout on safety and explain why it occurred. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In the three years after the town replaced its traffic lights with a roundabout, there were 30 crashes at the intersection.","After the roundabout replaced traffic lights, injury crashes fell from 9 to 1, likely because roundabouts slow drivers and prevent right-angle collisions.","A small town replaced traffic lights at a busy intersection with a roundabout, which forces drivers to slow down.","Before the town replaced its traffic lights with a roundabout, there were 41 crashes at the intersection over three years, 9 of which caused injuries, compared with 30 afterward."]$q$::jsonb, 1, $q$The goal is to show both the result and a reason for it. Only the correct answer gives the drop in injury crashes and the explanation.$q$, null),
  ($q$ei-h104$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Jazz musician Mary Lou Williams (1910–1981) was a pianist, composer, and arranger.<br>• She wrote and arranged music for Duke Ellington and Benny Goodman.<br>• In the 1940s, she mentored younger musicians such as Thelonious Monk and Dizzy Gillespie.<br>• Her apartment in Harlem was a gathering place for bebop musicians.<br>• She later composed sacred jazz works, including a jazz Mass.$q$, $q$The student wants to emphasize Williams's influence on the development of bebop. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Mary Lou Williams shaped bebop by mentoring Monk and Gillespie and hosting young musicians in her Harlem apartment.","Mary Lou Williams wrote and arranged music for well-known bandleaders, including Duke Ellington and Benny Goodman.","Mary Lou Williams, a pianist, composer, and arranger who wrote for Duke Ellington and Benny Goodman, later composed sacred jazz works, including a jazz Mass.","In the 1940s, the Harlem apartment of jazz pianist Mary Lou Williams was well known among musicians."]$q$::jsonb, 0, $q$The goal is to emphasize her role in the development of bebop. Only the correct answer describes her mentoring of bebop musicians and her role as host.$q$, null),
  ($q$ei-h105$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers tested the effect of background music on reading comprehension.<br>• Participants read passages in silence, with instrumental music, or with music that had lyrics.<br>• Scores were similar for silence and instrumental music.<br>• Scores were 12% lower with music that had lyrics.<br>• Researchers suggested that lyrics compete with reading for language processing.$q$, $q$The student wants to explain which kind of background music affected reading comprehension and why. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Participants read passages in silence, with instrumental music, or with music that had lyrics.","Reading comprehension scores were similar whether participants read in silence or with instrumental music playing.","Researchers suggested that song lyrics may compete with reading for the brain's language processing.","Only music with lyrics hurt reading scores (by 12%), perhaps because lyrics compete with reading for language processing."]$q$::jsonb, 3, $q$The goal is to explain which type of music affected comprehension and why. Only the correct answer identifies the type, the effect, and the proposed reason.$q$, null),
  ($q$ei-h106$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Spider silk is stronger by weight than steel.<br>• It is also highly elastic.<br>• Spiders cannot be farmed in large numbers because they are territorial and cannibalistic.<br>• Scientists have inserted spider-silk genes into silkworms.<br>• The resulting fibers can be produced on existing silk farms.$q$, $q$The student wants to explain how scientists have tried to overcome an obstacle to producing spider silk. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Spider silk, which is stronger by weight than steel and highly elastic, would be valuable, but spiders are territorial and cannibalistic and can't be farmed in large numbers.","Spiders are territorial and cannibalistic, so they cannot be farmed in large numbers for their silk.","Since spiders can't be farmed, scientists put spider-silk genes into silkworms, whose fibers can be produced on existing silk farms.","Scientists have inserted spider-silk genes into silkworms, which are raised on silk farms."]$q$::jsonb, 2, $q$The goal is to explain how scientists addressed a problem. Only the correct answer presents both the problem (spiders can't be farmed) and the solution.$q$, null),
  ($q$ei-h107$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• In 2015, a team in Kenya found stone tools dated to 3.3 million years ago.<br>• The site is called Lomekwi 3.<br>• Before this discovery, the oldest known stone tools were about 2.6 million years old.<br>• The earliest known members of the genus Homo date to about 2.8 million years ago.<br>• The tools may have been made by an earlier hominin species.$q$, $q$The student wants to explain why the Lomekwi 3 tools challenge the idea that the first stone tools were made by members of the genus Homo. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["At a site in Kenya called Lomekwi 3, a team found stone tools dated to 3.3 million years ago.","The 3.3-million-year-old Lomekwi 3 tools predate the earliest known Homo by about 500,000 years, suggesting an earlier species made them.","In 2015, a team at a site in Kenya called Lomekwi 3 found stone tools dated to 3.3 million years ago; before that, the oldest known tools were about 2.6 million years old.","The earliest known members of the genus Homo date to about 2.8 million years ago."]$q$::jsonb, 1, $q$The goal is to explain why the find challenged the idea that Homo made the first tools. Only the correct answer compares the tools' age with the earliest Homo fossils.$q$, null),
  ($q$ei-h108$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Bats are the only mammals capable of true flight.<br>• Bats can carry viruses that make other mammals sick without becoming ill themselves.<br>• Flying raises bats' body temperatures to about 40°C.<br>• Some scientists think this daily "fever" helps bats' immune systems control viruses.<br>• Bats also have unusually long lifespans for their size.$q$, $q$The student wants to present a hypothesis about why bats can carry viruses without becoming ill. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Some scientists think the fever-like body temperature bats reach in flight helps them tolerate viruses that sicken other mammals.","Bats, the only mammals capable of true flight, have unusually long lifespans for their size.","Bats can carry viruses that make other mammals sick, and their body temperature rises to about 40°C when they fly.","Bats' immune systems are of interest to scientists because bats carry viruses that sicken other mammals."]$q$::jsonb, 0, $q$The goal is to present a hypothesis linking flight and viral tolerance. Only the correct answer states the proposed connection. The choice saying bats carry viruses and their temperature rises in flight mentions both facts but doesn't connect them.$q$, null),
  ($q$ei-h109$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Novelist Gabriel García Márquez was born in Colombia in 1927.<br>• One Hundred Years of Solitude (1967) follows seven generations of the Buendía family.<br>• The novel blends realistic detail with fantastic events, such as a character ascending to heaven while folding laundry.<br>• This style is known as magical realism.<br>• The novel has sold more than 50 million copies.$q$, $q$The student wants to explain the style of magical realism using an example from the novel. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Gabriel García Márquez, born in Colombia in 1927, published One Hundred Years of Solitude in 1967.","Gabriel García Márquez's One Hundred Years of Solitude (1967), which follows seven generations of the Buendía family, has sold more than 50 million copies.","Magical realism is a literary style associated with Gabriel García Márquez and his 1967 novel.","One Hundred Years of Solitude exemplifies magical realism, mixing realistic detail with fantastic events like a woman rising to heaven while folding laundry."]$q$::jsonb, 3, $q$The goal is to illustrate magical realism with an example from the novel. Only the correct answer defines the style and gives a specific example.$q$, null),
  ($q$ei-h110$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers tracked carbon storage in two types of forest.<br>• Old-growth forests had trees averaging 300 years old.<br>• Young plantation forests had trees averaging 30 years old.<br>• Old-growth forests stored about 2.5 times as much carbon per hectare.<br>• Plantation trees grew faster and absorbed carbon more quickly each year.$q$, $q$The student wants to present an advantage of each type of forest in relation to carbon. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Researchers compared old-growth forests, with trees averaging 300 years old, to young plantation forests.","Old-growth forests, whose trees average 300 years old, stored about 2.5 times as much carbon per hectare as plantations.","Plantation trees absorb carbon faster each year, but old-growth forests store about 2.5 times as much carbon per hectare.","Plantation forests, with trees averaging 30 years old, grew faster than old-growth forests did."]$q$::jsonb, 2, $q$The goal is to present an advantage of each forest type. Only the correct answer gives the plantations' faster absorption and the old-growth forests' greater storage.$q$, null),
  ($q$ei-h111$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• In the 1930s, the U.S. Great Plains suffered severe dust storms.<br>• Farmers had plowed up native grasses whose roots held the soil.<br>• A drought dried the exposed soil.<br>• Winds carried the soil hundreds of kilometers.<br>• The Soil Conservation Service, created in 1935, promoted planting trees as windbreaks and plowing along contours.$q$, $q$The student wants to describe both the causes of the dust storms and the measures taken to prevent them. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In the 1930s, after farmers plowed up native grasses and a drought dried the soil, winds carried soil from the U.S. Great Plains hundreds of kilometers during severe dust storms.","After plowing removed grass roots and drought dried the soil, the Soil Conservation Service promoted windbreaks and contour plowing to hold it in place.","Farmers on the Great Plains had plowed up native grasses before a drought dried out the exposed soil.","The Soil Conservation Service, created in 1935, was a response to severe dust storms on the Great Plains."]$q$::jsonb, 1, $q$The goal is to describe causes and responses. Only the correct answer includes both the causes (plowing, drought) and the remedies (windbreaks, contour plowing).$q$, null),
  ($q$ei-h112$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Octopuses have about 500 million neurons.<br>• About two-thirds of these neurons are in their arms, not their central brain.<br>• An octopus arm can continue to react to touch after being severed.<br>• Arms can explore and grasp objects without direction from the brain.<br>• Researchers describe octopus intelligence as "distributed."$q$, $q$The student wants to explain what researchers mean when they describe octopus intelligence as "distributed". Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["With two-thirds of their neurons in their arms, octopuses have arms that can explore and grasp objects without direction from the brain.","Octopuses have about 500 million neurons, a large number for an invertebrate animal.","Researchers describe the intelligence of octopuses, which have about 500 million neurons, as \"distributed,\" and a severed arm can even continue to react to touch.","An octopus arm can continue to react to touch even after it has been severed from the body."]$q$::jsonb, 0, $q$The goal is to explain what "distributed" intelligence means. Only the correct answer explains that neurons are concentrated in the arms and that arms act independently.$q$, null),
  ($q$ei-h113$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The London Underground opened in 1863.<br>• It was the world's first underground railway.<br>• Early trains were pulled by steam locomotives.<br>• Smoke filled the tunnels, and some stations had openings to the street to let it escape.<br>• Electric trains were introduced in 1890 on a deeper line.$q$, $q$The student wants to describe a problem with the early Underground and how technology later addressed it. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The London Underground, which opened in 1863, was the world's first underground railway.","The London Underground, which opened in 1863 as the world's first underground railway, used steam locomotives until electric trains were introduced in 1890 on a deeper line.","In 1890, electric trains were introduced on a deeper line of the London Underground, which opened in 1863.","Steam trains on the early Underground filled tunnels with smoke, so some stations had openings to let it out—a problem electric trains, from 1890, avoided."]$q$::jsonb, 3, $q$The goal is to describe a problem with early trains and how it was later addressed. Only the correct answer includes both the smoke problem and the electric solution.$q$, null),
  ($q$ei-h114$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researcher Nalini Nadkarni studies forest canopies.<br>• She found that some trees grow roots from their branches into the soil that collects in the canopy.<br>• This canopy soil forms from decomposing mosses and other plants.<br>• The aerial roots let trees absorb nutrients from high above the ground.<br>• Her findings showed that canopies are complex ecosystems, not just collections of leaves.$q$, $q$The student wants to present one of Nadkarni's findings and explain its broader significance. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Nalini Nadkarni studies forest canopies, where soil forms from decomposing mosses and other plants and where some trees absorb nutrients from high above the ground.","Canopy soil, which forms from decomposing mosses and other plants, collects high above the forest floor.","Nadkarni found trees growing roots from branches into canopy soil, showing that canopies are complex ecosystems.","Researcher Nalini Nadkarni found that some trees absorb nutrients from high above the ground."]$q$::jsonb, 2, $q$The goal is to present a finding and its broader significance. Only the correct answer includes the aerial roots and what they reveal about canopies.$q$, null),
  ($q$ei-h115$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Indian Ocean tsunami of 2004 killed more than 225,000 people.<br>• There was no tsunami warning system in the Indian Ocean at the time.<br>• The Pacific Ocean had had a warning system since 1949.<br>• In 2006, an Indian Ocean warning system began operating.<br>• It uses seismic sensors and ocean buoys to detect tsunamis.$q$, $q$The student wants to describe a change that followed the 2004 tsunami and the gap it addressed. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The 2004 Indian Ocean tsunami killed more than 225,000 people, and in 2006 a warning system using seismic sensors and ocean buoys began operating in the Indian Ocean.","In 2004, the Indian Ocean, unlike the Pacific, had no tsunami warning system; one was established in 2006 using seismic sensors and buoys.","The Pacific Ocean has had a tsunami warning system since 1949, which uses sensors to detect tsunamis.","A tsunami warning system that began operating in the Indian Ocean in 2006 uses seismic sensors and ocean buoys."]$q$::jsonb, 1, $q$The goal is to explain how the 2004 disaster led to change. Only the correct answer describes the missing system and the new system created afterward.$q$, null),
  ($q$ei-h116$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers tested whether honeybees can understand zero.<br>• Bees were trained to choose the image with fewer dots.<br>• When then shown an image with no dots, bees chose it over images with one or more dots.<br>• Understanding zero as a number was once thought to be limited to humans and a few primates.<br>• Bee brains contain fewer than one million neurons.$q$, $q$The student wants to emphasize why the finding about honeybees is surprising. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Bees, with fewer than a million neurons, treated an empty image as \"fewer\" than one dot—suggesting an understanding of zero once thought limited to primates.","Honeybees, whose brains contain fewer than one million neurons, were trained to choose the image with fewer dots and were then shown an image containing no dots at all.","Understanding zero as a number was once thought to be limited to humans and a few other primates.","Bee brains, which contain fewer than one million neurons, are much smaller than primate brains."]$q$::jsonb, 0, $q$The goal is to emphasize how surprising the finding is. Only the correct answer combines the bees' small brains, their behavior, and the earlier belief about zero.$q$, null),
  ($q$ei-h117$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Some cities are adding "green roofs"—rooftops covered with plants.<br>• Green roofs absorb rainwater, reducing runoff into storm drains.<br>• They also insulate buildings, lowering heating and cooling costs.<br>• Installing a green roof costs about twice as much as a conventional roof.<br>• Green roofs can last up to twice as long as conventional roofs.$q$, $q$The student wants to respond to the concern that green roofs are too expensive. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Green roofs, which are rooftops covered with plants, absorb rainwater and reduce runoff into city storm drains.","Some cities are adding green roofs, which insulate buildings and lower their heating and cooling costs.","Installing a green roof, a rooftop covered with plants, costs about twice as much as a conventional roof.","Green roofs cost about twice as much to install, but they can last twice as long and cut heating and cooling costs."]$q$::jsonb, 3, $q$The goal is to address the cost objection. Only the correct answer acknowledges the higher cost and offers financial counterpoints.$q$, null),
  ($q$ei-h118$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Sculptor Augusta Savage (1892–1962) was a leading artist of the Harlem Renaissance.<br>• In 1923, she was rejected from a summer art program in France because she was Black.<br>• She publicly protested the decision.<br>• She later founded the Savage Studio of Arts and Crafts in Harlem.<br>• Her students included painters Jacob Lawrence and Gwendolyn Knight.$q$, $q$The student wants to emphasize Savage's role as a teacher of other artists. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Sculptor Augusta Savage was a leading artist of the Harlem Renaissance who lived from 1892 to 1962.","Augusta Savage, a sculptor of the Harlem Renaissance who was rejected from a program in France in 1923 because she was Black, later founded a studio in Harlem.","Augusta Savage nurtured the next generation of artists, teaching Jacob Lawrence and Gwendolyn Knight at her Harlem studio.","Augusta Savage founded the Savage Studio of Arts and Crafts in Harlem after being rejected from a program in France."]$q$::jsonb, 2, $q$The goal is to emphasize her influence as a teacher. Only the correct answer names her notable students.$q$, null),
  ($q$ei-h119$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Mississippi River delta is losing land.<br>• Since the 1930s, Louisiana has lost about 5,000 square kilometers of coastal land.<br>• Levees built to prevent flooding also stop the river from depositing sediment on the delta.<br>• Without new sediment, the land sinks and erodes.<br>• Engineers are building channels to divert sediment-rich water back into the wetlands.$q$, $q$The student wants to explain how engineers are trying to address a cause of land loss in the delta. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Since the 1930s, Louisiana has lost about 5,000 square kilometers of coastal land in the Mississippi River delta, where levees were built to prevent flooding.","Because levees block the sediment that rebuilds the delta, engineers are building channels to send sediment-rich water back into the wetlands.","Levees built along the Mississippi River prevent flooding in the communities along its banks.","Without new sediment, the land in the Mississippi River delta sinks and erodes over time."]$q$::jsonb, 1, $q$The goal is to explain the engineers' solution and the problem it addresses. Only the correct answer connects levees to the loss of sediment and describes the diversion channels.$q$, null),
  ($q$ei-h120$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Japanese bullet train, or Shinkansen, began service in 1964.<br>• Its trains reach speeds of up to 320 kilometers per hour.<br>• In nearly 60 years of operation, no passenger has died in a derailment or collision.<br>• Its trains have an average delay of under one minute.<br>• Earthquake sensors automatically stop trains when tremors are detected.$q$, $q$The student wants to emphasize the safety record of the Shinkansen. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In nearly 60 years, no Shinkansen passenger has died in a derailment or collision, aided by sensors that stop trains during earthquakes.","Japan's Shinkansen, which began service in 1964 and reaches speeds of up to 320 kilometers per hour, has trains with an average delay of under one minute.","The trains of the Shinkansen, Japan's bullet train system, have an average delay of under one minute.","Earthquake sensors on Japan's Shinkansen automatically stop trains when they detect tremors."]$q$::jsonb, 0, $q$The goal is to emphasize the system's safety record. Only the correct answer gives the record and a safety feature contributing to it.$q$, null),
  ($q$ei-h121$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers studied whether handwriting notes helps learning more than typing.<br>• Students who typed notes recorded more words, often copying lectures nearly verbatim.<br>• Students who wrote by hand recorded fewer words but summarized in their own words.<br>• On conceptual questions, the handwriting group scored higher.<br>• On factual questions, the groups scored about the same.$q$, $q$The student wants to present the study's findings and a possible explanation for them. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Students who typed their notes recorded more words than students who wrote by hand, often copying lectures nearly verbatim.","Researchers compared students who took notes by hand with those who typed, testing both conceptual and factual understanding.","On factual questions, students who typed notes and students who wrote them by hand scored about the same.","Handwriting students, forced to summarize rather than copy, outscored typists on conceptual questions, though the groups tied on factual ones."]$q$::jsonb, 3, $q$The goal is to present the findings with an explanation. Only the correct answer gives the conceptual advantage, the tie on factual questions, and the reason (summarizing).$q$, null),
  ($q$ei-h122$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Nobel Prize–winning chemist Marie Curie discovered polonium and radium.<br>• She named polonium after Poland, her homeland.<br>• Poland was not an independent country at the time; it was divided among Russia, Prussia, and Austria.<br>• Curie hoped the name would draw attention to Poland's lack of independence.<br>• Poland regained independence in 1918.$q$, $q$The student wants to explain the political meaning behind the name Curie chose for polonium. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Marie Curie, a Nobel Prize–winning chemist from Poland, discovered both polonium and radium, and Poland regained its independence in 1918.","Poland, Marie Curie's homeland, regained its independence in 1918 after being divided among Russia, Prussia, and Austria.","Curie named polonium after Poland, then divided among three empires, hoping to draw attention to its lack of independence.","Marie Curie discovered polonium and named it after Poland, the country where she was born."]$q$::jsonb, 2, $q$The goal is to explain the political significance of the name. Only the correct answer includes Poland's divided status and Curie's intention.$q$, null),
  ($q$ei-h123$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Some desert beetles in Namibia collect water from fog.<br>• Their backs have bumps that attract water droplets and grooves that repel water.<br>• Droplets grow on the bumps and roll down the grooves into the beetles' mouths.<br>• Engineers have used this design to create fog-harvesting nets.<br>• In some villages, such nets collect hundreds of liters of water a day.$q$, $q$The student wants to explain how a feature of the Namibian beetle has been applied to benefit people. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Some desert beetles in Namibia collect water from fog: droplets form on bumps on their backs and roll down water-repelling grooves into the beetles' mouths.","Engineers have copied the Namibian beetle's water-attracting bumps and water-repelling grooves to make nets that collect hundreds of liters of water daily.","Droplets grow on bumps on a Namibian beetle's back and roll down grooves into its mouth.","In some villages, fog-harvesting nets collect hundreds of liters of water each day for residents."]$q$::jsonb, 1, $q$The goal is to explain how the beetle has benefited humans. Only the correct answer links the beetle's design to the nets and their output.$q$, null),
  ($q$ei-h124$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers studied children's willingness to share.<br>• Children who were given a puppet to care for shared more stickers afterward than those who were not.<br>• The effect lasted only for the session in which children cared for the puppet.<br>• Children who watched an adult share showed no change.<br>• Researchers suggested that caregiving experiences may temporarily increase generosity.$q$, $q$The student wants to present a key finding of the study while noting a limitation of that finding. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Caring for a puppet increased children's sharing, but only during that session—suggesting caregiving may boost generosity temporarily.","Children who watched an adult share stickers showed no change in their own willingness to share.","Researchers studied whether caring for a puppet changed children's willingness to share stickers, and they also tested children who watched an adult share.","Children who were given a puppet to care for shared more stickers afterward than children who were not."]$q$::jsonb, 0, $q$The goal is to present a finding along with its limitation. Only the correct answer includes the increase in sharing and the fact that it didn't last.$q$, null),
  ($q$ei-h125$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Hurricanes draw energy from warm ocean water.<br>• They usually weaken over land.<br>• In 2017, Hurricane Harvey stalled over Houston for four days.<br>• It dropped more than 1,500 millimeters of rain in some areas.<br>• Scientists found that warmer Gulf of Mexico waters made the rainfall about 15% heavier.$q$, $q$The student wants to present evidence of a link between ocean temperatures and Hurricane Harvey's rainfall. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In 2017, Hurricane Harvey stalled over Houston for four days, dropping more than 1,500 millimeters of rain in places.","Hurricanes, which draw their energy from warm ocean water, usually weaken once they move over land.","Hurricane Harvey, which struck Houston in 2017, drew energy from warm ocean water in the Gulf of Mexico.","Scientists found that warmer Gulf waters made Hurricane Harvey's record rainfall over Houston about 15% heavier."]$q$::jsonb, 3, $q$The goal is to show a connection between warm water and rainfall. Only the correct answer states the scientists' finding that warmer water increased Harvey's rainfall.$q$, null),
  ($q$ei-h126$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers in Kenya tested whether beehive fences could protect farms from elephants.<br>• Elephants avoid bees, which can sting them around their eyes and trunks.<br>• Farms with beehive fences had 80% fewer elephant raids than unfenced farms.<br>• Farmers also earned income by selling honey from the hives.<br>• Beehive fences cost less than electric fences.$q$, $q$The student wants to emphasize two benefits that beehive fences provided to farmers. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Elephants avoid bees, which can sting them around their eyes and trunks, so beehives can deter them.","Researchers in Kenya tested whether beehive fences could protect farms from raids by elephants.","Beehive fences cut elephant raids by 80% and also gave farmers honey to sell.","Beehive fences cost less than electric fences and use bees that elephants try to avoid."]$q$::jsonb, 2, $q$The goal is to emphasize two benefits for farmers. Only the correct answer includes both the reduction in raids and the honey income.$q$, null),
  ($q$ei-h127$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Amazon River carries about 20% of all river water that flows into the world's oceans.<br>• It has no bridges across its main channel.<br>• Much of the river runs through sparsely populated rainforest.<br>• Its riverbanks shift frequently due to seasonal flooding.<br>• Ferries and boats carry people and goods across the river.$q$, $q$The student wants to explain why the Amazon River has no bridges across its main channel. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Amazon River carries about 20% of all river water that flows into the world's oceans.","The Amazon has no bridges across its main channel, partly because it crosses sparsely populated land and its banks shift with seasonal floods.","Ferries and boats carry people and goods across the Amazon River, which carries about 20% of all river water flowing into the oceans and runs through sparsely populated rainforest.","The Amazon River's banks shift frequently because of the seasonal flooding that occurs there."]$q$::jsonb, 1, $q$The goal is to explain why there are no bridges. Only the correct answer gives reasons for the absence of bridges.$q$, null),
  ($q$ei-h128$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• In medieval Europe, books were copied by hand.<br>• Copying a single Bible could take a scribe more than a year.<br>• Johannes Gutenberg developed a printing press with movable metal type around 1440.<br>• His press could produce about 3,600 pages a day.<br>• By 1500, an estimated 20 million books had been printed in Europe.$q$, $q$The student wants to contrast the speed of hand copying with that of Gutenberg's press. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Where a scribe might need a year to copy one Bible, Gutenberg's press could print about 3,600 pages a day.","Johannes Gutenberg developed a printing press with movable metal type around 1440.","By 1500, an estimated 20 million books had been printed in Europe, which had once relied on scribes.","In medieval Europe, books were copied by hand, so producing a book required a great deal of time."]$q$::jsonb, 0, $q$The goal is to contrast the speed of the two methods. Only the correct answer compares the time required for hand copying with the press's daily output.$q$, null),
  ($q$ei-h129$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The axial tilt of Earth is about 23.5 degrees.<br>• This tilt causes the seasons.<br>• Mars has a similar tilt, about 25 degrees, so it also has seasons.<br>• A Martian year lasts about 687 Earth days.<br>• As a result, each Martian season lasts roughly twice as long as an Earth season.$q$, $q$The student wants to describe a similarity and a difference between seasons on Earth and on Mars. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Earth's axial tilt of about 23.5 degrees causes the planet's seasons.","Mars has an axial tilt of about 25 degrees, similar to Earth's tilt of about 23.5 degrees—the tilt that is responsible for Earth's seasons.","A year on Mars lasts about 687 Earth days, much longer than a year on Earth.","Like Earth, Mars has seasons because of its tilt, but with a 687-day year, each Martian season lasts about twice as long."]$q$::jsonb, 3, $q$The goal is to give both a similarity and a difference. Only the correct answer states that both planets have tilt-driven seasons and that Martian seasons are longer.$q$, null),
  ($q$ei-h130$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers tested drivers in a simulator.<br>• Drivers talking on a hands-free phone missed twice as many traffic signals as undistracted drivers.<br>• Drivers talking with a passenger did not show this effect.<br>• Passengers tended to stop talking when traffic became difficult.<br>• People on the phone could not see the traffic and kept talking.$q$, $q$The student wants to explain why talking on a hands-free phone affected drivers differently than talking with a passenger. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Drivers talking on a hands-free phone missed twice as many traffic signals as undistracted drivers in a simulator.","Drivers talking with a passenger in a simulator did not miss more traffic signals than undistracted drivers did.","Unlike phone callers, passengers can see traffic and pause when driving gets hard, which may be why only hands-free calls doubled missed signals.","Researchers tested drivers in a simulator and found that those talking on a hands-free phone missed twice as many traffic signals as undistracted drivers did."]$q$::jsonb, 2, $q$The goal is to explain why the two kinds of conversation had different effects. Only the correct answer gives the explanation (passengers adjust to traffic).$q$, null),
  ($q$ei-h131$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Nazca Lines are large designs etched into the desert in southern Peru.<br>• They were made between 500 BCE and 500 CE.<br>• Some depict animals, such as a monkey and a hummingbird, and are hundreds of meters long.<br>• The designs are best seen from the air or nearby hills.<br>• The region's dry, windless climate has preserved them for centuries.$q$, $q$The student wants to explain why the Nazca Lines have survived for so long. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Nazca Lines, made between 500 BCE and 500 CE, are large designs etched into the desert in southern Peru.","The Nazca Lines have survived for centuries because the region's dry, windless climate has preserved them.","Some Nazca Lines depict animals, such as a monkey and a hummingbird, and are hundreds of meters long.","The Nazca Lines, which include designs of animals, are best seen from the air or from nearby hills."]$q$::jsonb, 1, $q$The goal is to explain why the lines still exist. Only the correct answer gives the reason for their preservation.$q$, null),
  ($q$ei-h132$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers studied how much water two crops need.<br>• Producing one kilogram of rice requires about 2,500 liters of water.<br>• Producing one kilogram of millet requires about 1,500 liters.<br>• Millet tolerates drought and poor soil.<br>• India declared 2023 the International Year of Millets to encourage its cultivation.$q$, $q$The student wants to argue that millet is better suited than rice to regions with limited water. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Millet needs about 1,000 fewer liters of water per kilogram than rice and tolerates drought, making it suited to water-scarce regions.","Producing one kilogram of rice requires about 2,500 liters of water, and in 2023, which India declared the International Year of Millets, farmers were encouraged to grow millet.","India declared 2023 the International Year of Millets to encourage farmers to grow the crop.","Millet, a crop that tolerates drought and poor soil, was the focus of the International Year of Millets."]$q$::jsonb, 0, $q$The goal is to argue that millet suits dry regions. Only the correct answer compares water needs and notes drought tolerance.$q$, null),
  ($q$ei-h133$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers measured how long people could hold a plank exercise.<br>• Participants who were told the exercise would last 60 seconds held it longer than those not given a time.<br>• Participants who were told it would last 30 seconds stopped soon after 30 seconds.<br>• The researchers concluded that expectations affect physical endurance.<br>• All participants were similarly fit.$q$, $q$The student wants to present the researchers' conclusion and the evidence that supports it. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Participants told that a plank would last 60 seconds held it longer than those given no time, while those told it would last 30 seconds stopped soon after 30 seconds.","Researchers measured how long participants, all similarly fit, could hold a plank exercise.","Participants who were told that the plank would last 30 seconds stopped soon after that time had passed.","Because similarly fit participants stopped near whatever time they expected, researchers concluded that expectations shape endurance."]$q$::jsonb, 3, $q$The goal is to present the conclusion with its supporting evidence. Only the correct answer notes that participants were equally fit (ruling out fitness) and that they stopped near their expected times.$q$, null),
  ($q$ei-h134$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Ancient Polynesian navigators sailed thousands of kilometers across the Pacific.<br>• They did not use compasses or charts.<br>• They read the stars, ocean swells, and the flight paths of birds.<br>• In 1976, the canoe Hōkūleʻa sailed from Hawaii to Tahiti using only traditional methods.<br>• The voyage helped disprove claims that Polynesians had settled islands by accident.$q$, $q$The student wants to explain the historical significance of the Hōkūleʻa voyage. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Ancient Polynesian navigators sailed thousands of kilometers without compasses or charts, reading the stars, ocean swells, and the flight paths of birds instead.","Polynesian navigators read the stars, ocean swells, and the flight paths of birds to find their way.","The 1976 voyage of Hōkūleʻa, guided only by traditional methods, helped show that Polynesians settled distant islands deliberately.","In 1976, the canoe Hōkūleʻa sailed from Hawaii to Tahiti across thousands of kilometers of ocean."]$q$::jsonb, 2, $q$The goal is to explain the significance of the Hōkūleʻa voyage. Only the correct answer links it to disproving the accidental-settlement claim.$q$, null),
  ($q$ei-h135$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The quagga was a type of zebra with stripes only on its front half.<br>• It lived in South Africa and was hunted to extinction by 1883.<br>• DNA studies showed the quagga was a subspecies of the plains zebra.<br>• The Quagga Project has bred plains zebras with fewer stripes.<br>• After several generations, some foals closely resemble quaggas.$q$, $q$The student wants to explain why scientists believed they could re-create the quagga's appearance through breeding. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The quagga, a zebra with stripes only on its front half, lived in South Africa until 1883.","Because the extinct quagga was a plains-zebra subspecies, breeders have produced quagga-like foals from plains zebras with fewer stripes.","The Quagga Project has bred plains zebras with fewer stripes over several generations, and some of the resulting foals now closely resemble the extinct quagga.","DNA studies showed that the quagga, which was hunted to extinction by 1883, was a type of zebra."]$q$::jsonb, 1, $q$The goal is to explain why the breeding project is possible. Only the correct answer connects the DNA finding (quagga as plains-zebra subspecies) to the project's approach.$q$, null),
  ($q$ei-h136$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers studied the sleep of college students during exams.<br>• Students who slept fewer than six hours before an exam scored 10% lower on average.<br>• Many students believed that staying up late to study would improve their scores.<br>• Students who slept at least eight hours scored highest.<br>• Sleep helps the brain consolidate memories.$q$, $q$The student wants to challenge a common belief among students about studying late. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Contrary to many students' belief, those who slept fewer than six hours before exams scored 10% lower on average.","Students who slept at least eight hours before an exam scored highest, researchers found.","Researchers studied the sleep of college students during exam periods to learn how it affected scores.","Sleep helps the brain consolidate memories, which is important for students preparing for exams."]$q$::jsonb, 0, $q$The goal is to challenge a common belief. Only the correct answer states the belief and the evidence against it.$q$, null),
  ($q$ei-h137$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Venus flytrap is native to a small area of North and South Carolina.<br>• It grows in nutrient-poor soil.<br>• It catches insects to obtain nitrogen.<br>• Its trap closes only if a trigger hair is touched twice within about 20 seconds.<br>• This prevents the plant from wasting energy on raindrops or debris.$q$, $q$The student wants to explain how the Venus flytrap avoids closing on things other than prey. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Venus flytrap, native to a small area of the Carolinas, catches insects to get nitrogen missing from its soil, closing its trap when a trigger hair is touched.","The Venus flytrap grows in nutrient-poor soil in a small area of North and South Carolina.","The Venus flytrap's trap closes when a trigger hair is touched, allowing it to catch insects.","By closing only when a trigger hair is touched twice within about 20 seconds, the flytrap avoids wasting energy on raindrops or debris."]$q$::jsonb, 3, $q$The goal is to explain how the flytrap avoids false triggers. Only the correct answer describes the two-touch mechanism and its purpose.$q$, null),
  ($q$ei-h138$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• In 2014, a landslide in Washington State destroyed the community of Oso.<br>• Heavy rain had saturated the hillside.<br>• The hill had experienced smaller landslides for decades.<br>• A 1999 report had warned of the risk of a large failure.<br>• After the disaster, the state increased funding for landslide mapping.$q$, $q$The student wants to emphasize that the disaster had been anticipated but that action was taken only afterward. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In 2014, after heavy rain saturated a hillside that had experienced smaller landslides for decades, a landslide destroyed the community of Oso in Washington State.","The hillside near Oso, Washington, had experienced smaller landslides for decades before 2014.","Although a 1999 report had warned of the danger at Oso, it was only after the 2014 disaster that the state increased funding for landslide mapping.","A report written in 1999 warned of the risk of a large landslide on the hill near Oso, Washington."]$q$::jsonb, 2, $q$The goal is to show that warnings preceded the disaster and that action followed only afterward. Only the correct answer includes both.$q$, null),
  ($q$ei-h139$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Galápagos marine iguana is the only lizard that forages in the sea.<br>• It eats algae growing on underwater rocks.<br>• It swallows a great deal of salt while feeding.<br>• Special glands near its nose remove excess salt.<br>• It expels the salt by sneezing.$q$, $q$The student wants to explain how the marine iguana copes with a challenge created by its diet. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Galápagos marine iguana is the only lizard in the world that forages for food in the sea.","Marine iguanas, which swallow salt while eating underwater algae, rid themselves of it through nasal glands and by sneezing.","Galápagos marine iguanas, the only lizards that forage in the sea, eat algae growing on underwater rocks and have special glands near their noses.","Marine iguanas of the Galápagos have special glands near their noses."]$q$::jsonb, 1, $q$The goal is to explain how the iguana deals with a challenge of its diet. Only the correct answer includes both the challenge (swallowing salt) and the solution.$q$, null),
  ($q$ei-h140$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$For decades, ecologists assumed that the decline of the region's songbirds was driven mainly by the loss of breeding habitat in North American forests. A 2019 tracking study complicated this picture: many of the birds were dying not in their summer ranges but during migration and in their wintering grounds in Central America. ______ conservation efforts focused only on protecting northern forests were unlikely, on their own, to reverse the decline.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Accordingly,","Nevertheless,","Similarly,","For instance,"]$q$::jsonb, 0, $q$The final sentence states a conclusion that follows from the study's finding that birds were dying elsewhere. "Accordingly" signals that the conclusion is a logical consequence. "Nevertheless" signals contrast, "Similarly" signals a parallel point, and "For instance" introduces an example.$q$, null),
  ($q$ei-h141$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The novelist's early books were praised for their lush, elaborate sentences, some of which ran for more than a page. Her later work, written after she began teaching high school English, is strikingly different. ______ her final novel contains hardly a sentence longer than fifteen words.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["However,","Regardless,","Meanwhile,","Indeed,"]$q$::jsonb, 3, $q$The final sentence strengthens the claim that her later work is "strikingly different" by giving an emphatic illustration. "Indeed" signals that the sentence reinforces and intensifies the previous point. "However" would signal a contrast with the previous sentence, which is not present.$q$, null),
  ($q$ei-h142$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Most species of bats navigate by echolocation, emitting high-pitched calls and listening for the echoes. Fruit bats of the genus Pteropus, ______ rely largely on their keen eyesight and sense of smell to find the ripe fruit they eat.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["as a result,","in addition,","by contrast,","for example,"]$q$::jsonb, 2, $q$The sentence presents fruit bats as an exception to the echolocation described for most species. "By contrast" correctly signals this difference. The other options signal cause, addition, or example.$q$, null),
  ($q$ei-h143$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The proposed dam would provide electricity for nearly a million homes and protect downstream towns from seasonal floods. ______ it would also flood a valley that contains some of the oldest rock art in the region, a fact that has led archaeologists to oppose the project.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus","Yet","Likewise,","In other words,"]$q$::jsonb, 1, $q$The second sentence presents a drawback that stands in tension with the benefits listed in the first. "Yet" signals this contrast. "Thus" signals a result, "Likewise" a similarity, and "In other words" a restatement.$q$, null),
  ($q$ei-h144$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$To test whether crows can recognize individual human faces, researchers wore a particular mask while trapping and banding several birds. Years later, crows in the area still scolded and dive-bombed anyone wearing that mask, even though most of them had never been trapped themselves. ______ the birds seemed to have learned to fear the mask from other crows.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In other words,","On the other hand,","Even so,","Second,"]$q$::jsonb, 0, $q$The last sentence restates and interprets the observation in the previous sentence: crows that had never been trapped still reacted to the mask, meaning they learned from others. "In other words" signals this clarifying restatement.$q$, null),
  ($q$ei-h145$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The first commercial jet airliner entered service in 1952 and could carry thirty-six passengers. ______ within two years, several of the planes had broken apart in midair, and investigators eventually traced the failures to metal fatigue around the aircraft's square windows.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Moreover,","Similarly,","In summary,","Tragically, however,"]$q$::jsonb, 3, $q$The second sentence describes a disastrous turn that contrasts with the milestone described in the first. "Tragically, however" captures both the contrast and the tone. "Moreover" adds a similar point, "Similarly" draws a parallel, and "In summary" introduces a conclusion.$q$, null),
  ($q$ei-h146$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Many plants defend themselves against insects with chemical weapons rather than thorns or tough leaves. ______ when caterpillars begin chewing on a tomato plant, the plant produces compounds that interfere with the insects' digestion and releases airborne signals that prompt neighboring plants to do the same.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["However,","Therefore,","For example,","In contrast,"]$q$::jsonb, 2, $q$The second sentence gives a specific case of a plant using chemical defenses, illustrating the general claim in the first sentence. "For example" signals this.$q$, null),
  ($q$ei-h147$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The museum's new climate-control system was designed to keep humidity in the galleries between 45 and 55 percent. ______ it held humidity at exactly 50 percent for the first six months, until a faulty sensor caused levels to spike during an unusually wet August.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Conversely,","Initially,","Nonetheless,","Similarly,"]$q$::jsonb, 1, $q$The second sentence describes how the system performed at first, before a later problem. "Initially" signals the first stage of a sequence that is later interrupted. The other choices signal contrast or similarity, which do not fit.$q$, null),
  ($q$ei-h148$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The candidate's campaign had raised more money than any other in the state's history, and early polls showed her with a comfortable lead. ______ she lost the election by nearly eight percentage points, a result that analysts attributed to low turnout among her supporters.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Still,","Hence,","Likewise,","Specifically,"]$q$::jsonb, 0, $q$The loss contradicts what the fundraising and early polls would lead one to expect. "Still" signals that the outcome occurred despite those advantages. "Hence" signals a result, "Likewise" a similarity, and "Specifically" an elaboration.$q$, null),
  ($q$ei-h149$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Critics have argued that the new prize rewards commercial success rather than literary merit. ______ several of this year's finalists were best-selling novels, but the winning book—a slim collection of experimental poems—had sold fewer than two thousand copies before the announcement.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Consequently,","In addition,","In other words,","Granted,"]$q$::jsonb, 3, $q$The second sentence concedes part of the critics' point (some finalists were best sellers) before undercutting it (the winner was not). "Granted" signals such a concession. The other choices signal a result, an addition, or a restatement.$q$, null),
  ($q$ei-h150$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$In 1928, Alexander Fleming noticed that a mold contaminating one of his bacterial cultures had killed the bacteria around it. He published his observation the following year, but he was unable to purify the active substance in large quantities. ______ it was not until the early 1940s that a team at Oxford developed a way to produce penicillin as a practical drug.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In comparison,","Even so,","As a result,","For instance,"]$q$::jsonb, 2, $q$Because Fleming could not purify the substance, a practical drug had to wait for later work. "As a result" signals this cause-and-effect relationship. "Even so" would wrongly suggest that the delay happened despite his difficulty.$q$, null),
  ($q$ei-h151$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The language has no word that corresponds exactly to the English word "blue." ______ it has separate words for the light blue of the sky and the dark blue of deep water, and speakers treat these as two distinct colors, much as English speakers treat red and pink.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","Rather,","Likewise,","Ultimately,"]$q$::jsonb, 1, $q$The second sentence corrects a possible misunderstanding created by the first: the language doesn't lack words for blue; it divides blue into two colors. "Rather" signals this corrective alternative.$q$, null),
  ($q$ei-h152$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The researchers had planned to collect soil samples from all forty sites in the national park. ______ flooding closed the park's southern roads for most of the summer, and they were able to reach only twenty-six sites.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["However,","Accordingly,","Moreover,","In fact,"]$q$::jsonb, 0, $q$The second sentence explains how the plan was disrupted, which contrasts with the original intention. "However" signals this contrast.$q$, null),
  ($q$ei-h153$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The ancient Romans built many of their harbors with a type of concrete that has survived two thousand years of pounding waves. Modern concrete, ______ often begins to crumble after only a few decades of exposure to seawater.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["for example,","in turn,","as such,","by comparison,"]$q$::jsonb, 3, $q$The sentence contrasts modern concrete with the durable Roman concrete. "By comparison" signals this contrast. "For example" would present modern concrete as an example of the Roman concrete's durability.$q$, null),
  ($q$ei-h154$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The startup's founders believed that customers would pay a premium for groceries delivered within fifteen minutes. ______ they raised more than $100 million to build a network of small warehouses in dense urban neighborhoods.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["On the contrary,","Similarly,","To that end,","Admittedly,"]$q$::jsonb, 2, $q$The second sentence describes an action taken in order to achieve the goal implied in the first (fast delivery). "To that end" signals an action taken for a stated purpose.$q$, null),
  ($q$ei-h155$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Rising ocean temperatures cause corals to expel the algae that live in their tissues and supply most of their food. Without the algae, corals turn white and begin to starve. ______ if temperatures return to normal within a few weeks, the algae can recolonize the coral, and it may recover.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Therefore,","However,","In other words,","Furthermore,"]$q$::jsonb, 1, $q$The last sentence introduces a hopeful exception that contrasts with the grim consequences just described. "However" signals this contrast. "Therefore" signals a result, "In other words" a restatement, and "Furthermore" an additional similar point.$q$, null),
  ($q$ei-h156$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$In her early career, the photographer worked exclusively in black and white, arguing that color distracted viewers from form and light. ______ she began using color film in the 1970s, she largely abandoned black and white and never returned to it.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Once","Although","Unless","Whereas"]$q$::jsonb, 0, $q$The sentence describes what happened after she began using color: she stopped using black and white. "Once" signals that one event happened and the other followed from that point on. "Although" would set up a contrast that the clauses don't support, "Unless" sets up a condition, and "Whereas" sets up a comparison.$q$, null),
  ($q$ei-h157$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The library's new policy allows patrons to borrow tools, musical instruments, and even fishing rods. ______ the most popular item in the collection, according to the head librarian, is a high-quality telescope that has a waiting list of more than two hundred people.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Consequently,","Nevertheless,","Similarly,","Notably,"]$q$::jsonb, 3, $q$The second sentence highlights an especially interesting detail about the new collection. "Notably" signals that a remarkable point is being drawn out. There is no cause-and-effect, contrast, or similarity relationship.$q$, null),
  ($q$ei-h158$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$If the river's water level drops below a certain point, the cooling system at the power plant cannot function. The plant's operators must therefore reduce its output during droughts; ______ they risk damaging the reactor.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["similarly,","for instance,","otherwise,","meanwhile,"]$q$::jsonb, 2, $q$The final clause describes what would happen if the operators did not reduce output. "Otherwise" signals this alternative, undesirable consequence.$q$, null),
  ($q$ei-h159$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The heavy clay soil in the valley holds water well, which allows crops to survive long dry spells. ______ it drains poorly during wet years, and fields can remain waterlogged for weeks after a storm.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["As a result,","At the same time,","For instance,","In short,"]$q$::jsonb, 1, $q$The second sentence presents a drawback of the same property (holding water) that is described as a benefit in the first. "At the same time" introduces a qualifying, contrasting consideration about the same soil. The other choices signal cause, example, or summary.$q$, null),
  ($q$ei-h160$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The violinist rehearsed the concerto for months, but on the night of the premiere a string snapped during the first movement. ______ she borrowed the concertmaster's instrument and finished the performance without missing more than a few bars.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Undeterred,","Consequently,","In contrast,","Previously,"]$q$::jsonb, 0, $q$The second sentence describes the violinist continuing despite the mishap. "Undeterred" signals that she was not stopped by the setback. "Consequently" would suggest the snapped string caused her to finish, which is illogical; "Previously" refers to an earlier time.$q$, null),
  ($q$ei-h161$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Most people assume that the brain is fully developed by adolescence. ______ research using brain scans shows that the prefrontal cortex, which governs planning and impulse control, continues to mature until the mid-twenties.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","Thus,","In addition,","In fact,"]$q$::jsonb, 3, $q$The second sentence corrects the common assumption presented in the first. "In fact" signals that what follows contradicts or corrects a previous statement. "Similarly" and "In addition" signal agreement, and "Thus" signals a result.$q$, null),
  ($q$ei-h162$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The engineers first tested the new battery design in a laboratory at room temperature, where it held its charge for more than a thousand cycles. ______ they tested it in freezing conditions, where its capacity fell by nearly half after just a hundred cycles.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nonetheless,","In other words,","Subsequently,","Likewise,"]$q$::jsonb, 2, $q$The second sentence describes a later step in the testing process. "Subsequently" signals that this test came next in time. The other choices signal contrast, restatement, or similarity.$q$, null),
  ($q$ei-h163$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The city council approved funding for the new bike lanes in 2016. ______ construction stalled for three years while residents argued about whether the lanes should replace parking spaces or traffic lanes.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","However,","Similarly,","Specifically,"]$q$::jsonb, 1, $q$The second sentence describes a delay that contrasts with the approval described in the first. "However" signals this contrast.$q$, null),
  ($q$ei-h164$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The fossil's teeth are flat and ridged, well suited to grinding tough plant material. ______ its jaw lacks the sharp, blade-like teeth that would have allowed it to slice through flesh. Paleontologists therefore conclude that the animal was almost certainly an herbivore.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Moreover,","However,","Instead,","For instance,"]$q$::jsonb, 0, $q$The second sentence adds a further piece of evidence that supports the same conclusion (that the animal ate plants). "Moreover" signals additional support. "However" would signal contrast, but the lack of slicing teeth is consistent with the flat teeth.$q$, null),
  ($q$ei-h165$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$In the 1800s, many doctors believed that diseases such as cholera were caused by "bad air" rising from rotting matter. ______ they focused their efforts on eliminating foul smells rather than on purifying drinking water.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","Similarly,","In contrast,","Consequently,"]$q$::jsonb, 3, $q$The doctors' focus on smells was a result of their belief in "bad air." "Consequently" signals this cause-and-effect relationship.$q$, null),
  ($q$ei-h166$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The bridge was designed to sway slightly in strong winds, a feature intended to keep it from cracking under stress. On the day it opened, ______ thousands of pedestrians walking in step caused it to sway so much that it had to be closed for nearly two years of modifications.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["therefore,","in addition,","however,","for example,"]$q$::jsonb, 2, $q$The opening-day events show the swaying feature backfiring, which contrasts with its intended purpose. "However" signals this contrast.$q$, null),
  ($q$ei-h167$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The author spent ten years researching the novel, traveling to archives in four countries and interviewing dozens of descendants of the people she wrote about. ______ the book that emerged is unusually rich in historical detail, from the price of bread in 1840s Dublin to the cut of a ship captain's coat.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Conversely,","Unsurprisingly,","Meanwhile,","Regardless,"]$q$::jsonb, 1, $q$Given the extensive research described in the first sentence, it is expected that the book would be rich in detail. "Unsurprisingly" signals that the outcome follows naturally from what came before.$q$, null),
  ($q$ei-h168$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Older adults who regularly learn new skills, such as playing an instrument or speaking a foreign language, tend to show slower cognitive decline than those who do not. ______ the researchers caution that their study shows only a correlation; it may be that people with healthier brains are simply more likely to take on new challenges.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Even so,","Thus,","For instance,","Likewise,"]$q$::jsonb, 0, $q$The second sentence qualifies the finding described in the first, warning against reading too much into it. "Even so" signals that what follows limits or complicates the preceding point. "Thus" signals a result, "For instance" an example, and "Likewise" a similarity.$q$, null),
  ($q$ei-h169$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The ice core contains layers that correspond to individual years, much like the rings of a tree. Each layer also preserves tiny bubbles of air from the time it formed. ______ by analyzing these bubbles, scientists can measure how much carbon dioxide was in the atmosphere hundreds of thousands of years ago.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","On the other hand,","Similarly,","Thus,"]$q$::jsonb, 3, $q$The final sentence describes what scientists can do because the layers preserve ancient air. "Thus" signals this consequence. The other choices signal contrast or similarity.$q$, null),
  ($q$ei-h170$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The architect designed the library to use as little energy as possible. Its walls are made of thick rammed earth that stays cool in summer and warm in winter. ______ its roof is angled to capture rainwater, which is filtered and used to flush the building's toilets.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Consequently,","However,","Additionally,","In other words,"]$q$::jsonb, 2, $q$The final sentence presents another feature that serves the same goal (efficiency). "Additionally" signals the addition of a parallel point.$q$, null),
  ($q$ei-h171$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Some economists argue that raising the minimum wage leads businesses to hire fewer workers. ______ others point to studies of neighboring states with different minimum wages that found little or no difference in employment.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Therefore,","Conversely,","Similarly,","In particular,"]$q$::jsonb, 1, $q$The second sentence presents an opposing view to that in the first. "Conversely" signals contrasting positions. "Therefore" signals a result, "Similarly" agreement, and "In particular" a specific example.$q$, null),
  ($q$ei-h172$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The new varieties of rice produce far more grain than traditional varieties, but only when they receive large amounts of fertilizer and water. ______ for farmers who cannot afford these inputs, the traditional varieties often remain the better choice.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","Meanwhile,","Similarly,","In addition,"]$q$::jsonb, 0, $q$The final sentence draws a conclusion based on the condition described in the previous sentence. "Thus" signals this logical consequence.$q$, null),
  ($q$ei-h173$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The team expected that the newly discovered planet, which orbits very close to its star, would have no atmosphere at all. ______ measurements from the space telescope revealed a thin layer of gas containing water vapor and carbon dioxide.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Accordingly,","Likewise,","Moreover,","Instead,"]$q$::jsonb, 3, $q$The measurements revealed the opposite of what was expected. "Instead" signals that something replaced the expected outcome. "Accordingly" would signal a result consistent with expectations.$q$, null),
  ($q$ei-h174$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Honeybees communicate the location of food through a "waggle dance": the angle of the dance indicates the direction of the food relative to the Sun, and the length of the waggle indicates the distance. ______ a bee that waggles for one second is signaling food roughly a kilometer away.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["However,","Therefore,","Specifically,","Meanwhile,"]$q$::jsonb, 2, $q$The final sentence gives a precise detail about how waggle length encodes distance, which elaborates on the previous sentence. "Specifically" signals this kind of detail.$q$, null),
  ($q$ei-h175$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The orchestra had performed in the same concert hall for more than a century. When engineers discovered that the building's foundation was sinking, the musicians were forced to move to a converted warehouse across town. ______ the warehouse's acoustics proved so good that the orchestra decided to stay there permanently.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Consequently,","Surprisingly,","Similarly,","In summary,"]$q$::jsonb, 1, $q$It is unexpected that a temporary, converted warehouse would have acoustics good enough to replace a century-old hall. "Surprisingly" signals this unexpected outcome. "Consequently" would wrongly imply that the sinking foundation caused the good acoustics.$q$, null),
  ($q$ei-h176$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Because ants follow chemical trails left by other ants, a colony can quickly locate and exploit a new food source. ______ the same system can sometimes trap ants in a "death spiral": if the trail forms a loop, ants may follow one another in a circle until they die of exhaustion.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Ironically,","Accordingly,","Likewise,","For example,"]$q$::jsonb, 0, $q$The same mechanism that makes ants efficient can also lead to their death, an outcome that runs contrary to the system's usual benefit. "Ironically" signals this unexpected reversal.$q$, null),
  ($q$ei-h177$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The board of the museum voted to return the sculpture to the country from which it had been taken in the 1890s. ______ the museum will display a high-resolution replica, along with a new exhibit explaining the sculpture's history and how it came to be in the collection.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For example,","On the contrary,","Similarly,","In its place,"]$q$::jsonb, 3, $q$The replica will occupy the position formerly held by the returned sculpture. "In its place" signals this substitution precisely. "On the contrary" signals a contradiction, and "Similarly" a parallel.$q$, null),
  ($q$ei-h178$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The language was spoken by fewer than fifty people in 1990, nearly all of them over the age of seventy. ______ thanks to a program that pairs fluent elders with young learners, more than five hundred people now speak it, including several dozen children who learned it as their first language.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Furthermore,","As a result,","Today, however,","Likewise,"]$q$::jsonb, 2, $q$The second sentence contrasts the language's dire situation in 1990 with its current revival. "Today, however" signals both the change in time and the contrast.$q$, null),
  ($q$ei-h179$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The study's authors note that their sample included only college students in a single country. ______ they caution against assuming that their findings would apply to older adults or to people in other cultures.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","For this reason,","In contrast,","By the same token,"]$q$::jsonb, 1, $q$The caution described in the second sentence follows from the limitation noted in the first. "For this reason" signals this causal link. "Nevertheless" signals contrast, and "By the same token" introduces a parallel argument.$q$, null),
  ($q$ei-h180$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Earlier models of the island's climate predicted that rainfall would decline steadily over the century. ______ newer models, which account for changes in ocean currents, predict that rainfall will remain roughly stable but will arrive in fewer, more intense storms.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["By contrast,","Similarly,","Accordingly,","In other words,"]$q$::jsonb, 0, $q$The newer models make a different prediction from the earlier ones. "By contrast" signals this difference.$q$, null),
  ($q$ei-h181$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The writer is best known for her novels, which have been translated into more than forty languages. ______ she considers herself primarily a poet and has said that she writes novels only "to pay for the poetry."$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","For instance,","Similarly,","Nevertheless,"]$q$::jsonb, 3, $q$The writer's view of herself as primarily a poet contrasts with her fame as a novelist. "Nevertheless" signals this contrast.$q$, null),
  ($q$ei-h182$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The plant's seeds can remain dormant in the soil for decades. They germinate only after a fire, when heat cracks their hard outer coats and smoke chemicals signal that competing vegetation has been cleared. ______ in areas where fires have been suppressed for many years, the species has nearly disappeared.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nonetheless,","Similarly,","Consequently,","In addition,"]$q$::jsonb, 2, $q$Because the seeds need fire to germinate, suppressing fires prevents new plants from growing. The near-disappearance is a result of the conditions described, so "Consequently" is correct.$q$, null),
  ($q$ei-h183$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Composer Florence Price wrote more than three hundred works, including four symphonies. ______ after her death in 1953, much of her music was forgotten, and dozens of her manuscripts were rediscovered only in 2009, in an abandoned house in Illinois.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Moreover,","However,","Thus,","Similarly,"]$q$::jsonb, 1, $q$The neglect of her music after her death contrasts with the impressive body of work described in the first sentence. "However" signals this contrast.$q$, null),
  ($q$ei-h184$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Glaciologists once thought that the massive ice shelf was stable, anchored in place by an underwater ridge. ______ satellite images taken over the past decade show that warm ocean water has been seeping beneath the shelf and melting it from below, causing the shelf to thin by several meters each year.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Recently, however,","Likewise,","As a result,","In addition,"]$q$::jsonb, 0, $q$The second sentence presents new evidence that contradicts the earlier belief. "Recently, however" signals both the shift in time and the contrast.$q$, null),
  ($q$ei-h185$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The first edition of the dictionary, published in 1828, contained about seventy thousand entries. ______ the most recent edition contains more than four hundred thousand, reflecting both the growth of the language and the addition of technical and scientific vocabulary.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Consequently,","For instance,","Even so,","By comparison,"]$q$::jsonb, 3, $q$The second sentence compares the size of the most recent edition with that of the first. "By comparison" signals this contrast in scale.$q$, null),
  ($q$ei-h186$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$To reduce the number of birds killed by collisions with its glass towers, the city now requires new buildings to use patterned glass that birds can see. ______ it offers tax credits to owners of older buildings who apply special films to their windows.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Instead,","Nevertheless,","In addition,","For example,"]$q$::jsonb, 2, $q$The second sentence describes a further measure the city takes toward the same goal. "In addition" signals this. "Instead" would imply that the tax credits replace the requirement.$q$, null),
  ($q$ei-h187$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The chess program was not taught any strategy by its designers; it learned only the rules of the game. ______ by playing millions of games against itself, it developed strategies that grandmasters described as alien yet brilliant.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Therefore,","Nonetheless,","In other words,","Similarly,"]$q$::jsonb, 1, $q$It is surprising that a program given only the rules developed brilliant strategies. "Nonetheless" signals that this outcome occurred despite the limited starting knowledge. "Therefore" would imply that knowing only the rules caused brilliance.$q$, null),
  ($q$ei-h188$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The sea otter is sometimes called a keystone species because its presence has an outsized effect on its ecosystem. Otters eat sea urchins, which graze on kelp. ______ where otters are abundant, urchin populations stay small, and kelp forests flourish, providing habitat for hundreds of other species.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","However,","Similarly,","Meanwhile,"]$q$::jsonb, 0, $q$The final sentence describes the consequence of the feeding relationships just explained. "Thus" signals this conclusion.$q$, null),
  ($q$ei-h189$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Most of the comet's surface is dark, reflecting only about four percent of the sunlight that strikes it. ______ a few small patches near its south pole are bright white, which scientists believe indicates exposed water ice.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Accordingly,","Moreover,","As such,","However,"]$q$::jsonb, 3, $q$The bright patches contrast with the comet's mostly dark surface. "However" signals this contrast.$q$, null),
  ($q$ei-h190$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The trial was designed to last five years. ______ the drug's benefits were so clear after only two years that the review board stopped the study early and offered the drug to participants who had been receiving the placebo.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["As a result,","Likewise,","In the end,","Previously,"]$q$::jsonb, 2, $q$The second sentence explains how the trial actually concluded, contrary to the original plan. "In the end" signals the eventual outcome. "As a result" wrongly suggests that the five-year design caused the early stop.$q$, null),
  ($q$ei-h191$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The museum's collection of ancient coins is one of the largest in the world. ______ only a small fraction of it is on display; the rest is stored in climate-controlled vaults and is available only to researchers by appointment.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus","Yet","Moreover,","Indeed,"]$q$::jsonb, 1, $q$The fact that only a small fraction is displayed contrasts with the size of the collection. "Yet" signals this contrast.$q$, null),
  ($q$ei-h192$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The new law requires that all packaging sold in the country be either recyclable or compostable by 2030. ______ manufacturers will have to redesign many common products, from potato-chip bags to toothpaste tubes, which currently combine several materials that cannot be separated.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["As a result,","On the other hand,","Similarly,","For example,"]$q$::jsonb, 0, $q$The redesign of products is a consequence of the new law's requirement. "As a result" signals this effect.$q$, null),
  ($q$ei-h193$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Many people assume that bats are blind. ______ all bat species can see, and some, such as the large fruit bats of Asia and Africa, have eyesight that is sharper than that of humans in dim light.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","Likewise,","Additionally,","In reality,"]$q$::jsonb, 3, $q$The second sentence corrects the false assumption in the first. "In reality" signals that what follows is the truth, in contrast to a misconception.$q$, null),
  ($q$ei-h194$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The painter worked slowly, often spending a year or more on a single canvas. ______ she produced fewer than sixty paintings during a career that lasted nearly half a century.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","In contrast,","Accordingly,","Specifically,"]$q$::jsonb, 2, $q$Her small total output follows from her slow working method. "Accordingly" signals a logical consequence.$q$, null),
  ($q$ei-h195$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$In the experiment, one group of mice was given access to an exercise wheel, while a second group was not. ______ the mice with wheels grew nearly twice as many new neurons in the hippocampus, a brain region associated with memory.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","After four weeks,","Nevertheless,","For example,"]$q$::jsonb, 1, $q$The second sentence reports the result of the experiment after it had run for some time. "After four weeks" signals the passage of time leading to the result. The other choices signal similarity, concession, or an example, none of which fits.$q$, null),
  ($q$ei-h196$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The violin's tone depends in part on the density of its wood. ______ violins made from spruce that grew slowly during the unusually cold decades of the late 1600s—including many of Stradivari's—may owe some of their prized sound to the climate in which their trees grew.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","Instead,","However,","Meanwhile,"]$q$::jsonb, 0, $q$The second sentence draws an inference based on the principle in the first: if density matters, then wood from slow-growing trees (denser) may explain the sound. "Thus" signals this inference.$q$, null),
  ($q$ei-h197$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Early reviewers dismissed the band's first album as noisy and unfocused. ______ within a decade, many of the same critics were calling it one of the most influential records of its era.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus","Moreover,","Similarly,","Yet"]$q$::jsonb, 3, $q$The later praise contrasts with the early dismissal. "Yet" signals this contrast.$q$, null),
  ($q$ei-h198$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Unlike most metals, gallium melts at a temperature just above 29°C (84°F). ______ a solid piece of gallium will melt if a person holds it in the palm of their hand for a few minutes.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["However,","Previously,","Consequently,","Similarly,"]$q$::jsonb, 2, $q$Because gallium melts at a temperature below that of the human body, holding it will melt it. "Consequently" signals this result. "However" signals a contrast, "Previously" an earlier time, and "Similarly" a parallel case.$q$, null),
  ($q$ei-h199$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The village's terraced rice fields were carved into the mountainside more than two thousand years ago and are still farmed today. ______ as young people move to cities for work, fewer families are left to maintain the stone walls, and some terraces have begun to collapse.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["As a result,","Increasingly, though,","Similarly,","In other words,"]$q$::jsonb, 1, $q$The second sentence describes a growing threat that contrasts with the long continuity described in the first. "Increasingly, though" signals both the contrast and the trend.$q$, null),
  ($q$ei-h200$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The sculptor rarely discusses the meaning of her work; she prefers to let viewers draw their own conclusions. ______ when a critic asked her what her towering steel spiral represented, she replied only, "Whatever you need it to."$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For example,","However,","Consequently,","Meanwhile,"]$q$::jsonb, 0, $q$Her reply to the critic illustrates her habit of not explaining her work. "For example" signals this illustration.$q$, null),
  ($q$ei-h201$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Many of the region's farmers have switched from growing corn to growing sorghum. Sorghum requires roughly a third less water than corn, ______ it can survive the droughts that have become more frequent in recent years.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["but","or","yet","and"]$q$::jsonb, 3, $q$The second clause adds a related advantage of sorghum to the first. "And" joins two parallel benefits. "But" and "yet" signal contrast, and "or" signals an alternative.$q$, null),
  ($q$ei-h202$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The theory predicted that the particle would decay in about a billionth of a second. ______ when physicists finally detected it, the particle lasted almost exactly as long as predicted, providing strong support for the theory.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Instead,","However,","Sure enough,","Conversely,"]$q$::jsonb, 2, $q$The detection confirmed the prediction. "Sure enough" signals that an outcome matched expectations. The other choices signal contrast or replacement.$q$, null),
  ($q$ei-h203$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The city's subway system was built in stages over more than a century. ______ its stations reflect a wide range of architectural styles, from ornate tiled halls of the 1900s to the bare concrete platforms of the 1970s.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","As a result,","In contrast,","For instance,"]$q$::jsonb, 1, $q$The variety of styles results from construction over a long period. "As a result" signals this cause-and-effect relationship.$q$, null),
  ($q$ei-h204$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The researchers asked volunteers to estimate the number of jelly beans in a jar. Individual guesses varied wildly, some too high by hundreds and others too low by hundreds. ______ the average of all the guesses came within a few beans of the true number.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Remarkably, though,","Therefore,","Likewise,","In other words,"]$q$::jsonb, 0, $q$It is surprising that wildly varying guesses produced an accurate average. "Remarkably, though" signals both the surprise and the contrast with the scattered individual guesses.$q$, null),
  ($q$ei-h205$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The poet's early work drew heavily on the forms of English Romanticism. ______ her mature work abandons rhyme and meter almost entirely, drawing instead on the rhythms of the Yoruba praise songs she heard as a child.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","Similarly,","Indeed,","In contrast,"]$q$::jsonb, 3, $q$The mature work is described as different from the early work. "In contrast" signals this difference.$q$, null),
  ($q$ei-h206$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The insect's wings are covered in tiny spikes that are too small to see with the naked eye. ______ the spikes act like a bed of nails, puncturing the cell walls of any bacteria that land on the wing and killing them within minutes.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Consequently,","Similarly,","Nevertheless,","Instead,"]$q$::jsonb, 2, $q$Although the spikes are too small to see, they are still powerful enough to kill bacteria. "Nevertheless" signals that the second sentence is true despite what the first might suggest. "Consequently" would wrongly suggest that the spikes' small size causes their effect, and "Similarly" and "Instead" do not fit.$q$, null),
  ($q$ei-h207$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Researchers studying the island's lizards introduced a predator, a larger ground-dwelling lizard, to six of twelve small islands. Within months, lizards on those six islands began spending more time high in the trees. ______ within a few generations, they had evolved stickier toe pads, which helped them cling to branches.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Instead,","Moreover,","Conversely,","Regardless,"]$q$::jsonb, 1, $q$The final sentence adds a further, related change in the lizards' response to predators. "Moreover" signals this additional point that builds on the previous one.$q$, null),
  ($q$ei-h208$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The city installed sensors on its streetlights to track traffic and air quality. ______ the data revealed that one intersection near an elementary school had pollution levels nearly double the city average during the morning drop-off period.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Within weeks,","In contrast,","Likewise,","Nonetheless,"]$q$::jsonb, 0, $q$The second sentence reports what the data showed shortly after the sensors were installed. "Within weeks" signals the timing. No contrast or similarity is being drawn.$q$, null),
  ($q$ei-h209$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Traditional economic models assume that people make decisions rationally, weighing costs and benefits. ______ behavioral economists have documented many ways in which people systematically depart from this ideal, such as valuing an item more highly simply because they already own it.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","For instance,","Similarly,","However,"]$q$::jsonb, 3, $q$The second sentence presents findings that challenge the assumption in the first. "However" signals this contrast.$q$, null),
  ($q$ei-h210$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The ancient Maya developed a sophisticated calendar system. ______ they tracked a 260-day ritual cycle and a 365-day solar year simultaneously, and the two cycles realigned only once every fifty-two years.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","Consequently,","Specifically,","In contrast,"]$q$::jsonb, 2, $q$The second sentence provides details about the calendar system mentioned in the first. "Specifically" signals this elaboration.$q$, null),
  ($q$ei-h211$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The museum's new director wanted to attract younger visitors. ______ she extended the museum's hours on Friday nights, added live music, and invited local artists to lead drop-in workshops.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","To this end,","Similarly,","In comparison,"]$q$::jsonb, 1, $q$The actions described in the second sentence were taken to achieve the goal stated in the first. "To this end" signals actions taken for a purpose.$q$, null),
  ($q$ei-h212$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Tomatoes were introduced to Europe from the Americas in the 1500s. For nearly two centuries, ______ many Europeans grew them only as ornamental plants, believing the fruit to be poisonous.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["however,","therefore,","for example,","similarly,"]$q$::jsonb, 0, $q$Growing tomatoes only as ornaments, out of fear, contrasts with the expectation that an introduced food plant would be eaten. "However" signals this contrast.$q$, null),
  ($q$ei-h213$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Some species of fish can change sex during their lifetimes. Clownfish, ______ all begin life as males; when the dominant female of a group dies, the largest male becomes female and takes her place.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["however,","therefore,","likewise,","for example,"]$q$::jsonb, 3, $q$Clownfish are given as an instance of fish that change sex. "For example" signals this illustration.$q$, null),
  ($q$ei-h214$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The first version of the software was praised for its speed but criticized for being difficult to use. ______ the developers spent the next year redesigning its interface, adding tutorials, and simplifying its menus.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Instead,","Similarly,","In response,","Even so,"]$q$::jsonb, 2, $q$The redesign was a reaction to the criticism described in the first sentence. "In response" signals this relationship.$q$, null),
  ($q$ei-h215$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Researchers once believed that adult brains could not grow new neurons. Studies in the 1990s, ______ found evidence of new neurons forming in the hippocampus of adult humans.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["therefore,","however,","likewise,","for instance,"]$q$::jsonb, 1, $q$The studies contradicted the earlier belief. "However" signals this contrast.$q$, null),
  ($q$ei-h216$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The river carries enormous amounts of sediment from the mountains to the sea. Where the river meets the ocean, the current slows and the sediment settles. ______ over thousands of years, this process has built a delta covering more than ten thousand square kilometers.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Gradually,","Conversely,","Nonetheless,","In other words,"]$q$::jsonb, 0, $q$The delta was built slowly as sediment accumulated over time. "Gradually" signals this slow process.$q$, null),
  ($q$ei-h217$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Many of the novelist's readers assumed that her books were autobiographical. ______ she had never visited the remote Alaskan villages where most of them are set and based her descriptions entirely on archival research and interviews.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Accordingly,","Additionally,","Similarly,","Actually,"]$q$::jsonb, 3, $q$The second sentence corrects the readers' assumption. "Actually" signals a correction.$q$, null),
  ($q$ei-h218$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The company's profits fell for three consecutive quarters. ______ its stock price rose steadily during the same period, as investors grew optimistic about a new product the company was developing.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Consequently,","Likewise,","Paradoxically,","For example,"]$q$::jsonb, 2, $q$A rising stock price during falling profits is an apparent contradiction. "Paradoxically" signals this seemingly contradictory situation.$q$, null),
  ($q$ei-h219$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The first photograph of a black hole, released in 2019, required data from eight telescopes on four continents. ______ the telescopes functioned as a single instrument with a dish as wide as Earth itself.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Instead,","Together,","Nevertheless,","Conversely,"]$q$::jsonb, 1, $q$The second sentence describes how the telescopes worked jointly. "Together" signals that they combined to act as one.$q$, null),
  ($q$ei-h220$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The library had planned to digitize its entire collection of historical newspapers within five years. ______ budget cuts have slowed the project, and at the current pace, it will take more than fifteen years.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["However,","Therefore,","Moreover,","In fact,"]$q$::jsonb, 0, $q$The slowdown contrasts with the original plan. "However" signals this contrast.$q$, null),
  ($q$ei-h221$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Wolves were reintroduced to the national park in 1995 after an absence of nearly seventy years. ______ the elk population, which had grown large in the wolves' absence, declined sharply, and willows and aspens along the riverbanks began to recover from decades of overgrazing.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","Similarly,","For instance,","Afterward,"]$q$::jsonb, 3, $q$The changes in elk and vegetation followed the wolves' reintroduction. "Afterward" signals this sequence in time.$q$, null),
  ($q$ei-h222$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The violinist's technique was nearly flawless. ______ critics complained that her performances lacked emotion and sounded more like demonstrations of skill than expressions of the music.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["As a result,","Similarly,","Even so,","In particular,"]$q$::jsonb, 2, $q$The critics' complaints arise despite her flawless technique. "Even so" signals this concession.$q$, null),
  ($q$ei-h223$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The new drug was effective at reducing blood pressure in clinical trials. ______ it caused dizziness in about one in five patients, a side effect that limited its use among older adults, who are more likely to fall.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Accordingly,","Unfortunately,","Likewise,","Specifically,"]$q$::jsonb, 1, $q$The side effect is an undesirable aspect that contrasts with the drug's effectiveness. "Unfortunately" signals this negative development.$q$, null),
  ($q$ei-h224$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The mountain's glaciers have shrunk by more than half since 1900. ______ the communities in the valley below, which rely on glacial meltwater during the dry season, face growing water shortages.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["As a result,","Nevertheless,","Similarly,","In contrast,"]$q$::jsonb, 0, $q$Water shortages are a consequence of the shrinking glaciers. "As a result" signals this.$q$, null),
  ($q$ei-h225$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The language spoken on the island has only three vowel sounds. ______ English, depending on the dialect, has as many as twenty.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","Moreover,","In other words,","By contrast,"]$q$::jsonb, 3, $q$The second sentence contrasts the number of vowel sounds in English with those of the island's language. "By contrast" signals this difference.$q$, null),
  ($q$ei-h226$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The architect insisted that the building's windows be made from glass produced using traditional methods. ______ she had panes manufactured by hand in a small workshop in Germany, at nearly ten times the cost of modern glass.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","Similarly,","Accordingly,","In comparison,"]$q$::jsonb, 2, $q$Having the panes made by hand follows from her insistence on traditional glass. "Accordingly" signals this consequence.$q$, null),
  ($q$ei-h227$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$For most of the twentieth century, scientists thought that the giant squid was too elusive ever to be filmed in its natural habitat. ______ in 2012, a team of researchers using a submersible with a special light that the squid could not see finally captured footage of one at a depth of about 600 meters.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","Then,","Similarly,","In addition,"]$q$::jsonb, 1, $q$The second sentence describes a later event that broke the long-standing belief. "Then" signals this turn in the sequence of events.$q$, null),
  ($q$ei-h228$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The scientists did not expect that the bacteria would survive the experiment's extreme conditions. ______ the bacteria not only survived but continued to reproduce.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["To their surprise,","As expected,","Similarly,","For example,"]$q$::jsonb, 0, $q$The bacteria's survival contradicted the scientists' expectations. "To their surprise" signals this unexpected outcome.$q$, null),
  ($q$ei-h229$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The trail was closed for most of the winter because of avalanche danger. ______ it reopened in May, after rangers had cleared fallen trees and repaired a damaged footbridge.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Consequently,","Conversely,","In other words,","Eventually,"]$q$::jsonb, 3, $q$The reopening came after a period of closure and repairs. "Eventually" signals that the event occurred after a delay.$q$, null),
  ($q$ei-h230$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Most species of sharks must keep swimming to force water over their gills. The nurse shark, ______ can pump water over its gills while lying motionless on the sea floor.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["for example,","therefore,","by contrast,","in addition,"]$q$::jsonb, 2, $q$The nurse shark is presented as an exception to the general rule. "By contrast" signals the difference.$q$, null),
  ($q$ei-h231$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The early printing press made books far cheaper to produce. ______ literacy rates in much of Europe rose significantly over the following two centuries.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In contrast,","In turn,","Nevertheless,","For example,"]$q$::jsonb, 1, $q$Cheaper books contributed to rising literacy; the second development followed from the first. "In turn" signals this chain of effects.$q$, null),
  ($q$ei-h232$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The candidate promised to lower taxes for working families. ______ she proposed raising the tax rate on incomes above one million dollars to pay for the cuts.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["At the same time,","Instead,","Consequently,","For instance,"]$q$::jsonb, 0, $q$The second sentence describes a complementary proposal made alongside the first. "At the same time" signals two things done together. "Instead" would imply that she abandoned the tax-cut promise.$q$, null),
  ($q$ei-h233$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The ice on the lake usually freezes solid by late December. ______ this year, unusually warm temperatures kept parts of the lake open until mid-February.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Therefore,","Similarly,","Accordingly,","However,"]$q$::jsonb, 3, $q$This year's late freeze contrasts with the usual pattern. "However" signals this contrast.$q$, null),
  ($q$ei-h234$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Archaeologists had long assumed that the site was abandoned after a devastating fire. ______ new excavations revealed that residents rebuilt many of their homes on top of the burned ruins and continued living there for another two centuries.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["So","And","But","Or"]$q$::jsonb, 2, $q$The new evidence contradicts the earlier assumption. "But" signals the contrast.$q$, null),
  ($q$ei-h235$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The new train line was expected to reduce car traffic between the two cities. ______ traffic on the highway fell by nearly twenty percent in the line's first year of operation.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","Indeed,","In contrast,","Otherwise,"]$q$::jsonb, 1, $q$The drop in traffic confirms the expectation. "Indeed" signals that what follows supports and confirms the preceding statement.$q$, null),
  ($q$ei-h236$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The novelist kept a detailed diary for more than sixty years, filling over a hundred notebooks. ______ she requested that the diaries be burned after her death, and her executors honored her wish.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Regrettably for historians,","Consequently,","For example,","Similarly,"]$q$::jsonb, 0, $q$The destruction of the diaries is a loss from the perspective of those who might have studied them. "Regrettably for historians" captures this. "Consequently" would imply that keeping a diary caused her request.$q$, null),
  ($q$ei-h237$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The forest's oldest trees are more than a thousand years old. ______ some of the fungi living among their roots may be even older, forming underground networks that have persisted through many generations of trees.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["So","For example,","Instead,","Yet"]$q$::jsonb, 3, $q$It is surprising that something could be older than thousand-year-old trees, and the sentence sets up this contrast. "Yet" signals it. "So" signals a result, "For example" an illustration, and "Instead" a replacement.$q$, null),
  ($q$ei-h238$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The city's population grew by more than forty percent between 2000 and 2020. ______ the number of housing units grew by only twelve percent, which helps explain why rents rose so sharply during the period.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Therefore,","For example,","Meanwhile,","Similarly,"]$q$::jsonb, 2, $q$The second sentence describes a development that occurred during the same period and contrasts with population growth. "Meanwhile" signals simultaneous events. "Similarly" would wrongly suggest housing kept pace.$q$, null),
  ($q$ei-h239$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The chef refuses to use any ingredient that must be shipped by air. ______ the restaurant's menu changes almost weekly, depending on what local farmers and fishers can supply.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","As a consequence,","In contrast,","For instance,"]$q$::jsonb, 1, $q$The frequently changing menu results from the chef's refusal to use air-shipped ingredients. "As a consequence" signals this.$q$, null),
  ($q$ei-h240$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The study tracked the health of more than 100,000 nurses over three decades. ______ it is one of the largest and longest-running investigations of women's health ever conducted.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In fact,","However,","Instead,","Otherwise,"]$q$::jsonb, 0, $q$The second sentence emphasizes and builds on the scale described in the first. "In fact" signals this emphasis.$q$, null),
  ($q$ei-h241$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Early telephone systems required human operators to connect each call by plugging cables into a switchboard. ______ automatic switching equipment, introduced in the early twentieth century, allowed callers to dial numbers directly.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","Consequently,","For example,","Later,"]$q$::jsonb, 3, $q$The second sentence describes a later development that replaced the earlier system. "Later" signals this sequence in time.$q$, null),
  ($q$ei-h242$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Unlike most birds, which have hollow bones that reduce their weight, penguins have dense, solid bones. ______ the heavier skeleton helps them dive deep beneath the surface without having to fight their own buoyancy.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","In other words,","For penguins, though,","Previously,"]$q$::jsonb, 2, $q$The second sentence explains why heavy bones—a disadvantage for flying birds—benefit penguins. "For penguins, though" signals the contrast between the general rule and the penguins' case.$q$, null),
  ($q$ei-h243$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The new vaccine must be stored at −70°C, far colder than standard freezers can reach. ______ many rural clinics, which lack ultracold freezers, were unable to offer it during the first months of its availability.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","Consequently,","Similarly,","In contrast,"]$q$::jsonb, 1, $q$Rural clinics' inability to offer the vaccine follows from its storage requirement. "Consequently" signals this result.$q$, null),
  ($q$ei-h244$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The composer wrote the opera in just six weeks. ______ it took her nearly ten years to find a company willing to stage it.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Ironically,","Therefore,","Likewise,","Specifically,"]$q$::jsonb, 0, $q$The contrast between the speed of composition and the long wait for a production is unexpected. "Ironically" signals this incongruity.$q$, null),
  ($q$ei-h245$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The bacteria that cause the disease can survive for weeks on dry surfaces. ______ hospitals must disinfect bed rails, door handles, and medical equipment frequently to prevent the bacteria from spreading between patients.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Even so,","In contrast,","For instance,","For this reason,"]$q$::jsonb, 3, $q$The need to disinfect frequently follows from the bacteria's ability to survive on surfaces. "For this reason" signals the cause-and-effect relationship.$q$, null),
  ($q$ei-h246$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The archive contains more than two million photographs. ______ fewer than ten percent have been cataloged, which means that most of the collection remains effectively invisible to researchers.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In addition,","Similarly,","Of these,","Consequently,"]$q$::jsonb, 2, $q$The second sentence refers to a portion of the photographs mentioned in the first. "Of these" signals that a subset is being discussed.$q$, null),
  ($q$ei-h247$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The theory that the Moon formed when a Mars-sized body collided with the early Earth explains many features of the Moon's composition. ______ it does not fully explain why the Moon's rocks are so chemically similar to Earth's.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","Still,","For example,","Likewise,"]$q$::jsonb, 1, $q$The second sentence notes a limitation of the theory despite its explanatory power. "Still" signals this concession.$q$, null),
  ($q$ei-h248$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$To protect the fragile mosses that grow on the volcanic slopes, the park requires hikers to stay on marked trails. ______ visitors who stray from the trails can be fined up to five hundred dollars.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Moreover,","Instead,","Conversely,","Nonetheless,"]$q$::jsonb, 0, $q$The second sentence adds an enforcement measure that supports the rule in the first. "Moreover" signals this addition.$q$, null),
  ($q$ei-h249$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The dancer trained in classical ballet for fifteen years before joining a modern dance company. ______ her movements combined the precise footwork of ballet with the floor-bound weight of modern dance.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["However,","For example,","Instead,","As a result,"]$q$::jsonb, 3, $q$Her blending of styles follows from her background in both. "As a result" signals this effect.$q$, null),
  ($q$ei-h250$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Some scientists argue that the extinction of the large mammals at the end of the last ice age was caused mainly by climate change. ______ others contend that human hunting played the decisive role, noting that the extinctions often followed soon after humans arrived in a region.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Consequently,","Similarly,","Conversely,","In particular,"]$q$::jsonb, 2, $q$The second sentence presents an opposing view. "Conversely" signals contrasting positions.$q$, null),
  ($q$ei-h251$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The author's first two novels sold only a few hundred copies each. Her third, a mystery set in a remote lighthouse, ______ became an international best seller and was adapted into a film.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["consequently,","by contrast,","likewise,","for instance,"]$q$::jsonb, 1, $q$The success of the third novel contrasts with the poor sales of the first two. "By contrast" signals this difference.$q$, null),
  ($q$ei-h252$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The drought reduced the region's wheat harvest by nearly half. ______ bread prices in the capital doubled within three months, sparking protests.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Predictably,","Nevertheless,","In contrast,","Similarly,"]$q$::jsonb, 0, $q$Rising bread prices are an expected consequence of a poor wheat harvest. "Predictably" signals an outcome that follows naturally from the situation.$q$, null),
  ($q$ei-h253$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The engineers expected the bridge's steel cables to last at least a century. ______ inspections after just forty years found that salt spray from the nearby ocean had corroded many of the wires inside the cables.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Accordingly,","Moreover,","In short,","Instead,"]$q$::jsonb, 3, $q$The inspection results contradict the engineers' expectation; something different from what was expected happened. "Instead" signals this replacement of the expected outcome.$q$, null),
  ($q$ei-h254$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The ancient city had no defensive walls, a fact that puzzled archaeologists for years. ______ the city may not have needed them: there is little evidence of warfare anywhere in the region during the period when the city flourished.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","Similarly,","As it turns out,","For example,"]$q$::jsonb, 2, $q$The second sentence resolves the puzzle described in the first by offering an explanation discovered later. "As it turns out" signals that the answer has emerged.$q$, null),
  ($q$ei-h255$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Hummingbirds can hover in place by beating their wings in a figure-eight pattern. ______ they generate lift on both the downstroke and the upstroke, unlike most birds, which generate lift mainly on the downstroke.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In contrast,","In this way,","Nonetheless,","Meanwhile,"]$q$::jsonb, 1, $q$The second sentence explains the result of the figure-eight motion described in the first. "In this way" signals that the second sentence describes how the method works.$q$, null),
  ($q$ei-h256$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The museum's visitors are encouraged to touch many of the objects on display. ______ the oldest and most fragile artifacts are kept behind glass and may not be handled.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["However,","Thus,","Similarly,","For instance,"]$q$::jsonb, 0, $q$The restriction on fragile artifacts contrasts with the general encouragement to touch objects. "However" signals this contrast.$q$, null),
  ($q$ei-h257$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$When the factory closed in 1998, nearly a third of the town's residents lost their jobs. ______ the population fell from about 12,000 to fewer than 7,000 as families moved away in search of work.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In contrast,","Even so,","For instance,","Over the next decade,"]$q$::jsonb, 3, $q$The population decline happened gradually after the closing. "Over the next decade" signals this sequence and time span.$q$, null),
  ($q$ei-h258$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Earthworms have no lungs. ______ they absorb oxygen directly through their moist skin, which is why they must stay in damp soil to survive.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Therefore,","Similarly,","Instead,","However,"]$q$::jsonb, 2, $q$The second sentence describes what earthworms do in place of breathing with lungs. "Instead" signals this alternative.$q$, null),
  ($q$ei-h259$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The research team had expected that participants who slept less would perform worse on the memory test. ______ the participants who slept less than five hours scored nearly twenty percent lower than those who slept eight hours or more.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Surprisingly,","As predicted,","Conversely,","Nevertheless,"]$q$::jsonb, 1, $q$The results matched the team's expectation. "As predicted" signals this confirmation. "Surprisingly" and "Nevertheless" signal unexpected or contrasting results.$q$, null),
  ($q$ei-h260$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The poet's first collection was praised for its formal precision. ______ some reviewers found the poems emotionally distant, as if the poet were more interested in craft than in feeling.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["At the same time,","As a result,","In other words,","For example,"]$q$::jsonb, 0, $q$The second sentence adds a qualifying criticism alongside the praise. "At the same time" signals that a contrasting consideration exists alongside the first.$q$, null),
  ($q$ei-h261$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The device can purify up to a thousand liters of water a day using only sunlight. ______ it requires no fuel, no electricity, and no replacement filters, making it practical for remote villages.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","In contrast,","Previously,","Furthermore,"]$q$::jsonb, 3, $q$The second sentence adds more advantages of the device. "Furthermore" signals additional supporting points.$q$, null),
  ($q$ei-h262$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$For centuries, the only way to cross the strait was by ferry, and storms often halted service for days at a time. ______ since the tunnel opened in 1994, travelers can make the crossing by train in about thirty-five minutes, regardless of the weather.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","Thus,","Now,","For example,"]$q$::jsonb, 2, $q$The second sentence describes the present situation, which contrasts with the past described in the first. "Now" signals this change in time.$q$, null),
  ($q$ei-h263$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Some researchers believe that the ancient carvings depict constellations. ______ the arrangement of dots on one stone closely matches the pattern of the Pleiades star cluster as it would have appeared in the night sky at the time the carving was made.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In contrast,","In support of this view,","Even so,","Instead,"]$q$::jsonb, 1, $q$The second sentence offers evidence for the researchers' belief. "In support of this view" signals supporting evidence.$q$, null),
  ($q$ei-h264$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Lightning is extremely hot, reaching temperatures of about 30,000°C. ______ when it strikes sand, it can melt the grains into hollow glass tubes called fulgurites.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Consequently,","Nonetheless,","In contrast,","Likewise,"]$q$::jsonb, 0, $q$The formation of fulgurites results from lightning's extreme heat. "Consequently" signals this result.$q$, null),
  ($q$ei-h265$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The neighborhood's community garden began with a single raised bed planted by two retired teachers. ______ it covers half a city block and supplies vegetables to more than sixty families.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","For instance,","Nevertheless,","Today,"]$q$::jsonb, 3, $q$The second sentence describes the garden's present state in contrast with its beginnings. "Today" signals this shift in time.$q$, null),
  ($q$ei-h266$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The company claims that its new phone is the most durable on the market. ______ independent testers found that its screen cracked when dropped from a height of just one meter, while competitors' screens survived falls from twice that height.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Indeed,","Accordingly,","However,","Likewise,"]$q$::jsonb, 2, $q$The test results contradict the company's claim. "However" signals this contrast.$q$, null),
  ($q$ei-h267$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The violin was made in 1721 and is valued at more than ten million dollars. ______ its owner, a foundation, lends it to a young performer who plays it in concerts around the world.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["As a result,","Rather than keep it in a vault,","In other words,","Similarly,"]$q$::jsonb, 1, $q$The second sentence describes the foundation choosing to put the valuable violin to use instead of storing it. "Rather than keep it in a vault" signals this contrast with what might be expected for so valuable an object.$q$, null),
  ($q$ei-h268$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Researchers found that people who were told a wine was expensive rated it as tasting better than people who were told the same wine was cheap. ______ brain scans showed greater activity in regions associated with pleasure when participants believed they were drinking the expensive wine.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["What's more,","Even so,","In contrast,","Instead,"]$q$::jsonb, 0, $q$The second sentence adds further, stronger evidence for the same finding. "What's more" signals this intensifying addition.$q$, null),
  ($q$ei-h269$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Some species of trees in the rainforest grow very slowly for decades in the shade of taller trees. ______ when a large tree falls and opens a gap in the canopy, these young trees can grow several meters in just a few years.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["So","For instance,","Or","But"]$q$::jsonb, 3, $q$The rapid growth after a gap opens contrasts with the slow growth in the shade. "But" signals this contrast.$q$, null),
  ($q$ei-h270$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The first edition of the encyclopedia was written almost entirely by a single scholar. ______ the current edition draws on the work of more than four thousand contributors from around the world.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","For example,","By contrast,","Likewise,"]$q$::jsonb, 2, $q$The many contributors to the current edition contrast with the single author of the first. "By contrast" signals this difference.$q$, null),
  ($q$ei-h271$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The new bus routes were designed to connect the city's poorest neighborhoods with its largest employers. ______ commute times for residents of those neighborhoods fell by an average of twenty minutes each way.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nonetheless,","As intended,","In contrast,","Previously,"]$q$::jsonb, 1, $q$The shorter commutes are the outcome the routes were designed to produce. "As intended" signals that a result matched the goal.$q$, null),
  ($q$ei-h272$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Early studies of the drug were promising: patients who took it reported fewer migraines than those who took a placebo. The studies, however, lasted only eight weeks. ______ researchers could not say whether the benefit would persist or whether side effects might emerge with longer use.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For instance,","Similarly,","Consequently,","Nevertheless,"]$q$::jsonb, 2, $q$The short length of the studies is the reason researchers couldn't judge long-term effects, so a cause-and-effect transition is needed. "Nevertheless" signals a contrast that isn't there, "Similarly" signals a parallel, and "For instance" signals an example.$q$, null),
  ($q$ei-h273$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Most hummingbirds defend feeding territories aggressively, chasing away any rival that approaches their flowers. The long-billed hermit, ______ follows a regular circuit among widely scattered flowers, visiting each one in turn and rarely confronting other birds.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["by contrast,","as a result,","for example,","in addition,"]$q$::jsonb, 0, $q$The hermit's behavior, a peaceful circuit, differs from the territorial behavior described for most hummingbirds, so "by contrast" is correct. "For example" would wrongly present the hermit as an instance of territorial behavior, and the other two signal addition and causation.$q$, null),
  ($q$ei-h274$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Architect Diébédo Francis Kéré built his first school, in his home village of Gando, Burkina Faso, from clay bricks made by local residents. The thick walls kept classrooms cool without air-conditioning. ______ the building's broad, overhanging roof shaded the walls and let hot air escape through vents.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["However,","Instead,","Therefore,","Moreover,"]$q$::jsonb, 3, $q$The second feature, the roof, adds to the first, the walls, as a way the building stayed cool, so the additive "Moreover" fits. "However" and "Instead" signal contrast or replacement, and "Therefore" would wrongly suggest the walls caused the roof's design.$q$, null),
  ($q$ei-h275$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Many people assume that a dog's wagging tail always signals friendliness. ______ researchers have found that the direction of the wag matters: dogs tend to wag more to the right when they see their owners and more to the left when they see an unfamiliar, dominant dog.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Meanwhile,","Likewise,","In fact,","Accordingly,"]$q$::jsonb, 2, $q$The research complicates and corrects the common assumption, and "In fact" introduces a more accurate account. "Likewise" signals similarity, "Accordingly" signals a consequence of the assumption, and "Meanwhile" signals something happening at the same time.$q$, null),
  ($q$ei-h276$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The violinist practiced the concerto's opening passage for months, slowing it down to half speed and playing each note with a metronome. ______ she could play it flawlessly at full tempo, even under the pressure of a live audience.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Still,","Conversely,","For instance,","Eventually,"]$q$::jsonb, 3, $q$The sentence describes the result reached after months of practice, so the time transition "Eventually" fits. "Conversely" signals an opposite case, "For instance" signals an example, and "Still" signals that something holds despite an obstacle, which misreads the relationship.$q$, null),
  ($q$ei-h277$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The volcano had shown no signs of activity for more than five centuries, and many geologists considered it extinct. ______ seismometers placed on its slopes in 2017 detected swarms of small earthquakes, suggesting that magma was moving beneath the surface.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Yet","Similarly,","Thus","Furthermore,"]$q$::jsonb, 0, $q$The earthquake data contradict the expectation that the volcano was extinct, so the contrast transition "Yet" fits. "Thus" signals a conclusion, "Furthermore" signals an addition in the same direction, and "Similarly" signals likeness.$q$, null),
  ($q$ei-h278$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Unlike most metals, gallium melts at just under 30°C, low enough that a piece held in the hand will turn to liquid. ______ it remains liquid over an unusually wide range of temperatures, not boiling until it reaches about 2,400°C.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Hence,","Additionally,","Nonetheless,","Specifically,"]$q$::jsonb, 1, $q$The second sentence adds a second unusual property of gallium, so "Additionally" fits. "Specifically" would need the sentence to give a detail of the melting point, "Nonetheless" signals contrast, and "Hence" signals that the low melting point causes the high boiling point, which the text doesn't claim.$q$, null),
  ($q$ei-h279$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Critics praised the novelist's first book for its tight plotting and spare prose. Her second novel, ______ sprawls across six hundred pages and three generations, digressing frequently into essays on history and music.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["as a result,","on the other hand,","in other words,","in the same way,"]$q$::jsonb, 1, $q$The second novel's sprawling, digressive style contrasts with the first book's tight, spare style, so "on the other hand" fits. "In other words" signals restatement, "as a result" signals causation, and "in the same way" signals similarity.$q$, null),
  ($q$ei-h280$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$In laboratory tests, the new battery stored twice as much energy as conventional lithium-ion cells. ______ it lost much of its capacity after only fifty charging cycles, far fewer than the thousands that commercial batteries must withstand.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["However,","Therefore,","In short,","Likewise,"]$q$::jsonb, 0, $q$The battery's rapid loss of capacity is a drawback that contrasts with its impressive energy storage, so "However" fits. "Therefore" signals a consequence, "Likewise" signals similarity, and "In short" signals a summary.$q$, null),
  ($q$ei-h281$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Historian Rhys Isaac argued that eighteenth-century Virginia's courthouse days were more than legal proceedings; they were social events at which planters displayed their wealth and status before the community. ______ the courthouse lawn served as a stage on which the colony's social hierarchy was performed and reinforced.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In other words,","Even so,","By contrast,","For example,"]$q$::jsonb, 0, $q$The second sentence restates Isaac's argument in a vivid way, so "In other words" fits. "By contrast" signals difference, "For example" would need a specific instance, and "Even so" signals concession.$q$, null),
  ($q$ei-h282$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The archaeologists expected to find evidence of a large permanent settlement at the site. ______ they uncovered only a few scattered hearths and stone tools, suggesting that the area was used as a seasonal hunting camp.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Instead,","Accordingly,","Similarly,","Moreover,"]$q$::jsonb, 0, $q$What the archaeologists found replaced what they expected, so "Instead" fits. "Moreover" signals addition, "Similarly" signals likeness, and "Accordingly" signals that the finding followed from the expectation.$q$, null),
  ($q$ei-h283$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Elephants communicate using rumbles too low for humans to hear. These infrasonic calls can travel several kilometers through the air. ______ they travel even farther through the ground, where other elephants detect the vibrations with sensitive cells in their feet and trunks.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Moreover,","Consequently,","In contrast,","Nevertheless,"]$q$::jsonb, 0, $q$The second point builds on the first (the calls travel far through air and even farther through the ground), so "Moreover" fits. "Nevertheless" and "In contrast" signal opposition, and "Consequently" suggests that traveling through air causes traveling through the ground.$q$, null),
  ($q$ei-h284$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The city's new bus routes were designed to cut commute times in half. ______ ridership fell during the first year, because many residents found the redesigned network confusing and the new stops farther from their homes.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","Ironically,","Predictably,","Specifically,"]$q$::jsonb, 1, $q$A plan meant to improve service led to fewer riders, an outcome opposite to what was intended, so "Ironically" fits. "Predictably" contradicts the stated goal, "Specifically" signals a detail, and "Similarly" signals likeness.$q$, null),
  ($q$ei-h285$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Hand-drawn animation requires artists to draw each frame individually, as many as twenty-four for every second of film. ______ a ninety-minute feature can require well over a hundred thousand drawings.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Meanwhile,","Alternatively,","Thus,","Nonetheless,"]$q$::jsonb, 2, $q$The large number of drawings follows from the frame-by-frame requirement, so the result transition "Thus" fits. "Nonetheless" signals contrast, "Alternatively" signals another option, and "Meanwhile" signals simultaneity.$q$, null),
  ($q$ei-h286$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Some economists argue that raising the minimum wage reduces employment, since businesses will hire fewer workers when labor costs rise. ______ a well-known 1994 study comparing fast-food restaurants in New Jersey and Pennsylvania found no such decline after New Jersey raised its wage.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["However,","Hence,","Likewise,","For example,"]$q$::jsonb, 0, $q$The study's finding runs counter to the economists' prediction, so "However" fits. "Hence" signals a conclusion, "For example" would wrongly present the study as supporting the argument, and "Likewise" signals agreement.$q$, null),
  ($q$ei-h287$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The poet's early work was rooted in the rural landscapes of her childhood: barns, orchards, and frozen ponds. ______ after she moved to the city in her thirties, her poems turned to subways, crowded markets, and the view from high-rise windows.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In fact,","Similarly,","For instance,","Later,"]$q$::jsonb, 3, $q$The sentence describes a later stage of the poet's career, so the time transition "Later" fits. "Similarly" ignores the change in subject matter, "For instance" signals an example, and "In fact" signals emphasis or correction.$q$, null),
  ($q$ei-h288$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$A single honeybee colony may contain fifty thousand workers. ______ the colony's survival through winter depends on just one individual: the queen, who alone lays the eggs that replenish the population.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","Therefore,","Furthermore,","In other words,"]$q$::jsonb, 0, $q$Despite the colony's huge numbers, its survival depends on one bee. That's a contrast between expectation and reality, so "Nevertheless" fits. "Therefore" implies that many workers cause dependence on the queen, "Furthermore" signals addition, and "In other words" signals restatement.$q$, null),
  ($q$ei-h289$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Sea otters eat large numbers of sea urchins, which graze on kelp. Where otters were hunted to near-extinction, urchin populations exploded and kelp forests disappeared. ______ where otters have returned, kelp forests have often regrown within a decade.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Conversely,","Similarly,","Specifically,","As a result,"]$q$::jsonb, 0, $q$The sentence describes the reverse situation, otters returning instead of disappearing, with the reverse outcome, so "Conversely" fits. "Similarly" signals likeness, "Specifically" signals a detail, and "As a result" would make the regrowth a consequence of the otters' disappearance.$q$, null),
  ($q$ei-h290$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The museum's collection of Roman coins is among the largest in Europe. ______ fewer than one percent of the coins are on display at any time; the rest are kept in climate-controlled storage beneath the building.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Likewise,","Indeed,","Therefore,","Even so,"]$q$::jsonb, 3, $q$Despite the collection's size, very few coins are shown, so the concessive "Even so" fits. "Therefore" signals a result, "Indeed" signals emphasis of the previous point, and "Likewise" signals similarity.$q$, null),
  ($q$ei-h291$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Psychologist Elena Fuentes found that students who explained a concept aloud to a classmate remembered it better than students who simply reread their notes. ______ students who explained the concept to an imaginary listener performed nearly as well as those who explained it to a real one.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Interestingly,","Consequently,","For example,","Conversely,"]$q$::jsonb, 0, $q$The second finding is a notable addition: even an imaginary listener helped. "Interestingly" introduces it as a surprising extension. "Consequently" signals a result the first finding doesn't produce, "For example" would need an instance of the first finding, and "Conversely" signals an opposite result.$q$, null),
  ($q$ei-h292$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The mountain's northern face receives almost no direct sunlight during winter. ______ snow accumulates there to depths of several meters and often lingers well into July.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","As a result,","In contrast,","Nevertheless,"]$q$::jsonb, 1, $q$The lack of sunlight causes snow to accumulate and linger, so "As a result" fits. "In contrast" and "Nevertheless" signal opposition, and "Similarly" signals likeness.$q$, null),
  ($q$ei-h293$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Translators of ancient poetry face a difficult choice. They can preserve the original's meter and rhyme, ______ sacrificing some precision of meaning, or they can render the meaning exactly at the cost of the poem's music.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["thereby","instead","however","similarly"]$q$::jsonb, 0, $q$Preserving meter and rhyme leads to a loss of precision, so "thereby" (meaning "by doing so") fits. "However" signals contrast, "similarly" signals likeness, and "instead" signals replacement.$q$, null),
  ($q$ei-h294$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Coffee plants produce caffeine in their leaves and seeds, where it acts as a natural pesticide that deters insects. ______ the plants also produce small amounts of caffeine in their nectar, where it seems to have the opposite effect: bees that taste it are more likely to remember the flower and return.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For this reason,","Curiously,","Accordingly,","In summary,"]$q$::jsonb, 1, $q$Caffeine attracting bees is a surprising contrast with its role as a pesticide, so "Curiously" fits. "Accordingly" and "For this reason" signal that the pesticide role causes the nectar effect, and "In summary" signals a conclusion.$q$, null),
  ($q$ei-h295$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The first edition of the dictionary, published in 1928, defined about 400,000 words. ______ the second edition, published in 1989, defined more than 600,000, reflecting both new coinages and words that earlier editors had overlooked.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["By comparison,","Nonetheless,","As a result,","For instance,"]$q$::jsonb, 0, $q$The sentence compares the second edition's word count with the first's, so "By comparison" fits. "As a result" implies the first edition caused the second's size, "For instance" signals an example, and "Nonetheless" signals contrast against an expectation that isn't set up.$q$, null),
  ($q$ei-h296$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Engineers initially designed the robot's legs to mimic those of a dog. ______ they discovered that the four-legged design struggled on loose sand, they borrowed instead from the six-legged gait of desert beetles.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Although","Unless","Because of","When"]$q$::jsonb, 3, $q$The engineers changed the design at the point when they discovered the problem, so "When" fits. "Although" signals concession, "Because of" requires a noun phrase rather than a clause, and "Unless" signals a condition that makes no sense here.$q$, null),
  ($q$ei-h297$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Critics of the proposed high-speed rail line argue that its construction costs will far exceed the official estimates. ______ large infrastructure projects frequently run over budget; the city's last two transit projects each cost nearly twice what was projected. But supporters contend that the line's long-term economic benefits will justify even a substantial overrun.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Therefore,","Granted,","Similarly,","Instead,"]$q$::jsonb, 1, $q$The writer briefly concedes the critics' point before "But" introduces the supporters' rebuttal, so the concessive "Granted" fits. "Therefore" would present the overruns as a conclusion from the critics' argument, "Instead" signals replacement, and "Similarly" signals a parallel rather than a concession.$q$, null),
  ($q$ei-h298$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The fossil's teeth were long, curved, and serrated, the kind typically associated with meat-eating dinosaurs. ______ chemical analysis of the tooth enamel revealed carbon isotope ratios consistent with a diet composed mostly of plants.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In particular,","Accordingly,","Indeed,","Surprisingly, though,"]$q$::jsonb, 3, $q$The chemical evidence contradicts what the teeth's shape suggests, so a contrast is needed, and "Surprisingly, though" supplies it. "Indeed" and "In particular" would treat the chemical evidence as supporting or specifying the meat-eating inference, and "Accordingly" would present it as a consequence of that inference.$q$, null),
  ($q$ei-h299$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Political scientist Hana Moreau studied voter turnout in cities that moved local elections to coincide with national ones. Turnout in those local elections rose dramatically, in some cases tripling. ______ the change did not appear to alter which candidates won: incumbents were reelected at about the same rate as before.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Notably, however,","Likewise,","In other words,","For this reason,"]$q$::jsonb, 0, $q$The second result (no change in outcomes) contrasts with what the turnout surge might lead readers to expect, so "Notably, however" fits. "In other words" signals restatement, "For this reason" signals that higher turnout caused the unchanged outcomes, and "Likewise" signals a parallel effect.$q$, null),
  ($q$ei-h300$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Unlike most sharks, which must keep swimming to push water over their gills, the nurse shark can rest motionless on the seafloor. It pumps water over its gills using muscles in its mouth and throat. ______ it can spend much of the day lying in caves and crevices, emerging to hunt at night.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Even so,","By contrast,","Thus,","For example,"]$q$::jsonb, 2, $q$The shark's ability to pump water explains why it can lie still for long periods, so the result transition "Thus" fits. "Even so" signals concession, "For example" would require an example of pumping water, and "By contrast" signals a difference that isn't present.$q$, null),
  ($q$ei-h301$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$In most languages, words for colors appear in a predictable order: if a language has only two color terms, they mean roughly "dark" and "light"; a third term almost always means "red." ______ a language with a word for "blue" will nearly always have words for "green" and "yellow" as well.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In short,","As a result,","Similarly,","However,"]$q$::jsonb, 2, $q$The final sentence gives another instance of the same predictable pattern, so "Similarly" fits. "However" signals contrast, "As a result" would claim that the earlier patterns cause this one, and "In short" would require a summary rather than a new example.$q$, null),
  ($q$ei-h302$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The novel's protagonist insists throughout the first half of the book that she has no interest in returning to her hometown. ______ she keeps a key to her childhood house on a chain around her neck, a detail the narrator mentions in nearly every chapter.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Specifically,","Moreover,","Yet","Hence"]$q$::jsonb, 2, $q$The key on her necklace contradicts her stated lack of interest, so "Yet" fits. "Hence" signals a result, "Moreover" would add a point in the same direction, and "Specifically" signals a detail of the previous claim.$q$, null),
  ($q$ei-h303$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The study found that participants who slept fewer than six hours were more likely to catch a cold after exposure to the virus. ______ the researchers caution that the study was observational: it shows an association between short sleep and illness, not that one causes the other.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Still,","Thus,","For instance,","Furthermore,"]$q$::jsonb, 0, $q$The researchers qualify the finding with a limitation, so the concessive "Still" fits. "Thus" signals that the caution follows from the finding, "Furthermore" signals an additional finding, and "For instance" signals an example.$q$, null),
  ($q$ei-h304$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Before the 1850s, few Americans had ever tasted a tomato that wasn't cooked; many believed the raw fruit was mildly poisonous. ______ by the end of the century, tomatoes were among the most widely eaten vegetables in the country, served raw in salads and sandwiches.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For this reason,","Similarly,","In addition,","Within a few decades, however,"]$q$::jsonb, 3, $q$The final sentence describes a change over time that contrasts with the earlier wariness, so "Within a few decades, however" fits. "For this reason" signals cause, "In addition" signals addition, and "Similarly" signals likeness.$q$, null),
  ($q$ei-h305$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Most migrating songbirds fly at night, navigating partly by the stars. ______ the birds can become disoriented by the lights of cities, and thousands die each year in collisions with illuminated buildings.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","Alternatively,","Consequently,","For example,"]$q$::jsonb, 2, $q$Because the birds fly at night and navigate by the stars, city lights can disorient them, so the result transition "Consequently" fits. "Nevertheless" signals contrast, "For example" would need an example of navigation, and "Alternatively" signals an option.$q$, null),
  ($q$ei-h306$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Many early photographs show subjects with stern, unsmiling faces. Historians once attributed this to long exposure times, which made holding a smile difficult. ______ exposure times had dropped to a fraction of a second by the 1880s, yet stiff expressions remained the norm for decades, suggesting that cultural expectations about dignity in portraits played a larger role.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus","Likewise,","But","For instance,"]$q$::jsonb, 2, $q$The final sentence challenges the historians' explanation, so the contrast transition "But" fits. "Thus" would present the evidence as following from the earlier explanation, "Likewise" signals agreement, and "For instance" signals an example of it.$q$, null),
  ($q$ei-h307$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$In the experiment, mice raised in cages with running wheels, tunnels, and toys developed more connections between neurons than mice raised in empty cages. ______ the enriched mice learned to navigate mazes significantly faster.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["They instead","They nonetheless","They therefore still","They also"]$q$::jsonb, 3, $q$Faster maze learning is an additional finding consistent with the first, so "They also" fits. "Instead" implies replacement, "nonetheless" implies a contrast with the first finding, and "therefore still" combines a cause with a concession that the text doesn't set up.$q$, null),
  ($q$ei-h308$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Wind turbines generate electricity only when the wind blows, which makes their output difficult for grid operators to predict. ______ new forecasting models that combine weather data with machine learning can now predict a wind farm's output a day in advance with errors of less than ten percent.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Therefore,","In other words,","Increasingly, though,","Similarly,"]$q$::jsonb, 2, $q$The improved forecasts counter the difficulty described in the first sentence, so "Increasingly, though" fits. "Therefore" would claim that unpredictability causes accurate forecasts, "In other words" signals restatement, and "Similarly" signals a parallel.$q$, null),
  ($q$ei-h309$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The composer completed only the first two movements of the symphony before his death. ______ the work, known today as the "Unfinished" Symphony, has become one of the most frequently performed pieces in the orchestral repertoire.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Accordingly,","Nonetheless,","In fact,","Specifically,"]$q$::jsonb, 1, $q$Despite being incomplete, the symphony became widely performed, so the concessive "Nonetheless" fits. "Accordingly" signals a result, "In fact" signals an intensification of the previous point, and "Specifically" signals a detail.$q$, null),
  ($q$ei-h310$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Volunteers in the citizen-science project classified images of hundreds of thousands of galaxies in the project's first year. ______ the volunteers identified an entirely new class of compact green galaxies, nicknamed "green peas," which professional astronomers had overlooked.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In the process,","In comparison,","On the contrary,","Even so,"]$q$::jsonb, 0, $q$The discovery happened during the classification work, so "In the process" fits. "On the contrary" signals contradiction, "Even so" signals concession, and "In comparison" signals a comparison, none of which matches the relationship.$q$, null),
  ($q$ei-h311$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$For decades, nutrition guidelines warned against eating eggs because of their high cholesterol content. ______ research has since shown that, for most people, dietary cholesterol has only a small effect on cholesterol levels in the blood, and many guidelines have dropped the warning.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Therefore,","Likewise,","However,","In addition,"]$q$::jsonb, 2, $q$Newer research contradicts the older warning, so "However" fits. "Therefore" would make the new research a consequence of the warning, and "Likewise" and "In addition" would treat it as continuing in the same direction.$q$, null),
  ($q$ei-h312$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The desert tortoise spends as much as 95 percent of its life underground, in burrows it digs with its powerful forelimbs. ______ the burrows protect the tortoise from both summer heat exceeding 60°C at the surface and winter frosts.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless, these","These","Instead, these","Conversely, these"]$q$::jsonb, 1, $q$The final sentence explains the benefit of the burrows just mentioned, with no contrast or reversal, so no transition is needed: "These" works. "Instead," "Nevertheless," and "Conversely" signal contrasts that the text doesn't support.$q$, null),
  ($q$ei-h313$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Some scholars have read the play as a critique of the monarchy. ______ the playwright was a favorite of the king, received a royal pension, and dedicated two other works to members of the royal family, facts that complicate that reading.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["After all,","Yet","For instance,","Thus"]$q$::jsonb, 1, $q$The facts about the playwright's royal favor complicate the scholars' reading, so the contrast transition "Yet" fits. "After all" would present the facts as support for the reading, "Thus" would present them as a conclusion drawn from it, and "For instance" would offer them as an example of the critique.$q$, null),
  ($q$ei-h314$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Chess grandmasters can recall the positions of pieces on a board after looking at it for just five seconds, far better than novices can. ______ when pieces are placed randomly, in positions that could never arise in a real game, grandmasters recall them no better than novices do.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For this reason,","Strikingly, however,","Similarly,","In other words,"]$q$::jsonb, 1, $q$The random-position result contrasts with the grandmasters' usual superior recall, so "Strikingly, however" fits. "For this reason" signals cause, "Similarly" signals a parallel, and "In other words" signals restatement.$q$, null),
  ($q$ei-h315$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The city's oldest bridge was scheduled for demolition in 1975. Residents organized protests, collected thousands of signatures, and persuaded a local historian to document the bridge's significance. ______ the city council voted to restore the bridge rather than replace it.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For example,","Nevertheless,","Instead,","Ultimately,"]$q$::jsonb, 3, $q$The council's vote is the final outcome of the residents' efforts, so "Ultimately" fits. "Instead" signals replacement of the previous action, "Nevertheless" signals contrast, and "For example" signals an illustration.$q$, null),
  ($q$ei-h316$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Lichens look like single organisms, but each is actually a partnership between a fungus and an alga or cyanobacterium. The fungus provides structure and absorbs water and minerals. ______ the alga or cyanobacterium produces food through photosynthesis.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Its partner, as a result,","Its partner, in turn,","Its partner, by contrast, then","Its partner, for instance,"]$q$::jsonb, 1, $q$The sentence describes the partner's reciprocal contribution, so "in turn" fits. "By contrast, then" adds a mismatched sequence word, "as a result" makes the fungus's work cause photosynthesis, and "for instance" signals an example.$q$, null),
  ($q$ei-h317$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Many runners believe that stretching before a race prevents injury. Several large studies, ______ have found that pre-exercise stretching has little or no effect on injury rates, though warming up with light activity may help.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["similarly,","for example,","therefore,","however,"]$q$::jsonb, 3, $q$The studies contradict the runners' belief, so "however" fits. "Therefore" signals a conclusion, "similarly" signals agreement, and "for example" signals an instance of the belief.$q$, null),
  ($q$ei-h318$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Monarch caterpillars feed only on milkweed, a plant that contains toxins called cardenolides. The caterpillars store these toxins in their bodies. ______ adult monarchs taste bitter to birds, which quickly learn to avoid them.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","As a result,","Similarly,","In contrast,"]$q$::jsonb, 1, $q$Storing the toxins makes the adults bitter, so the cause-and-effect transition "As a result" fits. "In contrast" and "Nevertheless" signal opposition, and "Similarly" signals a parallel.$q$, null),
  ($q$ei-h319$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The tallest sand dunes on Earth, in China's Badain Jaran Desert, rise more than 400 meters. ______ the desert also contains more than one hundred small lakes, fed by groundwater, nestled among the dunes.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Surprisingly,","Consequently,","For instance,","In other words,"]$q$::jsonb, 0, $q$Lakes in a desert of enormous dunes are unexpected, so "Surprisingly" fits. "Consequently" claims that the dunes cause the lakes, "In other words" signals restatement, and "For instance" signals an example of tall dunes.$q$, null),
  ($q$ei-h320$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The company's first electric scooter sold poorly; customers complained that its battery lasted less than an hour. ______ the company's engineers redesigned the battery pack, extending its range to nearly four hours, and sales of the second model quadrupled.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","In summary,","In response,","On the other hand,"]$q$::jsonb, 2, $q$The redesign was a reaction to the customers' complaints, so "In response" fits. "On the other hand" signals contrast, "Similarly" signals a parallel, and "In summary" signals a conclusion.$q$, null),
  ($q$ei-h321$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Medieval maps often placed Jerusalem at the center of the world and filled distant regions with imaginary creatures. Such maps were not meant primarily for navigation. ______ they expressed a religious worldview, showing viewers how the known world related to sacred history.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Rather,","For example,","Consequently,","Similarly,"]$q$::jsonb, 0, $q$The sentence replaces the denied purpose (navigation) with the actual purpose, so "Rather" fits. "Similarly" signals likeness, "Consequently" signals that not being meant for navigation caused the worldview, and "For example" signals an example.$q$, null),
  ($q$ei-h322$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Octopuses can change the color of their skin in a fraction of a second. ______ most species are thought to be colorblind, having only one type of light-sensitive cell in their eyes, which has led researchers to investigate whether the skin itself can detect light.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Therefore,","Likewise,","In short,","Puzzlingly,"]$q$::jsonb, 3, $q$Animals that match colors expertly but appear to be colorblind present a puzzle, so "Puzzlingly" fits. "Therefore" signals a result, "Likewise" signals similarity, and "In short" signals a summary.$q$, null),
  ($q$ei-h323$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The 1918 influenza pandemic killed an estimated fifty million people worldwide. Unusually, the disease was especially deadly for healthy adults between the ages of twenty and forty. ______ most influenza strains are most dangerous to the very young and the very old.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Furthermore,","By contrast,","As a result,","For instance,"]$q$::jsonb, 1, $q$Typical flu strains affect different age groups than the 1918 strain did, so "By contrast" fits. "As a result" signals a cause, "Furthermore" signals addition, and "For instance" signals an example.$q$, null),
  ($q$ei-h324$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The author spent eleven years researching the biography, interviewing more than three hundred people and reading thousands of letters. ______ the book contains details about its subject's early life that no previous biographer had uncovered.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","Not surprisingly,","Even so,","On the other hand,"]$q$::jsonb, 1, $q$New details are an expected result of such extensive research, so "Not surprisingly" fits. "Even so" and "On the other hand" signal contrast, and "Similarly" signals a parallel.$q$, null),
  ($q$ei-h325$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Coastal mangrove forests store carbon in their soils at rates up to four times higher than tropical rainforests on land. ______ they protect shorelines from storm surges and provide nursery habitat for many commercially important fish.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nonetheless,","In other words,","Instead,","Beyond this,"]$q$::jsonb, 3, $q$Storm protection and fish habitat are benefits in addition to carbon storage, so "Beyond this" fits. "Instead" signals replacement, "Nonetheless" signals contrast, and "In other words" signals restatement.$q$, null),
  ($q$ei-h326$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Philosopher Iris Murdoch was an accomplished novelist as well as a scholar. In her philosophical writing, she argued that moral life consists less in dramatic choices than in the quality of our everyday attention to others. ______ her novels are filled with characters whose moral failures stem from a self-absorbed inability to see the people around them clearly.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Conversely,","Fittingly,","Otherwise,","Admittedly,"]$q$::jsonb, 1, $q$The novels' themes match her philosophical argument about attention, so "Fittingly" signals the appropriate correspondence. "Conversely" signals opposition, "Admittedly" signals concession, and "Otherwise" signals an alternative condition.$q$, null),
  ($q$ei-h327$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The research team expected that crows raised in the laboratory would need to watch adults before they could use sticks to extract insects from logs. ______ young crows that had never seen a tool used began probing with twigs on their own within a few weeks.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["To their surprise,","Similarly,","Specifically,","For this reason,"]$q$::jsonb, 0, $q$The young crows' behavior contradicts the team's expectation, so "To their surprise" fits. "For this reason" signals cause, "Similarly" signals a parallel, and "Specifically" signals a detail of the expectation.$q$, null),
  ($q$ei-h328$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Copper is an excellent conductor of electricity, but it is heavy and increasingly expensive. ______ engineers designing long-distance power lines usually choose aluminum, which conducts electricity somewhat less well but weighs about a third as much.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","For example,","In contrast,","For these reasons,"]$q$::jsonb, 3, $q$Copper's weight and cost explain why engineers choose aluminum, so "For these reasons" fits. "In contrast" and "Nevertheless" signal opposition, and "For example" signals an illustration.$q$, null),
  ($q$ei-h329$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The Library of Alexandria is often said to have been destroyed in a single catastrophic fire. ______ historians now believe the library declined gradually over several centuries, as funding dwindled and scholars left for other centers of learning.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Accordingly,","In addition,","Likewise,","In reality,"]$q$::jsonb, 3, $q$The historians' view corrects the popular story, so "In reality" fits. "Accordingly" signals consequence, and "Likewise" and "In addition" signal agreement or continuation.$q$, null),
  ($q$ei-h330$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Ravens in one study learned to trade tokens for food, choosing a token that could be exchanged for a better reward later over a smaller reward available immediately. ______ the birds showed a capacity for planning previously documented mainly in great apes.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In doing so,","Instead,","Even so,","For instance,"]$q$::jsonb, 0, $q$By choosing the delayed reward, the ravens demonstrated planning, so "In doing so" links the action to what it showed. "Instead" signals replacement, "Even so" signals concession, and "For instance" signals an example.$q$, null),
  ($q$ei-h331$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Most modern cities are built on grids, with streets meeting at right angles. Many medieval European towns, ______ grew organically, their winding lanes following old footpaths, property lines, and the contours of the land.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["likewise,","for example,","however,","therefore,"]$q$::jsonb, 2, $q$Medieval towns' organic growth contrasts with modern grids, so "however" fits. "Therefore" signals a result, "for example" would present them as examples of grids, and "likewise" signals similarity.$q$, null),
  ($q$ei-h332$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The new telescope's mirror is 6.5 meters across, much larger than that of its predecessor. ______ the telescope can collect enough light to observe galaxies that formed only a few hundred million years after the Big Bang.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Because of this size,","Unlike this size,","Besides this size,","Despite this size,"]$q$::jsonb, 0, $q$The larger mirror is what lets the telescope collect so much light, so "Because of this size" fits. "Despite" signals contrast, "Besides" signals addition, and "Unlike" signals difference.$q$, null),
  ($q$ei-h333$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Many readers assume that Mary Shelley's <i>Frankenstein</i> is a story about a monster. ______ the novel spends far more time examining its creator, Victor Frankenstein, whose ambition and neglect of his creation drive the tragedy.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","Moreover,","Hence","Yet"]$q$::jsonb, 3, $q$The novel's actual focus contrasts with the common assumption, so "Yet" fits. "Hence" signals a result, and "Moreover" and "Similarly" signal agreement.$q$, null),
  ($q$ei-h334$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Before the invention of the marine chronometer, sailors could determine their latitude fairly easily by measuring the angle of the sun at noon. ______ longitude remained a problem; without an accurate clock, navigators had no reliable way to measure how far east or west they had traveled.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Longitude, likewise,","Longitude, however,","Longitude, therefore,","Longitude, for instance,"]$q$::jsonb, 1, $q$Longitude's difficulty contrasts with how easily latitude could be found, so "however" fits. "Therefore" signals a result, "likewise" signals similarity, and "for instance" signals an example.$q$, null),
  ($q$ei-h335$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$A 2019 survey found that 70 percent of the region's farmers had adopted no-till methods, which reduce soil erosion. ______ only 15 percent had adopted cover crops, another practice recommended by soil scientists, largely because of the extra cost of seed.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","Above all,","By comparison,","For this reason,"]$q$::jsonb, 2, $q$The sentence compares adoption rates for two practices, so "By comparison" fits. "For this reason" signals cause, "Similarly" ignores the large difference, and "Above all" signals emphasis.$q$, null),
  ($q$ei-h336$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The violinist's recording of the Bach sonatas was praised for its technical precision. Several critics, ______ found the performances emotionally distant, arguing that precision had been achieved at the expense of expression.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["therefore,","in fact,","though,","for instance,"]$q$::jsonb, 2, $q$The critics' complaint contrasts with the praise, so "though" fits. "Therefore" signals a result, "in fact" signals emphasis, and "for instance" signals an example.$q$, null),
  ($q$ei-h337$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The trees in the experimental plot were watered twice as often as those in the control plot. ______ they grew nearly 40 percent taller over five years, though their wood was less dense.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nevertheless,","Accordingly,","Similarly,","Instead,"]$q$::jsonb, 1, $q$The extra watering produced the extra growth, so "Accordingly" fits. "Nevertheless" and "Instead" signal contrast, and "Similarly" signals a parallel.$q$, null),
  ($q$ei-h338$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Native to the Andes, potatoes were cultivated there for thousands of years before Spanish explorers brought them to Europe in the 1500s. ______ Europeans regarded them with suspicion for nearly two centuries, and they became a staple food in most of the continent only in the 1700s.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Likewise,","In conclusion,","At first,","For instance,"]$q$::jsonb, 2, $q$The sentence describes the initial reaction followed by later adoption, so the time transition "At first" fits. "In conclusion" signals a summary, "For instance" signals an example, and "Likewise" signals a parallel.$q$, null),
  ($q$ei-h339$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The company argued that its new pesticide breaks down within days and poses no risk to bees. Independent researchers, ______ detected the chemical in pollen collected from hives more than a month after spraying.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["as a result,","by contrast,","likewise,","in other words,"]$q$::jsonb, 1, $q$The researchers' finding contradicts the company's claim, so "by contrast" fits. "As a result" signals cause, "likewise" signals agreement, and "in other words" signals restatement.$q$, null),
  ($q$ei-h340$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Before the 1970s, most scientists believed that the deep ocean floor was nearly lifeless, since no sunlight reaches it. ______ in 1977, researchers aboard the submersible <i>Alvin</i> discovered thriving communities of tube worms, clams, and crabs clustered around hydrothermal vents near the Galápagos Islands.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In short,","Thus,","Then,","Similarly,"]$q$::jsonb, 2, $q$The 1977 discovery is the next event in a sequence that overturned the old belief, so "Then" fits. "Thus" would present the discovery as a conclusion from the belief, "Similarly" signals agreement, and "In short" signals a summary.$q$, null),
  ($q$ei-h341$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Most bird species build a new nest every breeding season. Bald eagles, ______ often return to the same nest year after year, adding new sticks each time; one nest in Ohio grew to weigh nearly two tons.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["for example,","on the other hand,","consequently,","in addition,"]$q$::jsonb, 1, $q$Bald eagles' reuse of nests contrasts with the usual pattern, so "on the other hand" fits. "Consequently" signals a result, "for example" would present eagles as examples of building new nests, and "in addition" signals addition.$q$, null),
  ($q$ei-h342$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Economists often assume that people make decisions by carefully weighing costs and benefits. ______ behavioral economist Ruth Adeyemi has shown that when shoppers face more than about a dozen options, many simply choose nothing at all.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["As this assumption predicts,","Challenging this assumption,","Like this assumption,","Building on this assumption,"]$q$::jsonb, 1, $q$Adeyemi's finding, that too many options lead people to choose nothing, cuts against the assumption of careful cost-benefit weighing, so "Challenging this assumption" fits. The other choices present the finding as consistent with or derived from the assumption.$q$, null),
  ($q$ei-h343$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The glacier lost about 30 meters of thickness between 1990 and 2010. ______ it lost another 30 meters in just the following eight years, a sign that its melting is accelerating.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Alarmingly,","Conversely,","In other words,","For example,"]$q$::jsonb, 0, $q$The same loss in far less time shows acceleration, a troubling development, so "Alarmingly" fits. "Conversely" signals reversal, "For example" signals an illustration of the first loss, and "In other words" signals restatement.$q$, null),
  ($q$ei-h344$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$In the early 1900s, few people believed that a heavier-than-air machine could fly under its own power. ______ when the Wright brothers made their first successful flights in 1903, many newspapers declined to report the news, assuming it was a hoax.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Similarly,","In contrast,","However,","Thus,"]$q$::jsonb, 3, $q$Widespread disbelief explains why newspapers dismissed the news, so the result transition "Thus" fits. "However" and "In contrast" signal opposition, and "Similarly" signals a parallel.$q$, null),
  ($q$ei-h345$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Sunflowers are famous for tracking the sun across the sky. Only young plants do this, ______ once a sunflower matures and its head opens, it stops moving and faces east permanently.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["in addition;","however;","therefore;","for example;"]$q$::jsonb, 1, $q$The second clause qualifies the famous behavior, which applies only to young plants and not mature ones, so "however" fits. "Therefore" signals a result, "for example" an illustration, and "in addition" an added point.$q$, null),
  ($q$ei-h346$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Historians long believed that the Vikings never reached the Americas, dismissing Norse sagas describing a land called Vinland as legend. ______ in 1960, explorers Helge and Anne Stine Ingstad found the remains of a Norse settlement at L'Anse aux Meadows in Newfoundland.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Likewise,","Therefore,","Instead,","Then,"]$q$::jsonb, 3, $q$The 1960 discovery is the next event in the story, the one that overturned the long-held belief, so "Then" fits. "Therefore" implies the belief caused the discovery, "Likewise" signals agreement, and "Instead" signals replacement of a previous action.$q$, null),
  ($q$ei-h347$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Engineers can make concrete stronger by adding more cement to the mix. ______ cement production is responsible for roughly 8 percent of global carbon dioxide emissions, so stronger concrete often comes at a substantial environmental cost.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Consequently,","For instance,","Unfortunately,","Similarly,"]$q$::jsonb, 2, $q$The environmental cost is an undesirable downside to the method described, so "Unfortunately" fits. "Consequently" claims that adding cement causes cement's share of emissions, "For instance" signals an example, and "Similarly" signals likeness.$q$, null),
  ($q$ei-h348$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The poet wrote in both Spanish and English, often switching between them within a single line. ______ her poems resist translation, since any translator must decide whether to preserve the shifts or flatten them into one language.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In comparison,","For this reason,","Nevertheless,","On the contrary,"]$q$::jsonb, 1, $q$The poet's switching between languages is the reason her poems resist translation, so "For this reason" fits. "On the contrary" and "Nevertheless" signal opposition, and "In comparison" signals a comparison.$q$, null),
  ($q$ei-h349$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Zebra stripes were once thought to serve as camouflage, helping the animals blend into tall grass. Recent experiments suggest a different function. ______ horses wearing striped coats were landed on by biting flies far less often than horses wearing solid coats.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Nonetheless,","Similarly,","Instead,","Specifically,"]$q$::jsonb, 3, $q$The experiment provides details of the "different function" just mentioned, so "Specifically" fits. "Instead" would repeat the contrast already made, "Nonetheless" signals concession, and "Similarly" signals a parallel.$q$, null),
  ($q$ei-h350$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$A typical commercial airliner cruises at about 900 kilometers per hour. The Concorde, ______ cruised at more than twice the speed of sound, crossing the Atlantic in under three and a half hours.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["similarly,","for example,","as a result,","by contrast,"]$q$::jsonb, 3, $q$The Concorde's speed differs sharply from that of typical airliners, so "by contrast" fits. "For example" would present the Concorde as a typical airliner, "as a result" signals cause, and "similarly" signals likeness.$q$, null),
  ($q$ei-h351$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The orchestra had struggled financially for years, and in 2015 its board considered disbanding it. ______ a series of free outdoor concerts drew thousands of new listeners, and within three years the orchestra had doubled its subscriber base.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["That summer, for instance,","That summer, similarly,","That summer, accordingly,","That summer, however,"]$q$::jsonb, 3, $q$The concerts' success reversed the orchestra's decline, so "however" fits. "Accordingly" signals that the near-disbanding caused the success, "similarly" signals a parallel, and "for instance" signals an example.$q$, null),
  ($q$ei-h352$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Tardigrades, microscopic animals often called water bears, can survive being dried out for years. When water returns, they rehydrate and resume normal activity within hours. ______ tardigrades have survived exposure to the vacuum of space, extreme radiation, and temperatures near absolute zero.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Even more remarkably,","As a result,","In contrast,","In other words,"]$q$::jsonb, 0, $q$The final sentence adds even more extreme examples of survival, so "Even more remarkably" fits. "As a result" claims that surviving dryness causes surviving space, "In contrast" signals opposition, and "In other words" signals restatement.$q$, null),
  ($q$ei-h353$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The novelist insisted that her books were not autobiographical. ______ readers who knew her well recognized her mother, her childhood home, and her first marriage in thinly disguised form throughout her fiction.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In fact,","Moreover,","Still,","Thus,"]$q$::jsonb, 2, $q$Readers' recognition of her life in the books contrasts with her denial, so "Still" fits. "Thus" signals a result, and "In fact" and "Moreover" would treat the sentence as reinforcing her denial.$q$, null),
  ($q$ei-h354$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Some species of bamboo flower only once every several decades. ______ all the plants of a given species, even those growing on different continents, tend to flower in the same year, after which they die.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Stranger still,","For this reason,","On the other hand,","In summary,"]$q$::jsonb, 0, $q$Synchronized flowering across continents is an even more surprising fact, so "Stranger still" fits. "For this reason" signals cause, "On the other hand" signals contrast, and "In summary" signals a conclusion.$q$, null),
  ($q$ei-h355$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The ancient Romans built roads that lasted for centuries. Their engineers dug deep trenches and layered them with stones of decreasing size, topped by tightly fitted paving slabs. ______ water drained away quickly, and the roads resisted frost damage.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Apart from this construction,","Despite this construction,","Because of this construction,","Like this construction,"]$q$::jsonb, 2, $q$The layered construction caused the good drainage and frost resistance, so "Because of this construction" fits. "Despite" signals contrast, "Apart from" signals exclusion, and "Like" signals comparison.$q$, null),
  ($q$ei-h356$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The study's authors acknowledged that their sample was small, only forty-two participants. ______ they argued that the effect they observed was large and consistent enough to justify a larger follow-up study.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["In addition,","Therefore,","Nevertheless,","Likewise,"]$q$::jsonb, 2, $q$The authors argue for the finding's value despite the small sample, so "Nevertheless" fits. "Therefore" signals a result, and "Likewise" and "In addition" signal continuation.$q$, null),
  ($q$ei-h357$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$In most mammals, males are larger than females. Among spotted hyenas, ______ females are larger and more aggressive than males and dominate them in social interactions.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["similarly,","however,","therefore,","for example,"]$q$::jsonb, 1, $q$Spotted hyenas reverse the typical pattern, so "however" fits. "Therefore" signals a result, "for example" would present hyenas as typical, and "similarly" signals likeness.$q$, null),
  ($q$ei-h358$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Fireflies produce light through a chemical reaction that releases almost no heat. ______ nearly all of the energy from the reaction is emitted as light, making firefly light one of the most efficient forms of illumination known.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For example,","Still,","On the contrary,","In other words,"]$q$::jsonb, 3, $q$The second sentence restates "almost no heat" as "nearly all of the energy is emitted as light," so "In other words" fits. "On the contrary" signals contradiction, "Still" signals concession, and "For example" signals an example.$q$, null),
  ($q$ei-h359$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Many early computer programmers were women, hired in the 1940s and 1950s because programming was considered clerical work. ______ as the field gained prestige and higher salaries in the 1960s and 1970s, the proportion of women in it began to decline.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Thus,","For instance,","Similarly,","Later,"]$q$::jsonb, 3, $q$The sentence moves forward in time to describe a later change, so "Later" fits. "Thus" signals a result, "Similarly" signals a parallel, and "For instance" signals an example.$q$, null),
  ($q$ei-h360$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The country's population grew steadily throughout the twentieth century. ______ birth rates have fallen sharply since 2000, and demographers project that the population will begin shrinking within the next decade.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["Recently, likewise,","Recently, therefore,","Recently, however,","Recently, for example,"]$q$::jsonb, 2, $q$Falling birth rates contrast with the steady growth of the previous century, so "however" fits. "Therefore" signals a result, "likewise" signals continuation, and "for example" signals an illustration.$q$, null),
  ($q$ei-h361$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$Plants cannot run from insects that eat them, but they are far from defenseless. When a caterpillar chews on a tomato leaf, ______ the plant releases chemicals that make its leaves harder to digest and attract wasps that prey on caterpillars.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["nevertheless,","in contrast,","for instance,","as a result of this,"]$q$::jsonb, 2, $q$The tomato is an example of how plants defend themselves, so "for instance" fits. "In contrast" and "nevertheless" signal opposition. "As a result of this" would make the clause a consequence of plants being far from defenseless, rather than an illustration of it.$q$, null),
  ($q$ei-h362$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Great Green Wall is an initiative to restore degraded land across Africa's Sahel region.<br>• It was launched in 2007 by the African Union.<br>• Its original goal was a continuous belt of trees 8,000 km long.<br>• Planners later shifted to a "mosaic" approach: restoring farmland, grazing land, and water sources rather than only planting trees.<br>• Local farmers had found that many planted seedlings died, while native trees regrown from existing roots survived.$q$, $q$The student wants to explain why the initiative's approach changed. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Great Green Wall now restores farmland, grazing land, and water sources across the Sahel rather than only planting a belt of trees.","Native trees regrown from existing roots survived in the Sahel, while many seedlings planted as part of the Great Green Wall died.","Launched by the African Union in 2007, the Great Green Wall originally aimed to create a continuous belt of trees 8,000 km long stretching all the way across Africa's Sahel region.","After farmers found that planted seedlings often died while regrown native trees survived, the Great Green Wall shifted from a tree belt to a mosaic of restored land."]$q$::jsonb, 3, $q$Only the correct choice links the cause (farmers' observations about seedlings) to the change in approach. The choice beginning "The Great Green Wall…" describes the new approach without a reason, the choice beginning "Native trees regrown from…" gives the reason without the change, and the choice beginning "Launched by the African…" describes only the original goal.$q$, null),
  ($q$ei-h363$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Kintsugi is a Japanese technique for repairing broken pottery.<br>• Cracks are filled with lacquer mixed with powdered gold or silver.<br>• The repair is meant to be visible rather than hidden.<br>• The practice is associated with the idea that an object's history, including damage, adds to its beauty.<br>• It is thought to have originated in the late fifteenth century.$q$, $q$The student wants to emphasize the philosophy behind kintsugi. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In kintsugi, broken pottery is repaired with lacquer mixed with powdered gold or silver, making the cracks shimmer.","Kintsugi makes repairs visible rather than hiding them, reflecting the idea that an object's history, including its damage, adds to its beauty.","Kintsugi originated in Japan in the late fifteenth century as a technique for repairing broken pottery.","Kintsugi, a Japanese repair technique thought to date to the late fifteenth century, fills cracks in pottery with lacquer mixed with gold or silver."]$q$::jsonb, 1, $q$The goal is the philosophy, and only the correct choice explains the idea that damage adds to beauty. The other choices accurately describe the method or origin but say nothing about the philosophy.$q$, null),
  ($q$ei-h364$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers studied two groups of sticklebacks, a small fish.<br>• One group lived in a lake with trout, a predator; the other lived in a lake without trout.<br>• Sticklebacks in the trout lake had more bony armor plates.<br>• Sticklebacks in the trout-free lake had fewer plates but grew faster.<br>• Researchers concluded that armor provides protection but has a cost.$q$, $q$The student wants to present the study's conclusion and the evidence that supports it. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Researchers compared sticklebacks living in a lake with trout, a predator, with sticklebacks living in a lake without trout.","Sticklebacks living with trout had more armor plates, while those in a trout-free lake had fewer plates but grew faster, suggesting that armor protects but has a cost.","Sticklebacks in a trout-free lake grew faster than sticklebacks in a lake with trout, which had more armor plates.","Researchers who compared two groups of sticklebacks concluded that the bony armor plates of the fish provide protection against predators but also come with a cost."]$q$::jsonb, 1, $q$The goal requires both the conclusion and its support. The correct choice gives both. The choice beginning "Researchers who compared two…" gives only the conclusion, the choice beginning "Researchers compared sticklebacks living…" gives only the design, and the choice beginning "Sticklebacks in a trout-free…" gives evidence without the conclusion.$q$, null),
  ($q$ei-h365$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Zora Neale Hurston (1891–1960) was a novelist and anthropologist.<br>• She studied anthropology with Franz Boas at Barnard College.<br>• In the late 1920s, she collected folktales and songs in Florida and Louisiana.<br>• Her 1935 book <i>Mules and Men</i> presented this folklore.<br>• Her novel <i>Their Eyes Were Watching God</i> (1937) draws on the speech patterns she recorded.$q$, $q$The student wants to show how Hurston's anthropological work influenced her fiction. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Hurston studied anthropology with Franz Boas at Barnard College before collecting folktales and songs in Florida and Louisiana in the late 1920s and publishing them in 1935.","Hurston's novel <i>Their Eyes Were Watching God</i> draws on the speech patterns she recorded while collecting folklore in Florida and Louisiana.","In 1935, Hurston published <i>Mules and Men</i>, a book that presented the folktales and songs she had collected in the South.","Zora Neale Hurston, who lived from 1891 to 1960, was both a novelist and an anthropologist."]$q$::jsonb, 1, $q$Only the correct choice connects her field recordings to a novel. <i>Mules and Men</i> in the choice beginning "In 1935, Hurston published…" is a nonfiction folklore collection, so it doesn't show influence on fiction, and the other choices describe training or her dual career without connecting them.$q$, null),
  ($q$ei-h366$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Venus and Earth are similar in size and mass.<br>• Venus's surface temperature averages about 465°C.<br>• Its atmosphere is about 96% carbon dioxide.<br>• The thick atmosphere traps heat through a runaway greenhouse effect.<br>• Venus is hotter than Mercury, even though Mercury is closer to the Sun.$q$, $q$The student wants to explain why Venus is hotter than Mercury. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Venus's atmosphere is about 96% carbon dioxide, and its surface temperature averages about 465°C.","Venus, which is similar to Earth in size and mass, has a surface temperature averaging about 465°C.","Venus is hotter than Mercury, even though Mercury is closer to the Sun and Venus is similar in size and mass to Earth, with a surface temperature averaging about 465°C.","Although Mercury is closer to the Sun, Venus is hotter because its thick, carbon dioxide–rich atmosphere traps heat through a runaway greenhouse effect."]$q$::jsonb, 3, $q$The goal is an explanation. Only the correct choice gives the cause, the greenhouse effect of the thick atmosphere. The choice beginning "Venus's atmosphere is about…" lists the facts without linking them, and the choice beginning "Venus is hotter than…" states the comparison without explaining it.$q$, null),
  ($q$ei-h367$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Linguists classify about 7,000 languages into roughly 140 families.<br>• The Indo-European family includes English, Hindi, and Russian.<br>• It has about 3.3 billion native speakers.<br>• The Niger-Congo family includes Swahili, Yoruba, and Zulu.<br>• It contains more than 1,500 languages, more than any other family.$q$, $q$The student wants to contrast the two language families in terms of size. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Both the Indo-European family and the Niger-Congo family are among the roughly 140 language families classified by linguists.","The Indo-European family includes English, Hindi, and Russian, while the Niger-Congo family includes Swahili, Yoruba, and Zulu, among roughly 140 families classified by linguists.","The Indo-European family has about 3.3 billion native speakers, while the Niger-Congo family has more languages than any other family, more than 1,500.","With more than 1,500 languages, Niger-Congo is the largest of the roughly 140 language families that linguists recognize."]$q$::jsonb, 2, $q$The correct choice contrasts the two families on two measures of size: number of speakers and number of languages. The choice beginning "The Indo-European family includes…" compares member languages, not size, the choice beginning "With more than 1,500…" describes only one family, and the choice beginning "Both the Indo-European family…" notes a similarity rather than a contrast.$q$, null),
  ($q$ei-h368$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• In 1977, Kenyan biologist Wangari Maathai founded the Green Belt Movement.<br>• The movement paid rural women to plant trees.<br>• It has planted more than 51 million trees in Kenya.<br>• The trees provided firewood, reduced soil erosion, and gave women an income.<br>• Maathai won the Nobel Peace Prize in 2004.$q$, $q$The student wants to describe the benefits of the Green Belt Movement to an audience unfamiliar with it. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The trees planted by the movement provided firewood, reduced soil erosion, and gave women an income, and its founder later received the Nobel Peace Prize in 2004.","Since 1977, the Green Belt Movement has planted more than 51 million trees in Kenya.","The Green Belt Movement, founded in Kenya in 1977, paid rural women to plant trees, which gave them an income while supplying firewood and reducing soil erosion.","Wangari Maathai, who founded the Green Belt Movement in 1977, won the Nobel Peace Prize in 2004."]$q$::jsonb, 2, $q$An unfamiliar audience needs the movement introduced, and the goal is its benefits. The correct choice does both. The choice beginning "The trees planted by…" lists benefits but doesn't identify the movement ("the movement" assumes prior knowledge). The others give a prize or a tree count rather than benefits.$q$, null),
  ($q$ei-h369$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Antikythera mechanism was found in a shipwreck off a Greek island in 1901.<br>• It dates to roughly the second century BCE.<br>• It contains at least 30 interlocking bronze gears.<br>• It was used to predict the positions of the Sun and Moon and the dates of eclipses.<br>• No device of comparable complexity is known from the following thousand years.$q$, $q$The student wants to emphasize how advanced the mechanism was for its time. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Built around the second century BCE, the Antikythera mechanism used at least 30 bronze gears, a complexity unmatched by any known device for the next thousand years.","Discovered off a Greek island in 1901, the Antikythera mechanism contains at least 30 interlocking bronze gears.","The Antikythera mechanism, which dates to the second century BCE, was recovered from a shipwreck off a Greek island.","The Antikythera mechanism, found in a shipwreck off a Greek island in 1901, was used to predict the positions of the Sun and Moon as well as the dates of eclipses."]$q$::jsonb, 0, $q$To emphasize how advanced the device was for its time, the sentence needs its date and a comparison with later technology. Only the correct choice includes the comparison. The choice beginning "Discovered off a Greek…" gives the gear count without establishing that it was unusual for the era.$q$, null),
  ($q$ei-h370$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Most clouds form when air rises and cools.<br>• Contrails are clouds that form behind aircraft.<br>• They form when hot, humid exhaust mixes with cold air at high altitude.<br>• Some contrails disappear within seconds; others spread into cirrus-like clouds lasting hours.<br>• Persistent contrails can trap heat, contributing to warming.$q$, $q$The student wants to explain how contrails form differently from most clouds. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["While most clouds form when rising air cools, contrails form when an aircraft's hot, humid exhaust mixes with cold air at high altitude.","Persistent contrails, which can spread into cirrus-like clouds, trap heat and contribute to warming, unlike most other clouds.","Contrails, the clouds that form behind aircraft, can either disappear within seconds or spread into cirrus-like clouds lasting hours.","Contrails form when hot, humid exhaust from aircraft mixes with cold air at high altitude, sometimes creating persistent clouds."]$q$::jsonb, 0, $q$The goal is a difference in formation. Only the correct choice contrasts both formation processes. The choice beginning "Contrails form when hot…" explains contrail formation without the comparison, the choice beginning "Contrails, the clouds that…" addresses duration, and the choice beginning "Persistent contrails, which can…" makes a comparison about warming that the notes don't support.$q$, null),
  ($q$ei-h371$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers gave two groups of students the same math test.<br>• Group A was told the test measured innate ability.<br>• Group B was told the test measured skills that improve with practice.<br>• Group B students attempted more of the hardest problems.<br>• The two groups' overall scores did not differ significantly.$q$, $q$The student wants to present a finding of the study that might surprise readers. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Students who were told that a math test measured skills that improve with practice attempted more of the test's hardest problems.","Researchers gave two groups of students the same math test but told each group something different about what it measured.","Students told that the test measured improvable skills attempted more hard problems, yet their overall scores were no better than those of students told it measured innate ability.","In the study, one group of students was told that a math test measured innate ability, while another group was told that the same test measured skills that improve with practice."]$q$::jsonb, 2, $q$The surprising result is that attempting more hard problems didn't produce higher scores, and only the correct choice combines those findings. The choice beginning "Students who were told…" gives an expected result on its own, and the others describe the design.$q$, null),
  ($q$ei-h372$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Hokusai's <i>The Great Wave off Kanagawa</i> is a Japanese woodblock print from around 1831.<br>• It was printed in thousands of copies and sold cheaply.<br>• It used Prussian blue, a synthetic pigment recently imported from Europe.<br>• The print later influenced European artists such as Claude Monet and Vincent van Gogh.$q$, $q$The student wants to highlight the two-way artistic exchange between Japan and Europe. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Hokusai's <i>The Great Wave</i> used Prussian blue, a pigment imported from Europe, and in turn influenced European artists such as Monet and van Gogh.","Printed in thousands of copies, Hokusai's <i>The Great Wave</i> used Prussian blue, a synthetic pigment.","Hokusai's <i>The Great Wave</i>, a Japanese woodblock print sold cheaply in thousands of copies around 1831, later influenced European artists such as Claude Monet and Vincent van Gogh.","Hokusai's <i>The Great Wave</i> is a Japanese woodblock print that was sold cheaply in thousands of copies around 1831."]$q$::jsonb, 0, $q$A two-way exchange requires influence in both directions: a European pigment used in Japan, and the Japanese print influencing European artists. Only the correct choice includes both. The choice beginning "Hokusai's The Great Wave…" shows only one direction, and the choice beginning "Printed in thousands of…" omits that the pigment came from Europe.$q$, null),
  ($q$ei-h373$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Axolotls are salamanders native to lakes near Mexico City.<br>• Unlike most amphibians, they keep juvenile features, including gills, into adulthood.<br>• They can regrow lost limbs, parts of their hearts, and even parts of their brains.<br>• Scientists study them to understand tissue regeneration.<br>• Wild populations are critically endangered.$q$, $q$The student wants to explain why axolotls are of interest to scientists. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Because axolotls can regrow lost limbs and even parts of their hearts and brains, scientists study them to understand how tissue regenerates.","Unlike most amphibians, axolotls keep juvenile features into adulthood and can regrow lost limbs.","Although scientists study axolotls, wild populations of these salamanders are critically endangered.","Axolotls, salamanders native to lakes near Mexico City, keep their gills and other juvenile features into adulthood, unlike most other amphibians."]$q$::jsonb, 0, $q$The correct choice connects the regeneration ability to the scientific interest. The choice beginning "Unlike most amphibians, axolotls…" mentions regeneration but doesn't explain the scientific interest, and the others describe appearance or conservation status.$q$, null),
  ($q$ei-h374$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Erie Canal opened in 1825, linking the Hudson River to Lake Erie.<br>• Before the canal, shipping a ton of goods from Buffalo to New York City cost about $100.<br>• After the canal opened, the cost fell to about $10.<br>• Travel time dropped from about three weeks to eight days.<br>• New York City soon became the nation's busiest port.$q$, $q$The student wants to quantify the canal's effect on shipping. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Opened in 1825, the Erie Canal connected the Hudson River with Lake Erie, a distance once traveled in about three weeks.","After the Erie Canal opened, the cost of shipping a ton of goods from Buffalo to New York City fell from about $100 to $10, and travel time dropped from three weeks to eight days.","The Erie Canal, which opened in 1825, linked the Hudson River to Lake Erie and greatly reduced the cost and time of shipping, helping make New York City the nation's busiest port.","The Erie Canal dramatically reduced the cost and time of shipping goods between Buffalo and New York City."]$q$::jsonb, 1, $q$To quantify means to give numbers. Only the correct choice gives before-and-after figures for both cost and time. The choice beginning "The Erie Canal dramatically…" describes the effect only in general terms, and the others describe the canal's route or later importance.$q$, null),
  ($q$ei-h375$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Soprano Leontyne Price was born in Laurel, Mississippi, in 1927.<br>• In 1955, she sang the title role in an NBC television broadcast of <i>Tosca</i>.<br>• She was the first Black singer to perform opera on network television.<br>• In 1961, she made her Metropolitan Opera debut in <i>Il Trovatore</i>.<br>• The audience applauded for 42 minutes after the performance.$q$, $q$The student wants to emphasize the reception of Price's Metropolitan Opera debut. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Leontyne Price, born in Mississippi in 1927, made her Metropolitan Opera debut in <i>Il Trovatore</i> in 1961.","When Leontyne Price made her Metropolitan Opera debut in <i>Il Trovatore</i> in 1961, the audience applauded for 42 minutes.","Six years after her televised <i>Tosca</i>, Leontyne Price made her Metropolitan Opera debut.","In 1955, Leontyne Price became the first Black singer to perform opera on network television, singing the title role in <i>Tosca</i>."]$q$::jsonb, 1, $q$"Reception" refers to how the audience responded. Only the correct choice mentions the 42 minutes of applause. The other choices identify the debut or her earlier television milestone without describing a response.$q$, null),
  ($q$ei-h376$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Desert locusts usually live alone and avoid one another.<br>• When crowded, they undergo a change called gregarization.<br>• Gregarious locusts change color, become more active, and seek out other locusts.<br>• The change is triggered by repeated touching of their hind legs.<br>• Swarms can contain billions of locusts and devastate crops.$q$, $q$The student wants to explain what triggers locusts to begin swarming. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["When crowding causes repeated touching of their hind legs, desert locusts undergo gregarization, changing from solitary insects into ones that seek each other out.","Desert locusts usually live alone and avoid one another, but sometimes they form enormous swarms.","Swarms of desert locusts can contain billions of insects and devastate crops across large regions.","Desert locusts that undergo gregarization change color, become more active, and seek out other locusts, eventually forming swarms of billions that can devastate crops."]$q$::jsonb, 0, $q$The goal is the trigger. Only the correct choice names it: repeated touching of the hind legs caused by crowding. The choice beginning "Desert locusts that undergo…" describes the change without its cause, and the others describe swarms or the locusts' usual behavior.$q$, null),
  ($q$ei-h377$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers surveyed 1,200 residents of a city about their use of public parks.<br>• Residents living within 400 meters of a park visited an average of 3.1 times per week.<br>• Residents living more than 1 kilometer away visited an average of 0.6 times per week.<br>• Frequent park visitors reported lower stress levels.<br>• The city plans to build parks in neighborhoods currently lacking them.$q$, $q$The student wants to support the city's plan using the survey's findings. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The city plans to build new parks in neighborhoods that currently lack them, according to a survey of 1,200 residents.","Residents who visited parks frequently reported lower stress levels than those who visited less often, a survey found.","Since residents near parks visited about five times as often as those living far away, and frequent visitors reported less stress, new parks in underserved neighborhoods could benefit residents.","A survey of 1,200 residents found that those living within 400 meters of a park visited an average of 3.1 times per week, and the city now plans to build parks in neighborhoods lacking them."]$q$::jsonb, 2, $q$Supporting the plan requires linking proximity to use and use to benefits, then applying this to new parks. The correct choice does all three. The other choices present only one finding or misattribute the plan to the survey.$q$, null),
  ($q$ei-h378$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Physicist Chien-Shiung Wu (1912–1997) designed a 1956 experiment involving radioactive cobalt-60.<br>• The experiment tested a principle called parity conservation.<br>• Physicists had assumed nature does not distinguish between left and right.<br>• Wu's results showed that, in certain nuclear decays, nature does.<br>• Theorists Tsung-Dao Lee and Chen Ning Yang, who proposed the test, won the 1957 Nobel Prize; Wu did not.$q$, $q$The student wants to emphasize the significance of Wu's experimental results. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Chien-Shiung Wu, who lived from 1912 to 1997, was a physicist who designed experiments with radioactive materials.","Theorists Lee and Yang, who proposed the test that Wu carried out, received the 1957 Nobel Prize, but Wu did not.","Wu's 1956 experiment overturned a long-held assumption, showing that in certain nuclear decays nature does distinguish between left and right.","In 1956, Chien-Shiung Wu designed an experiment using radioactive cobalt-60 to test parity conservation, a principle proposed for testing by theorists Lee and Yang."]$q$::jsonb, 2, $q$The significance lies in overturning the assumption about left and right, which only the correct choice states. The choice beginning "In 1956, Chien-Shiung Wu…" describes the experiment without its result, and the choice beginning "Theorists Lee and Yang…" concerns recognition rather than the result's significance.$q$, null),
  ($q$ei-h379$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Mount Everest's height was measured by Indian surveyors in 1856 as 8,840 meters.<br>• A 1955 survey measured it at 8,848 meters.<br>• A 2020 joint survey by China and Nepal measured 8,848.86 meters.<br>• Measurements differ partly because of snow depth and differing reference points for sea level.<br>• The peak is also rising slowly because of tectonic activity.$q$, $q$The student wants to explain why measurements of Everest's height have varied. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Measurements of Everest's height have varied partly because surveyors have dealt differently with snow depth and with where sea level is defined to be.","Everest's height was measured at 8,840 meters in 1856, 8,848 meters in 1955, and 8,848.86 meters in 2020.","Because of tectonic activity, Mount Everest is slowly rising, so it is taller today than in 1856.","A 2020 joint survey by China and Nepal measured Mount Everest at 8,848.86 meters, nearly nine meters more than the figure Indian surveyors reported in 1856."]$q$::jsonb, 0, $q$The correct answer gives the reasons for the variation. The choice beginning "Everest's height was measured…" shows that the measurements varied but not why, the choice beginning "A 2020 joint survey…" reports a single measurement, and the choice beginning "Because of tectonic activity…" gives a factor (rising) that the notes don't present as the reason the measurements differ.$q$, null),
  ($q$ei-h380$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Novelist Kazuo Ishiguro was born in Nagasaki, Japan, in 1954.<br>• His family moved to England when he was five.<br>• His early novels, such as <i>A Pale View of Hills</i>, are set partly in Japan.<br>• <i>The Remains of the Day</i> (1989) is narrated by an English butler.<br>• He won the Nobel Prize in Literature in 2017.$q$, $q$The student wants to show the range of Ishiguro's settings. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Ishiguro, who won the 2017 Nobel Prize in Literature, wrote <i>The Remains of the Day</i> in 1989.","Ishiguro's novels range from <i>A Pale View of Hills</i>, set partly in Japan, to <i>The Remains of the Day</i>, narrated by an English butler.","Born in Nagasaki in 1954, Ishiguro moved to England with his family at the age of five.","Ishiguro's early novels, such as <i>A Pale View of Hills</i>, are set partly in Japan, where he was born in 1954 before moving to England at age five."]$q$::jsonb, 1, $q$Showing range requires contrasting settings from different works. Only the correct choice pairs a Japanese setting with an English one. The choice beginning "Ishiguro's early novels, such…" describes one setting only, and the others concern biography or awards.$q$, null),
  ($q$ei-h381$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers compared two methods for teaching fractions.<br>• Method 1 used number lines; Method 2 used pie diagrams.<br>• After six weeks, Method 1 students scored 18 points higher on a fractions test.<br>• The gap was largest on problems comparing fractions with different denominators.<br>• Both groups scored similarly on problems with like denominators.$q$, $q$The student wants to specify where the advantage of number lines was greatest. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Students taught with number lines outperformed those taught with pie diagrams most on problems comparing fractions with different denominators.","After six weeks, students taught with number lines scored 18 points higher on a fractions test than students who had been taught with pie diagrams instead.","Researchers compared two methods for teaching fractions, one using number lines and one using pie diagrams.","Students taught with number lines and students taught with pie diagrams scored similarly on problems with like denominators."]$q$::jsonb, 0, $q$The goal is the location of the greatest advantage, which only the correct choice identifies. The choice beginning "After six weeks, students…" gives the overall advantage, the choice beginning "Students taught with number lines and…" reports where there was no advantage, and the choice beginning "Researchers compared two methods…" describes the design.$q$, null),
  ($q$ei-h382$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Tarantula hawks are wasps that hunt tarantulas.<br>• A female paralyzes a tarantula with her sting.<br>• She drags it to a burrow and lays a single egg on it.<br>• The larva feeds on the living but paralyzed spider.<br>• Adult tarantula hawks feed mainly on flower nectar.$q$, $q$The student wants to contrast the diets of tarantula hawk larvae and adults. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["A female tarantula hawk paralyzes a tarantula and lays a single egg on it, and the larva feeds on the spider.","Tarantula hawks paralyze tarantulas with their stings and then drag them into burrows.","Adult tarantula hawks, wasps known for hunting tarantulas, feed mainly on flower nectar.","Tarantula hawk larvae feed on paralyzed tarantulas, but adults feed mainly on flower nectar."]$q$::jsonb, 3, $q$Only the correct choice gives both diets and contrasts them. The choice beginning "A female tarantula hawk…" gives only the larval diet, the choice beginning "Adult tarantula hawks, wasps…" only the adult diet, and the choice beginning "Tarantula hawks paralyze tarantulas…" describes hunting behavior.$q$, null),
  ($q$ei-h383$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Fast fashion refers to clothing produced quickly and cheaply to follow trends.<br>• The average consumer buys 60% more clothing than in 2000.<br>• Each item is kept about half as long.<br>• The fashion industry produces about 10% of global carbon emissions.<br>• Some brands now offer repair services and resale programs.$q$, $q$The student wants to argue that consumer habits contribute to fast fashion's environmental impact. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Since 2000, consumers have bought 60% more clothing and kept each item half as long, habits that fuel an industry responsible for about 10% of global carbon emissions.","Some fashion brands have begun offering repair services and resale programs to customers who want to keep clothing longer.","The fashion industry produces about 10% of global carbon emissions, though some brands now offer repair services and resale programs intended to keep clothing in use longer.","Fast fashion refers to clothing that is produced quickly and cheaply in order to follow the latest trends."]$q$::jsonb, 0, $q$The argument requires both consumer habits and the environmental impact, linked together. Only the correct choice provides both. The choice beginning "The fashion industry produces…" gives the impact but no consumer habits, and the others define the term or describe brand responses.$q$, null),
  ($q$ei-h384$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Sign languages are full natural languages with their own grammar.<br>• American Sign Language (ASL) and British Sign Language (BSL) are mutually unintelligible.<br>• ASL is more closely related to French Sign Language.<br>• This is because a French teacher, Laurent Clerc, helped found the first American school for deaf students in 1817.$q$, $q$The student wants to explain a surprising relationship between sign languages. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Sign languages, including American Sign Language and French Sign Language, are full natural languages with their own grammar.","In 1817, French teacher Laurent Clerc helped found the first school for deaf students in the United States.","American Sign Language and British Sign Language are mutually unintelligible, even though both are full natural languages with their own grammar and are used in English-speaking countries.","Although the United States and Britain share a spoken language, ASL is closer to French Sign Language, because a French teacher helped found the first American school for deaf students."]$q$::jsonb, 3, $q$The surprising relationship is ASL's closeness to French rather than British Sign Language, and the correct choice states and explains it. The choice beginning "American Sign Language and…" states that ASL and BSL differ without the explanation, and the others give background only. The shared spoken language is common knowledge used to frame the surprise.$q$, null),
  ($q$ei-h385$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Sociologist Mira Castell interviewed 80 remote workers.<br>• 70% said they were more productive at home.<br>• 55% said they felt more isolated from colleagues.<br>• Workers who had video calls at least three times a week reported less isolation.<br>• Castell recommends regular video check-ins for remote teams.$q$, $q$The student wants to present Castell's recommendation and the evidence behind it. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Castell, a sociologist, recommends that remote teams schedule regular video check-ins.","Because remote workers who had video calls at least three times a week reported less isolation, Castell recommends regular video check-ins for remote teams.","Castell found that 70% of the remote workers she interviewed said they were more productive at home.","Of the 80 remote workers Castell interviewed, 55% said that they felt more isolated from colleagues, even though 70% said they were more productive at home."]$q$::jsonb, 1, $q$Only the correct choice gives the recommendation and the evidence that directly supports it. The choice beginning "Castell, a sociologist, recommends…" gives the recommendation alone, and the choices beginning "Castell found that 70%…" and "Of the 80 remote…" give findings that don't support the recommendation by themselves.$q$, null),
  ($q$ei-h386$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Tasmanian devil is a carnivorous marsupial found only in Tasmania.<br>• Since 1996, a contagious facial cancer has killed about 80% of the population.<br>• The cancer spreads when devils bite one another during feeding and mating.<br>• Some devil populations now show genetic changes linked to cancer resistance.<br>• These changes appeared within just a few generations.$q$, $q$The student wants to emphasize how quickly the devils have responded to the disease. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The facial cancer affecting Tasmanian devils spreads when the animals bite one another during feeding and mating.","Since 1996, a contagious facial cancer spread by biting has killed about 80% of Tasmania's devil population.","Some populations of Tasmanian devils, carnivorous marsupials found only in Tasmania, now show genetic changes linked to cancer resistance.","Within just a few generations, some Tasmanian devil populations have developed genetic changes linked to resistance to the facial cancer."]$q$::jsonb, 3, $q$The goal concerns the speed of the response, and only the correct choice mentions "just a few generations." The choice beginning "Some populations of Tasmanian…" describes the resistance without its speed, and the others describe the disease.$q$, null),
  ($q$ei-h387$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Bauhaus was a German school of art and design (1919–1933).<br>• It aimed to unite fine art with craft and industrial production.<br>• Students studied weaving, metalwork, and furniture design alongside painting.<br>• Many of its designs, such as tubular steel chairs, were meant for mass production.<br>• The school closed under political pressure in 1933.$q$, $q$The student wants to illustrate the Bauhaus's goal with a specific example. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Bauhaus, a German school of art and design that operated from 1919 until 1933, aimed to unite fine art with craft and industry.","The Bauhaus, which aimed to unite fine art with craft and industrial production, closed under political pressure in 1933.","At the Bauhaus, students studied weaving, metalwork, and furniture design alongside painting until the school closed in 1933.","Seeking to unite art with industrial production, the Bauhaus produced designs such as tubular steel chairs intended for mass manufacture."]$q$::jsonb, 3, $q$The correct choice states the goal and supplies a concrete example that embodies it. The choice beginning "The Bauhaus, a German…" states the goal without an example, the choice beginning "At the Bauhaus, students…" lists subjects without linking them to the goal, and the fourth pairs the goal with the school's closing.$q$, null),
  ($q$ei-h388$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Ecologists studied two types of urban rooftops in Toronto.<br>• Conventional rooftops reached surface temperatures of up to 70°C in summer.<br>• Green roofs, covered with plants, reached a maximum of about 30°C.<br>• Green roofs also absorbed about 60% of rainfall.<br>• Installation costs for green roofs are higher.$q$, $q$The student wants to compare the two rooftops' summer temperatures. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Although green roofs cost more to install than conventional roofs, they absorbed about 60% of rainfall in a Toronto study.","Ecologists in Toronto studied two kinds of rooftops: conventional rooftops and green roofs covered with plants.","In summer, conventional rooftops in Toronto reached surface temperatures of up to 70°C, while green roofs peaked at about 30°C.","Green roofs in Toronto, which are covered with plants, reached a maximum surface temperature of about 30°C during the summer months."]$q$::jsonb, 2, $q$A comparison requires both temperatures. Only the correct choice gives them. The choice beginning "Green roofs in Toronto…" gives only the green roof's temperature, the third discusses rainfall and cost, and the choice beginning "Ecologists in Toronto studied…" describes the study's subjects.$q$, null),
  ($q$ei-h389$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Ada Lovelace (1815–1852) wrote notes on Charles Babbage's proposed Analytical Engine.<br>• Her notes included a method for calculating Bernoulli numbers with the machine.<br>• This is often called the first published computer program.<br>• She also suggested the machine could manipulate symbols, such as musical notes, not just numbers.<br>• The Analytical Engine was never built.$q$, $q$The student wants to emphasize that Lovelace saw possibilities beyond calculation. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Ada Lovelace, who lived from 1815 to 1852, wrote notes on a calculating machine proposed by Charles Babbage.","Lovelace's notes on the Analytical Engine included a method for calculating Bernoulli numbers, often called the first published program.","Lovelace suggested that Babbage's Analytical Engine could manipulate symbols such as musical notes, not merely perform numerical calculations.","Although Babbage's Analytical Engine was never built, Lovelace wrote detailed notes describing how the machine could be used."]$q$::jsonb, 2, $q$Only the correct choice describes her vision beyond numbers. The choice beginning "Lovelace's notes on the…" describes a calculation, which is precisely what the goal asks to go beyond, and the others give background.$q$, null),
  ($q$ei-h390$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Atacama Desert in Chile is one of the driest places on Earth.<br>• Some weather stations there have never recorded rain.<br>• Its high altitude and clear skies make it ideal for astronomy.<br>• It hosts major observatories, including ALMA, a radio telescope array.<br>• Its soil is so dry that NASA has tested Mars rovers there.$q$, $q$The student wants to explain how the Atacama's dryness makes it useful to scientists. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Because the Atacama is one of the driest places on Earth, it hosts major observatories and has been used by NASA scientists.","The Atacama Desert in Chile, one of the driest places on Earth, includes weather stations that have never recorded rain.","The Atacama's soil is so dry that NASA has used the desert to test rovers designed to explore Mars.","The Atacama's high altitude and clear skies have made it home to major observatories, including the ALMA radio telescope array."]$q$::jsonb, 2, $q$The correct choice links dryness specifically to a scientific use. The choice beginning "The Atacama's high altitude…" attributes the astronomy to altitude and clear skies rather than dryness, the choice beginning "The Atacama Desert in…" describes dryness without a use, and the fourth vaguely links dryness to uses without explaining how.$q$, null),
  ($q$ei-h391$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Psychologists asked 300 people to predict how happy they would be a year after a major event.<br>• Participants predicted that winning a prize would raise their happiness greatly.<br>• They predicted that losing a job would lower it greatly.<br>• A year later, happiness had shifted far less than predicted in both cases.<br>• Researchers call this tendency "impact bias."$q$, $q$The student wants to define impact bias for an audience unfamiliar with the term. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Impact bias is the tendency to overestimate how much a major event, good or bad, will change one's happiness over time.","After a year, participants' happiness had shifted far less than they had predicted, whether they had won a prize or lost a job.","Researchers use the term \"impact bias\" to describe a tendency they observed among 300 people asked to predict their future happiness.","In one study, people predicted that winning a prize would greatly raise their happiness, but a year later it had changed far less."]$q$::jsonb, 0, $q$Defining the term requires stating what it is. Only the correct choice gives a general definition. The choices beginning "In one study, people…" and "After a year, participants'…" describe results without naming the bias, and the choice beginning "Researchers use the term…" names the term without explaining it.$q$, null),
  ($q$ei-h392$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Mongol Empire's postal relay system was called the Yam.<br>• Stations were placed about every 30–50 kilometers.<br>• Riders could change horses at each station.<br>• Messages could travel up to 300 kilometers per day.<br>• Foreign travelers, including Marco Polo, described the system.$q$, $q$The student wants to explain how the Yam achieved its speed. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Because riders could change horses at stations spaced every 30–50 kilometers, messages in the Mongol Yam could travel up to 300 kilometers per day.","Foreign travelers, including Marco Polo, described the Yam, a postal relay system operated by the Mongol Empire.","The Mongol Empire's postal relay system, called the Yam, could carry messages as far as 300 kilometers in a single day, as foreign travelers such as Marco Polo described.","The Yam had stations every 30–50 kilometers, and foreign visitors such as Marco Polo wrote about the system."]$q$::jsonb, 0, $q$Only the correct choice explains the mechanism behind the speed: fresh horses at closely spaced stations. The choice beginning "The Mongol Empire's postal…" gives the speed without the cause, and the others mention travelers' accounts.$q$, null),
  ($q$ei-h393$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Two studies examined the effect of background music on reading.<br>• Study 1 (2015) found that instrumental music did not affect reading comprehension.<br>• Study 2 (2019) found that music with lyrics reduced comprehension by 12%.<br>• Both studies used college students as participants.$q$, $q$The student wants to present the studies' findings as consistent with a single conclusion. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["A 2015 study found that instrumental music did not affect reading comprehension, but a 2019 study found that background music did reduce it, so the studies' findings conflict.","A 2019 study found that background music with lyrics reduced college students' reading comprehension by 12%.","Both a 2015 study and a 2019 study used college students as participants to examine the effect of background music on reading.","Taken together, the studies suggest that lyrics, rather than music itself, interfere with reading: instrumental music had no effect, while music with lyrics reduced comprehension."]$q$::jsonb, 3, $q$The correct answer synthesizes both findings into one conclusion about lyrics. The choice beginning "A 2015 study found…" presents the studies as conflicting by omitting the lyrics distinction, the choice beginning "Both a 2015 study…" describes methods, and the choice beginning "A 2019 study found…" reports one study only.$q$, null),
  ($q$ei-h394$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Lake Baikal in Siberia is the world's deepest lake, at 1,642 meters.<br>• It holds about 20% of the world's unfrozen fresh surface water.<br>• It is about 25 million years old, the oldest lake on Earth.<br>• About 80% of its animal species are found nowhere else.<br>• Scientists link this high endemism to the lake's age and isolation.$q$, $q$The student wants to explain why so many of Baikal's species are unique. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Scientists link the fact that about 80% of Baikal's animal species are found nowhere else to the lake's great age and isolation.","Lake Baikal holds about 20% of the world's unfrozen fresh surface water and is home to many unique animal species.","About 80% of the animal species in Lake Baikal, the world's deepest lake, are found nowhere else on Earth.","Lake Baikal is about 25 million years old, making it the oldest lake on Earth, and it is also the deepest at 1,642 meters."]$q$::jsonb, 0, $q$Only the correct choice gives the explanation scientists offer. The choice beginning "About 80% of the…" states the fact without a cause, and the others list impressive figures without linking them to endemism.$q$, null),
  ($q$ei-h395$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Kente is a woven cloth originating with the Asante people of Ghana.<br>• It is woven in narrow strips, which are then sewn together.<br>• Each pattern and color has a name and meaning.<br>• Gold represents wealth; green represents growth and renewal.<br>• It was traditionally worn by royalty on important occasions.$q$, $q$The student wants to explain how meaning is conveyed through kente. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Kente cloth was traditionally worn by Asante royalty on important occasions, often featuring gold and green.","Kente cloth, which originated with the Asante people of Ghana and was traditionally worn by royalty, is woven in narrow strips that are later sewn together.","Originating with the Asante people of Ghana, kente is a woven cloth whose strips are sewn together into larger pieces.","In kente cloth, each pattern and color carries a name and meaning; gold, for example, represents wealth, and green represents growth and renewal."]$q$::jsonb, 3, $q$Only the correct choice explains that meaning lies in named patterns and colors, with examples. The choice beginning "Kente cloth was traditionally…" mentions colors without their meanings, and the others describe construction or origins.$q$, null),
  ($q$ei-h396$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• A team tested a new water filter in 12 villages.<br>• Before the filter, 34% of children had diarrheal illness each month.<br>• After one year, the rate dropped to 19%.<br>• In 12 comparison villages without the filter, the rate stayed near 33%.<br>• The filter costs about $15 per household.$q$, $q$The student wants to show that the drop in illness was likely caused by the filter. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In 12 villages without the filter, the monthly rate of diarrheal illness among children stayed near 33% throughout the year.","After one year of using the new water filter, which costs about $15 per household, the rate of diarrheal illness among children in 12 villages dropped from 34% to 19%.","The new water filter, which costs about $15 per household, was tested in 12 villages, where it reduced childhood illness.","Illness rates fell from 34% to 19% in villages that received the filter but stayed near 33% in comparable villages without it, suggesting the filter caused the drop."]$q$::jsonb, 3, $q$Showing causation requires the comparison group: illness dropped only where the filter was used. Only the correct choice includes both groups. The choice beginning "After one year of…" reports the drop without a comparison, which leaves other explanations open.$q$, null),
  ($q$ei-h397$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Hedy Lamarr (1914–2000) was a Hollywood film star.<br>• During World War II, she co-invented a frequency-hopping radio system with composer George Antheil.<br>• The system was designed to keep torpedo guidance signals from being jammed.<br>• The U.S. Navy did not adopt it during the war.<br>• Related techniques are now used in Wi-Fi and Bluetooth.$q$, $q$The student wants to highlight the lasting impact of Lamarr's invention. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["During World War II, Lamarr and composer George Antheil co-invented a frequency-hopping system to prevent jamming of torpedo signals.","Techniques related to the frequency-hopping system that Lamarr co-invented during World War II are used today in Wi-Fi and Bluetooth.","Although Lamarr co-invented a frequency-hopping radio system, the U.S. Navy did not adopt it during World War II.","Hedy Lamarr, a Hollywood film star who lived from 1914 to 2000, was also the co-inventor of a radio system."]$q$::jsonb, 1, $q$Lasting impact concerns modern uses, which only the correct choice mentions. The choice beginning "During World War II…" describes the invention's original purpose, the choice beginning "Although Lamarr co-invented a…" its lack of wartime adoption, and the choice beginning "Hedy Lamarr, a Hollywood…" her dual career.$q$, null),
  ($q$ei-h398$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers placed identical wallets on streets in 40 countries.<br>• Some wallets held no money; others held about $13.<br>• In 38 of 40 countries, wallets with money were returned more often than empty ones.<br>• Economists had predicted the opposite, expecting people to keep money.<br>• The researchers suggest that people dislike seeing themselves as thieves.$q$, $q$The student wants to present the study's results as contradicting expectations. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In a study spanning 40 countries, researchers placed identical wallets on streets, some empty and some holding about $13, to see how often people would return them.","The researchers suggest that people return wallets containing money because they dislike seeing themselves as thieves.","In 38 of 40 countries, wallets that held about $13 were returned more often than wallets that held no money at all.","Contrary to economists' predictions, wallets containing money were returned more often than empty wallets in 38 of the 40 countries studied."]$q$::jsonb, 3, $q$Only the correct choice presents the result together with the expectation it contradicts. The choice beginning "In 38 of 40…" gives the result without the expectation, the choice beginning "In a study spanning…" describes the design, and the choice beginning "The researchers suggest that…" gives an interpretation.$q$, null),
  ($q$ei-h399$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Glass frogs live in Central and South American rainforests.<br>• Their skin is partly transparent, revealing internal organs.<br>• When sleeping, they pack about 89% of their red blood cells into their liver.<br>• This makes their bodies two to three times more transparent.<br>• The transparency is thought to help them hide from predators.$q$, $q$The student wants to describe the mechanism that increases glass frogs' transparency. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Glass frogs, which live in Central and South American rainforests, have partly transparent skin that reveals their internal organs and may help them hide from predators.","Glass frogs become two to three times more transparent while sleeping, which may help them avoid predators.","The transparency of glass frogs is thought to help them hide from predators while they sleep in rainforest leaves.","While sleeping, glass frogs pack about 89% of their red blood cells into their liver, making their bodies two to three times more transparent."]$q$::jsonb, 3, $q$The mechanism is hiding red blood cells in the liver, which only the correct choice describes. The choice beginning "Glass frogs become two…" states the effect without the mechanism, and the others describe appearance or purpose.$q$, null),
  ($q$ei-h400$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The printing press reached Venice around 1469.<br>• By 1500, Venice had about 150 print shops, more than any other European city.<br>• Aldus Manutius, a Venetian printer, introduced small, portable books.<br>• He also popularized italic type, which fit more words on a page.<br>• These innovations made books cheaper and easier to carry.$q$, $q$The student wants to explain how Aldus Manutius changed books. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["By 1500, Venice, where Aldus Manutius worked as a printer, had about 150 print shops, more than any other European city.","Aldus Manutius introduced small, portable books and popularized space-saving italic type, innovations that made books cheaper and easier to carry.","Venetian printer Aldus Manutius popularized italic type, a typeface that was developed to fit more words on each page.","The printing press reached Venice around 1469, and by 1500 the city had about 150 print shops, including that of the Venetian printer Aldus Manutius."]$q$::jsonb, 1, $q$The correct choice describes both innovations and their effect on books. The choice beginning "Venetian printer Aldus Manutius…" describes only one innovation, the choice beginning "The printing press reached…" mentions small books without their effect, and the choice beginning "By 1500, Venice, where…" concerns Venice's print shops.$q$, null),
  ($q$ei-h401$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Nurse Florence Nightingale served in the Crimean War (1853–1856).<br>• She found that more soldiers died from disease than from battle wounds.<br>• She used a "rose diagram" to show monthly causes of death.<br>• Her visual data persuaded officials to improve hospital sanitation.<br>• Death rates in military hospitals fell sharply afterward.$q$, $q$The student wants to emphasize how Nightingale used data to bring about change. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Florence Nightingale, who served as a nurse in the Crimean War, created a type of chart known as a rose diagram.","During the Crimean War, Nightingale found that more soldiers died from disease than from wounds suffered in battle, and she recorded the monthly causes of death.","After the Crimean War, death rates in military hospitals fell sharply, in part because of improved sanitation.","Nightingale's rose diagram, showing that disease killed more soldiers than wounds did, persuaded officials to improve hospital sanitation."]$q$::jsonb, 3, $q$Only the correct choice connects her data visualization to the resulting policy change. The choice beginning "During the Crimean War…" gives a finding without the change, the choice beginning "Florence Nightingale, who served…" names the chart without its effect, and the choice beginning "After the Crimean War…" gives an outcome without her data.$q$, null),
  ($q$ei-h402$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The kakapo is a flightless, nocturnal parrot native to New Zealand.<br>• It is the world's heaviest parrot, weighing up to 4 kilograms.<br>• Introduced predators reduced it to 51 birds by 1995.<br>• Conservationists moved all kakapo to predator-free islands.<br>• The population had grown to about 250 by 2022.$q$, $q$The student wants to describe the success of the conservation effort. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The kakapo, a flightless and nocturnal parrot native to New Zealand, is the world's heaviest parrot species.","Introduced predators had reduced the kakapo population to just 51 birds by 1995, prompting conservationists to move all of the remaining birds to islands.","Conservationists moved every remaining kakapo, a flightless New Zealand parrot, to islands free of predators.","After conservationists moved all kakapo to predator-free islands, the population grew from 51 birds in 1995 to about 250 by 2022."]$q$::jsonb, 3, $q$Success is shown by the population's recovery after the intervention, which only the correct choice reports. The choice beginning "Conservationists moved every remaining…" describes the effort without its result, and the choice beginning "Introduced predators had reduced…" describes the decline.$q$, null),
  ($q$ei-h403$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Author Octavia Butler (1947–2006) wrote science fiction.<br>• Her novel <i>Kindred</i> (1979) sends a Black woman from 1970s California back to a Maryland plantation in the early 1800s.<br>• Butler said she wanted readers to feel slavery rather than just learn about it.<br>• <i>Kindred</i> is widely taught in schools.$q$, $q$The student wants to explain Butler's purpose in using time travel in <i>Kindred</i>. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["<i>Kindred</i>, which Butler published in 1979 and which is now widely taught, sends a Black woman from 1970s California back to a Maryland plantation.","Butler's 1979 novel <i>Kindred</i>, a work of science fiction about slavery, is now widely taught in schools.","By sending a modern woman back to a nineteenth-century plantation, Butler hoped to make readers feel slavery rather than just learn about it.","Octavia Butler, who lived from 1947 to 2006, used time travel in her science fiction novel <i>Kindred</i>."]$q$::jsonb, 2, $q$Only the correct choice connects the time-travel premise to Butler's stated purpose. The choice beginning "Kindred, which Butler published…" describes the plot without the purpose, and the others give publication or biographical details.$q$, null),
  ($q$ei-h404$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• A 2021 survey asked 2,000 adults where they get news.<br>• 48% said social media at least sometimes.<br>• Among adults aged 18–29, the figure was 70%.<br>• Among adults 65 and older, it was 26%.<br>• Television remained the most common source overall.$q$, $q$The student wants to show how news habits differ by age. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["A 2021 survey of 2,000 adults found that television remained the most common source of news among those surveyed.","In a 2021 survey, 70% of adults aged 18–29 got news from social media at least sometimes, compared with only 26% of those 65 and older.","In a 2021 survey, 70% of adults aged 18–29 said that they got news from social media at least some of the time.","In a 2021 survey of 2,000 adults, 48% said they got news from social media at least sometimes, though television was most common."]$q$::jsonb, 1, $q$Showing a difference by age requires figures for at least two age groups, which only the correct choice provides. The choice beginning "In a 2021 survey, 70% of adults aged 18–29 said…" gives one group, and the others report overall figures.$q$, null),
  ($q$ei-h405$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Stonehenge's large sarsen stones came from about 25 km away.<br>• Its smaller bluestones came from the Preseli Hills in Wales, about 225 km away.<br>• The bluestones weigh 2–5 metric tons each.<br>• How they were moved remains debated.<br>• One theory proposes sledges pulled over wooden rails.$q$, $q$The student wants to emphasize the challenge of moving the bluestones. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["One theory about Stonehenge's construction proposes that stones were moved on sledges pulled over wooden rails.","The bluestones at Stonehenge came from the Preseli Hills in Wales, which are located about 225 km from the monument.","Each weighing 2–5 metric tons, Stonehenge's bluestones were somehow moved about 225 km from Wales, a feat whose method is still debated.","Stonehenge's larger sarsen stones came from about 25 km away, while its smaller bluestones came from the Preseli Hills in Wales, about 225 km away."]$q$::jsonb, 2, $q$Emphasizing the challenge calls for weight, distance, and the unresolved method together, as in the correct choice. The choice beginning "The bluestones at Stonehenge…" gives distance alone, the choice beginning "Stonehenge's larger sarsen stones…" compares sources, and the choice beginning "One theory about Stonehenge's…" presents a proposed solution.$q$, null),
  ($q$ei-h406$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Dandelion seeds travel on a tuft of bristles called a pappus.<br>• Researchers found that air flowing through the pappus forms a stable vortex ring above it.<br>• This "separated vortex ring" had never been observed in nature before.<br>• It allows seeds to travel up to 150 km in some conditions.<br>• The pappus is about 90% empty space.$q$, $q$The student wants to explain what is new about the researchers' discovery. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Air flowing through the pappus of a dandelion seed, which is about 90% empty space, forms a stable vortex ring that allows the seed to travel up to 150 km.","The pappus, a tuft of bristles that carries dandelion seeds through the air, is about 90% empty space.","The researchers found that air passing through a dandelion seed's pappus forms a stable vortex ring above it, a type of flow never before observed in nature.","Dandelion seeds can sometimes travel as far as 150 km, carried by a tuft of bristles called a pappus."]$q$::jsonb, 2, $q$What is new is that this kind of vortex had never been seen in nature, which only the correct choice states. The choice beginning "Air flowing through the…" describes the vortex and its effect without its novelty, and the others give structural or distance facts.$q$, null),
  ($q$ei-h407$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• In 1848, the Seneca Falls Convention issued the Declaration of Sentiments.<br>• It was modeled on the Declaration of Independence.<br>• It stated that "all men and women are created equal."<br>• It demanded women's right to vote, among other rights.<br>• Women in the U.S. gained the national right to vote in 1920.$q$, $q$The student wants to show how the Declaration of Sentiments drew on an earlier document. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Issued at the Seneca Falls Convention in 1848, the Declaration of Sentiments stated that \"all men and women are created equal.\"","Women's right to vote, demanded in the 1848 Declaration of Sentiments, was finally secured nationally in 1920.","The Declaration of Sentiments, issued in 1848 at the Seneca Falls Convention, demanded women's right to vote, which women nationally gained in 1920, among other rights.","Modeled on the Declaration of Independence, the 1848 Declaration of Sentiments adapted its famous phrase to state that \"all men and women are created equal.\""]$q$::jsonb, 3, $q$The correct choice names the model and shows how its language was adapted. The fourth quotes the phrase without identifying the earlier document, and the others describe demands or outcomes.$q$, null),
  ($q$ei-h408$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Urban foxes in London were compared with rural foxes.<br>• Urban foxes had shorter, wider snouts.<br>• Their skulls resembled those of domesticated dogs.<br>• Researchers suggest the shape suits scavenging food waste rather than hunting.<br>• The changes appeared over a relatively short period.$q$, $q$The student wants to present the researchers' explanation for the difference in skull shape. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Compared with rural foxes, foxes living in London had shorter, wider snouts and skulls resembling those of dogs.","Researchers suggest that urban foxes' shorter, wider snouts suit scavenging food waste rather than hunting prey.","The skulls of urban foxes in London resemble those of domesticated dogs more than those of rural foxes.","Changes in the skull shape of London's urban foxes appeared over a relatively short period of time."]$q$::jsonb, 1, $q$Only the correct choice gives the researchers' explanation. The others describe the difference or its timing without explaining it.$q$, null),
  ($q$ei-h409$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers tracked 500 bumblebees fitted with tiny radio tags.<br>• Bees from colonies near pesticide-treated fields made foraging trips 25% shorter.<br>• They brought back 30% less pollen per trip.<br>• Colonies near untreated fields grew normally.<br>• The pesticide is widely used on canola crops.$q$, $q$The student wants to describe the effect of the pesticide on foraging. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Bumblebees from colonies near pesticide-treated fields made 25% shorter foraging trips and brought back 30% less pollen per trip.","Researchers tracked 500 bumblebees fitted with tiny radio tags to study a pesticide widely used on canola crops.","Bumblebee colonies located near fields that had not been treated with the pesticide grew normally, the researchers found.","The pesticide, which is widely used on canola crops, was studied by researchers who tracked bumblebees near treated fields."]$q$::jsonb, 0, $q$Only the correct choice reports the measured effects on foraging. The choice beginning "Bumblebee colonies located near…" describes untreated colonies, and the others describe methods or the pesticide's use.$q$, null),
  ($q$ei-h410$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Philosopher Simone Weil (1909–1943) wrote about attention.<br>• She argued that attention is the rarest and purest form of generosity.<br>• She believed school exercises were valuable mainly for training attention.<br>• This was true, she said, even if a student never solved the problem.<br>• Her essays were published after her death.$q$, $q$The student wants to present Weil's unusual view of schoolwork. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Weil argued that attention is the rarest and purest form of generosity, a view she developed in essays.","Weil, a philosopher whose essays were published after her death, wrote extensively about the nature of attention, which she considered the rarest form of generosity.","Simone Weil, who lived from 1909 to 1943, believed that schoolwork could be valuable for students.","Weil argued that school exercises were valuable mainly for training attention, even when a student never solved the problem."]$q$::jsonb, 3, $q$The unusual element is that the value lies in training attention regardless of success, which only the correct choice states. The choice beginning "Simone Weil, who lived…" is vague, the choice beginning "Weil argued that attention…" concerns generosity, and the choice beginning "Weil, a philosopher whose…" gives background.$q$, null),
  ($q$ei-h411$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Saturn's moon Enceladus is about 500 km across.<br>• Its south pole sprays plumes of water vapor and ice into space.<br>• The Cassini spacecraft flew through the plumes in 2008 and later.<br>• Cassini detected salt, silica, and organic molecules in the plumes.<br>• Scientists infer a global saltwater ocean beneath the icy crust.$q$, $q$The student wants to explain how scientists learned about Enceladus's hidden ocean. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Plumes of water vapor and ice spray into space from the south pole of Enceladus, one of Saturn's moons.","Scientists believe that Saturn's moon Enceladus, which is about 500 km across and sprays plumes of water vapor and ice, has a global saltwater ocean beneath its crust.","By flying through plumes erupting from Enceladus's south pole, Cassini detected salt and other materials that led scientists to infer an ocean beneath the ice.","The Cassini spacecraft flew through plumes from Enceladus in 2008 and detected salt, silica, and organic molecules."]$q$::jsonb, 2, $q$The correct choice connects the method (sampling the plumes) to the inference about the ocean. The choice beginning "The Cassini spacecraft flew…" describes the sampling without the inference, and the choice beginning "Scientists believe that Saturn's…" gives the inference without the method.$q$, null),
  ($q$ei-h412$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Mexican muralist Diego Rivera painted <i>Detroit Industry</i> in 1932–1933.<br>• The murals cover all four walls of a courtyard at the Detroit Institute of Arts.<br>• They depict workers at the Ford River Rouge automobile plant.<br>• Rivera spent months sketching inside the plant.<br>• Some critics at the time called the murals un-American; others praised them.$q$, $q$The student wants to indicate how Rivera prepared for the murals. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Rivera's <i>Detroit Industry</i> murals, which cover a courtyard's four walls, depict workers at Ford's River Rouge plant.","When Rivera's <i>Detroit Industry</i> murals were unveiled, some critics called them un-American while others praised them.","Diego Rivera painted his <i>Detroit Industry</i> murals at the Detroit Institute of Arts in 1932 and 1933.","Before painting <i>Detroit Industry</i>, Rivera spent months sketching workers inside Ford's River Rouge automobile plant."]$q$::jsonb, 3, $q$Only the correct choice describes his preparation. The others describe the murals' subject, reception, or date.$q$, null),
  ($q$ei-h413$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers trained dogs to sniff samples from people with and without COVID-19.<br>• The dogs correctly identified infected samples 94% of the time.<br>• A standard rapid antigen test was correct about 80% of the time in the same study.<br>• The dogs worked faster than laboratory tests.<br>• Each dog required weeks of training.$q$, $q$The student wants to compare the accuracy of the dogs with that of the rapid test. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Researchers trained dogs to sniff samples from people with and without COVID-19 and compared them with a rapid test.","Although each dog needed weeks of training, the dogs in the study worked faster than standard laboratory tests.","In the study, trained dogs identified infected samples correctly 94% of the time, compared with about 80% for a standard rapid antigen test.","Trained dogs identified samples from people infected with COVID-19 correctly 94% of the time, working faster than laboratory tests, though each dog required weeks of training."]$q$::jsonb, 2, $q$An accuracy comparison needs both accuracy figures, which only the correct choice provides. The choice beginning "Trained dogs identified samples…" compares speed rather than accuracy, and the choice beginning "Researchers trained dogs to…" describes the design.$q$, null),
  ($q$ei-h414$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The city of Curitiba, Brazil, launched a bus rapid transit (BRT) system in 1974.<br>• Buses run in dedicated lanes.<br>• Passengers pay before boarding at tube-shaped stations.<br>• These features let buses operate nearly as fast as subways at a fraction of the cost.<br>• More than 150 cities have since adopted BRT systems.$q$, $q$The student wants to explain why Curitiba's system was efficient. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Curitiba's bus rapid transit system, launched in 1974, operates nearly as fast as a subway at a fraction of the cost.","Passengers in Curitiba's bus rapid transit system wait for buses at distinctive tube-shaped stations.","With dedicated lanes and payment before boarding, Curitiba's buses could operate nearly as fast as subways at a fraction of the cost.","Curitiba, Brazil, launched its bus rapid transit system with tube-shaped stations in 1974, and more than 150 cities have since adopted similar systems."]$q$::jsonb, 2, $q$An explanation of efficiency needs the features that produce it, as in the correct choice. The choice beginning "Curitiba's bus rapid transit…" states the efficiency without the reasons, and the others give history or station design.$q$, null),
  ($q$ei-h415$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Linguist Lera Boroditsky studied speakers of Kuuk Thaayorre, an Aboriginal Australian language.<br>• The language uses cardinal directions (north, south, east, west) instead of "left" and "right."<br>• Speakers say things like "There's an ant on your southeast leg."<br>• Speakers stayed oriented even in unfamiliar places.<br>• Boroditsky argues that language can shape how people think about space.$q$, $q$The student wants to use the Kuuk Thaayorre example to support Boroditsky's argument. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In Kuuk Thaayorre, an Aboriginal Australian language, speakers say things like \"There's an ant on your southeast leg.\"","Unlike English, the Aboriginal Australian language Kuuk Thaayorre uses cardinal directions instead of \"left\" and \"right,\" so speakers say things like \"There's an ant on your southeast leg.\"","Kuuk Thaayorre speakers, whose language uses cardinal directions instead of \"left\" and \"right,\" stay oriented even in unfamiliar places, supporting the idea that language shapes spatial thinking.","Linguist Lera Boroditsky argues that the languages people speak can shape the ways they think about space."]$q$::jsonb, 2, $q$Supporting the argument requires linking the language feature to a cognitive effect, and then to the argument. Only the correct choice does so. The choices beginning "In Kuuk Thaayorre, an…" and "Unlike English, the Aboriginal…" describe the language, and the choice beginning "Linguist Lera Boroditsky argues…" states the argument without evidence.$q$, null),
  ($q$ei-h416$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Mansa Musa ruled the Mali Empire in the early fourteenth century.<br>• In 1324, he made a pilgrimage to Mecca with a caravan of thousands.<br>• He gave away so much gold in Cairo that its value there dropped for years.<br>• His journey made Mali famous in Europe and the Middle East.<br>• A 1375 European map shows him holding a gold nugget.$q$, $q$The student wants to illustrate the scale of Mansa Musa's wealth. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Mansa Musa's pilgrimage made Mali famous, and a 1375 European map shows him holding a gold nugget.","Mansa Musa, who ruled the Mali Empire in the early fourteenth century, made a pilgrimage to Mecca in 1324.","In 1324, Mansa Musa traveled to Mecca with a caravan made up of thousands of people.","During his 1324 pilgrimage, Mansa Musa gave away so much gold in Cairo that its value there dropped for years."]$q$::jsonb, 3, $q$The gold that depressed prices in Cairo best shows the scale of his wealth. The choice beginning "In 1324, Mansa Musa…" gives the caravan's size, which is suggestive but doesn't directly show wealth, and the others give dates or fame.$q$, null),
  ($q$ei-h417$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Most plants need sunlight for photosynthesis.<br>• The ghost plant (<i>Monotropa uniflora</i>) is white and lacks chlorophyll.<br>• It gets nutrients by tapping into fungi connected to the roots of nearby trees.<br>• The trees supply the fungi with sugars made through photosynthesis.<br>• The ghost plant can thus grow on dark forest floors.$q$, $q$The student wants to explain how the ghost plant indirectly benefits from photosynthesis. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Because it gets nutrients from fungi connected to the roots of nearby trees rather than from sunlight, the ghost plant can grow on dark forest floors.","Though it cannot photosynthesize, the ghost plant taps fungi that receive sugars from nearby trees, which make those sugars through photosynthesis.","The ghost plant gets its nutrients by tapping into fungi that are connected to the roots of nearby trees.","The ghost plant is white and lacks chlorophyll, so unlike most plants it cannot carry out photosynthesis."]$q$::jsonb, 1, $q$The indirect benefit is the chain from trees' photosynthesis to fungi to the ghost plant, which only the correct choice traces. The choice beginning "The ghost plant gets…" stops at the fungi, and the others describe the plant's appearance or habitat.$q$, null),
  ($q$ei-h418$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Harlem Renaissance was a flowering of Black art and literature in the 1920s.<br>• Langston Hughes wrote poems inspired by the rhythms of jazz and blues.<br>• His 1926 collection was titled <i>The Weary Blues</i>.<br>• Some Black critics argued that his poems emphasized the wrong aspects of Black life.<br>• Hughes defended writing about ordinary people.$q$, $q$The student wants to describe the debate over Hughes's work. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Hughes's 1926 poetry collection, <i>The Weary Blues</i>, drew on the rhythms of jazz and blues and was criticized by some reviewers during the Harlem Renaissance.","Langston Hughes, a leading poet of the Harlem Renaissance, wrote poems inspired by the rhythms of jazz and blues.","While some Black critics argued that Hughes's poems emphasized the wrong aspects of Black life, Hughes defended writing about ordinary people.","The Harlem Renaissance, a flowering of Black art and literature, took place during the 1920s."]$q$::jsonb, 2, $q$A debate needs both sides, which only the correct choice gives. The choice beginning "Hughes's 1926 poetry collection…" mentions criticism without its substance or Hughes's response, and the others give background.$q$, null),
  ($q$ei-h419$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers measured noise levels in 20 hospital wards.<br>• Average nighttime noise was 52 decibels.<br>• The World Health Organization recommends no more than 30 decibels at night in hospital rooms.<br>• Patients in noisier wards reported poorer sleep.<br>• Common sources included alarms, carts, and staff conversations.$q$, $q$The student wants to show that hospital noise exceeds recommended levels. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The World Health Organization recommends that noise in hospital rooms be kept at no more than 30 decibels at night.","Patients in noisier hospital wards reported poorer sleep, and common noise sources in the 20 wards studied included alarms, carts, and staff conversations.","Nighttime noise in the hospital wards averaged 52 decibels, well above the 30-decibel maximum recommended by the World Health Organization.","Researchers measured nighttime noise in 20 hospital wards and found an average level of 52 decibels."]$q$::jsonb, 2, $q$Showing that noise exceeds the recommendation requires both the measured level and the recommended maximum. Only the correct choice has both.$q$, null),
  ($q$ei-h420$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The pistol shrimp snaps its oversized claw shut at high speed.<br>• The snap creates a bubble that collapses with a loud crack.<br>• The collapse briefly reaches temperatures near 4,700°C.<br>• The shock wave stuns or kills small prey.<br>• Colonies of pistol shrimp can interfere with submarine sonar.$q$, $q$The student wants to explain how the pistol shrimp captures prey. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["When the pistol shrimp's collapsing bubble cracks, it briefly reaches temperatures near 4,700°C.","The pistol shrimp has an oversized claw that it can snap shut at high speed, producing a loud crack.","The pistol shrimp snaps its claw shut so fast that it creates a bubble whose collapse sends out a shock wave that stuns or kills prey.","Colonies of pistol shrimp, which snap their oversized claws at high speed and create collapsing bubbles reaching 4,700°C, can interfere with submarine sonar."]$q$::jsonb, 2, $q$Only the correct choice traces the full sequence from snap to bubble to shock wave to prey. The choice beginning "The pistol shrimp has…" stops at the crack, and the choices beginning "When the pistol shrimp's…" and "Colonies of pistol shrimp…" give striking facts unrelated to hunting.$q$, null),
  ($q$ei-h421$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• A public library launched a program lending tools, such as drills and ladders.<br>• In its first year, it lent tools 4,300 times.<br>• 62% of borrowers had not used the library in the previous year.<br>• Library card sign-ups rose 15%.<br>• Staff hope to add sewing machines and cameras.$q$, $q$The student wants to argue that the program attracted new library users. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In its first year, the library's tool-lending program, which offers drills and ladders, lent tools a total of 4,300 times, and staff hope to add sewing machines.","Library staff hope to expand the tool-lending program by adding items such as sewing machines and cameras.","The public library launched a program that allows patrons to borrow tools such as drills and ladders.","Of those who borrowed tools in the program's first year, 62% had not used the library in the previous year, and card sign-ups rose 15%."]$q$::jsonb, 3, $q$Evidence of new users comes from the share of borrowers new to the library and the rise in sign-ups. The choice beginning "In its first year…" shows use but not new users, and the others describe plans or the program.$q$, null),
  ($q$ei-h422$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Composer Florence Price (1887–1953) was the first Black woman to have a symphony performed by a major U.S. orchestra.<br>• The Chicago Symphony performed her Symphony in E Minor in 1933.<br>• Her music blends European classical forms with African American spirituals.<br>• Many of her manuscripts were found in an abandoned house in 2009.<br>• Since then, her works have been increasingly performed and recorded.$q$, $q$The student wants to explain the recent revival of interest in Price's music. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Florence Price's music, including the Symphony in E Minor performed in 1933, blends European classical forms with the melodies of African American spirituals.","After many of her manuscripts were discovered in an abandoned house in 2009, Florence Price's works have been increasingly performed and recorded.","In 1933, the Chicago Symphony performed Florence Price's Symphony in E Minor, making her a pioneer among composers.","Florence Price was the first Black woman to have a symphony performed by a major orchestra in the United States."]$q$::jsonb, 1, $q$The revival follows from the 2009 discovery, which only the correct choice connects to increased performances. The others describe her historic achievement or her style.$q$, null),
  ($q$ei-h423$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Sahara contains vast underground aquifers.<br>• The Nubian Sandstone Aquifer holds an estimated 150,000 cubic kilometers of water.<br>• Most of this water is "fossil water" that collected over 10,000 years ago.<br>• It is recharged extremely slowly, if at all.<br>• Libya pumps it to cities through the Great Man-Made River project.$q$, $q$The student wants to caution that the aquifer's water is not a renewable resource. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Through its Great Man-Made River project, Libya pumps water from beneath the Sahara to its cities.","The Nubian Sandstone Aquifer, beneath the Sahara, holds an estimated 150,000 cubic kilometers of water.","The Sahara contains vast underground aquifers, including the Nubian Sandstone Aquifer, which holds an estimated 150,000 cubic kilometers of water that Libya pumps to its cities.","Although the Nubian Sandstone Aquifer holds vast amounts of water, most of it is fossil water that collected over 10,000 years ago and is recharged extremely slowly, if at all."]$q$::jsonb, 3, $q$The caution depends on the water's age and negligible recharge, both of which only the correct choice includes. The choice beginning "The Sahara contains vast…" mentions fossil water without explaining that it isn't replenished, and the others describe size or use.$q$, null),
  ($q$ei-h424$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Two theories explain why the Leaning Tower of Pisa leans.<br>• Theory 1: the soft, clay-rich soil compressed unevenly under its weight.<br>• Theory 2: builders used foundations only 3 meters deep.<br>• Engineers today consider both factors responsible.<br>• Stabilization work in 1990–2001 reduced the lean by about 45 cm.$q$, $q$The student wants to present the current view of what caused the lean. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Stabilization work carried out between 1990 and 2001 reduced the lean of the Leaning Tower of Pisa by about 45 cm.","One theory holds that the Leaning Tower of Pisa leans because the soft, clay-rich soil beneath it compressed unevenly.","Engineers today attribute the Leaning Tower of Pisa's tilt both to soft, clay-rich soil and to foundations only 3 meters deep.","There are two competing theories that explain why the Leaning Tower of Pisa leans, one involving soil and one involving foundations."]$q$::jsonb, 2, $q$The current view holds both factors responsible, as only the correct answer states. The choice about two competing theories wrongly presents them as competing, the choice beginning "One theory holds that…" gives one theory, and the choice beginning "Stabilization work carried out…" concerns stabilization.$q$, null),
  ($q$ei-h425$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Marie Tharp (1920–2006) was an American geologist and cartographer.<br>• In the 1950s, she mapped the floor of the Atlantic Ocean using sonar data.<br>• She identified a rift valley running along the Mid-Atlantic Ridge.<br>• Her colleague initially dismissed the finding as "girl talk."<br>• The rift became key evidence for the theory of plate tectonics.$q$, $q$The student wants to emphasize the scientific importance of Tharp's discovery. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In the 1950s, Marie Tharp used sonar data to map the floor of the Atlantic Ocean, identifying a rift valley.","The rift valley that Marie Tharp identified along the Mid-Atlantic Ridge became key evidence for the theory of plate tectonics.","Marie Tharp's colleague initially dismissed her identification of a rift valley along the Mid-Atlantic Ridge as \"girl talk.\"","Marie Tharp, an American geologist and cartographer, lived from 1920 to 2006 and mapped the Atlantic Ocean floor."]$q$::jsonb, 1, $q$Importance is shown by the rift's role as evidence for plate tectonics, which only the correct choice states. The choice beginning "In the 1950s, Marie…" describes the discovery, the choice beginning "Marie Tharp's colleague initially…" its initial reception, and the choice beginning "Marie Tharp, an American…" her biography.$q$, null),
  ($q$ei-h426$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Some birds, such as Clark's nutcrackers, cache thousands of seeds each fall.<br>• A nutcracker can hide up to 30,000 seeds in a season.<br>• It recovers many of them months later, even under snow.<br>• The bird's hippocampus, a brain region tied to spatial memory, is enlarged.<br>• Unrecovered seeds can grow into new trees.$q$, $q$The student wants to connect the nutcracker's behavior to its brain. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The hippocampus, a brain region tied to spatial memory, is enlarged in some birds, such as Clark's nutcrackers.","Seeds that Clark's nutcrackers hide but fail to recover can grow into new trees, helping forests regenerate.","The Clark's nutcracker, which recovers many of its cached seeds months later, has an enlarged hippocampus, a brain region tied to spatial memory.","A Clark's nutcracker can hide up to 30,000 seeds in a single season and recover many of them months later, even under snow, while unrecovered seeds grow into trees."]$q$::jsonb, 2, $q$Only the correct answer links the behavior (recovering seeds) to the brain feature. The choice beginning "A Clark's nutcracker can…" describes behavior alone, the choice about the enlarged hippocampus in some birds the brain alone, and the choice beginning "Seeds that Clark's nutcrackers…" an ecological effect.$q$, null),
  ($q$ei-h427$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• In 2019, a team created a map of food access in Baltimore.<br>• About 23% of residents lived in "healthy food priority areas."<br>• These areas lacked supermarkets within a quarter mile.<br>• Rates were highest among Black residents, at 31%.<br>• The city has used the map to target new grocery programs.$q$, $q$The student wants to highlight a disparity revealed by the map. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Baltimore has used a 2019 map of food access to target new grocery programs to the areas that need them most.","In 2019, a team created a map showing which parts of Baltimore were healthy food priority areas.","While about 23% of Baltimore residents lived in healthy food priority areas, the rate among Black residents was higher, at 31%.","A 2019 map found that about 23% of Baltimore residents lived in areas lacking supermarkets within a quarter mile, and the city has used it to target grocery programs."]$q$::jsonb, 2, $q$A disparity requires comparing a group with the overall rate. Only the correct answer does this. The choice beginning "A 2019 map found…" gives the overall rate alone, and the others describe the map or its use.$q$, null),
  ($q$ei-h428$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Voyager Golden Records were launched aboard two spacecraft in 1977.<br>• Each contains sounds and images meant to represent life on Earth.<br>• Contents include greetings in 55 languages and music from many cultures.<br>• The committee was chaired by astronomer Carl Sagan.<br>• The spacecraft have now left the solar system's heliosphere.$q$, $q$The student wants to describe the contents of the Golden Records. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The committee that selected the contents of the Voyager Golden Records was chaired by astronomer Carl Sagan.","Launched in 1977 aboard two spacecraft, the Voyager Golden Records, chosen by a committee chaired by Carl Sagan, have now left the heliosphere.","Each Voyager Golden Record contains sounds and images, and each was launched aboard a spacecraft in 1977.","Meant to represent life on Earth, the Voyager Golden Records include greetings in 55 languages and music from many cultures."]$q$::jsonb, 3, $q$Only the correct choice gives specific contents. The fourth refers vaguely to "sounds and images," and the others describe the launch, location, or committee.$q$, null),
  ($q$ei-h429$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Some scientists propose reintroducing large herbivores to European landscapes, an approach called rewilding.<br>• At Oostvaardersplassen in the Netherlands, deer, cattle, and horses were released in the 1980s.<br>• Without predators, populations grew rapidly.<br>• During harsh winters, thousands of animals starved.<br>• Managers now cull animals to keep populations in check.$q$, $q$The student wants to present a challenge that rewilding projects can face. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Managers at Oostvaardersplassen in the Netherlands now cull animals as part of the site's rewilding project.","Rewilding, which involves reintroducing large herbivores such as deer, cattle, and horses, has been proposed by some scientists for European landscapes.","In the 1980s, deer, cattle, and horses were released at Oostvaardersplassen, a rewilding site in the Netherlands.","At Oostvaardersplassen, herbivores released without predators multiplied rapidly, and thousands starved in harsh winters, forcing managers to cull animals."]$q$::jsonb, 3, $q$The correct choice shows the challenge: unchecked population growth causing starvation and requiring culls. The choice beginning "Managers at Oostvaardersplassen in…" mentions culling without explaining the problem behind it, and the others define rewilding or describe the release.$q$, null),
  ($q$ei-h430$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers asked participants to write about a recent conflict.<br>• Group 1 wrote in the first person ("I").<br>• Group 2 wrote from a third-person perspective, using their own name.<br>• Group 2 reported less anger and more insight afterward.<br>• Researchers call this "self-distancing."$q$, $q$The student wants to summarize the study's method and main finding. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Participants who wrote about a recent conflict from a third-person perspective reported less anger, a result researchers call self-distancing.","Researchers use the term \"self-distancing\" to describe writing about one's own experiences from a third-person perspective.","Researchers asked one group of participants to write about a conflict in the first person and another to write in the third person.","When participants wrote about a conflict in the third person rather than the first, they reported less anger and more insight afterward."]$q$::jsonb, 3, $q$A summary of method and finding must describe the comparison and the result. The correct choice does both. The choice beginning "Researchers asked one group…" gives only the method. The choice beginning "Participants who wrote about…" gives the result but omits the first-person comparison group. The fourth defines a term.$q$, null),
  ($q$ei-h431$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Cuttlefish can change skin color and texture in under a second.<br>• Researchers placed cuttlefish on checkerboard backgrounds.<br>• On large squares, cuttlefish displayed bold, high-contrast patterns.<br>• On small squares, they displayed fine, mottled patterns.<br>• Cuttlefish appear to match the scale of background features.$q$, $q$The student wants to state the researchers' conclusion. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Cuttlefish are able to change both the color and the texture of their skin in less than one second, an ability that researchers have studied using checkerboards.","Cuttlefish appear to match the scale of features in their background.","On large checkerboard squares, cuttlefish displayed bold, high-contrast patterns, while on small squares they displayed fine, mottled ones.","Researchers placed cuttlefish, which can change the color and texture of their skin in under a second, on checkerboard backgrounds with squares of different sizes."]$q$::jsonb, 1, $q$The conclusion is the general statement that cuttlefish match background scale. The choice beginning "On large checkerboard squares…" reports the observations that support the conclusion, and the others describe the animal's ability or the method.$q$, null),
  ($q$ei-h432$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Inca Empire had no written alphabet.<br>• Officials recorded information using quipus: cords with knots.<br>• Knot types and positions represented numbers in a base-10 system.<br>• Quipus recorded census data, taxes, and storehouse inventories.<br>• Some scholars think quipus may also have recorded narratives.$q$, $q$The student wants to explain how quipus stored numerical information. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Lacking a written alphabet, the Inca Empire relied on quipus, cords with knots, to record a wide variety of important information.","On quipus, the types and positions of knots represented numbers in a base-10 system.","Inca officials, who had no written alphabet, used quipus to record census data, tax payments, and the contents of storehouses throughout the empire.","Although quipus were knotted cords used by Inca officials, some scholars think they may also have recorded narratives as well as numbers."]$q$::jsonb, 1, $q$Only the correct choice explains how numbers were encoded. The other choices describe what quipus recorded or who used them, which doesn't answer how they stored numbers.$q$, null),
  ($q$ei-h433$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers studied 1,000 children's books published from 1960 to 2020.<br>• Female main characters appeared in 25% of books in the 1960s.<br>• They appeared in 41% of books in the 2010s.<br>• Male animal characters still outnumbered female animal characters 2 to 1 in the 2010s.$q$, $q$The student wants to show that progress toward gender balance was incomplete. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Female main characters rose from 25% to 41% of children's books, but male animal characters still outnumbered female ones 2 to 1 in the 2010s.","Female main characters appeared in only 25% of children's books in the 1960s, a share that climbed to 41% by the 2010s according to researchers.","Researchers studied 1,000 children's books published between 1960 and 2020 to see how often female main characters appeared in them over the decades.","In the 2010s, male animal characters outnumbered female animal characters by 2 to 1."]$q$::jsonb, 0, $q$Showing incomplete progress requires both the gain and the remaining imbalance. The choice beginning "Female main characters appeared…" shows only progress, the choice beginning "In the 2010s, male…" only the imbalance, and the choice beginning "Researchers studied 1,000 children's…" describes the study.$q$, null),
  ($q$ei-h434$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• In 1928, Alexander Fleming noticed mold killing bacteria in a petri dish.<br>• The mold produced a substance he named penicillin.<br>• Fleming struggled to purify it and largely abandoned the work.<br>• In 1940, Howard Florey and Ernst Chain purified penicillin and tested it on mice.<br>• Mass production during World War II saved many soldiers' lives.$q$, $q$The student wants to emphasize that developing penicillin required work beyond Fleming's discovery. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Fleming discovered penicillin in 1928 but could not purify it; that step was achieved by Florey and Chain in 1940.","Howard Florey and Ernst Chain tested penicillin on mice in 1940.","In 1928, Alexander Fleming noticed that mold growing in one of his petri dishes was killing bacteria, and he named the substance it produced penicillin.","During World War II, the mass production of penicillin, a substance discovered by Alexander Fleming, saved the lives of many soldiers."]$q$::jsonb, 0, $q$The correct choice contrasts Fleming's discovery with the later purification by others. The choice beginning "In 1928, Alexander Fleming…" describes only the discovery, the choice beginning "During World War II…" credits Fleming alone, and the choice beginning "Howard Florey and Ernst…" omits the link to Fleming's unfinished work.$q$, null),
  ($q$ei-h435$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Rain gardens are shallow planted depressions that collect runoff from roofs and pavement.<br>• They allow water to soak into the ground instead of flowing into storm drains.<br>• Plants and soil filter pollutants from the water.<br>• A typical rain garden absorbs about 30% more water than an equal area of lawn.<br>• Many cities offer rebates for installing them.$q$, $q$The student wants to explain how rain gardens reduce water pollution. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Rain gardens absorb about 30% more water than lawns, keeping runoff out of storm drains.","Many cities now offer rebates to residents who install rain gardens, shallow depressions planted to collect runoff from roofs and pavement.","A typical rain garden, a shallow planted depression that collects runoff from roofs and pavement, absorbs about 30% more water than an equal area of lawn does.","Rain gardens collect runoff and let it soak into the ground, where plants and soil filter out pollutants."]$q$::jsonb, 3, $q$Only the correct choice explains the filtering that reduces pollution. The choice beginning "A typical rain garden…" concerns water absorption rather than pollution, the choice beginning "Many cities now offer…" concerns incentives, and the choice beginning "Rain gardens absorb about…" is a bare definition.$q$, null),
  ($q$ei-h436$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Painter Jacob Lawrence created <i>The Migration Series</i> (1940–41), 60 panels.<br>• The series depicts the Great Migration of Black Americans from the South to Northern cities.<br>• Each panel has a caption written by Lawrence.<br>• He used a limited palette, applying one color at a time to all panels.<br>• This method gave the series visual unity.$q$, $q$The student wants to explain how Lawrence achieved unity across the series. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Each of the 60 panels in Jacob Lawrence's <i>The Migration Series</i>, which depicts the movement of Black Americans to Northern cities, has a caption he wrote.","Lawrence gave <i>The Migration Series</i> visual unity by using a limited palette, applying one color at a time across all panels.","Each of the 60 panels in <i>The Migration Series</i> pairs an image with a caption that Lawrence wrote himself.","Jacob Lawrence's <i>The Migration Series</i>, created in 1940 and 1941, consists of 60 panels depicting the Great Migration of Black Americans from the South."]$q$::jsonb, 1, $q$Only the correct choice names the technique and its unifying effect. The other choices describe the series' subject, size, or captions.$q$, null),
  ($q$ei-h437$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The okapi lives in the rainforests of the Democratic Republic of the Congo.<br>• It has striped legs like a zebra.<br>• Its closest living relative is the giraffe.<br>• Like giraffes, okapis have long, flexible tongues.<br>• Western scientists did not describe the okapi until 1901.$q$, $q$The student wants to clarify a common misconception about the okapi's relationships. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Though its striped legs resemble a zebra's, the okapi's closest living relative is the giraffe.","Like its relative the giraffe, the okapi has a long, flexible tongue that it uses while feeding in the rainforests of central Africa.","The okapi, which lives in the rainforests of the Democratic Republic of the Congo, was not described by Western scientists until 1901.","Like giraffes, its closest living relatives, okapis have long, flexible tongues."]$q$::jsonb, 0, $q$The misconception arises from the zebra-like stripes. Only the correct choice addresses it by contrasting the stripes with the actual relationship. The choice beginning "Like its relative the…" states the relationship without the misconception.$q$, null),
  ($q$ei-h438$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers analyzed 3 million online restaurant reviews.<br>• Reviews of expensive restaurants used more words related to sensuality.<br>• Reviews of cheap restaurants used more words related to addiction, like "craving."<br>• Negative reviews often used language similar to descriptions of trauma.$q$, $q$The student wants to describe a contrast in how reviewers write about restaurants at different price levels. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Reviews of expensive restaurants used more sensual words, while reviews of cheap restaurants used more words related to addiction, like \"craving.\"","An analysis of 3 million online restaurant reviews found that reviews of expensive restaurants tended to use more words related to sensuality.","Reviews of cheap restaurants often used words related to addiction, such as \"craving.\"","Researchers who analyzed 3 million online restaurant reviews found that negative reviews often used language similar to descriptions of trauma."]$q$::jsonb, 0, $q$A contrast by price level needs both expensive and cheap restaurants. Only the correct choice gives both. The choice beginning "An analysis of 3…" gives one side, and the choice beginning "Researchers who analyzed 3…" concerns negative reviews.$q$, null),
  ($q$ei-h439$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Philosopher Hannah Arendt reported on the 1961 trial of Adolf Eichmann.<br>• She expected to find a monstrous figure.<br>• Instead, she found a bureaucrat focused on following orders and advancing his career.<br>• She coined the phrase "the banality of evil."<br>• The phrase remains widely discussed and disputed.$q$, $q$The student wants to explain what led Arendt to coin her famous phrase. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Philosopher Hannah Arendt reported on the 1961 trial of Adolf Eichmann for a general audience, observing him closely throughout the proceedings.","Expecting a monster at Eichmann's trial but finding a career-minded bureaucrat, Arendt coined the phrase \"the banality of evil.\"","Arendt's phrase \"the banality of evil\" has been widely discussed and disputed since the 1961 Eichmann trial.","Hannah Arendt's phrase \"the banality of evil,\" which she coined after reporting on a famous 1961 trial, remains widely discussed and disputed today."]$q$::jsonb, 1, $q$Only the correct choice explains what prompted the phrase: the gap between expectation and observation. The others mention the phrase or the trial without the reason.$q$, null),
  ($q$ei-h440$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Lithium-ion batteries power most electric cars.<br>• Sodium-ion batteries use abundant, inexpensive sodium.<br>• They store about 30% less energy by weight than lithium-ion batteries.<br>• They perform better in cold temperatures.<br>• Some carmakers plan to use them in low-cost models.$q$, $q$The student wants to present both an advantage and a disadvantage of sodium-ion batteries. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Unlike lithium-ion batteries, which power most electric cars, sodium-ion batteries rely on sodium.","Sodium-ion batteries perform better in the cold than lithium-ion batteries but store about 30% less energy by weight.","Sodium-ion batteries store about 30% less energy by weight than lithium-ion batteries do.","Sodium-ion batteries use sodium, an abundant and inexpensive element, and some carmakers plan to use them in their low-cost electric models."]$q$::jsonb, 1, $q$Only the correct choice includes both an advantage (cold performance) and a disadvantage (lower energy density). The choice beginning "Sodium-ion batteries use sodium…" gives advantages only, the choice beginning "Sodium-ion batteries store about…" a disadvantage only, and the choice beginning "Unlike lithium-ion batteries, which…" neither.$q$, null),
  ($q$ei-h441$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The 2004 Indian Ocean tsunami struck 14 countries.<br>• On Simeulue Island, Indonesia, only 7 of about 78,000 residents died.<br>• Islanders had passed down a story called <i>smong</i> after a 1907 tsunami.<br>• The story taught people to flee to high ground when the sea recedes.<br>• Researchers credit the oral tradition with saving lives.$q$, $q$The student wants to emphasize the role of oral tradition in disaster survival. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The 2004 Indian Ocean tsunami struck 14 countries, but on Indonesia's Simeulue Island, only 7 of about 78,000 residents lost their lives, a remarkably low death toll.","Because of <i>smong</i>, a story passed down since 1907 urging people to flee when the sea recedes, only 7 of Simeulue's 78,000 residents died in the 2004 tsunami.","Researchers credit an oral tradition with saving lives on Simeulue Island in Indonesia during the 2004 tsunami.","After a tsunami struck their island in 1907, the residents of Simeulue passed down a story called <i>smong</i>."]$q$::jsonb, 1, $q$The correct choice links the story's lesson to the low death toll. The choice beginning "The 2004 Indian Ocean…" gives the outcome without the tradition, the choice beginning "Researchers credit an oral…" makes the claim without specifics, and the choice beginning "After a tsunami struck…" describes the story without its effect.$q$, null),
  ($q$ei-h442$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers measured how long shoppers spent in two versions of a store.<br>• Version A played slow-tempo music.<br>• Version B played fast-tempo music.<br>• Shoppers in Version A stayed 17% longer and spent 38% more.<br>• The researchers studied one grocery store over nine weeks.$q$, $q$The student wants to acknowledge a limitation of the study. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Researchers compared two versions of a grocery store, one playing slow-tempo music and one playing fast-tempo music, to measure how long shoppers stayed.","Because the researchers studied only one grocery store, it is unclear whether slow music would have the same effect elsewhere.","Shoppers who heard slow-tempo music stayed 17% longer and spent 38% more than shoppers who heard fast-tempo music, according to the nine-week study.","The study, which lasted nine weeks, found that slow music increased both shopping time and spending."]$q$::jsonb, 1, $q$A limitation concerns how far the results can be generalized, and the single-store design is one. Only the correct choice states it. The choice beginning "The study, which lasted…" gives a detail without framing it as a limitation.$q$, null),
  ($q$ei-h443$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The coelacanth is a fish once known only from fossils.<br>• Scientists believed it had gone extinct about 66 million years ago.<br>• In 1938, a living coelacanth was caught off South Africa.<br>• Museum curator Marjorie Courtenay-Latimer recognized its significance.<br>• A second species was found in Indonesia in 1998.$q$, $q$The student wants to explain why the 1938 catch was surprising. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Museum curator Marjorie Courtenay-Latimer recognized the significance of the coelacanth caught off South Africa in 1938.","The 1938 catch of a living coelacanth was surprising because scientists believed the fish had gone extinct about 66 million years earlier.","In 1938, a living coelacanth, a fish previously known only from fossils, was caught off the coast of South Africa and identified by a museum curator.","A living coelacanth was caught off South Africa in 1938, and a second species was found in Indonesia in 1998."]$q$::jsonb, 1, $q$Only the correct choice gives the reason for surprise: the fish was thought long extinct. The choice beginning "In 1938, a living…" implies the surprise but doesn't explain it, and the others concern recognition or a later find.$q$, null),
  ($q$ei-h444$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Architect Zaha Hadid (1950–2016) was born in Baghdad.<br>• For years, many of her designs were considered impossible to build.<br>• Her first major completed building, a fire station in Germany, opened in 1993.<br>• Advances in computer modeling later made her curving forms buildable.<br>• In 2004, she became the first woman to win the Pritzker Prize.$q$, $q$The student wants to explain how technology affected Hadid's career. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Hadid's curving designs, made buildable in part by computer modeling, earned her the Pritzker Prize in 2004.","Hadid's designs were long considered impossible to build until advances in computer modeling made her curving forms buildable.","Hadid's first major completed building, a fire station in Germany that opened in 1993, came after years of designs considered impossible to build.","Zaha Hadid, who was born in Baghdad in 1950, became the first woman to win architecture's prestigious Pritzker Prize in 2004."]$q$::jsonb, 1, $q$Only the correct choice links technology to her designs becoming buildable. The choice beginning "Hadid's first major completed…" mentions her unbuildable designs but not technology, and the others give biographical facts.$q$, null),
  ($q$ei-h445$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Ecologists counted insects at 63 nature reserves in Germany from 1989 to 2016.<br>• The total mass of flying insects fell by 76%.<br>• The decline occurred even in protected areas.<br>• Causes are uncertain but may include pesticide use and habitat loss on nearby farmland.$q$, $q$The student wants to emphasize why the decline alarmed ecologists. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Pesticide use and habitat loss on nearby farmland may explain why flying insects declined by 76%.","The causes of the insect decline are uncertain but may include pesticide use and loss of habitat on farmland near the reserves.","Between 1989 and 2016, the mass of flying insects at German nature reserves fell by 76%, even though the areas were protected.","Ecologists counted flying insects at 63 nature reserves in Germany over a period of nearly three decades, from 1989 until 2016."]$q$::jsonb, 2, $q$The alarming features are the size of the decline and that it happened in protected areas, which only the correct choice includes. The others describe the method or possible causes.$q$, null),
  ($q$ei-h446$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Two historians studied the causes of the 1929 stock market crash.<br>• Historian A emphasized excessive borrowing to buy stocks.<br>• Historian B emphasized weak regulation of banks.<br>• Both agreed that public panic accelerated the crash.$q$, $q$The student wants to identify a point on which the historians agreed. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Historian A emphasized excessive borrowing to buy stocks as a cause of the 1929 crash, while Historian B emphasized weak regulation of banks.","Historian A and Historian B each identified a different underlying cause of the 1929 crash.","Both historians agreed that public panic accelerated the 1929 stock market crash.","Two historians studied the causes of the 1929 stock market crash, each emphasizing a different factor that contributed to the collapse of prices."]$q$::jsonb, 2, $q$Only the correct answer states the point of agreement. The choices beginning "Historian A emphasized excessive…" and "Two historians studied the…" describe differences, and the choice beginning "Historian A and Historian…" gives one historian's view.$q$, null),
  ($q$ei-h447$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Spider silk is stronger by weight than steel.<br>• Spiders cannot be farmed like silkworms because they are territorial and eat each other.<br>• Scientists inserted spider silk genes into bacteria and yeast.<br>• These microbes produce silk proteins that can be spun into fibers.<br>• The fibers are being tested for use in sutures and lightweight armor.$q$, $q$The student wants to explain why scientists turned to microbes to produce spider silk. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Unlike silkworms, spiders produce silk that is stronger by weight than steel.","Spider silk is stronger by weight than steel, and fibers spun from silk proteins are being tested for sutures and lightweight armor.","Scientists inserted spider silk genes into bacteria and yeast, which produce silk proteins that can then be spun into useful fibers for medicine.","Because spiders are territorial and eat each other, they cannot be farmed, so scientists inserted silk genes into bacteria and yeast."]$q$::jsonb, 3, $q$Only the correct choice gives the reason for using microbes and connects it to that approach. The choice beginning "Scientists inserted spider silk…" describes the method without the reason, and the choice beginning "Unlike silkworms, spiders produce…" gives a reason with no connection to microbes.$q$, null),
  ($q$ei-h448$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Great Barrier Reef experienced mass coral bleaching in 2016, 2017, 2020, and 2022.<br>• Bleaching occurs when high water temperatures cause coral to expel algae living in its tissues.<br>• Bleached coral can recover if temperatures drop soon enough.<br>• Recovery typically takes 10–15 years.$q$, $q$The student wants to explain why frequent bleaching events threaten recovery. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Great Barrier Reef experienced mass coral bleaching events in 2016, 2017, 2020, and 2022, according to researchers who monitor the reef.","Coral typically needs 10–15 years to recover from bleaching, yet the reef bleached four times between 2016 and 2022.","Bleached coral can recover if temperatures drop soon enough, a process that typically takes 10–15 years.","Bleaching occurs when high water temperatures cause coral to expel the algae living in its tissues, though bleached coral can recover if waters cool."]$q$::jsonb, 1, $q$The threat comes from the mismatch between the recovery time and the frequency of events, which only the correct choice presents. The choice beginning "The Great Barrier Reef…" lists the events without the recovery time, and the choice beginning "Bleaching occurs when high…" explains the mechanism.$q$, null),
  ($q$ei-h449$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Kenyan runner Tegla Loroupe won the New York City Marathon in 1994.<br>• She was the first African woman to win a major marathon.<br>• She founded a foundation that organizes peace races in conflict regions.<br>• The races bring together members of rival communities.<br>• In 2016, she led the first Refugee Olympic Team.$q$, $q$The student wants to describe how Loroupe uses running to promote peace. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Tegla Loroupe, who founded a foundation devoted to peace, led the first Refugee Olympic Team at the 2016 Olympic Games.","Loroupe's foundation organizes peace races in conflict regions that bring together members of rival communities.","After winning the 1994 New York City Marathon, Loroupe went on to lead the first Refugee Olympic Team.","In 1994, Kenyan runner Tegla Loroupe won the New York City Marathon, becoming the first African woman to win a major marathon."]$q$::jsonb, 1, $q$Only the correct choice describes how running promotes peace: races that unite rival communities. The others give athletic achievements or an unrelated role.$q$, null),
  ($q$ei-h450$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers taught crows to associate a masked face with being captured.<br>• Years later, crows scolded people wearing that mask.<br>• Crows that had never been captured also scolded the mask.<br>• Researchers concluded that crows learn about dangerous humans from other crows.$q$, $q$The student wants to present the evidence for the researchers' conclusion. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Crows that had been captured by masked researchers scolded people wearing that mask years later.","Researchers taught crows to associate a particular masked face with being captured, and years later the crows still scolded people wearing it.","Even crows that had never been captured scolded the mask associated with capture, suggesting they learned of the danger from other crows.","Researchers concluded that crows learn about dangerous humans from one another, in addition to learning from their own experiences."]$q$::jsonb, 2, $q$The key evidence for social learning is that crows never captured also scolded the mask. Only the correct choice gives it. The choice beginning "Researchers taught crows to…" shows individual memory, not social learning, and the choice beginning "Researchers concluded that crows…" states the conclusion without evidence.$q$, null),
  ($q$ei-h451$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Library of Congress's "Chronicling America" project has digitized over 20 million newspaper pages.<br>• The pages date from 1756 to 1963.<br>• Optical character recognition makes the text searchable.<br>• Historians have used it to trace how stories spread between newspapers.$q$, $q$The student wants to explain how a feature of the project supports historical research. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Library of Congress's \"Chronicling America\" project has digitized more than 20 million pages from newspapers dating from 1756 to 1963.","Historians have used the \"Chronicling America\" project to trace how stories spread between newspapers.","Historians have used the \"Chronicling America\" project, run by the Library of Congress, to research a variety of topics in American history.","Because optical character recognition makes the project's pages searchable, historians can trace how stories spread between newspapers."]$q$::jsonb, 3, $q$The correct choice links a feature (searchability) to a research use. The choice beginning "The Library of Congress's…" describes scale, the choice beginning "Historians have used the "Chronicling America" project…" mentions use vaguely, and the choice beginning "Historians have used the "Chronicling America" project…" gives a date range.$q$, null),
  ($q$ei-h452$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers compared sleep in hunter-gatherer communities in Tanzania, Namibia, and Bolivia.<br>• People slept an average of 6.4 hours per night.<br>• This is similar to or less than sleep in industrial societies.<br>• Many had assumed that modern technology had reduced human sleep.$q$, $q$The student wants to present a finding that challenges a common assumption. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Many people had assumed that modern technology, including electric lighting, had reduced the amount of sleep humans get each night.","Researchers compared sleep in hunter-gatherer communities in three countries, Tanzania, Namibia, and Bolivia, and found that people there slept an average of 6.4 hours per night.","Hunter-gatherers slept about 6.4 hours a night, no more than people in industrial societies, challenging the idea that technology has reduced human sleep.","People in the hunter-gatherer communities slept 6.4 hours per night."]$q$::jsonb, 2, $q$Only the correct choice gives the finding, the comparison, and the assumption it challenges. The choice beginning "People in the hunter-gatherer…" gives the finding without the comparison, and the others give the design or the assumption alone.$q$, null),
  ($q$ei-h453$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Poet Joy Harjo is a member of the Muscogee (Creek) Nation.<br>• In 2019, she became the first Native American U.S. Poet Laureate.<br>• Her poems often draw on Muscogee stories and history.<br>• She is also a saxophonist who performs her poetry with music.$q$, $q$The student wants to describe how Harjo combines art forms. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Joy Harjo's poems often draw on the stories and history of the Muscogee (Creek) Nation, of which she is a member.","Harjo, the first Native American U.S. Poet Laureate, draws on Muscogee stories in her poems.","In 2019, Joy Harjo, a member of the Muscogee (Creek) Nation, became the first Native American to serve as Poet Laureate of the United States.","A saxophonist as well as a poet, Joy Harjo performs her poetry with music."]$q$::jsonb, 3, $q$Only the correct choice describes the combination of poetry and music. The others describe her honors or her sources.$q$, null),
  ($q$ei-h454$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers placed fake fruit of different colors in a forest.<br>• Birds took red fruit more often than green fruit.<br>• Mammals showed no color preference.<br>• Many bird-dispersed plants produce red fruit.<br>• Researchers suggest fruit color evolved partly to attract birds.$q$, $q$The student wants to connect the experimental results to a broader pattern in plants. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["In an experiment, birds took red fake fruit more often than green fake fruit, while mammals in the same forest showed no color preference at all.","Birds preferred red fake fruit, and many bird-dispersed plants produce red fruit, suggesting that fruit color evolved partly to attract birds.","Researchers placed fake fruit of several different colors in a forest to see which colors birds and mammals would prefer to take.","Many plants whose seeds are dispersed by birds produce red fruit."]$q$::jsonb, 1, $q$Connecting the results to the broader pattern requires both the bird preference and the prevalence of red fruit, as in the correct choice. The choice beginning "In an experiment, birds…" gives results only, and the choice beginning "Many plants whose seeds…" gives the pattern only.$q$, null),
  ($q$ei-h455$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Treaty of Westphalia (1648) ended the Thirty Years' War.<br>• It recognized the sovereignty of individual states within the Holy Roman Empire.<br>• Scholars often cite it as the origin of the modern system of independent states.<br>• Some historians argue this view oversimplifies the treaty's actual terms.$q$, $q$The student wants to present the scholarly debate about the treaty's significance. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["The Treaty of Westphalia, signed in 1648, ended the Thirty Years' War and recognized the sovereignty of individual states within the Holy Roman Empire.","Scholars often cite the 1648 Treaty of Westphalia, which ended the Thirty Years' War, as the origin of the modern system of independent states.","Some historians argue that the common view of the Treaty of Westphalia oversimplifies its actual terms.","While many scholars cite the Treaty of Westphalia as the origin of the modern state system, some historians argue that this view oversimplifies its terms."]$q$::jsonb, 3, $q$A debate requires both positions, which only the correct choice presents. The choice beginning "Scholars often cite the…" gives the common view only, and the choices beginning "The Treaty of Westphalia…" and "Some historians argue that…" describe the treaty's terms.$q$, null),
  ($q$ei-h456$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• Researchers gave participants a puzzle to solve.<br>• Some participants were told to take a 10-minute break midway.<br>• During the break, half did an undemanding task; half rested.<br>• The undemanding-task group solved 41% more puzzles afterward.<br>• Researchers suggest mind-wandering during simple tasks aids creative problem-solving.$q$, $q$The student wants to present the researchers' suggestion and the result that prompted it. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Some participants who were given a puzzle to solve were told to take a 10-minute break midway, during which half rested and half did a simple task.","Participants who did an undemanding task during a break solved 41% more puzzles, leading researchers to suggest that mind-wandering aids creative problem-solving.","Taking a 10-minute break midway through a puzzle helped participants solve 41% more puzzles afterward.","Researchers suggest that the mind-wandering that occurs during simple tasks can help people solve problems creatively, especially when they take a 10-minute break midway through a puzzle."]$q$::jsonb, 1, $q$The correct choice gives both the result and the suggestion it prompted. The choice beginning "Researchers suggest that the…" gives only the suggestion, the choice beginning "Some participants who were…" only the method, and the choice beginning "Taking a 10-minute break…" an imprecise result.$q$, null),
  ($q$ei-h457$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Rhetorical Synthesis$q$, 3, $q$While researching a topic, a student has taken the following notes:<br>• The Panama Canal uses locks to lift ships 26 meters above sea level.<br>• Each ship passage uses about 200 million liters of fresh water from Gatun Lake.<br>• A 2023 drought lowered Gatun Lake's water level.<br>• Authorities reduced the number of daily ship crossings.$q$, $q$The student wants to explain why the drought affected canal traffic. Which choice most effectively uses relevant information from the notes to accomplish this goal?$q$, $q$["Because each ship passage uses about 200 million liters of water from Gatun Lake, a drought that lowered the lake led authorities to reduce crossings.","The Panama Canal uses a system of locks to lift ships 26 meters above sea level as they pass between the Atlantic and Pacific Oceans.","In 2023, a drought lowered the water level of Gatun Lake, and authorities reduced the number of ships allowed to cross the Panama Canal each day.","Each ship passage through the Panama Canal's locks uses about 200 million liters of fresh water."]$q$::jsonb, 0, $q$Explaining why requires the link between the canal's water use and the drought, which only the correct choice makes. The choice beginning "In 2023, a drought…" reports the drought and the reduction without the causal link.$q$, null),
  ($q$ei-h458$q$, $q$rw$q$, $q$Expression of Ideas$q$, $q$Transitions$q$, 3, $q$The first transatlantic telegraph cable, completed in 1858, allowed messages to cross the ocean in minutes rather than the ten days required by ship. ______ the cable's insulation failed after only three weeks, and a durable connection was not established until 1866.$q$, $q$Which choice completes the text with the most logical transition?$q$, $q$["For instance,","Unfortunately,","Consequently,","Similarly,"]$q$::jsonb, 1, $q$The cable's quick failure was an undesirable turn after its promising start, so "Unfortunately" fits. "Consequently" would claim that fast messaging caused the failure, "Similarly" signals a parallel, and "For instance" signals an example.$q$, null),
  ($q$conv-1$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Once the votes were tallied______the results were announced to a stunned crowd.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Once the votes were tallied' is an introductory dependent clause and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-2$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The city's water tower had stood for over a century______no one wanted to see it demolished.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," so, ",": "]$q$::jsonb, 0, $q$Both parts are independent clauses with no coordinating conjunction, so they must be joined with a semicolon; a comma alone would create a comma splice.$q$, null),
  ($q$conv-3$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The experiment's outcome confirmed the hypothesis______heat does accelerate the reaction.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the explanation of what the hypothesis was, following a complete independent clause.$q$, null),
  ($q$conv-4$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Employees______who complete the training will receive a certificate.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[" ",", ","; ",": "]$q$::jsonb, 0, $q$'Who complete the training' is a restrictive (essential) clause identifying which employees, so no comma is needed before it.$q$, null),
  ($q$conv-5$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The recipe, ______ was passed down through four generations, calls for a pinch of saffron.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["which","that","who","whom"]$q$::jsonb, 0, $q$The clause is nonessential (set off by commas) and refers to a thing, the recipe, so 'which' is correct; 'that' is reserved for restrictive clauses.$q$, null),
  ($q$conv-6$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Ticket sales exceeded expectations______therefore, the band added a second show.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$A conjunctive adverb like 'therefore' joining two independent clauses requires a semicolon before it (and a comma after).$q$, null),
  ($q$conv-7$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Exhausted from the overnight flight______the team went straight to bed instead of sightseeing.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Exhausted from the overnight flight' is an introductory participial phrase and must be followed by a comma.$q$, null),
  ($q$conv-8$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The rain continued for hours______the streets began to flood.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Two independent clauses with no conjunction must be separated by a semicolon; a comma alone would create a comma splice.$q$, null),
  ($q$conv-9$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The museum acquired three new pieces this year______a bronze sculpture, an oil painting, and a hand-woven tapestry.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", ",""]$q$::jsonb, 0, $q$A colon correctly introduces the list of items following the complete independent clause.$q$, null),
  ($q$conv-10$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$In the years following the merger______the company's revenue nearly tripled.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'In the years following the merger' is an introductory phrase and requires a comma before the main clause.$q$, null),
  ($q$conv-11$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Critics were divided on the film's pacing______audiences overwhelmingly loved it.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Two independent clauses with a contrast in meaning but no coordinating conjunction must be joined with a semicolon.$q$, null),
  ($q$conv-12$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The award, ______ given annually since 1962 to the reporter whose work most advances the public interest, honors excellence in local journalism.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["which has been","that has been","who has been","being"]$q$::jsonb, 0, $q$The nonessential clause set off by commas describes a thing (the award), not the reporter named later in the sentence, so it needs the thing-pronoun 'which' with a complete verb phrase; 'who has been' is tempting because a person is mentioned nearby, but the clause still modifies 'award.'$q$, null),
  ($q$conv-13$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The bakery sold out of croissants by nine a.m.______the line had formed before sunrise.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," because "]$q$::jsonb, 0, $q$Both clauses are independent and closely related, so a semicolon correctly joins them without a coordinating conjunction.$q$, null),
  ($q$conv-14$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The flock of geese______south every autumn.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["migrates","migrate","have migrated","are migrating"]$q$::jsonb, 0, $q$'Flock' is a singular collective noun, so it takes the singular verb 'migrates.'$q$, null),
  ($q$conv-15$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Neither the coach nor the players______satisfied with the referee's call.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["were","was","is","has been"]$q$::jsonb, 0, $q$In an 'either/or' or 'neither/nor' construction, the verb agrees with the nearer subject, 'players,' which is plural, so 'were' is correct.$q$, null),
  ($q$conv-16$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Each of the applicants______required to submit three letters of recommendation.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["is","are","were","have been"]$q$::jsonb, 0, $q$'Each' is singular, regardless of the plural noun in the prepositional phrase that follows it, so the singular verb 'is' is correct.$q$, null),
  ($q$conv-17$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$By the time the guests arrive, she______dinner for two hours.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["will have been cooking","will cook","cooked","is cooking"]$q$::jsonb, 0, $q$'By the time' with a future event signals the future perfect progressive tense, 'will have been cooking,' to show an action continuing up to that future point; 'will cook' is tempting because it is also future tense, but it lacks the progressive aspect needed to show the two-hour duration.$q$, null),
  ($q$conv-18$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The data______surprising, prompting the team to repeat the experiment.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["were","was","is","has been"]$q$::jsonb, 0, $q$In formal Standard English, 'data' is treated as a plural noun (the plural of 'datum'), so it takes the plural verb 'were.'$q$, null),
  ($q$conv-19$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The company reminded its employees to submit______expense reports by Friday.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["their","his","its","one's"]$q$::jsonb, 0, $q$The antecedent 'employees' is plural, so the plural possessive pronoun 'their' is required for agreement.$q$, null),
  ($q$conv-20$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The twins each brought______own laptop to the study session.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["their","his","its","one's"]$q$::jsonb, 0, $q$'The twins' is the plural antecedent, so 'their' is the only pronoun among the choices that agrees with it correctly.$q$, null),
  ($q$conv-21$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Walking through the old district, ______$q$, $q$Which choice most logically and clearly completes the sentence?$q$, $q$["I finally saw the cathedral's spires come into view.","the cathedral's spires finally came into view.","a faded guidebook listed the cathedral's spires among the highlights.","the narrow streets led directly to the cathedral's spires."]$q$::jsonb, 0, $q$The introductory phrase 'Walking through the old district' describes a person, so the noun immediately after the comma must be the walker, 'I'; a guidebook or a set of streets cannot walk, even though both sentences read smoothly on their own.$q$, null),
  ($q$conv-22$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The internship taught her to manage budgets, delegate tasks, and______client meetings.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["lead","leading","how to lead","she led"]$q$::jsonb, 0, $q$The sentence lists parallel infinitive actions ('to manage,' '[to] delegate,' '[to] lead'), so 'lead' maintains the parallel structure.$q$, null),
  ($q$conv-23$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The award recognizes work that is original, rigorous, and______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["clearly written","clarity in writing","written with clarity","the writing is clear"]$q$::jsonb, 0, $q$The list requires parallel adjective phrases ('original, rigorous, and ___'), and 'clearly written' matches that adjectival form.$q$, null),
  ($q$conv-24$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Yesterday, the technician inspected the wiring and______that a fuse had blown.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["determined","determines","will determine","determining"]$q$::jsonb, 0, $q$The sentence is in past tense ('Yesterday...inspected'), so the second verb must also be past tense, 'determined,' to remain consistent.$q$, null),
  ($q$conv-25$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Of the two finalists, the second speaker was the______prepared.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["more","most","much","many"]$q$::jsonb, 0, $q$When comparing exactly two things, the comparative form 'more' is required rather than the superlative 'most,' which is used for three or more.$q$, null),
  ($q$conv-26$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The storm knocked out power across the county______residents relied on generators for nearly a week.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," "," and, "]$q$::jsonb, 0, $q$Two independent clauses ('The storm knocked out power...' and 'residents relied on generators...') must be joined with a semicolon (or a comma plus conjunction); only the semicolon is offered correctly here.$q$, null),
  ($q$conv-27$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The committee, along with its three advisors,______meeting every Thursday afternoon.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["holds","hold","holding","have held"]$q$::jsonb, 0, $q$'Along with its three advisors' is a parenthetical phrase, not part of the subject. The true subject is the singular 'committee,' which requires the singular verb 'holds.'$q$, null),
  ($q$conv-28$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Having rehearsed the presentation a dozen times______the intern still felt nervous walking into the boardroom.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," and "]$q$::jsonb, 0, $q$An introductory participial phrase ('Having rehearsed...times') must be separated from the main clause with a comma.$q$, null),
  ($q$conv-29$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The city council recommended that the new ordinance______before the next fiscal year begins.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["take effect","takes effect","will take effect","took effect"]$q$::jsonb, 0, $q$'Recommended that' triggers the subjunctive mood, which uses the base form of the verb, 'take effect,' regardless of the subject's number or the sentence's tense; the ordinary past-tense form 'took effect' is tempting but is indicative, not subjunctive.$q$, null),
  ($q$conv-30$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Only the applicants______submitted every required document were invited to interview.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["who","who, ",", who",", who,"]$q$::jsonb, 0, $q$The clause 'who submitted every required document' is essential (restrictive) to identifying which applicants are meant, so it takes no surrounding commas; ', who' is the closest trap because it would be correct only if the clause were nonessential, merely adding extra detail about applicants already identified.$q$, null),
  ($q$conv-31$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The workshop teaches participants not only how to write persuasive essays but also______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["how to revise them effectively","how revising them is done effectively","how effective their revisions are","revising them effectively"]$q$::jsonb, 0, $q$'Not only...but also' requires matching grammatical forms; since the first element is the infinitive phrase 'how to write persuasive essays,' the second must match with 'how to revise them effectively.' The other choices keep the word 'how' or a gerund but drop the parallel infinitive structure, so they break the parallelism.$q$, null),
  ($q$conv-32$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The recipe calls for three ingredients______flour, sugar, and butter.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the list that follows a complete independent clause ('The recipe calls for three ingredients').$q$, null),
  ($q$conv-33$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Neither the manager nor the employees______aware of the policy change until the memo arrived.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["were","was","is","has been"]$q$::jsonb, 0, $q$In 'neither...nor' constructions, the verb agrees with the nearer subject. Since 'employees' (plural) is nearer, the plural verb 'were' is correct.$q$, null),
  ($q$conv-34$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The bridge closed for repairs at midnight______traffic was rerouted through downtown for the remainder of the week.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Both parts are independent clauses with no coordinating conjunction joining them, so a semicolon is required; a comma alone would create a comma splice.$q$, null),
  ($q$conv-35$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Everyone in the auditorium______asked to silence their phones before the performance began.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["was","were","are","have been"]$q$::jsonb, 0, $q$The indefinite pronoun 'everyone' is grammatically singular, so it takes the singular verb 'was.'$q$, null),
  ($q$conv-36$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$After weeks of drought______the first heavy rainfall finally soaked the parched fields.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'After weeks of drought' is an introductory prepositional phrase and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-37$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The band members loaded______instruments onto the bus before the sun rose.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["their","his","its","one's"]$q$::jsonb, 0, $q$The antecedent 'band members' is plural, so the plural possessive pronoun 'their' is required for agreement.$q$, null),
  ($q$conv-38$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The chef's pantry contained only the essentials______olive oil, garlic, and sea salt.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", ",""]$q$::jsonb, 0, $q$A colon correctly introduces the list of items following the complete independent clause.$q$, null),
  ($q$conv-39$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$By the time the fire crew arrived, the flames______the roof.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["had already consumed","would have consumed","have already consumed","were already consuming"]$q$::jsonb, 0, $q$Because the roof was consumed before another past event (the crew's arrival), the past perfect 'had already consumed' is required; 'would have consumed' is tempting because it also pairs two past events, but the conditional perfect implies an unmet hypothetical condition rather than simply reporting what had already happened.$q$, null),
  ($q$conv-40$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The final vote______a stunning, unanimous 7-to-2 decision—reshaped the court's approach to digital privacy.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["—",", ",": ","; "]$q$::jsonb, 0, $q$The interrupting phrase 'a stunning, unanimous 7-to-2 decision' already contains its own internal comma, so only a matching dash—not a comma, colon, or semicolon—can open the interruption without creating ambiguity about where the aside begins.$q$, null),
  ($q$conv-41$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Scanning the horizon for storm clouds, ______$q$, $q$Which choice most logically and clearly completes the sentence?$q$, $q$["the sailor decided to postpone the voyage.","the voyage required postponing before nightfall.","storm clouds gathered quickly along the horizon.","the weather forecast warned of an approaching storm."]$q$::jsonb, 0, $q$The introductory phrase 'Scanning the horizon for storm clouds' describes a person performing the action, so the noun immediately after the comma must be that person, 'the sailor'; the voyage, the clouds, and the forecast cannot scan the horizon, even though each sentence is otherwise well formed.$q$, null),
  ($q$conv-42$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The negotiations stalled for weeks______both sides finally agreed to bring in a mediator.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Both clauses are independent and lack a coordinating conjunction, so they must be joined with a semicolon rather than a comma, which would create a comma splice.$q$, null),
  ($q$conv-43$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The award goes to______the committee considers most deserving.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["whomever","whoever","whom","who"]$q$::jsonb, 0, $q$Within the clause, the pronoun functions as the object of 'considers' ('the committee considers whom'), so the objective case 'whomever' is required even though the whole clause follows the preposition 'to'; 'whoever' is the closest trap because it would be correct if the pronoun were instead the subject of 'considers,' which it is not.$q$, null),
  ($q$conv-44$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Startled by the sudden thunderclap______the toddler began to cry.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Startled by the sudden thunderclap' is an introductory participial phrase and must be followed by a comma before the main clause.$q$, null),
  ($q$conv-45$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Of the three routes into town, the coastal road is the______scenic.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["most","more","much","many"]$q$::jsonb, 0, $q$When comparing three or more items, the superlative form 'most' is required rather than the comparative 'more,' which is used for exactly two.$q$, null),
  ($q$conv-46$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The panel featured three experts______Dr. Alavi, a virologist; Ms. Ferreira, an epidemiologist; and Mr. Osei, a public health researcher.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the list following the complete independent clause, and because the items themselves contain commas, semicolons separate the items; the semicolon is the closest trap, since semicolons do correctly separate the list's items, but only a colon can introduce the list as a whole.$q$, null),
  ($q$conv-47$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The corporation announced that______quarterly earnings had exceeded projections.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["its","it's","their","it is"]$q$::jsonb, 0, $q$The possessive pronoun 'its' (no apostrophe) is needed to show the corporation's earnings; 'it's' is a contraction of 'it is' and does not fit here.$q$, null),
  ($q$conv-48$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The council approved the new budget______but several residents voiced concerns at the meeting.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'But' is a coordinating conjunction joining two independent clauses, so a comma must precede it.$q$, null),
  ($q$conv-49$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The new policy is intended both to reduce costs and to______employee satisfaction.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["improve","improving","improvement of","the improvement in"]$q$::jsonb, 0, $q$'Both...and' requires parallel structure; since the first element is the infinitive 'to reduce,' the second must match with the base verb 'improve' after 'to.' 'Improving' is the closest trap because it still reads smoothly after 'to,' but pairing 'to' with a gerund breaks the required infinitive parallel with 'to reduce.'$q$, null),
  ($q$conv-50$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Books______written before 1900 are displayed in the rare collections room.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[" ",", ","; ",": "]$q$::jsonb, 0, $q$'Written before 1900' is a restrictive (essential) phrase identifying which books are meant, so no comma is needed before it.$q$, null),
  ($q$conv-51$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The old photographs had______in the attic for decades before anyone rediscovered them.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["lain","laid","lay","layed"]$q$::jsonb, 0, $q$The intransitive verb 'lie' (to rest in a place) takes the past participle 'lain' after 'had.' 'Laid' is the closest trap because it is the past participle of the similar-sounding verb 'lay,' but 'lay' is transitive and requires a direct object, which this sentence does not have.$q$, null),
  ($q$conv-52$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The proposal was, however______far too costly for the city's current budget.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'However' interrupts a single independent clause rather than joining two clauses, so it must be enclosed in a pair of commas; since the first comma is already given, a matching comma is needed here. The semicolon is the closest trap because 'however' often pairs with a semicolon when it joins two independent clauses, but here it merely interrupts one clause, which calls for commas instead.$q$, null),
  ($q$conv-53$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Fifteen minutes______enough time to finish the quiz, according to the instructor.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["is","are","were","have been"]$q$::jsonb, 0, $q$When an amount of time is treated as a single unit rather than individual minutes, it takes a singular verb, so 'is' is correct.$q$, null),
  ($q$conv-54$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The bridge was closed for inspection______consequently, commuters faced long delays for a week.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$'Consequently' is a conjunctive adverb joining two independent clauses, so it must be preceded by a semicolon and followed by a comma.$q$, null),
  ($q$conv-55$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Her weekend routine consists of jogging, reading, and______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["cooking","to cook","she cooks","cooked meals"]$q$::jsonb, 0, $q$The list requires parallel gerunds ('jogging, reading, and ___'), so 'cooking' matches the established form.$q$, null),
  ($q$conv-56$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Because the trail was covered in ice______the rangers closed it to hikers until spring.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Because the trail was covered in ice' is an introductory dependent clause and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-57$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$One of the boxes in the storage room______missing when the inventory was taken.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["was","were","are","have been"]$q$::jsonb, 0, $q$The subject of the sentence is the singular pronoun 'one,' not the object of the preposition 'boxes,' so the singular verb 'was' is correct.$q$, null),
  ($q$conv-58$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Even though the museum extended its hours for the holidays______attendance remained lower than expected.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": ",". "]$q$::jsonb, 0, $q$'Even though the museum extended its hours for the holidays' is a dependent clause; ending it with a period would create a sentence fragment, so it must be joined to the independent clause with a comma.$q$, null),
  ($q$conv-59$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The negotiations proceeded______than either side had anticipated.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["more smoothly","smoother","more smooth","smoothly more"]$q$::jsonb, 0, $q$The verb 'proceeded' must be modified by an adverb, not an adjective, so 'more smoothly' is correct. 'Smoother' is the closest trap because it is a natural-sounding comparative, but as an adjective it cannot modify the verb 'proceeded.'$q$, null),
  ($q$conv-60$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$After centuries of naked-eye observation______astronomers finally photographed a black hole directly.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'After centuries of naked-eye observation' is an introductory prepositional phrase and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-61$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The school of herring______toward deeper water every evening.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["moves","move","have moved","are moving"]$q$::jsonb, 0, $q$'School' is a singular collective noun, so it takes the singular verb 'moves.'$q$, null),
  ($q$conv-62$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The cathedral's stained-glass windows survived two world wars______a stray ember from a nearby fire nearly destroyed them in 1970.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Both parts are independent clauses with no coordinating conjunction, so they must be joined with a semicolon; a comma alone would create a comma splice.$q$, null),
  ($q$conv-63$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Last spring, archaeologists excavated the site and______several intact pottery shards.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["uncovered","uncover","will uncover","uncovering"]$q$::jsonb, 0, $q$The sentence is in past tense ('excavated'), so the second verb must also be past tense, 'uncovered,' to remain consistent.$q$, null),
  ($q$conv-64$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The central bank's decision______a quarter-point rate cut, its first in three years—surprised most analysts who had expected no change.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["—",", ",": ","; "]$q$::jsonb, 0, $q$The interrupting phrase 'a quarter-point rate cut, its first in three years' already contains its own internal comma, so only a matching dash—not a comma, colon, or semicolon—can open the interruption without creating ambiguity about where the aside begins.$q$, null),
  ($q$conv-65$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The research team ensured that______data collection methods met ethical standards.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["its","their","his","one's"]$q$::jsonb, 0, $q$'Team' functions as a singular collective noun acting as one unit, so it takes the singular possessive 'its,' not the plural 'their.'$q$, null),
  ($q$conv-66$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Because the wetland absorbs excess rainfall______nearby towns rarely experience severe flooding.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Because the wetland absorbs excess rainfall' is an introductory dependent clause and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-67$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The chef's morning routine includes tasting sauces, plating desserts, and______the walk-in cooler.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["restocking","restock","to restock","she restocks"]$q$::jsonb, 0, $q$The list requires parallel gerunds ('tasting,' 'plating,' and ___), so 'restocking' matches the established form.$q$, null),
  ($q$conv-68$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The expedition relied on three specialists______Dr. Nkemelu, a glaciologist; Ms. Petrova, a mountaineer; and Mr. Diallo, a logistics coordinator.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the list following the complete independent clause, and because the items themselves contain commas, semicolons separate the items; the semicolon is the closest trap, since semicolons do correctly separate the list's items, but only a colon can introduce the list as a whole.$q$, null),
  ($q$conv-69$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$There______several dialects spoken across the small island chain.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["are","is","was","has been"]$q$::jsonb, 0, $q$The subject that follows, 'several dialects,' is plural, so the verb must agree with it: 'are.'$q$, null),
  ($q$conv-70$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Adjusting the aperture for low light______the photographer captured the dim alleyway in sharp detail.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Adjusting the aperture for low light' is an introductory participial phrase and must be followed by a comma before the main clause.$q$, null),
  ($q$conv-71$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Of the two compounds tested, the second proved the______stable under heat.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["more","most","much","many"]$q$::jsonb, 0, $q$When comparing exactly two things, the comparative form 'more' is required rather than the superlative 'most,' which is used for three or more.$q$, null),
  ($q$conv-72$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The fault line, ______ runs beneath three counties, has not produced a major earthquake in decades.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["which","that","who","whom"]$q$::jsonb, 0, $q$The clause is nonessential (set off by commas) and refers to a thing, the fault line, so 'which' is correct; 'that' is reserved for restrictive clauses.$q$, null),
  ($q$conv-73$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The board insisted that every member______the annual report before the vote.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["review","reviews","reviewed","will review"]$q$::jsonb, 0, $q$'Insisted that' triggers the subjunctive mood, which uses the base form of the verb, 'review,' regardless of the subject's number; 'reviews' is tempting because it agrees with the singular 'member,' but ordinary subject-verb agreement does not apply inside a subjunctive clause.$q$, null),
  ($q$conv-74$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The flight was rerouted due to turbulence______and passengers arrived nearly an hour late.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'And' is a coordinating conjunction joining two independent clauses, so a comma must precede it.$q$, null),
  ($q$conv-75$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Researchers______the ancient manuscript for nearly a decade, and they have yet to translate it fully.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["have studied","studied","study","will study"]$q$::jsonb, 0, $q$The action began in the past and continues into the present ('for nearly a decade...have yet to'), so the present perfect 'have studied' is correct.$q$, null),
  ($q$conv-76$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Plants______native to arid climates often store water in thick, fleshy leaves.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[" ",", ","; ",": "]$q$::jsonb, 0, $q$'Native to arid climates' is a restrictive (essential) phrase identifying which plants are meant, so no comma is needed before it.$q$, null),
  ($q$conv-77$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Designed to withstand extreme temperatures, ______$q$, $q$Which choice most logically and clearly completes the sentence?$q$, $q$["the rover continued transmitting data from the Martian surface.","the Martian surface posed new engineering challenges for the team.","mission engineers monitored the rover's systems around the clock.","the data collected revealed surprising temperature swings."]$q$::jsonb, 0, $q$The introductory phrase 'Designed to withstand extreme temperatures' describes the rover, so the noun immediately after the comma must be 'the rover'; the surface, the engineers, and the data were not themselves designed for that purpose, even though each choice forms a complete, sensible sentence.$q$, null),
  ($q$conv-78$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Inflation slowed in the first quarter______unemployment climbed to its highest level in five years.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Two independent clauses with a contrast in meaning but no coordinating conjunction must be joined with a semicolon.$q$, null),
  ($q$conv-79$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$City planners asked residents to submit______feedback on the proposed bike lanes.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["their","his","its","one's"]$q$::jsonb, 0, $q$The antecedent 'residents' is plural, so the plural possessive pronoun 'their' is required for agreement.$q$, null),
  ($q$conv-80$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$After tuning each string by ear______the violinist began the rehearsal.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'After tuning each string by ear' is an introductory phrase and requires a comma before the main clause.$q$, null),
  ($q$conv-81$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The number of stray cats in the neighborhood______significantly since the shelter opened.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["has decreased","have decreased","decrease","are decreasing"]$q$::jsonb, 0, $q$'The number of' is treated as singular, so it takes the singular verb 'has decreased'; this differs from 'a number of,' which takes a plural verb.$q$, null),
  ($q$conv-82$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The coin______a rare 1943 copper penny, one of only a dozen known to exist—sold at auction for more than one million dollars.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["—",", ",": ","; "]$q$::jsonb, 0, $q$The interrupting phrase 'a rare 1943 copper penny, one of only a dozen known to exist' already contains its own internal comma, so only a matching dash—not a comma, colon, or semicolon—can open the interruption without creating ambiguity about where the aside begins.$q$, null),
  ($q$conv-83$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The entomologist observed the colony for three days and then______her findings in a field journal.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["recorded","records","will record","recording"]$q$::jsonb, 0, $q$The sentence is in past tense ('observed'), so the second verb must also be past tense, 'recorded,' to remain consistent.$q$, null),
  ($q$conv-84$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The old-growth forest had never been logged______conservationists fought hard to keep it that way.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", "," so, ",": "]$q$::jsonb, 0, $q$Both parts are independent clauses with no coordinating conjunction, so they must be joined with a semicolon; a comma alone would create a comma splice.$q$, null),
  ($q$conv-85$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The majority of the ballots______already been counted by midnight.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["had","has","having","was"]$q$::jsonb, 0, $q$In 'the majority of the ballots,' the verb agrees with the plural noun 'ballots,' so the plural 'had' is correct, not the singular 'has.'$q$, null),
  ($q$conv-86$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The cipher revealed a single truth______the message had been hidden in plain sight all along.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the explanation of what the truth was, following a complete independent clause; the semicolon is the closest trap because it could also join these two independent clauses, but it lacks the colon's specific signal that what follows defines or explains the 'single truth' just mentioned.$q$, null),
  ($q$conv-87$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The dough had______for two hours before the baker shaped it into loaves.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["risen","raised","rose","raise"]$q$::jsonb, 0, $q$The intransitive verb 'rise' (to go up on its own) takes the past participle 'risen' after 'had'; 'raised' is the past participle of the transitive verb 'raise,' which requires a direct object.$q$, null),
  ($q$conv-88$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The marathon route wound through the historic district______but organizers rerouted it after the storm.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'But' is a coordinating conjunction joining two independent clauses, so a comma must precede it.$q$, null),
  ($q$conv-89$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The exhibit's centerpiece was praised as bold, inventive, and______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["thought-provoking","provoking thought","thoughts were provoked","provoker of thought"]$q$::jsonb, 0, $q$The list requires parallel adjectives ('bold, inventive, and ___'), and 'thought-provoking' matches that adjectival form.$q$, null),
  ($q$conv-90$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The novel______won the award last year has been translated into a dozen languages.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["that","which","who","whom"]$q$::jsonb, 0, $q$The clause 'won the award last year' is essential to identifying which novel is meant and has no surrounding commas, so the restrictive pronoun 'that' is correct.$q$, null),
  ($q$conv-91$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$If the sample______contaminated, the results would have shown far greater variance.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["had been","was","were","has been"]$q$::jsonb, 0, $q$The main clause 'would have shown' signals a past unreal conditional, which requires the past perfect 'had been' in the if-clause. 'Were' is the closest trap because it is the correct subjunctive form for a present contrary-to-fact condition, but this sentence is about a past, completed event, which needs the past perfect instead.$q$, null),
  ($q$conv-92$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Consumer demand for sustainable fabrics grew rapidly______nonetheless, many manufacturers were slow to adapt.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$'Nonetheless' is a conjunctive adverb joining two independent clauses, so it must be preceded by a semicolon and followed by a comma.$q$, null),
  ($q$conv-93$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The volcano erupted without warning, and ash______the sky for nearly a week afterward.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["darkened","darkens","will darken","darkening"]$q$::jsonb, 0, $q$The sentence is in past tense ('erupted'), so the second verb must also be past tense, 'darkened,' to remain consistent.$q$, null),
  ($q$conv-94$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The author's debut work______a slim volume of interconnected short stories, published when she was only twenty-two—went largely unnoticed until decades after her death.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["—",", ",": ","; "]$q$::jsonb, 0, $q$The interrupting phrase 'a slim volume of interconnected short stories, published when she was only twenty-two' already contains its own internal comma, so only a matching dash—not a comma, colon, or semicolon—can open the interruption without creating ambiguity about where the aside begins.$q$, null),
  ($q$conv-95$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The newly discovered fossil is older than______specimen found in the region.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["any other","any","all","every"]$q$::jsonb, 0, $q$Because the fossil is itself a specimen found in the region, it must be compared to 'any other specimen' to exclude itself from the comparison. 'Any' is the closest trap because it almost completes the idiom correctly, but without 'other' it illogically includes the fossil among the things it is being compared to.$q$, null),
  ($q$conv-96$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The beekeeper checked the hive every week______the colony's honey production still declined sharply in late summer.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Both parts are independent clauses with no coordinating conjunction, so they must be joined with a semicolon; a comma alone would create a comma splice.$q$, null),
  ($q$conv-97$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Although the bridge had been inspected twice______engineers still worried about its structural integrity.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Although the bridge had been inspected twice' is an introductory dependent clause and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-98$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The warehouse lost power during the storm______the backup generators kicked in within seconds.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Both clauses are independent with no coordinating conjunction, so they must be joined with a semicolon; a comma alone would create a comma splice.$q$, null),
  ($q$conv-99$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The jury reached a unanimous decision______the defendant was guilty beyond a reasonable doubt.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the explanation of what the decision was, following a complete independent clause.$q$, null),
  ($q$conv-100$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Volunteers______available on weekends were assigned to the overnight shift.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[" ",", ","; ",": "]$q$::jsonb, 0, $q$'Available on weekends' is a restrictive (essential) phrase identifying which volunteers are meant, so no comma is needed before it.$q$, null),
  ($q$conv-101$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The lighthouse, ______ has guided ships since 1887, was recently restored by local volunteers.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["which","that","who","whom"]$q$::jsonb, 0, $q$The clause is nonessential (set off by commas) and refers to a thing, the lighthouse, so 'which' is correct; 'that' is reserved for restrictive clauses.$q$, null),
  ($q$conv-102$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The proposal lacked sufficient funding______moreover, it ignored community feedback entirely.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$'Moreover' is a conjunctive adverb joining two independent clauses, so it must be preceded by a semicolon and followed by a comma.$q$, null),
  ($q$conv-103$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Drenched by the sudden downpour______the hikers sought shelter under a rocky outcrop.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Drenched by the sudden downpour' is an introductory participial phrase and must be followed by a comma before the main clause.$q$, null),
  ($q$conv-104$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The gallery's new exhibit features three mediums______oil painting, charcoal sketching, and mixed-media collage.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", ",""]$q$::jsonb, 0, $q$A colon correctly introduces the list of items following the complete independent clause.$q$, null),
  ($q$conv-105$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The forecast predicted clear skies all weekend______a sudden storm rolled in Saturday afternoon.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Two independent clauses with a contrast in meaning but no coordinating conjunction must be joined with a semicolon.$q$, null),
  ($q$conv-106$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The lighthouse keeper's logbook, ______ kept meticulously since 1901 by three generations of the same family, records every ship that has passed the point.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["which has been","that has been","who has been","being"]$q$::jsonb, 0, $q$The nonessential clause set off by commas describes a thing (the logbook), not the family mentioned later in the sentence, so it needs the thing-pronoun 'which' with a complete verb phrase; 'who has been' is tempting because people are mentioned nearby, but the clause still modifies 'logbook.'$q$, null),
  ($q$conv-107$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The negotiations dragged on for months______yet both sides eventually reached a fair settlement.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Yet' is a coordinating conjunction joining two independent clauses, so a comma must precede it.$q$, null),
  ($q$conv-108$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The sculpture's base______a slab of unpolished granite, cut from a single quarry block—weighs nearly two tons.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["—",", ",": ","; "]$q$::jsonb, 0, $q$The interrupting phrase 'a slab of unpolished granite, cut from a single quarry block' already contains its own internal comma, so only a matching dash—not a comma, colon, or semicolon—can open the interruption without creating ambiguity about where the aside begins.$q$, null),
  ($q$conv-109$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The itinerary included stops in three cities______Lisbon, a coastal capital; Porto, a riverside hub; and Braga, a historic university town.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the list following the complete independent clause, and because the items themselves contain commas, semicolons separate the items; the semicolon is the closest trap, since semicolons do correctly separate the list's items, but only a colon can introduce the list as a whole.$q$, null),
  ($q$conv-110$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The results were, indeed______surprising to everyone on the research team.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Indeed' interrupts a single independent clause rather than joining two clauses, so it must be enclosed in a pair of commas; since the first comma is already given, a matching comma is needed here. The semicolon is the closest trap because interrupters like 'indeed' can also join two independent clauses with a semicolon before and comma after, but here 'indeed' only interrupts one clause.$q$, null),
  ($q$conv-111$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Even though the airline added extra flights for the holidays______demand still outpaced the available seats.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": ",". "]$q$::jsonb, 0, $q$'Even though the airline added extra flights for the holidays' is a dependent clause; ending it with a period would create a sentence fragment, so it must be joined to the independent clause with a comma.$q$, null),
  ($q$conv-112$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The software update______fixed the security flaw was released without any public announcement.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["that","which","who","whom"]$q$::jsonb, 0, $q$The clause 'fixed the security flaw' is essential to identifying which update is meant and has no surrounding commas, so the restrictive pronoun 'that' is correct.$q$, null),
  ($q$conv-113$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The______testimony contradicted the physical evidence presented at trial.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["witness's","witnesses'","witnesses","witness"]$q$::jsonb, 0, $q$Only one witness is referenced here, so the singular possessive is formed by adding an apostrophe and 's': 'witness's.'$q$, null),
  ($q$conv-114$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The______complaints finally prompted the city to repave the entire street.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["residents'","resident's","residents","residents's"]$q$::jsonb, 0, $q$Since many residents are complaining, the plural possessive 'residents'' is required, formed by adding only an apostrophe after the final s.$q$, null),
  ($q$conv-115$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$______research on coral bleaching was published in a leading science journal after three years of fieldwork.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["Maria and Carlos's","Maria's and Carlos's","Maria and Carlos'","Maria's and Carlos'"]$q$::jsonb, 0, $q$Because Maria and Carlos jointly produced one shared piece of research, only the final name takes the possessive marker, and a singular name ending in 's,' like Carlos, still takes 's' to form that possessive: 'Carlos's.' Marking both names as possessive ('Maria's and Carlos's') would wrongly imply two separate studies, and dropping the 's' after Carlos ('Carlos'') is the wrong way to form a singular possessive.$q$, null),
  ($q$conv-116$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The company revised______return policy after receiving dozens of customer complaints.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["its","it's","its'","it is"]$q$::jsonb, 0, $q$The possessive 'its' (no apostrophe) shows that the policy belongs to the company; 'it's' is a contraction of 'it is,' and 'its'' is not a standard word.$q$, null),
  ($q$conv-117$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The committee could not determine______proposal had been submitted first.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["whose","who's","who","whom"]$q$::jsonb, 0, $q$'Whose' is the possessive form needed here, since the proposal belongs to someone; 'who's' is a contraction of 'who is,' which does not fit this context.$q$, null),
  ($q$conv-118$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Many city parks have cut back their watering schedules this summer______for example, the botanical garden now waters its lawns only twice a week.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$'For example' introduces a second independent clause, so like a conjunctive adverb it must be preceded by a semicolon and followed by a comma. The comma is the closest trap because 'for example' is often set off by commas when it interrupts a single clause, but here it introduces a whole new independent clause, which requires the stronger semicolon break.$q$, null),
  ($q$conv-119$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The ferry service was suspended due to high winds______so passengers had to wait at the terminal overnight.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'So' is a coordinating conjunction joining two independent clauses, so a comma must precede it.$q$, null),
  ($q$conv-120$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The chef plated the dessert with great precision______and the diners applauded as it arrived at the table.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'And' is a coordinating conjunction joining two independent clauses, so a comma must precede it.$q$, null),
  ($q$conv-121$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The keynote speaker______a leading expert in renewable energy, discussed the future of solar storage technology.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'A leading expert in renewable energy' is a nonessential appositive renaming 'the keynote speaker,' so it must be set off with a pair of commas; since the closing comma is already given, the opening comma is needed here.$q$, null),
  ($q$conv-122$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The scholarship committee selected the applicant______the faculty panel had unanimously recommended.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["whom","who","which","that"]$q$::jsonb, 0, $q$Within the clause, the pronoun functions as the object of 'recommended' ('the panel had recommended whom'), so the objective case 'whom' is required; 'who' is the closest trap because it would be correct if the pronoun were the subject of 'recommended' rather than its object.$q$, null),
  ($q$conv-123$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The recipe requires______flour, sugar, and eggs, all of which must be measured precisely.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[" ",": ","; ",", "]$q$::jsonb, 0, $q$'Flour, sugar, and eggs' serves as the direct object of 'requires,' so nothing should separate the verb from its object. The colon is the closest trap because colons often introduce lists, but a colon cannot separate a verb from its own direct object the way it can follow a complete independent clause.$q$, null),
  ($q$conv-124$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The construction crew finished the east wing ahead of schedule______meanwhile, the west wing fell further behind.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$'Meanwhile' is a conjunctive adverb joining two independent clauses, so it must be preceded by a semicolon and followed by a comma.$q$, null),
  ($q$conv-125$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Whenever the river crests above flood stage______the town opens its emergency shelters without delay.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Whenever the river crests above flood stage' is an introductory dependent clause and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-126$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Since the archive had no digital backup of the records______staff spent weeks re-scanning every page by hand.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": ",". "]$q$::jsonb, 0, $q$'Since the archive had no digital backup of the records' is a dependent clause; ending it with a period would create a sentence fragment, so a comma is needed to join it to the main clause.$q$, null),
  ($q$conv-127$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Everyone in the office dreaded the______latest round of budget cuts.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["boss's","bosses'","boss'","bosses"]$q$::jsonb, 0, $q$For a singular noun ending in 's' ('boss'), Standard English still adds 's to form the possessive: 'boss's'; 'boss'' omits the required s.$q$, null),
  ($q$conv-128$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The committee's final report—delayed for nearly a year by budget disputes, lawsuits, and staff turnover______was finally released to the public.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["—",", ",": ","; "]$q$::jsonb, 0, $q$The interrupting phrase 'delayed for nearly a year by budget disputes, lawsuits, and staff turnover' already contains internal commas separating its list, so only a matching dash—not a comma, colon, or semicolon—can close the interruption without creating ambiguity about where the aside ends.$q$, null),
  ($q$conv-129$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Dr. Alvarez, ______ has led the clinic for over a decade, announced her retirement last week.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["who","that","which","whom"]$q$::jsonb, 0, $q$The nonessential clause set off by commas refers to a person, Dr. Alvarez, and functions as the subject of 'has led,' so the subjective case 'who' is correct.$q$, null),
  ($q$conv-130$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The archivist digitized the entire photo collection______preserving images that had begun to fade badly.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Preserving images that had begun to fade badly' is a participial phrase modifying the whole preceding clause, so it must be set off with a comma.$q$, null),
  ($q$conv-131$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The inspector's report identified a single cause of the collapse______corroded support beams.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the explanation of what the cause was, following a complete independent clause.$q$, null),
  ($q$conv-132$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$She finished her shift at midnight______she drove straight home without stopping.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Both clauses are independent with no coordinating conjunction, so they must be joined with a semicolon; a comma alone would create a comma splice.$q$, null),
  ($q$conv-133$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The password______protects the company's servers must be changed every ninety days.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["that","which","who","whom"]$q$::jsonb, 0, $q$The clause 'protects the company's servers' is essential to identifying which password is meant and has no surrounding commas, so the restrictive pronoun 'that' is correct rather than 'which.'$q$, null),
  ($q$conv-134$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The manager and the head chef______responsible for approving the new seasonal menu.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["are","is","was","has been"]$q$::jsonb, 0, $q$A compound subject joined by 'and' ('the manager and the head chef') is plural, so it takes the plural verb 'are.'$q$, null),
  ($q$conv-135$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Either the plumber or the electricians______available to come by tomorrow morning.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["are","is","was","has been"]$q$::jsonb, 0, $q$In an 'either/or' construction, the verb agrees with the nearer subject, 'electricians,' which is plural, so 'are' is correct.$q$, null),
  ($q$conv-136$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$None of the cake______left by the time the guests arrived at the party.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["was","were","are","have been"]$q$::jsonb, 0, $q$'Cake' here is a noncount (mass) noun referring to a single whole, so 'none' takes the singular verb 'was.' 'Were' is the closest trap because 'none' can take a plural verb when it refers to a count noun ('none of the cookies were left'), but 'cake' here is treated as an uncountable whole.$q$, null),
  ($q$conv-137$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$None of the volunteers______willing to work the overnight shift on such short notice.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["were","was","is","has been"]$q$::jsonb, 0, $q$'Volunteers' is a plural count noun, so 'none of the volunteers' takes the plural verb 'were.'$q$, null),
  ($q$conv-138$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The nonprofit updated______mission statement to reflect its expanded community programs.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["its","their","his","one's"]$q$::jsonb, 0, $q$'Nonprofit' is a singular organization, so it takes the singular possessive pronoun 'its,' not the plural 'their.'$q$, null),
  ($q$conv-139$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The disagreement about the budget was strictly between the treasurer and______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["me","I","myself","mine"]$q$::jsonb, 0, $q$As the object of the preposition 'between,' the objective case 'me' is required, not the subjective 'I.'$q$, null),
  ($q$conv-140$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The director asked Priya and______to present the quarterly results.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["me","myself","I","mine"]$q$::jsonb, 0, $q$As the object of the verb 'asked,' the objective pronoun 'me' is required; 'myself' is a reflexive pronoun and cannot stand in as a simple object here.$q$, null),
  ($q$conv-141$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The new assembly line produces______defective parts than the old one did.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["fewer","less","lesser","little"]$q$::jsonb, 0, $q$'Defective parts' is a countable plural noun, so the countable modifier 'fewer' is required rather than 'less,' which modifies noncount nouns.$q$, null),
  ($q$conv-142$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The council must either approve the new zoning law or______it back to committee for revision.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["send","sending","the sending of","to send"]$q$::jsonb, 0, $q$'Either...or' requires parallel structure; since the first element is the base verb 'approve' (governed by 'must'), the second must match with the base verb 'send.' 'To send' is the closest trap because it reads naturally, but reinserting 'to' breaks the parallel with the bare infinitive 'approve.'$q$, null),
  ($q$conv-143$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The clinic______over three thousand patients since it opened its doors in 2015.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["has treated","treated","treats","will treat"]$q$::jsonb, 0, $q$An action that began in the past and continues up to the present, marked by 'since,' requires the present perfect tense, 'has treated.'$q$, null),
  ($q$conv-144$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The pilot reported that the storm______by the time the plane reached cruising altitude.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["had already passed","would have passed","has already passed","was already passing"]$q$::jsonb, 0, $q$Because the storm passed before another past event (the plane's reaching altitude), the past perfect 'had already passed' is required to show the earlier action; 'would have passed' is tempting because it also relates two past events, but the conditional perfect wrongly implies the passing depended on some unstated condition.$q$, null),
  ($q$conv-145$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The new lighting system did not______the plants' growth rate in any measurable way.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["affect","effect","affects","effected"]$q$::jsonb, 0, $q$'Affect' is the verb meaning 'to influence,' which fits the sentence; 'effect' is primarily a noun meaning 'a result.'$q$, null),
  ($q$conv-146$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The second applicant was far more qualified______the first.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["than","then","that","when"]$q$::jsonb, 0, $q$'Than' is used to introduce a comparison; 'then' refers to time and does not fit this context.$q$, null),
  ($q$conv-147$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Every department submitted its budget report______the marketing team, which requested an extension.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["except","accept","excepting for","excepted"]$q$::jsonb, 0, $q$'Except' means 'excluding,' which fits the meaning here; 'accept' means 'to receive or agree to' and does not make sense in this context.$q$, null),
  ($q$conv-148$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The warranty______covers manufacturing defects, not damage caused by misuse.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["only","the only","only that","that only"]$q$::jsonb, 0, $q$Placing 'only' immediately before the verb 'covers' correctly limits the meaning to manufacturing defects alone, matching the contrast drawn in the second half of the sentence. 'That only' is the closest trap because it still precedes 'covers,' but inserting 'that' turns the sentence into an incomplete relative-clause fragment rather than a complete main clause.$q$, null),
  ($q$conv-149$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Either the judge or the jury______the final say on the sentencing recommendation.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["has","have","having","had been having"]$q$::jsonb, 0, $q$In an 'either/or' construction, the verb agrees with the nearer subject, the singular 'jury,' so 'has' is correct.$q$, null),
  ($q$conv-150$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Two-thirds of the orchard______damaged by the early frost last spring.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["was","were","has been","is"]$q$::jsonb, 0, $q$With fractions, the verb agrees with the noun in the 'of' phrase; 'orchard' is singular, so the singular verb 'was' is correct. 'Were' is the closest trap because fractions take a plural verb when the noun that follows is plural ('two-thirds of the apples were damaged'), but here the noun is the singular 'orchard.'$q$, null),
  ($q$conv-151$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The veteran guide______the hikers safely down the mountain before the storm hit.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["led","lead","leaded","has lead"]$q$::jsonb, 0, $q$The past-tense form of the verb 'lead' is spelled 'led'; 'lead' is either the present tense or the name of the metal, neither of which fits this past-tense sentence.$q$, null),
  ($q$conv-152$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The audience showed______appreciation with a long standing ovation.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["its","their","it's","them"]$q$::jsonb, 0, $q$'Audience' is a singular collective noun acting as one unit, so it takes the singular possessive 'its,' not the plural 'their.'$q$, null),
  ($q$conv-153$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The detective finally identified______had tampered with the evidence.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["who","whom","whoever's","which"]$q$::jsonb, 0, $q$The pronoun functions as the subject of 'had tampered,' so the subjective case 'who' is required, not the objective 'whom.'$q$, null),
  ($q$conv-154$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The internship involved shadowing senior engineers, documenting lab results, and______client presentations.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["reviewing","review","to review","the review of"]$q$::jsonb, 0, $q$The list requires parallel gerunds ('shadowing,' 'documenting,' and ___), so 'reviewing' matches the established form.$q$, null),
  ($q$conv-155$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Among the finalists______two former Olympic swimmers from the same training club.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["were","was","is","has been"]$q$::jsonb, 0, $q$In this inverted sentence, the true subject, 'two former Olympic swimmers,' follows the verb and is plural, so the plural verb 'were' is required even though it comes first. 'Was' is the closest trap because a reader might wrongly match the verb to the nearer word 'finalists' in the opening phrase instead of to the actual subject after the verb.$q$, null),
  ($q$conv-156$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$When the results______from the lab, the research team will schedule a press conference.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["arrive","will arrive","would arrive","arriving"]$q$::jsonb, 0, $q$In a future time clause introduced by 'when,' Standard English uses the simple present tense, 'arrive,' rather than 'will arrive,' even though the overall meaning is future.$q$, null),
  ($q$conv-157$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The hikers decided to travel ten miles______before setting up camp for the night.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["farther","further","farthest","furthest"]$q$::jsonb, 0, $q$'Farther' refers to physical distance, which fits this context, while 'further' is generally reserved for figurative or additional extent.$q$, null),
  ($q$conv-158$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The farm reported a significant______of crop losses after the unexpected hailstorm.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["number","amount","quantity of","numbering"]$q$::jsonb, 0, $q$'Crop losses' is a countable plural noun, so 'number' is the correct modifier; 'amount' is reserved for noncount nouns.$q$, null),
  ($q$conv-159$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Although the volcano had been dormant for nearly two centuries______geologists continued to monitor its seismic activity.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Although the volcano had been dormant for nearly two centuries' is an introductory dependent clause and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-160$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Blending seamlessly into the coral______the octopus evaded the diver's camera for several minutes.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Blending seamlessly into the coral' is an introductory participial phrase and must be followed by a comma before the main clause.$q$, null),
  ($q$conv-161$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The library's renovation took far longer than planned______the reading room did not reopen until late autumn.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Both parts are independent clauses with no coordinating conjunction, so they must be joined with a semicolon; a comma alone would create a comma splice.$q$, null),
  ($q$conv-162$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Merchants along the Silk Road carried a range of valuable goods______silk, spices, and precious stones.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", ",""]$q$::jsonb, 0, $q$A colon correctly introduces the list of items following the complete independent clause.$q$, null),
  ($q$conv-163$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The stock's price rebounded quickly after the announcement______however, analysts remained skeptical of its long-term growth.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$'However' is a conjunctive adverb joining two independent clauses, so it must be preceded by a semicolon and followed by a comma.$q$, null),
  ($q$conv-164$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The food truck's line stretched around the block all afternoon______but the owners ran out of ingredients by five o'clock.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'But' is a coordinating conjunction joining two independent clauses, so a comma must precede it.$q$, null),
  ($q$conv-165$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The antique clock, ______ had not kept accurate time in decades, was finally repaired by a local craftsman.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["which","that","who","whom"]$q$::jsonb, 0, $q$The clause is nonessential (set off by commas) and refers to a thing, the clock, so 'which' is correct; 'that' is reserved for restrictive clauses.$q$, null),
  ($q$conv-166$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The satellite's final component______a solar panel engineered to unfold in orbit, its hinges modeled on origami—was tested rigorously before launch.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["—",", ",": ","; "]$q$::jsonb, 0, $q$The interrupting phrase 'a solar panel engineered to unfold in orbit, its hinges modeled on origami' already contains its own internal comma, so only a matching dash—not a comma, colon, or semicolon—can open the interruption without creating ambiguity about where the aside begins.$q$, null),
  ($q$conv-167$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$During her solo, the______bow suddenly snapped, forcing her to borrow one from the concertmaster.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["violinist's","violinists'","violinists","violinist"]$q$::jsonb, 0, $q$The pronoun 'her' earlier in the sentence shows that only one violinist is being discussed, so the singular possessive 'violinist's' is required.$q$, null),
  ($q$conv-168$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The______lockers were inspected after several reports of missing textbooks.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["students'","student's","students","students's"]$q$::jsonb, 0, $q$Since many students' lockers are involved, the plural possessive 'students'' is required, formed by adding only an apostrophe after the final s.$q$, null),
  ($q$conv-169$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The sensor______malfunctioned during testing was replaced before the device shipped.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["that","which","who","whom"]$q$::jsonb, 0, $q$The clause 'malfunctioned during testing' is essential to identifying which sensor is meant and has no surrounding commas, so the restrictive pronoun 'that' is correct rather than 'which.'$q$, null),
  ($q$conv-170$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Climbers______attempting the north face must register with the ranger station in advance.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[" ",", ","; ",": "]$q$::jsonb, 0, $q$'Attempting the north face' is a restrictive (essential) phrase identifying which climbers are meant, so no comma is needed before it.$q$, null),
  ($q$conv-171$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The mural, ______ repainted twice since its unveiling by the same artist who created the original, has become a symbol of the neighborhood.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["which has been","that has been","who has been","being"]$q$::jsonb, 0, $q$The nonessential clause set off by commas describes a thing (the mural), not the artist named later in the sentence, so it needs the thing-pronoun 'which' with a complete verb phrase; 'who has been' is tempting because a person is mentioned nearby, but the clause still modifies 'mural.'$q$, null),
  ($q$conv-172$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Firefighters contained the blaze within two days______the surrounding hillsides remained charred for months.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Two independent clauses with a contrast in meaning but no coordinating conjunction must be joined with a semicolon.$q$, null),
  ($q$conv-173$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Regulators raised concerns about the exchange's security practices______therefore, several investors withdrew their funds.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$'Therefore' is a conjunctive adverb joining two independent clauses, so it must be preceded by a semicolon and followed by a comma.$q$, null),
  ($q$conv-174$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$She shaped the clay carefully on the wheel______and the instructor praised her steady hands.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'And' is a coordinating conjunction joining two independent clauses, so a comma must precede it.$q$, null),
  ($q$conv-175$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The Antarctic station housed three researchers______Dr. Lindqvist, a climatologist; Mr. Oyelaran, a mechanic; and Ms. Voss, a physician.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the list following the complete independent clause, and because the items themselves contain commas, semicolons separate the items; the semicolon is the closest trap, since semicolons do correctly separate the list's items, but only a colon can introduce the list as a whole.$q$, null),
  ($q$conv-176$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Because the tsunami warning system detected the tremor within seconds______coastal towns had time to evacuate.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Because the tsunami warning system detected the tremor within seconds' is an introductory dependent clause and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-177$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$After decades buried beneath the peat bog______the Viking ship's timbers were finally excavated intact.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'After decades buried beneath the peat bog' is an introductory prepositional phrase and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-178$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The orchestra's new conductor—trained at a conservatory in Vienna, where she studied under two renowned mentors______surprised the board by programming an entirely contemporary season.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["—",", ",": ","; "]$q$::jsonb, 0, $q$The interrupting phrase 'trained at a conservatory in Vienna, where she studied under two renowned mentors' already contains its own internal comma, so only a matching dash—not a comma, colon, or semicolon—can close the interruption without creating ambiguity about where the aside ends.$q$, null),
  ($q$conv-179$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The expedition's lead scientist______a marine biologist specializing in deep-sea ecosystems, briefed the crew before the dive.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'A marine biologist specializing in deep-sea ecosystems' is a nonessential appositive renaming 'the lead scientist,' so it must be set off with a pair of commas; since the closing comma is already given, the opening comma is needed here.$q$, null),
  ($q$conv-180$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The committee dedicated the award to the volunteer______they credited with founding the animal shelter.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["whom","who","which","that"]$q$::jsonb, 0, $q$Within the clause, the pronoun functions as the object of 'credited' ('they credited whom'), so the objective case 'whom' is required; 'who' is the closest trap because it would be correct if the pronoun were the subject of the clause rather than its object.$q$, null),
  ($q$conv-181$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$Professor Alemu, ______ has studied medieval trade guilds for thirty years, published her findings last month.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["who","that","which","whom"]$q$::jsonb, 0, $q$The nonessential clause set off by commas refers to a person, Professor Alemu, and functions as the subject of 'has studied,' so the subjective case 'who' is correct.$q$, null),
  ($q$conv-182$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Pedaling against a fierce headwind______the cyclist fell behind the lead pack during the final stretch.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Pedaling against a fierce headwind' is an introductory participial phrase and must be followed by a comma before the main clause.$q$, null),
  ($q$conv-183$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The startup's app crashed repeatedly during the demo______investors still expressed interest in funding the project.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$Both clauses are independent with no coordinating conjunction, so they must be joined with a semicolon; a comma alone would create a comma splice.$q$, null),
  ($q$conv-184$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$The planetarium's new show reveals a startling fact______most stars visible at night no longer exist in their observed form.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[": ","; ",", "," "]$q$::jsonb, 0, $q$A colon correctly introduces the explanation of what the fact was, following a complete independent clause.$q$, null),
  ($q$conv-185$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The brewery's new recipe sold out within hours______so the owners doubled production for the following week.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'So' is a coordinating conjunction joining two independent clauses, so a comma must precede it.$q$, null),
  ($q$conv-186$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The troupe's final rehearsal______a full run-through in costume, complete with the orchestra—convinced the director the show was ready.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["—",", ",": ","; "]$q$::jsonb, 0, $q$The interrupting phrase 'a full run-through in costume, complete with the orchestra' already contains its own internal comma, so only a matching dash—not a comma, colon, or semicolon—can open the interruption without creating ambiguity about where the aside begins.$q$, null),
  ($q$conv-187$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The traffic study revealed severe congestion downtown______consequently, the city fast-tracked the new bus rapid transit line.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["; ",", ",": "," "]$q$::jsonb, 0, $q$'Consequently' is a conjunctive adverb joining two independent clauses, so it must be preceded by a semicolon and followed by a comma.$q$, null),
  ($q$conv-188$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Since the blood bank's reserves had dropped to a critical low______the hospital organized an emergency donation drive.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[", ","; ",": "," "]$q$::jsonb, 0, $q$'Since the blood bank's reserves had dropped to a critical low' is an introductory dependent clause and must be set off from the main clause with a comma.$q$, null),
  ($q$conv-189$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The ingredient______triggered the allergic reaction was removed from the recipe immediately.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["that","which","who","whom"]$q$::jsonb, 0, $q$The clause 'triggered the allergic reaction' is essential to identifying which ingredient is meant and has no surrounding commas, so the restrictive pronoun 'that' is correct.$q$, null),
  ($q$conv-190$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$The suspension bridge, ______ engineered by a team that had never designed for hurricane-force winds before, has never sustained structural damage.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["which was","that was","who was","being"]$q$::jsonb, 0, $q$The nonessential clause set off by commas describes a thing (the bridge), not the team mentioned later in the sentence, so it needs the thing-pronoun 'which' with a complete verb phrase; 'who was' is tempting because a team of people is mentioned nearby, but the clause still modifies 'bridge.'$q$, null),
  ($q$conv-191$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 2, $q$______proposal for the new wing was approved unanimously by the board.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["Chen and Okafor's","Chen's and Okafor's","Chen and Okafor's'","Chens and Okafor's"]$q$::jsonb, 0, $q$Because Chen and Okafor jointly produced one shared proposal, only the final name takes the apostrophe and s; marking both names as possessive would incorrectly suggest two separate proposals.$q$, null),
  ($q$conv-192$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Boundaries$q$, 1, $q$Drivers______caught speeding in the school zone will receive an automatic fine.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$[" ",", ","; ",": "]$q$::jsonb, 0, $q$'Caught speeding in the school zone' is a restrictive (essential) phrase identifying which drivers are meant, so no comma is needed before it.$q$, null),
  ($q$conv-193$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The curator and her assistant______responsible for cataloging every artifact in the new wing.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["are","is","was","has been"]$q$::jsonb, 0, $q$A compound subject joined by 'and' ('the curator and her assistant') is plural, so it takes the plural verb 'are.'$q$, null),
  ($q$conv-194$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The researchers reviewed______data before submitting the paper for publication.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["their","his","its","one's"]$q$::jsonb, 0, $q$The antecedent 'researchers' is plural, so the plural possessive pronoun 'their' is required for agreement.$q$, null),
  ($q$conv-195$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The panel of judges______unanimous in awarding first prize to the young violinist.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["was","were","are","have been"]$q$::jsonb, 0, $q$'Panel' is a singular collective noun, so it takes the singular verb 'was,' regardless of the plural noun 'judges' in the prepositional phrase that follows it.$q$, null),
  ($q$conv-196$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The praise for the championship win was shared equally between the team captain and______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["me","I","myself","mine"]$q$::jsonb, 0, $q$As the object of the preposition 'between,' the objective case 'me' is required, not the subjective 'I.'$q$, null),
  ($q$conv-197$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The exhibit was praised not only for its striking visuals but also for______.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["its clear explanation of complex science","explaining complex science with clarity","how clearly it explained complex science","the complex science it explained clearly"]$q$::jsonb, 0, $q$'Not only...but also' pairs two objects of 'for'; since the first is the possessive noun phrase 'its striking visuals,' the second must match that form: 'its clear explanation of complex science.' The other choices are grammatical as objects of 'for' but shift to a gerund phrase or a clause, breaking the parallel structure.$q$, null),
  ($q$conv-198$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$The diver descended slowly and then______for the shipwreck visible below.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["searched","searches","will search","searching"]$q$::jsonb, 0, $q$The sentence is in past tense ('descended'), so the second verb must also be past tense, 'searched,' to remain consistent.$q$, null),
  ($q$conv-199$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Carving late into the night, ______$q$, $q$Which choice most logically and clearly completes the sentence?$q$, $q$["the sculptor finally finished the marble bust.","the marble bust took its final shape under the studio lights.","the studio remained quiet except for the scrape of the chisel.","exhaustion finally caught up with the long project."]$q$::jsonb, 0, $q$The introductory phrase 'Carving late into the night' describes a person performing the action, so the noun immediately after the comma must be that person, 'the sculptor'; the bust, the studio, and the exhaustion cannot carve, even though each choice reads as a complete, plausible sentence.$q$, null),
  ($q$conv-200$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The board recommended that the policy______revised before the next fiscal quarter.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["be","is","was","will be"]$q$::jsonb, 0, $q$'Recommended that' triggers the subjunctive mood, which uses the base form 'be' regardless of the subject's number or the sentence's tense; 'will be' is tempting because the revision is a future event, but the subjunctive 'be' is required after a verb of recommendation, not an ordinary future tense.$q$, null),
  ($q$conv-201$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Everybody at the conference______asked to wear a name badge at all times.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["was","were","are","have been"]$q$::jsonb, 0, $q$The indefinite pronoun 'everybody' is grammatically singular, so it takes the singular verb 'was.'$q$, null),
  ($q$conv-202$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$By the time the train reached the station, the passengers______for nearly three hours.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["had been waiting","waited","would have been waiting","are waiting"]$q$::jsonb, 0, $q$Because the waiting began before and continued up to another past event (the train's arrival), the past perfect progressive 'had been waiting' is required; 'would have been waiting' is tempting because it also combines past time with progressive aspect, but the conditional form wrongly implies the waiting depended on some unstated condition.$q$, null),
  ($q$conv-203$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The grant will go to______submits the most innovative proposal.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["whoever","whomever","who","whom"]$q$::jsonb, 0, $q$The pronoun functions as the subject of 'submits' within its own clause, so the subjective case 'whoever' is correct even though the entire clause follows the preposition 'to'; 'whomever' is the closest trap because it would be correct if the pronoun were instead the object of a verb inside the clause.$q$, null),
  ($q$conv-204$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Of the two bridges spanning the river, the older one is the______traveled.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["more","most","much","many"]$q$::jsonb, 0, $q$When comparing exactly two things, the comparative form 'more' is required rather than the superlative 'most,' which is used for three or more.$q$, null),
  ($q$conv-205$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 1, $q$Of the three trails leading up the ridge, the eastern one is the______difficult.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["most","more","much","many"]$q$::jsonb, 0, $q$When comparing three or more items, the superlative form 'most' is required rather than the comparative 'more,' which is used for exactly two.$q$, null),
  ($q$conv-206$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$A number of residents______attended the town hall to voice their concerns.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["have","has","having","is"]$q$::jsonb, 0, $q$'A number of' is treated as plural, so it takes the plural verb 'have'; this differs from 'the number of,' which takes a singular verb.$q$, null),
  ($q$conv-207$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The tools had______on the workbench untouched since the shop's relocation last spring.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["sat","set","sitten","setted"]$q$::jsonb, 0, $q$The intransitive verb 'sit' (to rest in a place) takes the past participle 'sat' after 'had'; 'set' is the past participle of the transitive verb 'set,' which requires a direct object.$q$, null),
  ($q$conv-208$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$The coupon______applies to online purchases, not in-store ones.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["only","the only","only that","that only"]$q$::jsonb, 0, $q$Placing 'only' immediately before the verb 'applies' correctly limits the meaning to online purchases alone, matching the contrast drawn in the second half of the sentence.$q$, null),
  ($q$conv-209$q$, $q$rw$q$, $q$Standard English Conventions$q$, $q$Form, Structure, and Sense$q$, 2, $q$Her role as project manager involves tracking budgets, scheduling inspections, and______client questions.$q$, $q$Which choice completes the text so that it conforms to the conventions of Standard English?$q$, $q$["answering","answer","to answer","the answering of"]$q$::jsonb, 0, $q$The list requires parallel gerunds ('tracking,' 'scheduling,' and ___), so 'answering' matches the established form.$q$, null)
on conflict (id) do update set
  module = excluded.module,
  domain = excluded.domain,
  skill = excluded.skill,
  difficulty = excluded.difficulty,
  passage = excluded.passage,
  prompt = excluded.prompt,
  choices = excluded.choices,
  answer = excluded.answer,
  explanation = excluded.explanation,
  choice_explanations = excluded.choice_explanations;
